// New procedures, checklists and toolbox talks written for the industries above (same schemas as PROCS, CHECKLISTS, TALKS).
const PROCS3 = [
{id:"p3-press",t:"Power Presses & Press Shop (Mechanical, Hydraulic, Servo)",cat:"Industrial",tags:["Industrial","Automotive","Machinery"],purpose:"Prevent hand and finger amputations, crush injuries and die-ejection incidents on power presses, press brakes and transfer lines in press shops and component units.",scope:"Mechanical (clutch/brake), hydraulic and servo presses 10–2,500 t; press brakes; tandem and transfer lines; die setting and try-out; coil/blank feeding; scrap handling; die storage and maintenance.",roles:["Press shop head (authorises operators and die-setters)","Press operators (trained, authorised, ≥ 18 yrs)","Die setters / tool room","Maintenance (clutch-brake, PL/SIL safety circuits)","Safety officer (guard and safety-distance verification)"],hazards:["Hands in point of operation: clutch failure, double stroke, repeat, unexpected descent; crush between ram and bolster","Die ejection, slug/scrap fly-out, broken punch fragments; coil whip when cutting bands; sharp blanks","Die setting: 1–20 t dies lifted by EOT/forklift, hands between die halves, ram creep with no safety blocks","Noise 95–110 dB(A) at impact; vibration; oil mist; back and shoulder strain from repetitive loading"],pre:["Each press risk-assessed per ISO 12100; safeguarding by fixed/interlocked guards, light curtains (ISO 13855: S = 1,600 mm/s × T + C), two-hand control (both within 0.5 s) or automatic feed with enclosure","Mechanical presses: part-revolution clutch with brake monitor, anti-repeat, stroke selector keyed; full-revolution (positive-clutch) presses only with fixed enclosure or hand-removal tools; no foot pedal without light curtain","Safety circuit designed and validated to ISO 13849-1 PL d/e (Cat 3/4) or IEC 62061 SIL 2/3; e-stops at every station; stop time measured and recorded at commissioning and after brake work","Die-setting: safety blocks (ram props) rated for ram weight, die clamps/lifting points inspected, EOT with rated slings, die carts; die height and shut height set under written procedure","Operators 18+, trained and authorised in writing; state dangerous-operations schedule for power presses complied (TN Rule 53 Schedule / KA Rule 56 Schedule — verify); hearing-conservation zone marked"],steps:["Shift start: operator checks guards, light curtain function (test piece at three heights), two-hand controls, e-stop, brake-monitor lamp, lubrication; records in press log; defects → tag out, inform supervisor.","Set-up by die setter only: press isolated (LOTO) before hands enter die space; ram at bottom or safety blocks in; die clamped at all designated points; guard re-fitted and verified before first stroke.","First-off inspection in inch/single-stroke mode with hands outside; verify stripper, slug chute, scrap exit, part ejection; approve run.","Production: feed/unload with hands outside the light-curtain plane or with tongs/magnets; never reach to clear a misfeed on a cycling press — stop, isolate, then clear.","Multi-operator presses: a two-hand station per operator, all required to initiate; supervisor keys stroke selector; no bypass keys left in machines.","Coil handling: cut bands from the side with band cutter, face shield, gloves; coil cars/decoilers interlocked; secure coil before releasing clamp.","Hydraulic presses: check pressure relief setting and hose condition; treat hydraulic leaks as injection-injury risk; isolate and bleed before work on cylinders.","Scrap: enclosed chutes and conveyors to bins; cut-resistant gloves for blank handling; no hand-trimming of burrs on moving line.","Maintenance: LOTO at main isolator plus pneumatic/hydraulic dump; brake lining, clutch air pressure and stop-time checked at defined intervals","Thorough examination of press and safety devices every 6 months (12 months if fixed guards only — PUWER benchmark, verify).","Record near misses (light-curtain trips, double strokes); investigate every double stroke as a dangerous occurrence; retrain and re-verify after any modification or relocation."],ppe:["Safety glasses, cut-resistant gloves (not where entanglement risk), safety shoes with metatarsal guard at die-setting, hearing protection (SNR ≥ 25), no loose clothing or jewellery"],stop:["Light curtain or two-hand control fails test","Brake-monitor fault or stop time exceeds recorded value","Ram moves with hands in die space / safety blocks missing during set-up","Operator not authorised or under 18","Bypass key, jumper or taped sensor found"],records:["Press register with safeguarding type, stop-time and PL/SIL validation, shift checks, die-setting log, 6-monthly examinations, operator authorisations, audiometry, near-miss log"],refs:{india:["Factories Act ss.21–23, 26 (fencing, machinery in motion, young persons, casing of new machinery) via state rules / OSH Code s.6","IS 9474 (guarding); IS 16819 / ISO 12100; Sch. II noise limit 90 dB(A); Third Schedule (noise-induced hearing loss notifiable)"],ka:["Karnataka Factories Rules 1969 Rule 56 Schedule (power presses — verify number); DFBISH; Karnataka Safety Audit Rules 2024"],tn:["TN Factories Rules 1950 Rule 53 Schedule (power presses, shears, guillotines — verify); DISH TN"],osha:["1910.217 (mechanical power presses, incl. brake monitors & PSDI), 1910.212, 1910.147; ANSI B11.1 (mechanical presses), B11.2 (hydraulic presses), B11.19 (safeguarding)"],intl:["ISO 16092-1/-2/-3 (presses safety); ISO 13855, ISO 13849-1, ISO 13857, ISO 14119 (interlocks); UK PUWER regs 32–35 & HSG236 (power presses)"]},checklist:"cl4-press"},
{id:"p3-robot",t:"Industrial Robot Cells, Interlocked Guarding & Collaborative Robots",cat:"Industrial",tags:["Industrial","Automotive","Machinery"],purpose:"Prevent crushing, striking and trapping of people inside robot cells during production, teaching, maintenance and recovery from faults.",scope:"Welding, handling, painting, palletising and assembly robots; perimeter-guarded cells; multi-robot lines; AGV/AMR interfaces; collaborative robots (power-and-force limiting, speed and separation monitoring); cell integration and modification.",roles:["Cell owner / production engineer","Robot programmers (teach-mode trained)","Maintenance (safety PLC, interlocks)","Integrator (risk assessment per ISO 10218-2)","Safety officer (validation witness)"],hazards:["Unexpected motion from a stopped-looking robot (waiting for signal); reach beyond visible envelope; high speed (> 2 m/s) and payload inertia","Person inside cell unseen when cycle restarted from outside; muted or defeated interlocks; climbing over fences","Teach mode: pendant enabling device released late; wrong frame/speed; collision with fixtures; crush against fixed objects","Secondary hazards: weld spatter and fume, laser, pinch points of grippers, dropped parts, pneumatic/hydraulic stored energy, hot tooling"],pre:["Cell risk assessment to ISO 10218-2:2025 / ISO 12100 covering all task-based modes (production, teach, maintenance, cleaning, recovery); safeguarded space defined; restricted space limited by software and hard stops","Perimeter guard ≥ 1.4 m (ISO 13857 reach), interlocked gates with guard locking and trapped-key or request-to-enter","Presence sensing (laser scanners/light curtains) covering every hiding zone so restart is impossible while someone is inside","Safety functions (protective stop, speed monitoring, safe zones) on safety PLC validated to ISO 13849-1 PL d; stop performance (stopping distance/time) measured and used for safeguarding distances","Teach pendant with 3-position enabling device; T1 reduced speed ≤ 250 mm/s; T2/high-speed teaching only with written authorisation and second person at e-stop","Cobots: collision test on body regions against ISO 10218 (ex-ISO/TS 15066) force/pressure limits with calibrated measuring device; sharp tools and payload edges covered; hand-guiding only with enabling device"],steps:["Before entry for any reason: request access at gate, wait for 'safe to enter' (robot in protective stop, drives disabled), open gate, take gate key/lock with you — the key in your pocket keeps the cell from restarting.","Inside the cell: carry the pendant with e-stop; never trust a motionless robot — it may be waiting for a part present signal; stay out of pinch zones between robot and fixtures.","Teaching: T1 mode; enabling device held in middle position; check tool frame and speed override; second person outside at e-stop for complex paths; no production parts in cell unless needed.","Fault recovery (dropped part, weld stuck, gripper jam): follow the task-specific procedure; isolate pneumatics (dump valve) before freeing gripper; hot tooling cooled or gloves rated.","Leaving: confirm nobody else inside (visual sweep of every robot), tools removed, gate closed and reset by the same person who entered; cycle start from outside only.","Maintenance: LOTO of main disconnect, pneumatics and hydraulics; support arm before brake release; capacitor discharge time (per OEM, typically 5 min — verify) before touching drives.","Changes to program, tooling, fixtures or cell layout → management of change: re-run risk assessment, re-validate safeguarding distances, document, retrain.","Interlock audit monthly: test every gate switch, scanner zone, muting function and e-stop; any bypass found is a stop-work and investigation.","AGV/AMR interfaces: pedestrian lanes separated; AMR safety scanners validated; handover stations guarded.","Train all cell entrants (operators, cleaners, maintenance) on cell-specific hazards; record authorisation; refresher yearly."],ppe:["Safety glasses, safety shoes, gloves as task requires, welding PPE where arc exposure, hearing protection; no loose clothing"],stop:["Any interlock, scanner or e-stop bypassed or faulty","Person can enter cell without robot going to protective stop","Teaching at high speed without authorisation and second person","Cell modified without MoC and re-validation","Cobot force/pressure test not done after tool/payload change"],records:["Cell risk assessment, safety validation report (stop times, PL), interlock test log, pendant/teach authorisations, MoC records, incident and near-miss log"],refs:{india:["Factories Act ss.21–22 via state rules / OSH Code s.6 (fencing, machinery in motion); IS 9474; IS 16819 / ISO 12100; IS 17893 (permits for cell maintenance); OSH Central Rules 2026 (machinery)"],ka:["Karnataka Factories Rules 1969 (fencing & maintenance of machinery); Karnataka Safety Audit Rules 2024"],tn:["TN Factories Rules 1950 (fencing of machinery); DISH TN"],osha:["1910.212, 1910.147 (incl. minor servicing exception limits); OSHA Technical Manual Sec. IV Ch. 4 (industrial robots); ANSI/RIA R15.06-2012; RIA TR R15.306/R15.806"],intl:["ISO 10218-1 & -2:2025 (robots and robot applications; incorporates ISO/TS 15066); ISO 13849-1; ISO 13855; ISO 13857; ISO 14119; ISO 3691-4 (AGVs); EU Machinery Regulation 2023/1230"]},checklist:"cl4-robot"},
{id:"p3-paintshop",t:"Paint Shop – Spray Booths, Solvents, Isocyanates & Ovens",cat:"Chemical",tags:["Chemical","Automotive","Fire","Health"],purpose:"Prevent fire and explosion from flammable solvents, occupational asthma from isocyanates, and burns, falls and chemical injuries in pre-treatment, e-coat, sealer, primer, top-coat and oven areas.",scope:"Pre-treatment/phosphating, electro-deposition (ED) tanks, spray booths (manual, electrostatic, robotic), paint mix rooms, solvent and thinner storage, curing ovens, paint sludge and VOC abatement (RTO), repair/touch-up, booth maintenance.",roles:["Paint shop head","Painters (fit-tested for RPE, medical surveillance)","Paint mix room operators","Maintenance (Ex equipment, oven burners, booth filters)","Fire officer; occupational physician"],hazards:["Flammable vapours (thinners, xylene, butyl acetate; flash points < 23 °C) — ignition by static, non-Ex electricals, hot work, electrostatic guns","Isocyanates (HDI/IPDI in 2K clear coats): respiratory sensitisation and asthma at µg/m³ levels; skin absorption; also solvents (neurotoxic), chromates in some primers, nickel/zinc phosphate","Ovens: gas explosion on light-off without purge; CO; burns; drying overspray self-heating in ducts; RTO flashback","ED tanks: 200–400 V DC in large tanks, drowning/chemical immersion; conveyors and skids overhead; falls from booth grids, pits and oven roofs; paint sludge pits (confined, H2S/solvent)"],pre:["Hazardous-area classification per IS 5572 / IEC 60079-10-1 (Zone 1 inside booths and mix rooms, Zone 2 around openings — verify extents)","Ex-rated electricals, lighting through sealed glass, intrinsically safe instruments; IS/IEC 60079-14/-17 inspections","Booths: downdraught/side-draught ventilation keeping vapour < 25% LEL and capture velocity ≈ 0.5 m/s at face (verify)","Overspray filters monitored by differential pressure; interlock: no spraying without airflow; sprinklers/deluge or CO2 flooding","Static: bonding and earthing of parts, conveyors, hoses and containers (< 10 Ω bonding, verify); conductive flooring and footwear; electrostatic guns interlocked with conveyor earth and ventilation","Isocyanate control: enclosed robotic application where possible; manual spraying only with supplied-air RPE (airline hood, APF 40 — verify) or PAPR with combined filters","Booth clearance time before entry; biological monitoring (urinary HDA) and annual lung-function tests for painters","Ovens per NFPA 86: pre-ignition purge ≥ 4 volume changes, flame safeguard, high-temperature limit, LEL control for solvent load, explosion relief","Solvent storage per Petroleum Rules 2002 (Class A), daily quantities only inside shop; spill kits, foam extinguishers"],steps:["Mix room: weigh and mix under LEV; containers earthed and bonded before pouring; lids closed; no electronic devices unless Ex; waste solvent to closed, earthed drums.","Before spraying: ventilation running and interlock proved, filters within DP limits, RPE fit and airline flow checked, no one else in booth during 2K application, warning light on.","Spraying: keep gun earthed; never point at people; stop if airflow alarm; clean guns in enclosed gun washers; dispose of rags in self-closing metal bins emptied each shift.","Booth exit: wait clearance time; remove coveralls and gloves before leaving; wash hands and face; no eating/smoking in paint areas.","Oven light-off: operator follows burner start-up sequence; never bypass purge or flame failure; check exhaust and LEL readings; keep oven doors interlocked; no entry until < 40 °C and gas-free.","ED/pre-treatment: isolate rectifier and verify dead before any work near the bath; guardrails and covers on tanks; acid/alkali handling with face shield, apron, gloves; eyewash within 10 s travel.","Booth and duct cleaning: hot work prohibited; remove overspray deposits per schedule (self-heating); confined-space permit for sludge pits and ducts; Ex-rated tools only.","Hot work or maintenance in paint shop: PTW with gas test (0% LEL), isolation of solvent lines, ventilation running; fire watch 60 min after.","Paint sludge, spent solvent, filters = hazardous waste (HOWM Sch. I); manifests; VOC emissions within SPCB consent; RTO maintained.","Health: pre-placement and annual surveillance (lung function, skin, urinary HDA where 2K used); remove sensitised workers from exposure; record and report occupational asthma as notifiable."],ppe:["Supplied-air hood or PAPR with A2P3 filters for spraying, chemical splash goggles, nitrile gloves (change after contamination), antistatic FR coveralls (EN 1149/ISO 11612), conductive footwear in Zone 1"],stop:["Booth ventilation or LEL interlock bypassed","Non-Ex equipment or phone in Zone 1/2","Isocyanate spraying without supplied-air/PAPR or with others in booth","Oven purge or flame-failure defeated","Hot work in paint shop without permit and gas test"],records:["Area classification drawings, Ex inspection register, airflow and LEL records, RPE fit tests and airline checks, biological monitoring, oven safety-device tests, HW manifests, VOC monitoring, PTW records"],refs:{india:["Petroleum Act 1934 & Rules 2002 (Class A/B storage, licensing); Factories Act ss.37, 87 via state rules (explosive atmospheres","Dangerous operations incl. cellulose/paint spraying — verify schedule); IS 5572, IS/IEC 60079-14/-17; IS 7689 (static); IS 3103 (ventilation); HOWM Rules 2016; Air Act consent (VOC); Sch. II PELs"],ka:["Karnataka Factories Rules 1969 Rule 129 schedule (spray painting / cellulose — verify); KSPCB VOC conditions; KSFES"],tn:["TN Factories Rules 1950 Rule 95 schedule (spray painting / cellulose solutions — verify); TNPCB; TNFRS"],osha:["1910.107 (spray finishing), 1910.94(c), 1910.106 (flammable liquids), 1910.307, 1910.134; NFPA 33 (spray application), NFPA 34 (dipping), NFPA 86 (ovens), NFPA 30, NFPA 77"],intl:["UK HSE HSG276 (motor vehicle repair — isocyanates), COSHH; ATEX 1999/92/EC; EN 16985 (spray booths); EN 12981 (powder booths); IEC 60079 series; ISO 16000 (isocyanate monitoring — verify)"]},checklist:"cl4-paintshop"},
{id:"p3-weldshop",t:"Body Shop – Resistance Spot Welding, MIG/Laser Welding & Weld Fume Control",cat:"Health",tags:["Industrial","Automotive","Health","Fire"],purpose:"Control welding fume (a Group 1 carcinogen), burns, crush and eye injuries, electrical and laser hazards in body-in-white shops and fabrication cells.",scope:"Manual and robotic resistance spot welding (RSW), MIG/MAG and CuSi brazing, stud and projection welding, laser welding/brazing, hemming, sealing; weld guns, transformers, cooling water, fume extraction; galvanised, boron and stainless steels, aluminium.",roles:["Body shop head","Welders / line operators","Maintenance (gun tips, transformers, cooling, LEV)","Laser safety officer (Class 4 cells)","Industrial hygienist / occupational physician"],hazards:["Welding fume: Mn (TLV 0.02 mg/m³ respirable), ZnO from galvanised sheet (metal fume fever), Cr(VI)/Ni from stainless, ozone from MIG on aluminium; IARC Group 1 for all welding fume (2017)","RSW: crush between electrodes (3–6 kN force), spatter burns, hot tips, molten expulsion; magnetic fields near transformers (pacemakers); shock from primary 415 V and damaged cables","Laser: Class 4 — eye/skin injury from direct or reflected beam, fume with fine particles, fire; enclosure interlocks","Fire from spatter on sealers, cardboard, oils; cooling-water leaks onto electrics; manual handling of weld guns (balancers), awkward postures; noise and UV (arc eye) for MIG"],pre:["Fume control hierarchy: enclosed robotic welding with extraction; on-torch/on-gun LEV for manual MIG","General ventilation alone is not acceptable for indoor welding (HSE 2019 benchmark); RPE (FFP3/PAPR) where LEV cannot capture","Exposure monitoring for Mn, Zn, Cr(VI), Ni, total fume against Sch. II / ACGIH values; health surveillance (lung function, respiratory questionnaire, Cr(VI)/Ni skin checks)","RSW guns: insulated handles, two-hand or enabling initiation for manual guns, tip dressers guarded, balancers and rails inspected; transformer secondary earthed; cables inspected weekly; water-flow switches interlocked","Laser cells: Class 1 enclosure with interlocked access, beam stops, warning lamps, laser safety officer, eyewear for maintenance in Class 4 mode (IEC 60825-1/-4); fume extraction with HEPA","Fire: sealers/adhesives and packaging kept away from arc zones; spark screens; extinguishers (CO2/DCP) every 15 m; hot-work permit for any welding outside designated shop areas"],steps:["Shift start: check LEV airflow indicators, hood positions, gun insulation, cables, water hoses, balancers; defective items tagged out.","Manual RSW: position panel, keep fingers clear of electrode line, initiate with both hands/enable; dress tips only with guarded dresser; let tips cool before handling.","MIG/MAG: position extraction nozzle ≤ 150–300 mm from arc (verify by smoke test); use welding helmet with correct shade (9–13), leather gloves/jacket; screens for others.","Galvanised or coated parts: extra extraction; stop and report metal fume fever symptoms (chills, fever after shift); remove coating where practical before welding.","Aluminium MIG: ozone — extraction plus ventilation; check for 'sweet' smell; stainless: treat as Cr(VI) — LEV, RPE, health surveillance.","Laser cells: access only with interlock sequence; beam off and verified before entry; service in Class 4 with LSO present, eyewear rated for wavelength, exclusion zone.","Robotic weld cells: see robot-cell procedure; tip dressing and spatter cleaning under LOTO.","Cooling water: check for leaks every shift; isolate power before fixing hoses near transformers; conductivity controlled per OEM.","Housekeeping: spatter and dust vacuumed (no compressed air); fume filters changed per DP with RPE and bagged as hazardous waste.","Health: pre-placement and periodic surveillance; pacemaker wearers kept away from RSW transformers (sign); notify occupational diseases (metal fume fever clusters, asthma)."],ppe:["Welding helmet/shade, leather gauntlets and apron, FR cotton clothing, safety glasses under helmet, FFP3 or PAPR where LEV inadequate, hearing protection, laser eyewear (maintenance)"],stop:["LEV not running or airflow below set point","Gun insulation damaged or water leaking on live parts","Laser interlock bypassed or cell entered with beam enabled","Welding on coated parts without extraction","Combustibles or sealers within spatter range"],records:["LEV examination (14-monthly benchmark), airflow checks, exposure monitoring, health surveillance, gun/cable inspections, laser safety records, hot-work permits, incident log"],refs:{india:["Factories Act s.14 (dust & fume), s.36A, s.87 via state rules / OSH Code s.6; Sch. II PELs (welding fume, Mn, Zn oxide, Cr(VI))","IS 818 (electric & gas welding safety), IS 3016 (fire precautions), IS 3103 (ventilation), IS 7194 (noise); IS 15298 PPE; HOWM Rules (fume filters)"],ka:["Karnataka Factories Rules 1969 (Rule 129 dangerous-operations schedules — chrome, lead where applicable; verify)"],tn:["TN Factories Rules 1950 (Rule 95 schedules; welding fume PEL; medical examination)"],osha:["1910.252–255 (welding, cutting, brazing; 1910.255 resistance welding), 1910.1026 (Cr(VI) PEL 5 µg/m³), 1910.1000, 1910.134; ANSI Z49.1; NFPA 51B"],intl:["IARC Monograph 118 (welding fume Group 1); UK HSE WL3 & COSHH welding fume guidance (2019); EN ISO 15012 (fume extraction); IEC 60825-1/-4 (lasers); EN ISO 11611 (welder's clothing); ACGIH TLVs"]},checklist:"cl4-weldshop"},
{id:"p3-ev-battery",t:"EV Traction Batteries – Pack Assembly, HV Work, Storage & Charging",cat:"Electrical",tags:["Electrical","Automotive","Fire","Energy/Carbon/ESG"],purpose:"Prevent electric shock, arc flash, thermal runaway fires and chemical exposure when assembling, testing, servicing, storing, charging and transporting lithium-ion traction batteries and high-voltage vehicles.",scope:"Cell and module handling, pack assembly and end-of-line testing, HV system work on vehicles (48 V–800 V DC), battery storage and quarantine, charging bays (AC Mode 3 / DC Mode 4), damaged or crashed vehicle handling, battery waste.",roles:["HV competent persons (Level 2/3 trained per OEM/DGUV 200-005 benchmark — verify)","Pack assembly operators","Battery storage in-charge","Fire officer / ERT (Li-ion fire trained)","Safety officer"],hazards:["HV DC 400–800 V: shock, arc flash with no current zero; stored energy in capacitors and contactors; insulation faults on chassis","Thermal runaway from internal short, over-charge, mechanical damage or heat: 600–1,000 °C, toxic/flammable gases (HF, CO, H2, electrolyte vapours), jet flames, re-ignition hours to days later","Cell handling: external short by tools/jewellery, dropped modules (20–60 kg), busbar laser welding fume, electrolyte (LiPF6 → HF with moisture), NMP in electrode coating","Charging: cable/connector damage, DC leakage without Type B RCD, vehicle fire in enclosed parking; transport: UN 38.3 untested or damaged cells"],pre:["HV work only by trained and authorised persons; HV areas marked","Insulated tools to IEC 60900 (1,000 V), Class 0 insulating gloves (EN 60903) with leather over-gloves, face shield (arc-rated), insulated mats (IS 15652), CAT III/IV meter with proven test leads","Vehicle/pack de-energising procedure per OEM: service disconnect removed and locked","Wait capacitor discharge time (typically 5–10 min — verify), measure HV bus < 60 V DC and insulation resistance before touching orange cables","Pack assembly: ESD and short-circuit control — insulated workbenches, covered busbars, torque tools with insulated shafts, no metal watches/rings","Module lifting aids; thermal cameras and gas (CO/VOC/H2) detection in formation/EOL test areas","Storage: SoC 30–50% for storage; temperature 15–25 °C; segregated fire-compartment or outdoor containers per NFPA 855 benchmark","Damaged/defective/returned (DDR) cells quarantined outdoors ≥ 15 m from buildings (verify) in metal containers with vermiculite/sand; off-gas/smoke detection and water-based suppression","Charging bays: CEA 2023 EV charging provisions; EVSE to IS 17017 series; Type B RCD or 6 mA DC detection; emergency stop","Fire detection in enclosed parking; no charging of visibly damaged vehicles; extinguishers and vehicle-fire plan"],steps:["Before HV work: PTW (Electrical), vehicle on insulated stand, 12 V battery disconnected, service plug removed and locked in worker's possession","Wait discharge time, verify 0 V with meter proven on live source before and after, barrier the bay with 'HV work' sign.","Work on HV components with insulated tools and gloves; one hand where possible; never work on HV alone; second HV-trained person within sight with rescue hook and AED.","Re-energising: remove tools, check insulation resistance (IMD), close service plug, verify interlock loop, log.","Cell/module handling: inspect for dents, swelling, leakage, odour; reject and quarantine suspect cells immediately; carry modules with lifting aids; cover terminals during moves.","Formation/ageing and EOL testing: fixtures with rated contactors; thermal monitoring per channel; alarm → isolate channel, remove cell to quench tank/sand if safe, evacuate area if venting.","Crashed or damaged vehicles/packs: treat as thermal-runaway risk for 48 h — isolate outdoors, thermal camera every hour, no charging, inform OEM; transport as damaged Li-ion (UN 3480/3481 special provisions — verify).","Fire response: raise alarm, isolate charger/vehicle HV if safe, evacuate, call fire service with 'lithium-ion vehicle/pack' information","Cool with large volumes of water (thousands of litres) or submerge pack; expect re-ignition — monitor 24 h; do not use Class D agents (for lithium metal only).","Charging operations: visual check of cable/connector each use; RCD test monthly; keep bays clear of combustibles; smoke detection linked to alarm; weekly thermal scan of high-use chargers.","Battery waste: Battery Waste Management Rules 2022 — hand over to registered recycler/refurbisher via producer EPR; discharged and terminals insulated; manifests kept.","Training and drills: HV authorisation renewal every 2 years (verify), Li-ion fire drill 6-monthly with fire service, first aid for electrical injury and HF burns (calcium gluconate gel available)."],ppe:["Class 0 insulating gloves with over-gloves, arc-rated face shield, insulated footwear, FR clothing, safety glasses, chemical gloves for electrolyte, FFP3/PAPR for venting or fume"],stop:["HV bus not proven dead before contact","Working alone on HV","Swollen, hot, hissing or leaking cell in production or storage","Charger RCD fails test or cable damaged","DDR cells stored inside building"],records:["HV authorisations, PTW/isolation records, discharge/verification logs, cell inspection and quarantine register, thermal monitoring logs, charger RCD tests, fire drill reports, BWMR manifests"],refs:{india:["CEA Safety Regulations 2023 (EV charging; electrical installations); AIS-156 & AIS-038 Rev 2 (EV battery safety); IS 17855 (traction battery packs), IS 16893 (Li-ion traction cells — verify), IS 17017 (EVSE)","IS 16046 / IEC 62619; Battery Waste Management Rules 2022; Factories Act via state rules / OSH Code; IS 15652 (insulating mats)"],ka:["CEIG Karnataka approval for charging installations above thresholds; KSFES; KSPCB (battery waste)"],tn:["CEIG Tamil Nadu; TNFRS; TNPCB; TN EV Policy 2023 charging safety conditions (verify)"],osha:["1910.333–335, 1910.147; NFPA 70E (DC arc-flash tables), NFPA 70 Art. 625 (EV charging); NFPA 855 (ESS as benchmark); UL 9540A; SAE J2990 (hybrid/EV first and second responder); 1910.178(g) (charging areas)"],intl:["ISO 6469-1/-3 (EV electrical safety), ECE R100 (Class B voltage 60–1,500 V DC), UN 38.3 & UN Model Regulations SP 376/377; IEC 62660, IEC 62485; DGUV Information 200-005 (HV qualification — verify); UK HSE EV guidance"]},checklist:"cl4-ev-battery"},
{id:"p3-test-track",t:"Vehicle Test Tracks, Proving Grounds & Dynamometer Testing",cat:"Management",tags:["Automotive","Transport","Management"],purpose:"Prevent collisions, rollovers, run-off and struck-by incidents during vehicle development and end-of-line testing on tracks, high-speed ovals, off-road courses and chassis dynamometers.",scope:"OEM and component test tracks, end-of-line test strips and roller brake testers, ARAI/NATRAX-type proving grounds, durability and brake testing, autonomous/ADAS testing, chassis and engine dynamometer cells, test vehicles with prototype systems.",roles:["Track controller (radio dispatch, single point of control)","Test drivers (licensed, medically fit, track-certified by level)","Test engineers / ride-along observers","Track maintenance & recovery crew","Safety officer; medical/ambulance provider"],hazards:["Loss of control at speed (prototype brakes/tyres), rollover in handling/stability tests, run-off into barriers; collision with slower vehicles, pedestrians or maintenance crews on track","Multiple vehicles on one circuit without separation; wrong-way entry; poor visibility (rain, fog, night, dust); animals on perimeter","Dynamometer cells: vehicle restraint failure, rotating rollers, exhaust CO, hot brakes/tyres bursting, fuel leaks on hot exhaust; EV HV systems","Fatigue on long durability shifts; heat in cabins without AC; fire in prototype vehicles (fuel, HV battery)"],pre:["Track rules booklet: speed limits per zone, direction, entry/exit protocol, radio procedure, right-of-way, maximum vehicles per circuit, weather limits (wet grip, visibility < 200 m — verify)","Displayed and signed by every driver","Driver certification tiers (e.g. up to 80 km/h; high-speed; handling/limit testing) with practical assessment, medical fitness, annual re-check; zero alcohol; mobile phones off while driving","Vehicles: pre-run check (tyres, brakes, fluid leaks, HV status), roll cage/5-point harness and helmet for limit-handling and rollover-risk tests; fire extinguisher; prototype systems' kill switches","Track infrastructure: run-off areas and barriers (tyre walls/guardrail), marshal posts or CCTV, radio coverage, lighting","Drainage, fencing against animals and intruders, separate access for maintenance vehicles with flashing beacons","Emergency: ambulance or trained paramedic on site during high-speed/limit tests, hospital tie-up, recovery vehicle, fire response for fuel and HV fires, HV rescue hooks; incident reporting to MV Act/OSH Code as applicable"],steps:["Daily track inspection by controller: surface debris, oil, water, barriers, signage, radio check; track status board set (open/closed/wet).","Driver and vehicle sign-in with controller; test plan declared (speed band, manoeuvres, zone); controller allocates slot and confirms maximum vehicles on circuit.","Entry/exit only at designated points on controller's clearance; acceleration lanes used; indicate and look before merging; no stopping on racing line — pull to shoulder and radio.","During test: driver keeps radio on and reports faults or anomalies; observers belted; no passengers during limit-handling or brake-fade tests unless role-essential and protected.","Limit-handling, J-turn, rollover-propensity and ADAS tests on dedicated dynamic pad with outriggers/safety vehicles; exclusion zone; no other traffic.","Maintenance or pedestrians on track only after controller closes the zone, barriers/cones placed, hi-vis and radios carried; vehicles re-admitted only when crew confirms clear.","Weather: suspend high-speed runs in heavy rain, standing water, fog, lightning or dust storms; night tests only with lighting and reflective markers.","Dynamometer cells: vehicle restrained per OEM (chains/straps rated), wheel chocks on non-driven axle, exhaust extraction connected, CO monitor, cooling fan, no one in cell during test, e-stop at console","HV vehicles with IMD monitoring.","Incident: controller stops all traffic (red flag/radio), dispatches rescue, isolates HV if EV, preserves scene, notifies as per statutory requirements; restart only after investigation clearance.","Fatigue: driving blocks ≤ 2 h with breaks on durability runs (verify against site policy), hydration, shift limits; audit driver hours."],ppe:["Helmet (ECE/FIA rated) and harness for high-speed/limit tests, hi-vis vest for anyone on foot, fire-retardant suit for fuel-system or HV prototype tests, safety shoes, hearing protection in dyno cells"],stop:["Controller or radio not available","Driver not certified for the test tier or unfit","Vehicle fault affecting brakes, steering, tyres or HV isolation","Pedestrians or maintenance on track without zone closure","Weather or visibility below limits"],records:["Driver certifications and medicals, daily track inspection, vehicle pre-run checks, test plans and track logs, incident reports, maintenance records, emergency drills"],refs:{india:["Motor Vehicles Act 1988 & CMV Rules 1989 (Rule 126 test agencies — ARAI, ICAT, NATRAX, GARC; registration/trade certificates for test vehicles); OSH Code s.6 (duty of care","Non-factory premises as establishment); Factories Act via state rules where track is within factory; CEA 2023 (EV HV); AIS standards for testing"],ka:["Karnataka Factories Rules 1969 (where within licensed premises); RTO Karnataka trade certificates"],tn:["TN Factories Rules 1950; RTO TN; GARC/Oragadam & Sriperumbudur OEM test tracks local emergency tie-ups"],osha:["General Duty Clause; 1910.178 (industrial trucks), 1910.147 (dyno maintenance), 1910.1000 (CO); NFPA 30A (motor fuel), SAE J2990"],intl:["ISO 3888 (lane change), ISO 4138 (steady-state circular), ISO 17387 (ADAS test methods)","FIA/FIM circuit safety guidance (barriers, run-off) as benchmark; UK HSE guidance on proving grounds (MIRA); ISO 39001 (road traffic safety management)"]},checklist:"cl4-test-track"},
{id:"p3-ammonia-ref",t:"Ammonia Refrigeration Plants – Machinery Rooms, Oil Draining & Leak Response",cat:"Chemical",tags:["Chemical","Food","Process Safety","Industrial"],purpose:"Prevent ammonia releases, cold burns, asphyxiation and fire/explosion in refrigeration plants of dairies, cold stores, breweries, meat and seafood processors and ice plants.",scope:"Machinery rooms (compressors, receivers, oil pots), condensers, evaporators in cold rooms and freezers, pump recirculation, hot-gas defrost, charging and oil draining, maintenance, decommissioning; 50 kg to several tonnes of NH3.",roles:["Refrigeration plant in-charge (certified operator)","Operators trained in oil draining and leak response (minimum two per shift)","Maintenance contractor (IIAR 6 inspections)","ERT with SCBA and ammonia suits","Occupational physician"],hazards:["NH3: TLV 25 ppm, STEL 35 ppm, IDLH 300 ppm; flammable 15–28% v/v in confined machinery rooms; dense cold cloud on release; corrosive to eyes/lungs; frostbite from liquid (−33 °C)","Oil draining: liquid ammonia blow-out when valve left open or trapped liquid; hydraulic shock in hot-gas defrost; over-pressure from trapped liquid between closed valves","Machinery-room asphyxia/panic; single exit; corrosion under insulation causing pipe failure; relief valves vented inside; forklift strikes on evaporator pipes in cold rooms","Charging/decanting from cylinders or tankers; hose failure; contaminated oil; fire in compressor room oils"],pre:["Design per IS 660 / IS 4544 / IIAR 2 and EN 378 benchmark: machinery room with two exits (doors outward, panic bars), emergency ventilation, NH3 detection (alarm 25 ppm","Emergency ventilation and shutdown at 150–200 ppm — verify per IIAR 2), emergency stop outside door, eyewash/shower at exit, lighting Ex where required","Relief valves vented outdoors to safe height, replaced every 5 years (IIAR 6 benchmark)","Pressure vessels (receivers) registered and tested under state Factories Rules / SMPV(U) Rules 2016 where applicable; pipe labelling (IIAR Bulletin 114 style: physical state, pressure, direction)","Oil-draining: self-closing (dead-man) oil drain valves, two persons, written procedure, PPE; oil pots isolated and pumped down; never leave an open ammonia drain","Emergency: SCBA (≥ 2 sets) and Type B gas suits stored outside machinery room, escape respirators for all in NH3 areas","Wind sock, assembly points upwind/crosswind, water fog for vapour knock-down (not on liquid pool), hospital tie-up","MSIHC thresholds checked (site notification/on-site plan if exceeded — verify quantity)","Evaporators in cold rooms protected by bollards; NH3 detectors in rooms with evaporators; cold-room procedures (see cold-room entry)"],steps:["Shift round: compressor oil levels and pressures, receiver level, detector readings, ventilation, PRV discharge lines","Pipe insulation (wet/stained = inspect for corrosion), unusual smell (NH3 odour threshold 5–50 ppm — any smell is a leak).","Oil draining: two trained persons, full-face respirator with K filter and gloves, dead-man valve, pot isolated and warmed, drain slowly into closed container, close and verify; never leave a drain open.","Pump-down and isolation for maintenance: evacuate section to flare/absorption, confirm pressure ≤ 0 bar g, never trap liquid between closed valves without relief; LOTO; hot work only after nitrogen purge and NH3 < 25 ppm.","Hot-gas defrost: follow OEM sequence to avoid hydraulic shock; investigate any banging in lines.","Charging: tanker/cylinder earthed, hose rated and within test date, excess-flow protection, operator in full PPE, second person at emergency stop; stop at design charge.","Minor leak (< 25 ppm alarm): approach upwind with SCBA, isolate at source, ventilate, repair under PTW; log and investigate root cause.","Major leak: toxic-gas alarm, evacuate crosswind/upwind, headcount, shelter-in-place for non-ERT; ERT in SCBA/gas suits isolates compressors and king valve","Water fog to knock down vapour; call fire service, inform District authorities if off-site impact; MSIHC 48-h report and dangerous-occurrence notice (12 h).","First aid: flush eyes/skin with water 15–20 min; remove contaminated clothing; frostbite — warm slowly; inhalation — fresh air, oxygen, hospital.","Integrity programme: IIAR 6 benchmark — annual inspection of vessels, piping, valves, relief, insulation; 5-yearly thickness survey; replace PRVs; test detectors quarterly; calibrate yearly.","Training: operators certified (refrigeration trade); annual refresher and leak drill; records; review after any leak."],ppe:["Escape respirator for all in NH3 areas; full-face respirator with K filter for routine; SCBA and Type B gas suit for ERT; chemical goggles, cold-insulating and chemical gloves, face shield for oil draining"],stop:["Detector alarm active or smell of ammonia without known source","Only one trained person available for oil draining or charging","Machinery-room ventilation or detector out of service","SCBA/suits missing or out of test","PRV vent line blocked or vented indoors"],records:["Charge inventory, operator certificates, shift logs, oil-draining log, detector tests, PRV register, vessel test certificates, maintenance/inspection reports (IIAR 6), leak and drill reports, MSIHC documents where applicable"],refs:{india:["IS 660 (safety code for mechanical refrigeration), IS 4544 (code of safety for ammonia); Factories Act s.31 pressure plant & s.41B–H hazardous processes via state rules / OSH Code Ch. XII","SMPV(U) Rules 2016 (receivers > 1,000 L — verify); Gas Cylinders Rules 2016; MSIHC Rules (ammonia thresholds — verify); Sch. II PEL 25 ppm; IS 10592 (showers/eyewash)"],ka:["Karnataka Factories Rules 1969 (pressure plant rule; verify number); MAH Control (Karnataka) Rules 1994 if threshold exceeded; KSFES"],tn:["TN Factories Rules 1950 Rule 61 pressure plant (verify); TN CIMAH Rules 1994; DISH TN; TNFRS"],osha:["1910.111 (anhydrous ammonia), 1910.119 PSM (≥ 10,000 lb / 4,536 kg), 1910.134, 1910.146; IIAR 2, 6, 7, 8, 9; ANSI/ASHRAE 15; NFPA 1 Ch. 53"],intl:["EN 378-1 to -4 (refrigeration safety); ISO 5149; UK IOR Ammonia Refrigeration Safety Guide; EIGA; EU Seveso III (ammonia thresholds)"]},checklist:"cl4-ammonia-ref"},
{id:"p3-cip",t:"CIP Systems & Food-Plant Chemicals (Caustic, Acid, Peracetic, Hypochlorite)",cat:"Chemical",tags:["Chemical","Food","Industrial"],purpose:"Prevent chemical burns, toxic gas generation, scalds and entrapment during clean-in-place, manual cleaning and sanitiser handling in food, beverage, dairy and brewery plants.",scope:"CIP sets (caustic 1–3% at 70–85 °C, nitric/phosphoric acid 0.5–1.5%, peracetic acid 0.1–0.3%, hypochlorite), bulk and IBC chemical storage, dosing systems, manual foam cleaning, bottle washers, membrane cleaning, chemical deliveries.",roles:["Hygiene/CIP manager","CIP operators and sanitation crew (contract and own)","Chemical supplier (SDS, couplings, training)","Maintenance (valves, interlocks, dosing)","First aiders trained for chemical burns"],hazards:["Concentrated NaOH 30–50% and nitric acid 55–60%: severe burns, blindness; exothermic dilution; hot CIP solutions 80 °C scald","Mixing errors: acid + hypochlorite → chlorine gas; peracetic acid (strong oxidiser, organic peroxide UN 3109, pungent vapour, STEL 0.4 ppm) decomposes with heat/contamination; hypochlorite + ammonia → chloramines","Cross-connection: CIP solution routed to a tank or line a person is inside or that holds product; opening a manway/clamp on a line under CIP pressure","Slips on wet floors, foam; manual handling of 25–35 kg jerry cans; splashes while dipping sample cups; inadequate eyewash response"],pre:["Chemical inventory with SDS (IS 17859/GHS), segregation (acids away from caustic and hypochlorite","PAA in its own cool, vented store), bunding 110%, vented IBCs, labelled lines and valves; delivery couplings unique per chemical (different sizes/colours) to prevent wrong-tank filling","CIP sets with automated dosing, concentration and temperature control, interlocks: mix-proof valves or physical breaks between CIP and product routes","Tanks under CIP have 'CIP in progress' lock-out on manways; conductivity return verified","Emergency showers/eyewash within 10 s travel (ANSI Z358.1 / IS 10592) tested weekly, tempered water; spill kits with neutraliser; chlorine gas awareness in sanitation areas","PPE standard per task: chemical goggles + face shield, nitrile/neoprene gloves (gauntlet), chemical apron, boots; respirators for PAA/hypochlorite fogging","Training in local language with pictograms; written cleaning cards (chemical, concentration, temperature, time, PPE, never-mix list); contractors inducted to same standard"],steps:["Deliveries: driver and operator confirm chemical, tank, coupling and level; bund drains closed; PPE worn; stand by throughout; sample and seal.","Making up solutions: add concentrate to water, never water to concentrate; use dosing pumps; no decanting by hand from 200 L drums without pump; label every container.","Before starting CIP: confirm route, tank empty of people (visual plus sign-off), manways locked, hoses connected to correct ports, drains free; start sequence and verify return temperature/conductivity.","During CIP: no opening of clamps, sight glasses or manways; treat all lines as hot and chemical-filled; investigate leaks only after stopping and draining.","Manual foam cleaning: apply at low pressure away from electrical panels; one chemical at a time with rinse between acid and chlorine products; ventilate rooms; keep others out.","PAA/hypochlorite sanitising: measure concentration; ventilate; avoid heat and contamination; store PAA away from caustic, metals and organics; never return unused PAA to drum.","Entering tanks after CIP: confined-space permit, rinse verified, isolate CIP supply with blinds/locks, gas test (chlorine, O2), cool below 40 °C.","Spills: evacuate, PPE, contain, neutralise (dilute acid for caustic; soda ash for acid), dispose via ETP within consent limits; report.","First aid: flush with water ≥ 20 min, remove clothing, eyes held open under eyewash, go to hospital for alkali eye splashes; keep SDS for doctor.","Audit monthly: showers, bunds, labels, couplings, PPE condition, concentration logs; review near misses (wrong-coupling, splash) and update cleaning cards."],ppe:["Chemical goggles and face shield, gauntlet nitrile/neoprene gloves, chemical apron or suit, safety gumboots, respirator (ABEK/P3) for PAA or chlorine fogging"],stop:["Person inside tank or line not positively confirmed empty before CIP","Delivery coupling does not match tank or label missing","Shower/eyewash not working within 10 s travel","Mixing acid and chlorine products in same area/sequence","Opening equipment under CIP pressure or temperature"],records:["Chemical inventory and SDS, delivery and dosing logs, CIP cycle records (conc./temp.), shower/eyewash tests, PPE issue, training (language), spill and first-aid log, ETP discharge records"],refs:{india:["Factories Act s.41B/41C (hazardous substances information), s.36/36A via state rules / OSH Code s.6, s.11; MSIHC Rule 17 SDS","IS 17859 (GHS/SDS), IS 10592 (showers/eyewash), IS 4209 (chemical plant safety); FSSAI Schedule 4 (cleaning chemical control); Water Act consent for effluent; HOWM Rules"],ka:["Karnataka Factories Rules 1969 (first aid, washing facilities; dangerous operations schedule for chlorine/acids where applicable); KSPCB"],tn:["TN Factories Rules 1950 (Rule 95 schedules; washing facilities Rule 42 — verify); TNPCB"],osha:["1910.1200 HazCom, 1910.151(c) eyewash, 1910.132–138 PPE, 1910.146, 1910.1000 (chlorine ceiling 1 ppm); ANSI/ISEA Z358.1"],intl:["EHEDG hygienic design & CIP guidance; UK HSE Food Information Sheets (chemical burns, CIP); COSHH; EN ISO 374 (chemical gloves); EN 166 (eye protection)"]},checklist:"cl4-cip"},
{id:"p3-silo",t:"Silos, Hoppers & Bulk Bins – Engulfment Prevention, Entry & Dust Explosion",cat:"Industrial",tags:["Industrial","Food","Agri","Process Safety"],purpose:"Prevent engulfment, asphyxiation, falls and dust explosions in silos, flat stores, hoppers and bins holding grain, flour, sugar, feed, cement, fly ash and other bulk solids.",scope:"Steel and concrete silos, hopper-bottom bins, flat storage with sweep augers, feed bins, cement/fly-ash silos, bucket elevators and conveyors feeding them; clearing of bridged or caked material; cleaning and inspection entries.",roles:["Plant manager (entry authorisation)","Entry supervisor, attendant and entrants (confined-space trained)","Maintenance (isolation of feed/discharge)","Rescue team with retrieval equipment","Fumigation contractor where used"],hazards:["Engulfment: flowing grain buries a person knee-deep in 4–5 s and fully in 20–30 s; bridged crust collapses; vertical wall avalanche; > 300 kg force needed to pull a buried person — recovery becomes a body recovery","Atmosphere: O2 depletion and CO2 from grain respiration/spoilage, CO from smouldering, phosphine from fumigation, dust > PEL; heat","Dust explosion in bucket elevators, dust collectors and silo headspace (flour/sugar/starch St 1; MIE 10–30 mJ); ignition from bearings, belt slip, static, hot work","Falls from silo roofs and internal ladders; moving augers/sweeps; roof collapse from vacuum/over-pressure; bin structural failure from off-centre discharge"],pre:["Zero-entry policy: design out entry with external poles, air cannons, vibrators, bin whips and cameras; entry only when no alternative and under permit","Permit-required confined-space programme: isolation and LOTO of all feed and discharge equipment (augers, sweeps, pneumatic lines, elevators)","Bridging/caking assessment, atmosphere testing (O2 19.5–23.5%, CO < 25 ppm, LEL < 10%, dust, PH3 < 0.3 ppm), continuous ventilation","Entrant on full-body harness with lifeline attached to a rated anchor and mechanical retrieval (winch/tripod) controlled by attendant; never attached to equipment; second lifeline where sweep auger present","Dust explosion controls: Dust Hazard Analysis (NFPA 652/61), explosion vents on elevators and collectors, bearing-temperature and belt-alignment switches","Magnets before mills, Ex-rated electricals in Zone 20/21/22, housekeeping limit, hot-work permit system","Roof access: fixed ladders with cages/fall-arrest rail, guardrails or anchor points at roof hatches, no walking on grain surface; weather limits; signage 'Engulfment hazard — no entry without permit'"],steps:["Try every non-entry method first: run discharge, use poles/air lances from outside hatch with harness tied off, use bin whip; schedule entry only if these fail.","Pre-entry: LOTO all equipment that moves material (verify by attempted start), check for bridging or wall build-up with camera/light from hatch; if material is caked above entrant's level — no entry; plan removal from above.","Test atmosphere from outside at several depths; ventilate; continue monitoring during entry; check fumigation records and PH3 reading before any entry to a treated bin.","Entrant in harness with lifeline on retrieval device; attendant in constant contact; no entry below the level of hanging material; never walk on grain to break crusts; use platform/boards from above where possible.","Work from the top down when clearing walls; keep lifeline taut; stop and exit if material starts to flow or shift.","Rescue plan: on-site team can reach and begin retrieval within minutes; grain rescue tube/cofferdam and vacuum where available; never jump in after a victim; call fire service with silo details.","Elevator/conveyor operation: respond to bearing and belt alarms; keep covers closed; clean dust layers daily; no compressed-air blow-down near ignition sources.","Hot work on silos, elevators or ducts: shut down and empty, clean to bare metal around the work, wet or inert, gas/dust test, fire watch 60 min; permit.","Inspection: annual structural inspection of silo walls, roofs, hoppers and anchors; explosion vents and sensors tested; records.","Training and drills: engulfment awareness for all, entry team competence yearly, rescue drill yearly with local fire service."],ppe:["Full-body harness with retrieval lifeline, FFP3 dust respirator (or SCBA/airline where atmosphere not proven), goggles, helmet with chin strap, gloves, antistatic clothing, personal 4-gas monitor"],stop:["Feed/discharge not isolated and locked","Entrant without lifeline on retrieval device or attendant absent","Material bridged or caked above entrant level","Atmosphere outside limits or fumigant present","Hot work without emptying, cleaning and permit"],records:["Confined-space entry permits, isolation/LOTO records, gas-test logs, rescue plan and drill records, DHA and explosion-protection maintenance, bearing/belt alarm logs, structural inspections, fumigation records"],refs:{india:["Factories Act s.36, s.37 (confined spaces; explosive dust) via state rules / OSH Code s.6; IS 17893 (permit system); IS/IEC 60079-10-2","Dust-codes (NFPA 652/61 as benchmark); FCI/CWC storage guidelines for bag/bulk stacks; Insecticides Act 1968 (fumigation operators)"],ka:["Karnataka Factories Rules 1969 (confined space rule — verify number); KSFES"],tn:["TN Factories Rules 1950 (confined space Rule 61A — verify); DISH TN"],osha:["1910.272 (grain handling — engulfment, entry, housekeeping), 1910.146, 1910.147; NFPA 61 (agricultural & food dusts), NFPA 652, 68, 69; OSHA Grain Handling SLTC"],intl:["UK HSE Agriculture Information Sheets (grain stores, silos) & INDG258 (confined spaces); ATEX 1999/92/EC; EN 14491 (dust explosion venting); Purdue University grain-entrapment research (rescue tubes, cofferdams)"]},checklist:"cl4-silo"},
{id:"p3-bakery",t:"Bakery & Hot-Process Food Lines – Gas Ovens, Fryers, Mixers & Hot Surfaces",cat:"Industrial",tags:["Industrial","Food","Fire","Health"],purpose:"Prevent burns, gas explosions, fires, entanglement and flour-dust asthma in bakeries, biscuit and snack plants, confectionery and frying lines.",scope:"Deck, rack and tunnel ovens (LPG/PNG/electric), proofers, fryers (hot oil 170–190 °C), kettles and jacketed pans, spiral and planetary mixers, dividers, moulders, slicers, depositors, flour silos and sifters, cooling conveyors, packaging.",roles:["Production manager","Oven and fryer operators","Gas fitter / burner service (licensed)","Maintenance (interlocks, LOTO)","Safety officer; occupational physician (asthma surveillance)"],hazards:["Gas: leaks and explosion on light-off without purge; flame failure; CO from poor combustion; LPG cylinder/bulk and PNG supply faults","Burns from oven surfaces > 200 °C, trays, steam injection, hot oil splash and fryer fires (Class F); scalds from kettles; thermal-fluid leaks","Entanglement in mixers (bowl/agitator), dividers, moulders, slicer blades, depositors; hands in conveyors; manual cleaning of running machines","Flour dust: baker's asthma (flour dust TLV 0.5 mg/m³ inhalable, ACGIH), explosion in silos/sifters; heat stress near ovens; slips on flour/oil; night shifts and fatigue"],pre:["Gas installation to IS 6044 (LPG) / PNGRB T4S (PNG): isolation valve at entry, double block-and-bleed and pressure switches on burners","Flame-failure devices, pre-purge ≥ 4 volume changes (NFPA 86 benchmark), gas detectors with auto shut-off in oven rooms and cylinder stores, CO detection","Fryers: high-temperature limit cut-out independent of thermostat, lid or fixed suppression (wet-chemical/Class F), oil-level interlocks, no water near fryer; kitchen-style exhaust hoods cleaned per schedule (grease fire)","Mixers and machines: interlocked bowl guards and covers (no run with guard open), e-stops, LOTO for cleaning; slicers with blade guards and push sticks; young persons excluded from dangerous machines","Flour dust: enclosed transfer, LEV at tipping/sifting, vacuum cleaning, no compressed air; silo/sifter dust-explosion controls; health surveillance questionnaire and lung function yearly for flour-exposed staff","Heat: oven-room ventilation, WBGT monitoring, water and rest breaks; burns first aid (cool running water 20 min, cling film, burn dressings) in every area"],steps:["Oven start-up: verify gas pressure, purge complete, ignition by sequence; never light manually with a flame; stop and ventilate on any gas smell; report flame-failure trips.","Loading/unloading ovens: heat-resistant gauntlets and sleeves, trolleys locked, clear path; steam-injection ovens opened from the side after venting.","Fryers: heat slowly, keep oil below max line, no wet product/ice into oil, skim from the side; fire — cover/suppression, isolate heat, never use water; cool below 50 °C before draining/cleaning.","Mixers and dividers: stop and isolate before scraping, adding by hand or clearing jams; test interlocks at start of shift; keep hair covered and no loose sleeves.","Slicers/cutters: blade guard in place, push stick, cut-resistant gloves for blade changes under LOTO.","Flour handling: tip under LEV, minimise dust clouds, wet-wipe or vacuum surfaces; sifters sealed; check silo controls; report chest tightness or rhinitis to OHC.","Cleaning: machines isolated and locked; hot-surface warning; non-slip footwear; chemicals per cleaning cards (see CIP/chemical procedure).","Gas cylinders/bulk: stored outdoors, upright, segregated; changeover by trained person with leak test; regulators and hoses within date.","Night/early shifts: minimum two persons; fatigue management; welfare; women's night-work conditions per state rules.","Maintenance: annual burner and safety-device service by licensed gas fitter; thermal-fluid systems inspected; exhaust duct cleaning records."],ppe:["Heat-resistant gauntlets and sleeves, face shield at fryers, FFP2 for flour tipping, non-slip safety shoes, hairnet, cut-resistant gloves for blade work, apron"],stop:["Gas smell or detector alarm","Flame-failure or purge bypassed","Interlocked guard open with machine running","Fryer high-limit or suppression not functional","Flour LEV not running during tipping"],records:["Gas installation certificates and annual service, detector tests, oven/fryer safety-device checks, interlock tests, LEV checks, health surveillance (asthma), burn/first-aid log, cleaning and LOTO records"],refs:{india:["Factories Act ss.21–23 (fencing, young persons), s.14 (dust), s.13 (temperature), s.38 (fire) via state rules / OSH Code","Gas Cylinders Rules 2016 & IS 6044 Pt 1–2 (LPG installations); PNGRB T4S (PNG); IS 9474 (guarding); FSSAI Schedule 4; IS 2190 (extinguishers, Class F); Sch. II dust limits"],ka:["Karnataka Factories Rules 1969; KSFES fire NOC for bakeries using LPG above exemption; KSPCB"],tn:["TN Factories Rules 1950 (Rule 53 schedules for food machinery — verify); TNFRS; Catering Establishments Act for retail bakeries"],osha:["1910.212, 1910.147, 1910.263 (bakery equipment), 1910.94, 1910.1000; NFPA 86 (ovens), NFPA 96 (commercial cooking exhaust), NFPA 10 (Class K); ANSI Z50.1"],intl:["UK HSE bakery guidance (flour dust, ovens, mixers); EN 453 (dough mixers), EN 1674 (dough moulders), EN 12042 (dividers), EN 1673 (rack ovens); COSHH flour dust WEL 10 mg/m³"]},checklist:"cl4-bakery"},
{id:"p3-bottling",t:"Bottling & Packaging Lines – Conveyors, Fillers, Glass & CO2",cat:"Industrial",tags:["Industrial","Food","Machinery","Health"],purpose:"Prevent entanglement, crush, cuts from glass, CO2 asphyxiation, caustic burns, noise damage and slips on high-speed bottling, canning and packaging lines.",scope:"Depalletisers, rinsers, fillers/cappers, pasteurisers, labellers, case packers, palletisers and stretch wrappers; conveyor systems; bottle washers (returnable glass); carbonation and CO2 storage; PET blow moulders; CIP of fillers.",roles:["Line manager","Operators (trained per machine, interlock-aware)","Maintenance and changeover technicians","CO2 system operator","Safety officer"],hazards:["Conveyor nip points, star wheels, infeed screws, transfer plates, palletiser hoists and cells; reaching in to clear jams on running lines (most common injury)","Glass: bottle bursts at filler/capper (2–4 bar carbonation), shards on conveyors, bottle-washer breakages; eye and hand lacerations","CO2: bulk tank and carbonators — leaks in enclosed rooms (TLV 5,000 ppm; STEL 30,000 ppm; IDLH 40,000 ppm), odourless; dry-ice; cold burns","Bottle washer caustic 2–3% at 60–80 °C; pasteuriser heat; noise 85–95 dB(A); slips on wet floors; manual handling of cases; PET blow-moulder hot moulds and high-pressure air (40 bar)"],pre:["Machines guarded to EN 415 benchmark: interlocked guards with guard locking where run-down > 1 s, e-stops every 10–15 m along conveyors, pull-wires, perimeter guarding on palletiser/depalletiser cells with presence sensing","Written jam-clearing procedure per machine: stop, isolate (or use inching/control-reliable hold-to-run with guards), clear with tools, restart; 'no hands in a running machine' rule","CO2: detectors with alarms at 5,000 ppm (action) and 15,000–30,000 ppm (evacuate) in carbonation rooms, cellars and tank enclosures","Ventilation; tank per SMPV(U) Rules 2016 (> 1,000 L) with PESO licence (verify); PRVs vented outdoors","Glass: polycarbonate guards at filler/capper, face shields in glass zones, cut-resistant gloves (EN 388 level C+), broken-glass procedure (stop, clear zone, brush/tongs, bin for sharps); eye-protection zones marked","Noise: hearing-conservation zones (≥ 85 dB(A)), audiometry yearly; anti-slip flooring and drainage; drip trays; chain-lube control"],steps:["Shift start: test e-stops and interlocks on each machine, check guards, CO2 detector status, floor condition, lighting; log.","Normal running: never reach over, under or through guards; remove fallen bottles with tools from outside; keep hair, lanyards and loose clothing secured.","Jam or fault: press stop, wait for run-down, open interlocked guard, clear with tool; if guard must be open with motion — only trained person using hold-to-run at reduced speed per machine procedure.","Glass breakage at filler: stop, purge affected containers (count per procedure), remove shards with tongs/brush, check conveyors downstream; never use bare hands; log breakage rate.","Palletiser/depalletiser cells: enter only via interlocked gate with key in pocket; see robot-cell procedure for hoist/stored-energy isolation.","Bottle washer: caustic handling PPE, lid interlocks, steam/hot-water isolation before entry for cleaning; confined-space permit for tanks.","CO2 handling: tanker fill by trained operator with PPE; never enter a CO2 alarm area without SCBA; dry ice only in ventilated areas; cold-protective gloves.","PET blow moulders: isolate high-pressure air and heaters; wait for mould cool-down; guard interlocks tested.","Changeovers and maintenance: LOTO at machine isolator; verify zero energy (air, electrical, gravity on palletiser hoists); test guards before handing back.","Noise and ergonomics: hearing protection in zones; rotate manual-case-handling roles; lifting aids; report MSD symptoms."],ppe:["Safety glasses (face shield in glass zones), cut-resistant gloves, hearing protection, non-slip safety shoes, hairnet, caustic PPE at washer, cold gloves for CO2/dry ice"],stop:["Interlock or e-stop defeated or failed test","Hands in running machine / jam cleared without stopping","CO2 detector alarm or detector out of service","Caustic or hot-water line not isolated before entry","Glass breakage zone not cleared before restart"],records:["Interlock/e-stop test log, jam-clearing training and authorisations, CO2 detector calibration, SMPV licence and PRV tests, glass-breakage log, noise surveys and audiometry, LOTO records, injury and near-miss log"],refs:{india:["Factories Act ss.21–23, 31, 36 via state rules / OSH Code s.6; IS 9474 & IS 16819 (guarding/machinery safety); SMPV(U) Rules 2016 (CO2 tanks)","Gas Cylinders Rules 2016; Sch. II (CO2 5,000 ppm; noise 90 dB(A)); IS 7194 (noise); FSSAI Sch. 4; IS 15298 footwear"],ka:["Karnataka Factories Rules 1969 (fencing; noise); KSFES; PESO Karnataka (CO2 SMPV)"],tn:["TN Factories Rules 1950 (Rule 53 schedules; noise); DISH TN; PESO Chennai"],osha:["1910.212, 1910.147 (minor servicing exception), 1910.95 (noise), 1910.1000 (CO2), 1910.146; ANSI/PMMI B155.1 (packaging machinery safety); NFPA 55 (CO2)"],intl:["EN 415 series (packaging machines), EN 1672-2 (food machinery hygiene & safety), ISO 13849-1, ISO 14119; UK HSE Food Information Sheets (conveyors, palletisers, CO2 in breweries); EIGA Doc 66 (CO2 refrigerated storage)"]},checklist:"cl4-bottling"},
{id:"p3-coldroom",t:"Cold Rooms, Blast Freezers & Controlled-Atmosphere Stores – Entrapment & Cold Stress",cat:"Health",tags:["Health","Food","Industrial","Transport"],purpose:"Prevent entrapment, hypothermia, asphyxiation in controlled-atmosphere stores, ammonia exposure and forklift incidents in chillers (0–5 °C), freezers (−18 to −30 °C), blast freezers (−40 °C) and CA fruit stores.",scope:"Cold stores and dark stores, blast and spiral freezers, ripening and CA rooms (O2 1–3%, CO2 up to 5%), refrigerated containers and reefer trucks, ice plants; work inside by pickers, forklift operators, hygiene and maintenance staff.",roles:["Cold store manager","Operators and pickers","Forklift operators (cold-rated)","Refrigeration maintenance","Occupational physician (cold-stress fitness)"],hazards:["Entrapment: door latch frozen, interior release missing or frozen, lights off, phone no signal; hypothermia within hours at −25 °C; blast-freezer air flow (wind chill −60 °C)","CA/ripening rooms: oxygen 1–3% kills in seconds; CO2; ethylene (flammable) in ripening rooms; nitrogen generators; entering to retrieve fruit or a fallen colleague","Cold stress: frostbite (fingers, ears), reduced dexterity, slips on ice, fogged visors; dehydration; cardiovascular strain","Forklifts in freezers: fogging, icy floors, battery capacity drop, reduced visibility in fog at doors; rack collapse with frozen loads; ammonia or CO2 evaporators in rooms; falling frozen product"],pre:["Every cold room door openable from inside at all times, even when locked from outside — luminous internal release handle, tested weekly and kept ice-free","Trapped-person alarm (battery backed, audible outside and to control room) inside; axe/emergency light; door heaters working","CA rooms: locked, placarded 'Low oxygen — do not enter'; entry only after ventilation to O2 > 19.5% confirmed by calibrated meter; two persons; O2 alarm; ethylene detection and Ex equipment in ripening rooms","Cold-stress plan: work/warm-up schedule (e.g. −25 °C: 50 min work / 10 min warm-up","Below −30 °C shorter — verify against ACGIH table), heated rest room, warm drinks, medical fitness (circulatory conditions), buddy system, no lone working inside freezers","PPE: freezer suits (EN 342), insulated gloves with liners, thermal boots (EN ISO 20345 CI), balaclava, anti-fog goggles; forklift cabs heated where possible","Forklifts: cold-rated hydraulics and batteries, lights, cameras; floor ice management; racking inspected for frozen-load damage; refrigerant (NH3/CO2) detectors in rooms with evaporators linked to alarm"],steps:["Entry: sign in on door board/headcount system, carry radio or alarm pendant, check internal release works before door closes behind you; report any frozen handle immediately.","Work inside within scheduled durations; leave at first signs of shivering, numbness or confusion; buddy checks every 20–30 min in freezers.","Forklift work: speed ≤ 5 km/h inside rooms, horn at doors, lights on; stop in fog; de-ice floors; never stack above rack SWL; report damaged racking.","Blast freezers: isolate fans before entry; interlocked door; never enter while air blast running; product on trolleys secured.","CA/ripening rooms: no entry without permit, ventilation record and O2 reading at door and inside; never enter to rescue without SCBA — raise alarm; keep room locked during storage period.","Hygiene and defrost cleaning: isolate evaporator fans, PTW for work at height, hot water/steam scald control, chemicals per cleaning cards.","Reefer containers/trucks: chock and lock before entry, door held open with stop, internal release checked, never close with person inside; genset exhaust away from doors.","Refrigerant alarm inside room: leave immediately, close door, report; re-entry only after plant operator clears.","Emergency (person missing): check headcount, search all rooms including CA with SCBA team, call ERT; frostbite — warm slowly, no rubbing; hypothermia — insulate, warm drinks if conscious, hospital.","Weekly tests: internal releases, alarms, emergency lights, door heaters, O2 meters; monthly ice/floor audit; records."],ppe:["Freezer suit (EN 342), insulated gloves with liners, thermal safety boots, balaclava/hood, anti-fog goggles, alarm pendant/radio; SCBA for CA-room rescue"],stop:["Internal door release or trapped-person alarm not working","Lone working inside freezer or CA room","CA room O2 < 19.5% at entry","Forklift without lights/cameras in foggy room or icy floor uncleared","Refrigerant detector alarm in room"],records:["Door-release and alarm test log, headcount/sign-in records, work/warm-up schedule, cold-stress fitness, O2 readings for CA entries, forklift and racking inspections, refrigerant detector tests, incident log"],refs:{india:["Factories Act s.13 (temperature), s.36 (confined space — CA rooms), s.38 via state rules / OSH Code s.6; IS 660 (mechanical refrigeration safety)","IS 4544 (ammonia); Shops & Establishments Acts for dark stores; FSSAI cold-chain guidelines; Sch. II (CO2)"],ka:["Karnataka Factories Rules 1969; Karnataka Shops & Commercial Establishments Act 1961 (dark stores); KSFES"],tn:["TN Factories Rules 1950; TN Shops & Establishments Act 1947; DISH TN"],osha:["General Duty Clause (cold stress), 1910.36–37 (exits — doors operable from inside), 1910.146 (CA rooms), 1910.178, 1910.1000; OSHA Cold Stress Guide"],intl:["ACGIH Cold Stress TLV (work/warm-up schedule); EN 342 (cold protective clothing), EN 511 (gloves), EN ISO 20345 CI","EN 378 (refrigeration safety); UK HSE 'Working in cold stores' & Food Information Sheet 3; ISO 15743 (cold workplaces)"]},checklist:"cl4-coldroom"},
{id:"p3-solvent",t:"Solvent Recovery, Flammable Solvent Storage & Dispensing",cat:"Chemical",tags:["Chemical","Pharma","Fire","Process Safety"],purpose:"Prevent fire, explosion and toxic exposure in solvent recovery (distillation), bulk and drum storage, dispensing and spent-solvent handling in API, formulation, agrochemical and speciality chemical plants.",scope:"Methanol, acetone, toluene, IPA, ethyl acetate, THF, DCM, hexane and mixed spent solvents; recovery columns and receivers; tank farms and day tanks; drum stores; dispensing booths; solvent transfer by pump, vacuum and nitrogen; waste solvent.",roles:["Plant head (PSM owner)","Solvent recovery operators","Stores/dispensing operators","Maintenance (Ex equipment, earthing)","Fire officer; safety officer"],hazards:["Class A petroleum (flash point < 23 °C): vapours heavier than air travel to ignition sources; static from splash filling, non-conductive hoses/liners, people; non-Ex lighting, phones, forklifts","Column upsets: loss of cooling → over-pressure; vacuum leaks admitting air into hot vapour; peroxide formation in THF/ether/dioxane and detonation on distillation to dryness","Toxicity: methanol (blindness), DCM (CO formation, carcinogen), hexane (neuropathy), toluene (CNS); oxygen deficiency from nitrogen in confined receivers","Drum handling: bulging drums, pressure on opening, spills, falls from racks; hot work on 'empty' drums; waste solvent mixing (incompatibles, peroxides)"],pre:["Petroleum Rules 2002 licence for Class A/B storage beyond exemption; layout and separation distances per Rules and OISD-118 benchmark","Dyke 110%; tank venting with flame arresters, nitrogen blanketing or conservation vents; day-tank quantities limited to shift needs","Hazardous-area classification (IS 5572 / IEC 60079-10-1) with drawings; Ex-rated electricals, forklifts and tools; IS/IEC 60079-17 inspections; LEL detection in recovery and storage areas (alarm 20% LEL, trip 40% — verify)","Static control per IS 7689 / NFPA 77 / IEC TS 60079-32-1: bonding and earthing of tanks, drums, pumps, hoses (conductive)","Dip-pipe or bottom filling, initial flow ≤ 1 m/s, relaxation time, conductive footwear and flooring, no plastic liners/scoops with Class A","Process: HAZOP of recovery system; interlocks on cooling water, reflux temperature, vacuum and receiver level","Relief sized for fire and runaway cases to scrubber/safe location; peroxide testing before distilling peroxide-formers (discard > 100 ppm — verify); never distil to dryness","Fire: foam (alcohol-resistant) hydrants/monitors, deluge on tank farm, CO2/DCP extinguishers at 15 m, no smoking zone 30 m, emergency isolation valves remote from tanks","Spill kits; solvent-rated ventilation in dispensing booths (face velocity ≈ 0.5 m/s)"],steps:["Receipt: check tanker earthing and bonding before hose connection; sample and verify material; unload with pump within flow limits; stand by throughout; record quantity against licence limit.","Dispensing: in booth with LEV running, drum earthed and bonded to receiving vessel, Ex pump, closed transfer; no open pouring of Class A; label containers; return drums capped.","Recovery start-up: verify cooling water, vacuum integrity, receiver earth, nitrogen purge; charge within batch limits; monitor column temperatures and pressure; respond to alarms per SOP.","Peroxide-formers: test before every distillation; never heat residues to dryness; discard dated containers; store THF/ether in dark, dated, inhibitor-checked.","Shutdown/maintenance: pump out, nitrogen purge, gas-free verification (< 10% LEL and O2 20.9% for entry), LOTO, PTW with hot-work controls; blind flanges on live solvent lines.","Hot work anywhere in solvent area: process stopped or isolated, drains covered, gas test at work location and dyke, fire watch 60 min after","No hot work on drums or tanks that held solvent without cleaning and gas-free certificate.","Spills: stop source, eliminate ignition, absorb with inert material, ventilate, dispose as hazardous waste; vapour > 20% LEL → evacuate area, call ERT.","Waste solvent: segregated by compatibility, labelled, earthed collection drums, stored ≤ 90 days (HOWM) and sent to authorised recycler/co-processing with manifest; no mixing of oxidisers, acids or peroxide-formers.","Health: solvent exposure monitoring (methanol 200 ppm, toluene 20 ppm, DCM 50 ppm ACGIH — verify), biological monitoring where used, annual medical; first aid for splashes and inhalation.","Audit quarterly: licence compliance (quantities, drawings), Ex register, earthing resistance tests, LEL detectors, foam stocks, drills; MoC for any solvent or equipment change."],ppe:["Antistatic FR coveralls (EN 1149/ISO 11612), conductive safety shoes, chemical goggles/face shield, solvent-resistant gloves (butyl/nitrile per SDS), respirator with A2 filter for dispensing, escape set in recovery plant"],stop:["Earthing/bonding not verified before transfer","Non-Ex equipment or phone in Zone 1/2","LEL > 20% or detector out of service","Peroxide test not done for THF/ether/dioxane","Hot work in solvent area without gas test and isolation"],records:["PESO licence and approved drawings, stock registers, Ex inspection register, earthing test records, LEL detector calibration, HAZOP and MoC, PTW/gas-test records, HW manifests, exposure monitoring, drill reports"],refs:{india:["Petroleum Act 1934 & Petroleum Rules 2002 (Class A/B/C; licence forms; separation); Factories Act ss.37, 41B–H via state rules / OSH Code Ch. XII; MSIHC Rules (flammable thresholds","Rule 17 SDS); IS 5572, IS/IEC 60079-14/-17; IS 7689 (static); IS 11457 Pt 1 (fire safety of chemical plants); IS 15325 (foam); HOWM Rules 2016; Sch. II PELs"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules — solvents/benzene where applicable); MAH Control (Karnataka) Rules 1994; PESO Bengaluru; KSPCB VOC conditions"],tn:["TN Factories Rules 1950 Rule 95 schedules (benzene/solvents — verify); TN CIMAH Rules 1994; PESO Chennai; TNPCB"],osha:["1910.106 (flammable liquids), 1910.119 PSM, 1910.307, 1910.1000/1910.1052 (DCM), 1910.146; NFPA 30, NFPA 77, NFPA 69, NFPA 45; API RP 2003"],intl:["IEC TS 60079-32-1 (electrostatics); ATEX 1999/92/EC & DSEAR; UK HSE HSG140 (flammable liquids), HSG51 (containers); EN 13463/ISO 80079-36 (non-electrical Ex equipment); CCPS Guidelines for Fire Protection in Chemical Plants"]},checklist:"cl4-solvent"},
{id:"p3-potent",t:"Potent Compound (OEB 4/5) Containment & Occupational Exposure Control",cat:"Health",tags:["Health","Pharma","Chemical"],purpose:"Protect workers from highly potent APIs (hormones, cytotoxics, immunosuppressants, high-potency peptides) with occupational exposure limits below 10 µg/m³, and prevent cross-contamination of products.",scope:"Dispensing, granulation, milling, compression, coating, filling and packing of OEB 4 (1–10 µg/m³) and OEB 5 (< 1 µg/m³) materials; isolators and RABS; sampling and QC labs; cleaning, maintenance, waste; gowning and de-gowning.",roles:["Site head / QA (containment policy)","Industrial hygienist (banding, monitoring)","Operators (fit-tested, medically cleared)","Maintenance (BIBO filter changes, glove-port integrity)","Occupational physician (surveillance, reproductive-health counselling)"],hazards:["Inhalation and skin absorption of dusts/aerosols at µg levels: hormonal effects, reproductive toxicity, carcinogenicity, sensitisation; effects may be irreversible and delayed","Containment breaches: torn isolator gloves, open split-butterfly valves, bag changes, spills during dispensing, dust on gowns carried to canteen; positive-pressure cleanroom pushing contaminated air into corridors","De-gowning is the highest-exposure step; respirator fit failure (beards); cross-contamination of other products (regulatory and patient risk)","Waste and effluent: cytotoxic residues in wash water, HEPA filters, cleaning cloths; maintenance on contaminated equipment without decontamination"],pre:["Occupational Exposure Banding by toxicologist; OEL/ADE set per compound; containment strategy selected from band (OEB 4: closed handling, local containment, RPE as backup; OEB 5: isolators, closed transfer, no open handling)","Engineering: isolators at −30 to −50 Pa (verify) with H14 HEPA on exhaust, glove-port integrity testing per campaign, split-butterfly valves or continuous liners for transfers, closed milling/granulation, wash-in-place","Dedicated or campaign facilities per Schedule M (beta-lactams, hormones, cytotoxics)","Containment verification by surrogate testing (ISPE SMEPAC: lactose/naproxen/mannitol) at installation and after modification; routine air and surface monitoring against OEL; results trended","Gowning: dedicated gowning/de-gowning airlocks with pressure cascade (negative to corridor for potent suites)","Disposable coveralls (Type 5/6), double gloves, PAPR (APF 1,000 — verify) or supplied-air hoods for OEB 5 interventions","Fit testing yearly; no beards with tight-fitting masks","Medical: pre-placement and periodic surveillance; women of child-bearing age and pregnant workers counselled/relocated for hormone and cytotoxic exposure per policy; exposure records retained 30–40 years"],steps:["Before entering suite: check pressure differentials, isolator alarms, glove inspection log; gown per pictorial SOP; buddy check of PAPR flow and seals.","Dispensing/charging: through isolator or split-butterfly valve only; liners and bags tied and cut inside containment; no open scoops; vacuum any visible dust immediately with HEPA vacuum.","Interventions (jams, sampling): plan with supervisor, use glove ports/half-suits; if containment must be opened — PAPR/supplied air, local extraction, minimum persons, decontaminate before closing.","Glove-port breach: stop, withdraw hand slowly, change outer glove, replace port glove per SOP, record as containment incident; monitor exposure.","Cleaning: wet methods only (no dry sweeping/compressed air); cleaning agents validated to deactivate compound where possible; cloths and PPE bagged as hazardous waste inside suite.","De-gowning: slowest step — remove outer gloves and coverall rolling inside-out in airlock, respirator last, shower where OEB 5; dispose into sealed bins; wash hands and face.","Maintenance: equipment decontaminated and swab-verified before release; BIBO (bag-in/bag-out) HEPA changes by trained team in PAPR; filters double-bagged for incineration.","Waste and effluent: segregated potent waste to incinerator (HOWM/BMW rules as applicable); wash water to dedicated treatment/detoxification before ETP; no release untreated.","Monitoring: personal air sampling per campaign; surface wipes on exit side of airlocks and canteen door handles as spread indicators; investigate any result > 10% of OEL (verify trigger).","Review: containment incidents, monitoring trends, medical findings and SMEPAC results reviewed quarterly; re-test after any change (MoC)."],ppe:["Disposable Type 5/6 coveralls, double nitrile gloves taped, PAPR with P3/HEPA or supplied-air hood, goggles (if not hooded), dedicated footwear/overshoes; never reuse disposable PPE"],stop:["Isolator pressure or HEPA alarm active","Glove-port or liner breach not managed per SOP","Open handling of OEB 5 material","PAPR not fit-tested/flow-checked for the user","Pressure cascade reversed (suite positive to corridor)"],records:["OEB/OEL assessments, containment verification (SMEPAC) reports, air and surface monitoring, glove integrity logs, fit-test records, medical surveillance (long retention), containment incident log, waste manifests, MoC"],refs:{india:["Drugs & Cosmetics Rules Schedule M (revised 2023/24 — dedicated facilities, HVAC, containment); Factories Act ss.41B–H, s.87 via state rules / OSH Code Ch. XII","MSIHC Rule 17; IS 17859 (GHS); HOWM Rules 2016 & BMW Rules 2016 (cytotoxic waste); Third Schedule notifiable diseases; Sch. II PELs (where listed)"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules; medical examination); DFBISH; KSPCB (incinerator/ETP consent)"],tn:["TN Factories Rules 1950 (Rule 95 schedules; medical examination Form 27 — verify); DISH TN; TNPCB"],osha:["1910.1000, 1910.1200, 1910.134 (fit testing, APF table), 1910.1020 (exposure records 30 yr); NIOSH List of Hazardous Drugs; USP <800> (hazardous drugs handling) as benchmark"],intl:["ISPE Good Practice Guide: Assessing Particulate Containment Performance (SMEPAC); ISPE Baseline Guide Vol. 7 (Risk-MaPP)","EU GMP Annex 1 & Ch. 3/5 (dedicated facilities); EN 149/EN 12942 (RPE); UK HSE COSHH & EH40; SafeBridge/ISPE OEB schemes"]},checklist:"cl4-potent"},
{id:"p3-cleanroom",t:"Clean Rooms & Pharma HVAC – AHU Work, HEPA Changes, Fumigation & Gas Suppression",cat:"Industrial",tags:["Industrial","Pharma","Electronics","Health"],purpose:"Prevent injuries and exposures in clean-room suites and their HVAC/utility systems: falls from AHU platforms, entrapment by interlocked doors, fumigant/decontaminant exposure, gaseous fire-suppression discharge, UV and nitrogen hazards.",scope:"Grade A–D pharma cleanrooms and ISO 5–8 electronics cleanrooms; AHUs, HEPA/ULPA filters, ducts, plenums and interstitial spaces; VHP/formaldehyde fumigation; clean-agent and CO2 suppression rooms; laminar airflow units, isolators, autoclaves, depyrogenation tunnels, lyophilisers.",roles:["Engineering head (HVAC)","HVAC technicians and validation team","Production/QA (room release)","Fumigation operators (trained)","Fire officer (suppression isolation); safety officer"],hazards:["AHU work: fan start-up during filter change, belt/pulley nip points, electric heaters, falls from AHU roofs and service platforms, ladders in plant rooms, noise","Interlocked airlocks trapping persons during fire/evacuation if fail-locked; disorientation in smoke in windowless rooms; gaseous suppression (CO2 lethal; inert gas/Novec oxygen reduction) discharging with people inside","Fumigation: VHP (H2O2 35% liquid corrosive; vapour TLV 1 ppm), formaldehyde (IARC Group 1; TLV 0.1 ppm) — leaks to adjacent rooms, re-entry before aeration; sporicides (PAA/hypochlorite)","Hot/cold utilities: autoclave steam, depyrogenation tunnels 300 °C, lyophiliser nitrogen/vacuum, LN2","UV-C lamps in LAF/pass-boxes (eye and skin burns); slips on polished epoxy floors; gowning heat stress; IPA 70% bulk (flammable)"],pre:["HVAC work under PTW: AHU isolated (LOTO) at starter plus local isolator; fans proved stopped","Duct dampers closed/locked where others feed the system; filter changes with FFP3/PAPR and bagging (BIBO for potent or biological areas)","Platforms, guardrails and fixed access for AHUs and rooftop units; fall-arrest anchors where guardrails impossible; ladders secured; lighting in plant rooms; permit for roof work","Door interlocks fail-safe: fire alarm or power loss releases interlocks for egress; manual override at every door; emergency exit signage visible in cleanroom; evacuation drill includes gowned staff (no de-gowning in a fire)","Gaseous suppression: pre-discharge alarm and time delay (≥ 30 s), abort switch, manual isolation (lock-off) before anyone enters protected enclosure for maintenance","CO2 systems in occupiable rooms replaced or strictly interlocked (NFPA 12); O2 monitoring where inert gas stored","Fumigation: written plan, room sealed and placarded, adjacent-area checks, HVAC isolation/recirculation set","Continuous monitoring with calibrated sensors, re-entry only after aeration to < 1 ppm H2O2 or < 0.1 ppm HCHO (verify), trained operators in PPE","Formaldehyde phased out where possible"],steps:["Daily: check pressure differentials, alarms, door-interlock override function, suppression panel status (no unexplained isolations), UV lamp interlocks.","Before AHU/filter work: PTW, LOTO at panel and local isolator, test start, close dampers, allow fan run-down; wear FFP3/PAPR for used filters; bag and label filters; test platform guardrails.","HEPA change on terminal housings: work from stable platform/scaffold, two persons, no leaning over equipment; validate (DOP/PAO) after change — test aerosol handled per SDS.","Duct/plenum entry: treat as confined space — isolate fans, test atmosphere, attendant, lighting; no entry to live interstitial spaces without permit.","Fumigation (VHP): seal room, post warnings, lock doors with key control, start cycle, monitor leaks at doors with handheld sensor","After cycle aerate and verify concentration at head height in several points before unlocking; log.","Gas-suppression rooms: before maintenance inside, isolate release (panel + mechanical lock-off), hang tag, restore after exit; never defeat abort or delay; if pre-discharge alarm sounds — leave immediately, close door.","Autoclaves/tunnels/lyophilisers: operate per pressure-vessel rules (autoclave is a pressure vessel), door interlocks, let cool before unloading, heat-resistant gloves; nitrogen areas with O2 monitors (< 19.5% alarm).","UV-C: switch off before opening LAF/pass-box; interlocks tested; eye protection if servicing lit lamps.","Cleaning and disinfectants: 70% IPA bulk stored per Petroleum Rules; sporicides per cleaning cards with PPE and ventilation; slip control (dry floors, footwear).","Emergency: evacuate gowned, follow lit exit signs, assembly headcount by room; fire service told about suppression gases, fumigation in progress and LN2/solvent storage."],ppe:["Cleanroom garments plus task PPE over them: FFP3/PAPR for filter changes, chemical goggles and gloves for disinfectants/H2O2","Heat-resistant gloves for autoclaves, harness for AHU roofs, hearing protection in plant rooms, UV face shield when servicing"],stop:["AHU not isolated/verified before filter or belt work","Door interlock does not release on alarm/override test","Gas-suppression release not isolated before entry for maintenance","Fumigation re-entry without concentration verification","Fall protection missing at AHU/roof platforms"],records:["PTW and LOTO records, HEPA change and validation reports, fumigation logs (concentration, aeration), suppression isolation log","Interlock and override tests, O2/VHP sensor calibration, evacuation drill reports, confined-space permits"],refs:{india:["Factories Act ss.13, 31, 36, 38 via state rules / OSH Code; Drugs & Cosmetics Rules Schedule M (HVAC, cleanroom design); IS 3103 (ventilation); IS 15105 (sprinklers), IS 2189 (detection & alarm)","NFPA 2001 / NFPA 12 as gaseous-suppression benchmark; Petroleum Rules (IPA storage); Sch. II (formaldehyde, H2O2 — verify); BMW/HOWM Rules for filters and chemicals"],ka:["Karnataka Factories Rules 1969; KSFES (suppression systems); KSPCB"],tn:["TN Factories Rules 1950 (Rule 61 pressure vessels — autoclaves; verify); TNFRS; TNPCB"],osha:["1910.147, 1910.146, 1910.160/161/162 (fixed extinguishing systems — CO2, gaseous agents), 1910.1048 (formaldehyde), 1910.1000 (H2O2 1 ppm), 1910.23/28 (platforms, ladders); NFPA 12, NFPA 2001, NFPA 86 (tunnels)"],intl:["ISO 14644 series (cleanrooms); EU GMP Annex 1 (2022); EN 12101/EN 15004 (gaseous suppression); UK HSE guidance on fumigation (HSG251) & CO2 systems; EN 14175 (fume cupboards); IEC 60335-2-109 (UV lamps)"]},checklist:"cl4-cleanroom"},
{id:"p3-reactor",t:"Reactor Charging, Inerting & Reactive Chemistry Control",cat:"Chemical",tags:["Chemical","Pharma","Process Safety"],purpose:"Prevent flash fires, explosions, runaway reactions and exposures during manual and closed charging of powders and liquids into reactors containing flammable solvents, and during reaction, sampling and discharge.",scope:"Glass-lined and SS reactors 100 L–20 kL in API, intermediate and speciality chemical plants; manual drum/bag charging through manways, closed charging (hoppers, split valves, vacuum transfer), inerting, exothermic and gas-evolving reactions, sampling, filtration/centrifuge discharge.",roles:["Plant head / process safety lead","Shift in-charge and operators (charging-trained)","R&D/process chemist (reaction hazard data)","Maintenance (earthing, inerting, relief)","Safety officer"],hazards:["Electrostatic ignition of solvent vapour when pouring powder through an open manway: brush discharges from non-conductive liners/drums, cone discharges from powder heaps, charged operators; MIE of many APIs < 10 mJ","Runaway reaction: wrong order/quantity of reagent, cooling failure, agitator stop, accumulation of unreacted reagent, late initiation; gas evolution over-pressuring vessel; relief undersized","Exposure: solvent vapour and API dust at open manway; hot vapour release on opening; toxic by-products (HCl, H2S, HCN in some chemistries); nitrogen asphyxiation on entry","Mechanical: falls into open manway, agitator start during charging, glass-lining failure, hose whip, centrifuge/filter discharge of solvent-wet cake (static), hot surfaces"],pre:["Reaction hazard assessment for every process: DSC/ARC data, adiabatic temperature rise, onset temperature vs operating temperature margin, gas-evolution rate, relief sizing (DIERS methods)","HAZOP; safe operating limits in batch record","Inerting: nitrogen purge to O2 below limiting oxygen concentration with margin (typically keep < 5–8% O2 — verify per solvent) before and during charging of powders into flammable solvent","O2 analyser with alarm; N2 supply assured","Static control (IS 7689 / IEC TS 60079-32-1): reactor, hopper, chute, drums and operator earthed (equipment < 10 Ω; footwear/floor < 10⁸ Ω — verify)","Conductive or static-dissipative liners and FIBCs (Type C earthed or Type D); metal scoops; no plastic drums for Class A solvents; restrict charging rate","Closed charging preferred: hopper with LEV and split-butterfly valve, vacuum conveying or drum-tipping enclosure","Manway charging only after risk assessment, with inerting, LEV and solvent temperature below flash point where possible","Hazardous-area Ex equipment; agitator interlocked to charging mode; cooling-water low-flow and high-temperature alarms with automatic actions (stop feed, emergency cooling, quench/dump)","Emergency power for agitator/cooling; PTW for maintenance; manway guard rail/grating"],steps:["Pre-batch: verify batch record, materials (identity, quantity, order of addition), reaction hazard sheet, inert gas supply, O2 analyser, cooling, agitator, relief and vent path, earthing clamps; sign off.","Set inert atmosphere: purge to O2 target, confirm on analyser; keep purge on during charging; solvent temperature below flash point where feasible.","Powder charging: operator earthed (conductive shoes, floor check), drum/bag earthed and bonded to reactor, LEV on, add through chute/hopper at controlled rate","No pouring from height; close manway between additions; no tipping of plastic liners into solvent vapour.","Liquid charging: by pump or vacuum through dip pipe; bottom or submerged entry; limit velocity; never free-fall flammable liquids into reactor.","Reaction: controlled addition with temperature tracking — stop feed if temperature deviates from profile (accumulation sign); never leave an exothermic addition unattended; verify agitation before and during reagent addition.","Sampling: closed sampler or through sample valve with inert blanket; PPE; never open manway of hot or pressurised reactor; vent and cool first.","Deviation/runaway signs (rapid temperature or pressure rise, venting): stop feeds, maximum cooling, emergency quench/dump per SOP, evacuate area, alert ERT; do not open vessel.","Discharge to centrifuge/filter: earth and bond, inert where solvent-wet, Ex equipment, keep lids closed; cake handling with LEV.","After batch: purge, clean per SOP; reactor entry only under confined-space permit with isolation of all lines, O2 20.9%, LEL 0, agitator locked.","Any new product, scale-up or change of solvent/vendor/equipment → MoC with reaction hazard review; incidents and near misses (static sparks, temperature excursions) investigated."],ppe:["Antistatic FR coveralls, conductive safety shoes, chemical goggles/face shield, solvent/API-rated gloves, respirator (A2P3 or PAPR per dust/vapour), hard hat near manways; escape set for toxic chemistries"],stop:["O2 above inerting limit or analyser not working during powder charging","Earthing of operator/drum/reactor not verified","Unknown or undocumented reaction hazard / deviation from batch record","Cooling or agitator failure with exotherm in progress","Open manway with solvent above flash point without inerting and LEV"],records:["Reaction hazard assessments and HAZOP, batch records with O2/earthing checks, N2/O2 analyser calibration, earthing resistance tests, relief/interlock test records, MoC, incident and deviation reports, exposure monitoring"],refs:{india:["Factories Act ss.37, 41B–H via state rules / OSH Code Ch. XII; MSIHC Rules (safety report, on-site plan where thresholds exceeded)","IS 7689 (static); IS 5572 & IS/IEC 60079 series; IS 4209 (chemical plants); IS 11457 Pt 1; Petroleum Rules 2002; Sch. II PELs; IS 17893 (permits)"],ka:["MAH Control (Karnataka) Rules 1994; Karnataka Factories Rules 1969 (Rule 129 schedules); Karnataka Safety Audit Rules 2024"],tn:["TN CIMAH Rules 1994; TN Factories Rules 1950 (Rule 95 schedules); DISH TN safety audit (MAH units)"],osha:["1910.119 PSM (process hazard analysis, operating procedures, MoC), 1910.106, 1910.307, 1910.146; NFPA 77, NFPA 69 (inerting), NFPA 654; CSB reports (reactive incidents)"],intl:["IEC TS 60079-32-1 (electrostatic hazards); CCPS Guidelines for Chemical Reactivity Evaluation & Application to Process Design","UK HSE HSG143 (chemical reaction hazards); DIERS (AIChE) relief design; EN 1127-1 (explosion prevention)"]},checklist:"cl4-reactor"},
{id:"p3-cotton-dust",t:"Cotton Dust & Byssinosis Control (Blow Room to Weaving)",cat:"Health",tags:["Health","Textiles","Industrial"],purpose:"Prevent byssinosis, chronic bronchitis and asthma from cotton, flax and jute dust in spinning mills, ginning, waste processing and weaving sheds, and meet medical-surveillance duties.",scope:"Bale opening, blow room, carding, combing, drawing, speed and ring frames, open-end spinning, winding, warping, sizing, weaving; waste/willow rooms; cotton ginning and pressing; housekeeping and waste handling.",roles:["Mill manager / occupier","Department supervisors","Maintenance (LEV, filtration plant)","Occupational physician / certifying surgeon (lung-function tests)","Safety officer; workers' representatives"],hazards:["Cotton dust (lint-free respirable fraction with bacterial endotoxin): byssinosis — Monday chest tightness progressing to permanent airflow obstruction; highest exposure in blow room, carding and waste rooms","Secondary: dust fires in blow room/filter plant, lint build-up on hot motors; endotoxin fever; eye irritation; noise 90–100 dB(A) in ring and weaving sheds","Cleaning with compressed air and brooms re-suspends dust; untreated (unwashed) cotton; poor filter-plant maintenance returning dust to shed","Vulnerable workers: smokers, asthmatics; new workers reacting on first exposure"],pre:["Exposure limits: OSHA 1910.1043 benchmark — 0.2 mg/m³ (yarn manufacturing), 0.75 mg/m³ (slashing and weaving), 0.5 mg/m³ (waste houses) lint-free dust by vertical elutriator","Indian Sch. II cotton dust limit (verify value) — set site action level at half","Engineering: enclosed blow-room machines with suction, card suction hoods and continuous waste removal (pneumafil), travelling cleaners on frames","Central filtration plant with rotary filters discharging outside the shed, air changes and humidification (see humidification procedure)","Housekeeping: vacuum or wet methods; no compressed-air blow-down while workers present; scheduled floor and overhead cleaning; waste bagged at source","Medical surveillance: pre-placement history, spirometry (FEV1, FVC) before and after the shift on the first working day of the week","Annual (6-monthly for high-exposure) by certifying surgeon; byssinosis is a notifiable disease (Third Schedule)","Respirators (FFP2/FFP3) for blow room, card stripping, filter cleaning and waste rooms until controls achieve limits; fit, training, replacement schedule"],steps:["Monthly dust monitoring at fixed stations (blow room, carding, ring, weaving, waste room) and personal samples on rotation; results on department notice board; action if > action level.","Daily: check suction at hoods, filter-plant differential pressure and discharge, travelling cleaners, waste removal; report blocked ducts.","Card stripping/grinding and blow-room cleaning: machine stopped and isolated; respirators worn; waste bagged; floor vacuumed after.","Filter-plant maintenance: isolate fans, treat chamber as confined space, FFP3/PAPR, clean with vacuum; fire watch for lint accumulations on motors and lights.","New workers: baseline spirometry and symptom questionnaire before posting to dusty departments; start in low-exposure jobs where possible; educate on Monday symptoms.","Weekly symptom check by supervisors: chest tightness, cough, breathlessness on Mondays → refer to OHC; relocate symptomatic workers to low-dust areas pending medical review.","Annual medical: spirometry; FEV1 fall ≥ 5% across shift or ≥ 200 mL (verify criteria) → investigate; grades of byssinosis recorded; notify DISH/DFBISH and ESI for notifiable disease.","Smoking banned in mill premises (fire and health); health education in local language.","Noise: hearing-protection zones and audiometry in ring and weaving sheds (see noise procedure).","Annual review: exposure trends, medical findings, control effectiveness; capital plan for enclosure/suction upgrades."],ppe:["FFP2/FFP3 respirators for dusty tasks, safety glasses, hearing protection in ≥ 85 dB(A) sheds, head covering, no loose dupatta/scarf near machines"],stop:["Dust at monitoring point above PEL with controls down","Filter plant or card suction not operating while running","Compressed-air cleaning while workers present","Worker with suspected byssinosis kept in high-dust job","Spirometry programme lapsed > 12 months"],records:["Dust monitoring results, LEV/filter-plant maintenance, spirometry and medical records (Form per state rules), notifiable disease reports, respirator issue and training, symptom surveillance, noise/audiometry"],refs:{india:["Factories Act s.14 (dust & fume), s.87 (dangerous operations), s.89 (notifiable disease — byssinosis, Third Schedule), s.27 (cotton openers) via state rules / OSH Code s.6, s.12","Sch. II cotton dust PEL (verify); IS 3103 (ventilation); IS 7194 (noise); ESI occupational-disease benefits"],ka:["Karnataka Factories Rules 1969 Rule 129 schedule (cotton dust — verify) & medical examination forms; DFBISH"],tn:["TN Factories Rules 1950 Rule 95 schedule on cotton dust/textile (verify) & Form 17/27 medical records; DISH TN; Coimbatore/Tiruppur spinning-mill clusters"],osha:["1910.1043 (cotton dust — PELs, vertical elutriator, medical surveillance, washed cotton exemption), 1910.134, 1910.95"],intl:["UK HSE 'Cotton dust' guidance & COSHH; ILO Code of Practice on Safety and Health in Textiles (2022); ACGIH cotton dust TLV 0.1 mg/m³ (thoracic); WHO byssinosis grading (Schilling)"]},checklist:"cl4-cotton-dust"},
{id:"p3-dyehouse",t:"Dye House & Wet Processing – Chemicals, HT Dyeing Machines, Stenters & Boilers",cat:"Chemical",tags:["Chemical","Textiles","Fire","Pressure/Boilers"],purpose:"Prevent chemical burns, toxic gas release, scalds and pressure-vessel failures, stenter and lint fires, and boiler incidents in dyeing, bleaching, printing and finishing units.",scope:"Chemical stores and dispensing; bleaching (H2O2, hypochlorite), scouring and mercerising (NaOH), dyeing (reactive, disperse, vat with sodium hydrosulphite), jigger/winch/soft-flow/HT dyeing machines, stenters and dryers, printing, boilers and thermic-fluid heaters, ETP/ZLD.",roles:["Processing head","Dye-house operators and chemical dispensers","Boiler attendant / operation engineer (certified)","Maintenance (pressure vessels, gas trains, stenter ducts)","Safety officer; ETP operator"],hazards:["Caustic soda (lye 48–50%, flakes — exothermic dissolution), sulphuric/acetic/formic acids, H2O2 50% (oxidiser), hypochlorite (+ acid → chlorine)","Sodium hydrosulphite (self-heating with moisture → SO2, fire), reactive dye powders (respiratory sensitisers)","HT dyeing machines at 130 °C / 3 bar: door opened under pressure, PRV failure; hot liquor and steam scalds from jiggers/winches; steam line failures","Stenters: lint and oil accumulation in ducts ignites at 180–220 °C; thermic-fluid leaks on hot surfaces; gas-fired burners without purge/flame failure; roller nip points at entry","Boilers/thermic heaters: low water, scale, uncertified attendants; ETP: H2S in anaerobic sumps, sludge handling, chlorine dosing"],pre:["Chemical store: segregation (oxidisers from reducers — H2O2 away from hydrosulphite","Acids from hypochlorite and caustic), dry cool store for hydrosulphite in sealed drums, bunding, labelled containers, SDS in local language, dispensing booth with LEV and weighing under extraction for dye powders","HT machines: pressure vessels registered and tested under state Factories Rules (Rule 61 TN / KA equivalent — verify) with door interlock preventing opening above 0.3 bar / 80 °C (verify)","PRV and gauge calibrated, operator trained","Stenters: scheduled duct and filter cleaning (weekly minimum), lint traps, temperature limits, gas train with pre-purge and flame safeguard (NFPA 86 benchmark)","Thermic-fluid leak checks, fire detection/suppression in exhaust ducts, nip guards and e-stops","Boilers: Boilers Act 2025 / IBR registration and annual certificate; attendant and operation engineer certified (Boiler Attendants Rules 2011 / BOE Rules 2011)","Water treatment; low-water cut-offs tested; thermic-fluid heaters under state rules where applicable","Emergency showers/eyewash within 10 s travel; spill kits (dry absorbent — no sawdust with oxidisers); chlorine awareness; ETP sumps as confined spaces with H2S monitors"],steps:["Dispensing: weigh dye powders in booth with LEV and FFP2/3; dissolve caustic flakes by adding to cold water slowly with stirring; never water into acid or caustic; label all buckets.","Hydrosulphite: keep drums sealed, handle dry, use only what is needed, never return to drum; wet or warm drum → isolate outdoors, do not seal, inform supervisor.","Bleaching: H2O2 stored vented, away from organics and reducers; hypochlorite never near acids; ventilate bleach ranges.","HT dyeing: check interlock, PRV, gauge; load/unload only after cool-down below 80 °C and pressure zero; stand aside when cracking door; hot liquor drained to safe drain.","Jiggers/winches/steam: guard nips, lids closed while running, steam valves opened slowly, lagging intact; scald first aid (cool 20 min).","Stenter start-up: purge, ignition sequence, no manual lighting; check duct cleaning done; respond to over-temperature or flame-failure alarms; fire in stenter — stop fabric, close dampers, use suppression/CO2, call fire team.","Boiler operation: only certified attendant; blow-down, water tests, low-water cut-off test each shift; annual inspection and hydraulic test by Boiler Inspectorate; log book.","Thermic fluid: leak checks each shift; fluid sampled yearly; no hot work near; drip trays; smoke from lagging → shut down and cool.","ETP: H2S monitoring at anaerobic units and sumps, confined-space permits, chlorine dosing PPE, sludge as HW; ZLD evaporator hot surfaces and chemicals.","Monthly audit: chemical segregation, showers, PRV/interlock tests, duct cleaning records, boiler log, PPE; incident review."],ppe:["Chemical goggles and face shield, gauntlet rubber/nitrile gloves, acid/alkali apron, gumboots, FFP2/3 for dye powders, heat-resistant gloves at stenters/HT doors, hearing protection in jet dyeing areas"],stop:["Opening HT machine above interlock limits or interlock bypassed","Hydrosulphite drum warm, wet or smoking in store","Stenter duct cleaning overdue or flame-safeguard defeated","Boiler run by uncertified person or low-water cut-off failed","Shower/eyewash out of service in dye house"],records:["Chemical inventory/SDS, dispensing logs, pressure-vessel certificates and interlock tests, stenter cleaning and burner service","Boiler certificate and log book, attendant certificates, thermic-fluid tests, ETP gas-monitor logs, incident and first-aid log"],refs:{india:["Boilers Act 2025 & IBR; Boiler Attendants Rules 2011, BOE Rules 2011; Factories Act ss.31, 36, 37, 38, 41B via state rules / OSH Code","MSIHC Rule 17; IS 17859 (GHS); IS 10592 (showers); IS 4209; Water Act consents (ZLD in Tiruppur per Madras HC orders); HOWM Rules (ETP sludge)"],ka:["Karnataka Boiler Rules 1982; Karnataka Factories Rules 1969 (pressure plant; Rule 129 schedules — dyes/chrome/acids verify); KSPCB"],tn:["TN Boiler Rules / Directorate of Boilers TN; TN Factories Rules 1950 Rule 61 (pressure plant — verify); DISH TN; TNPCB (Tiruppur/Erode ZLD CETPs)"],osha:["1910.1200, 1910.151(c), 1910.212, 1910.147, 1910.106 (hydrosulphite as reactive solid under 1910.1200), 1910.1000; NFPA 86 (stenters/dryers), NFPA 400 (oxidisers), ASME BPVC"],intl:["ILO Code of Practice Textiles (2022); UK HSE Textiles guidance (dyeing machines, stenters); EN 12921 (cleaning machines), EN 1539 (dryers and ovens); PED 2014/68/EU"]},checklist:"cl4-dyehouse"},
{id:"p3-textile-machines",t:"Textile & Garment Machinery Guarding (Carding, Ring Frames, Looms, Cutting)",cat:"Industrial",tags:["Industrial","Textiles","Machinery"],purpose:"Prevent entanglement, amputation, cuts and burns on spinning, weaving, knitting and garment machinery, with special attention to cleaning and piecing while running.",scope:"Blow room beaters and cleaners, cards, combers, draw/speed frames, ring frames, OE rotors, autoconers, warping and sizing, shuttle and shuttleless looms, circular/flat knitting; garment cutting (band knife, straight knife), sewing, fusing, ironing/pressing; beam and cone handling.",roles:["Mill/unit manager","Department supervisors (authorise cleaning while running only where designed)","Operators and tenters","Maintenance/fitters","Safety officer; safety committee"],hazards:["Blow room: hands in beaters while clearing choke; lids opened before run-down (rotors spin > 1 min); card lickerin/cylinder/flats during stripping or lap removal; comber nippers","Ring/speed frames: spindle tapes, drafting rollers, flyers, hair/dupatta/saree pallu entanglement while piecing; doffing trolleys; OE rotors opened running","Looms: shuttle fly-out (eye/head), beam lifting (200–500 kg), heald/reed changes, air-jet noise and compressed-air injection; knitting needles and cams","Garments: band-knife and straight-knife cuts, needle punctures, overlock eye injury, fusing press and iron burns, steam boiler/iron hoses; sitting ergonomics; fire exits blocked by stock in dense halls"],pre:["Guards per Factories Act ss.21–22 and state schedules (TN Rule 53 Schedule I textile machinery; KA Rule 56 Schedule — verify): fixed guards at gears, belts, tapes","Interlocked lids with time-delay on beaters/cleaners/rotors; lickerin and cylinder covers interlocked; nip guards on drafting and calender rollers","Rule: clearing chokes, lap-ups and cleaning only with machine stopped and isolated unless the machine is designed for safe running maintenance; written list of permitted running tasks per machine","Dress code: hair covered, no loose dupatta/scarf/jewellery, fitted sleeves; enforced for all including visitors; women and children not employed at cotton openers (Factories Act s.27)","Looms: shuttle guards and fly catchers, e-stops reachable from both sides, beam hoists/trolleys inspected, noise zone ≥ 85 dB(A) marked; knitting machines with needle-bed guards","Garment cutting: band knife with chain-mail glove and finger guard, straight knife with blade guard and sharpening interlock; needle guards and eye guards on sewing/overlock","Fusing press interlocks and heat shields; irons on insulated stands with steam-hose checks; exits and aisles ≥ 1.2 m kept clear"],steps:["Shift start: supervisor checks guards and interlocks on each line, e-stops, time-delay function on beater lids; defects tagged and machine stopped until fixed.","Blow room choke: stop, isolate, wait for rotor run-down (interlock timer), open lid, clear with tool; never bypass lid switch.","Card stripping/grinding, lap removal: machine stopped and locked; two persons for cylinder work; respirators (dust); restore guards before restart.","Ring/speed frames: piecing with hands only in permitted zones; stop frame for roller lapping removal and tape replacement; doffing with trolleys on marked paths.","Autoconer/warping: guard splicers and drums; stop before threading inside guards; beam handling with hoist and trained crew, clear path.","Looms: shuttle guards in place; stop before heald/reed/pick-finding inside; air-jet lines isolated for nozzle work; hearing protection in zone.","Garment cutting: chain-mail glove on free hand, blade guard set to fabric height, no cutting above shoulder; blade change under isolation; straight-knife cord management.","Sewing floor: needle guards fitted; broken-needle procedure; no bypassing eye guards; posture breaks every 2 h; adjustable chairs/footrests where possible.","Fusing/ironing: heat-resistant gloves, steam-hose inspections, iron boilers (small boilers) inspected per IBR exemption limits (verify), hot-surface signage; burns first aid.","Monthly: guard audit with safety committee, young-worker (< 18) check against dangerous-machine list, dress-code compliance, exit/aisle audit; incidents reviewed."],ppe:["Head covering/hairnet, safety glasses (looms, cutting), chain-mail glove for band knife, hearing protection in weaving/ring sheds, FFP2 for cleaning, safety shoes; no loose garments"],stop:["Interlock or time-delay lid switch bypassed","Clearing/cleaning inside a running machine not on permitted list","Shuttle guard missing on running loom","Band knife used without chain-mail glove and guard","Exit or aisle blocked by stock/trolleys"],records:["Machine guard register and audits, interlock tests, permitted running-task list, training/dress-code briefings, young-worker register, beam-hoist inspections, injury/near-miss log, exit audits"],refs:{india:["Factories Act ss.21–23, 26, 27 (cotton openers), 32, 38 via state rules / OSH Code; IS 9474 (guarding); IS 16819; NBC 2016 Part 4 (exits for industrial occupancy); Boilers Act 2025/IBR (iron boilers above exemption)"],ka:["Karnataka Factories Rules 1969 Rule 56 Schedule (textile machinery — verify); DFBISH"],tn:["TN Factories Rules 1950 Rule 53 Schedule I (textile machinery: cotton openers, scutchers, cards, ring frames, looms, hosiery machines — verify); DISH TN; Tiruppur garment cluster fire-safety drives"],osha:["1910.262 (textiles), 1910.212, 1910.219, 1910.147, 1910.95, 1910.36–37 (exits)"],intl:["ILO Code of Practice on Safety and Health in Textiles, Clothing, Leather and Footwear (2022); ISO 11111 series (textile machinery safety)","EN ISO 10821 (sewing machines); UK HSE Textiles Industry Advisory Committee guidance; EN 13998 (band knives — verify)"]},checklist:"cl4-textile-machines"},
{id:"p3-humidification",t:"Humidification, Ventilation & Heat in Spinning and Weaving Sheds",cat:"Health",tags:["Health","Textiles","Environment"],purpose:"Keep humidified textile sheds within statutory temperature and humidity limits, prevent heat illness, and control legionella and water-quality hazards from humidification plants and air washers.",scope:"Humidification plants (air washers, spray nozzles, ultrasonic/evaporative systems), ducting and return-air filtration, water supply and treatment, hygrometer stations, spinning/weaving sheds operating at RH 50–75%, high-heat zones (sizing, stenters, compressors).",roles:["Mill engineer (plant owner)","Shift supervisors (hygrometer readings)","Maintenance/water-treatment contractor","Occupational physician / first aiders","Safety officer"],hazards:["Heat stress: dry-bulb 32–38 °C with RH 60–75% gives WBGT > 30 °C in summer sheds; heat exhaustion/stroke, especially new or fasting workers; 12-hour shifts","Humidification water: stagnant sumps and spray systems — legionella and biofilm; untreated water aerosolised into breathing zone; dust-laden return air","Air-washer plant rooms: confined sump tanks, chemical dosing (biocide, scale inhibitor), slippery floors, fan and pump guards, electrical in wet areas","Poor ventilation: CO2 and lint build-up; fogging on floors; condensation on electrical panels"],pre:["Statutory: Factories Act s.15 (artificial humidification) and state rules — water of drinking quality or purified, hygrometers at prescribed stations","Dry/wet-bulb readings recorded at prescribed times (e.g. thrice daily — verify TN/KA schedule), humidification stopped when wet-bulb exceeds the rule limit (TN/KA table — verify value ≈ 29.4 °C)","Heat stress plan: WBGT measurement in each department (IS 7243 / ISO 7243), action levels with work-rest and hydration, cool rest rooms, ORS/water points within 50 m, acclimatisation for new workers (7–14 days), buddy watch","Summer timetable for heavy tasks","Legionella control: written scheme for air washers and humidifiers — sump cleaning and disinfection ≥ quarterly (verify)","Biocide dosing, water quality (TVC monthly, Legionella quarterly where risk), drift eliminators, no dead legs","Filters cleaned; make-up water treated","Plant room: pumps/fans guarded, RCD-protected sockets, non-slip floors, drainage; sump entry = confined space; chemical dosing with PPE and SDS","Ventilation: air changes and return-air filtration designed to remove lint and heat; exhaust in sizing/stenter areas; temperature display boards in sheds"],steps:["Readings: take dry/wet-bulb at each station at the rule times, record in Humidity Register; if wet-bulb exceeds limit — switch humidification to ventilation-only and inform manager.","Daily: check air-washer water clarity, nozzle spray, drift eliminators, sump level, biocide dosing; remove lint from filters; log.","Summer protocol (WBGT ≥ action level): extra breaks, rotate heavy tasks, water/ORS rounds every hour, loosen production targets, monitor new and older workers; stop heavy outdoor/roof work in peak hours.","Heat illness response: move to cool area, cool with water/fans, oral fluids if conscious, OHC/hospital for confusion or no sweating (heat stroke — emergency); record and report.","Weekly: flush low-use spray lines, check hygrometer wicks and calibration, clean spray nozzles; monthly TVC sampling.","Quarterly: drain, clean and disinfect air-washer sumps and tanks (confined-space permit), Legionella sampling, filter replacement; disinfectant neutralised before discharge.","Positive Legionella or cluster of pneumonia: shock-dose, re-sample, inform health authority and workers; review scheme.","Plant-room work: isolate fans/pumps, LOTO, dry floors; chemical dosing in PPE; eyewash available.","Monsoon/condensation: inspect panels and lights for water ingress; ELCB/RCD tests; anti-slip measures.","Annual: review hygrometer locations, WBGT survey, legionella scheme, worker heat-illness records; training refresh in local language."],ppe:["Light cotton clothing, head covering, non-slip footwear; gloves/goggles for dosing chemicals; FFP3 and harness/retrieval for sump cleaning"],stop:["Wet-bulb above statutory limit with humidification running","Humidification water not of required quality/untreated","Air-washer sump entry without confined-space controls","Worker showing heat-stroke signs not removed and treated","Legionella ≥ 1,000 cfu/L untreated"],records:["Humidity Register (dry/wet-bulb), hygrometer calibration, WBGT surveys, heat-illness log, legionella scheme with cleaning/disinfection and sampling results, water-quality tests, biocide logs, confined-space permits"],refs:{india:["Factories Act s.13 (ventilation & temperature), s.15 (artificial humidification), s.18 (drinking water) via state rules / OSH Code s.6, s.23–24","IS 7243 (WBGT), IS 3103 (ventilation), IS 10500 (water quality); NDMA heat-wave guidelines; Sch. II"],ka:["Karnataka Factories Rules 1969 humidification rules (hygrometer records, wet-bulb limits — verify rule numbers); Karnataka Heat Action Plan"],tn:["TN Factories Rules 1950 Rules 20–26 on humidification (hygrometers, prescribed times, wet-bulb table — verify); TN Heat Wave guidelines (TNSDMA); DISH TN"],osha:["OSHA Heat NEP & proposed 1910.148; OSHA Technical Manual Sec. III Ch. 4 (heat) & Ch. 7 (legionella); 1910.146 (sumps)"],intl:["ISO 7243 (WBGT), ISO 7933 (PHS); ACGIH Heat Stress TLV; UK HSE L8/HSG274 Pt 2 (humidifiers & air washers); ILO Code of Practice Textiles (2022); ASHRAE 188"]},checklist:"cl4-humidification"},
{id:"p3-moulding",t:"Injection Moulding Machines – Guarding, Purging, Mould Changes & Fumes",cat:"Industrial",tags:["Industrial","Plastics & Rubber","Machinery","Health"],purpose:"Prevent crush and trap injuries in the mould and clamp area, burns from hot plastic and heaters, injuries during mould changes, and exposure to thermal-decomposition fumes on injection and blow-moulding machines.",scope:"Hydraulic, electric and hybrid injection moulding machines 50–3,000 t; blow moulders; vertical insert moulders; take-out robots and sprue pickers; hopper loaders and dryers; granulators; mould changing and storage; hot-runner systems; nitrogen gas-assist.",roles:["Moulding shop head","Machine operators and setters (authorised)","Mould changers / toolroom","Maintenance (hydraulics, heaters, safety circuits)","Safety officer"],hazards:["Clamp closing (up to 3,000 t) with body part in mould area: failed/bypassed gate interlocks, reaching through rear or top openings, insert loading in semi-auto; ejector and core pulls","Hot plastic: purging at 200–300 °C — splash, gas pockets expelling molten material, barrel and nozzle contact burns; hot-runner leaks (drool); nitrogen gas-assist pressure (300 bar)","Fumes: PVC → HCl; acetal/POM → formaldehyde; polyurethane → isocyanates; PTFE > 400 °C → polymer fume fever; overheated residues; dust from regrind and masterbatch","Mould changes: 0.5–10 t moulds on EOT/forklift, hands between halves, inadequate clamping/pin alignment; granulator rotor knives; hydraulic injection injuries; noise; slips on spilled pellets"],pre:["Machines to ISO 20430 (ex-EN 201) benchmark: front gate with at least two independent interlocks (electrical plus hydraulic/mechanical), rear and top guards interlocked, purge guard, nozzle guard, hopper interlock","Safety circuit PL d/e; gate interlocks tested every shift","Setter authorisation and written set-up procedure; mould area entry (for insert loading, cleaning) only in set-up mode with clamp blocked or machine isolated","Semi-auto insert loading via two-hand/gate cycle with mechanical restraint where risk assessed","Purging: written procedure — purge shield down/guard closed, operator to side, face shield and heat gloves, purge into tray, no one in front of nozzle","Material-specific limits for residence time/temperature to prevent decomposition","Fume control: LEV at nozzle/purge and at hopper dryers for PVC/POM/PU; general ventilation; exposure monitoring for HCl, formaldehyde, isocyanates where processed; material SDS reviewed","Mould change: lifting plan — rated eyebolts (inspected, correct thread), slings, EOT with certificate, mould clamps torqued, locating ring engaged before releasing crane, die-height set, safety strap on mould halves","Forklift mould carts rated; granulators with interlocked hopper and time-delay, LOTO for blade work"],steps:["Shift start: test front gate interlocks (machine must not close with gate open), e-stops, purge guard, hopper guard, hydraulic leaks; record in machine log; defects → machine off until repaired.","Normal running: reach into mould area only through the front gate in semi-auto cycle; never through rear/top; use tongs for sprues/stuck parts; keep hands clear of ejectors.","Stuck parts or blocked nozzles: set-up mode, clamp open and blocked (or machine isolated), tools not hands; nozzle cleaning with heat PPE after pressure released.","Purging: shield/guard in place, face shield and gloves, purge in short shots, step aside; dispose of purge in metal bin after cooling; vent fumes.","Material changes: follow temperature profiles; never leave heated barrels full of PVC/POM idle — purge with stable resin; respond to smell/smoke (decomposition) by lowering heat and evacuating fumes.","Mould change: isolate hydraulics and heaters as required, confirm crane/eyebolt capacity, two persons, hands never between mould halves while crane holds load, clamp before releasing, verify alignment and safety strap","Test with low pressure.","Granulator: feed only closed items by hand; blockage → stop, isolate, wait run-down, use tools; blade change under LOTO with cut-resistant gloves.","Hopper loaders/dryers: isolate before clearing; hot-dryer burns; dust LEV; pellet spills swept immediately (slips).","Maintenance: LOTO at main isolator, hydraulic accumulators discharged, barrel heaters cooled or guarded, electrical cabinets by electricians; safety-circuit changes only by OEM/competent person and re-validated.","Monthly: interlock audit on all machines, fume/LEV check, noise, lifting-gear inspection, incident review; retrain setters yearly."],ppe:["Safety glasses (face shield for purging), heat-resistant gloves/sleeves, safety shoes, hearing protection where > 85 dB(A), FFP2/respirator per material, cut-resistant gloves for granulator blades"],stop:["Gate interlock failed or bypassed","Hands in mould area outside set-up mode or without clamp block","Purging with person in front of nozzle or without shield","Smoke/decomposition fumes at barrel","Mould lifted with uninspected eyebolt or hands between halves"],records:["Machine safety log (interlock tests), setter authorisations, purge and material procedures, LEV checks and exposure monitoring, mould lifting-gear inspections, LOTO records, granulator blade-change log, injury/near-miss log"],refs:{india:["Factories Act ss.21–23, 26, 29 via state rules / OSH Code s.6; IS 9474 (guarding); IS 16819 / ISO 12100; IS 17893 (permits)","Sch. II (HCl 5 ppm ceiling, formaldehyde — verify); HOWM Rules (purge waste); lifting-gear-codes (eyebolts/slings tests)"],ka:["Karnataka Factories Rules 1969 Rule 56 Schedule (rubber/plastic machinery — verify); DFBISH"],tn:["TN Factories Rules 1950 Rule 53 Schedule (plastic/rubber mills — verify); DISH TN"],osha:["1910.212, 1910.147 (incl. OSHA letters on IMM guarding), 1910.179 (EOT), 1910.1000, 1910.134; ANSI/PLASTICS B151.1 (horizontal IMM safety), B151.11 (granulators)"],intl:["ISO 20430:2020 (injection moulding machines), EN 422 (blow moulding), EN 12012-1 (granulators), ISO 13849-1; UK HSE PPS1/PPS series (plastics processing: IMM guarding, purging, fumes); BPF guidance"]},checklist:"cl4-moulding"},
{id:"p3-extruder",t:"Extruders, Film Lines & Hot-Melt Systems",cat:"Industrial",tags:["Industrial","Plastics & Rubber","Machinery","Health"],purpose:"Prevent burns, entanglement, high-pressure release and fume exposure on single/twin-screw extruders, blown and cast film lines, pipe/profile lines, compounding and hot-melt adhesive systems.",scope:"Extruder barrels, dies and screw changes; blown-film towers and winders; cast film chill rolls; pipe/profile lines with haul-offs, cutters and saws; pelletisers and strand baths; compounding with side feeders and vacuum vents; hot-melt tanks, hoses and applicators (150–200 °C).",roles:["Extrusion shop head","Line operators and die setters","Maintenance (heaters, hydraulics, rupture discs)","Winder/roll-change crews","Safety officer"],hazards:["Hot surfaces 180–300 °C on barrels, dies and adaptors; molten polymer splash during start-up, die bolt tightening and blockage clearing; frozen-die over-pressure and rupture; rupture-disc discharge","Entanglement: haul-off and nip rolls, winders (web wrap pulls hand in), corona treaters (HV), chill rolls, pelletiser rotors, strand cutters, pipe saws; manual threading of web","Screw removal: hot screw pulled with hoist/pusher; residual pressure; weight; burns; use of torch on blocked die (fire/decomposition)","Fumes/dust: decomposition on over-temperature or long residence (PVC, PE additives, flame retardants), ozone from corona treaters, resin dust and masterbatch; hot-melt vapours; height on film towers; noise"],pre:["Guarding per ISO 12100 / EN 1114 series (extruders and dies), EN 12012 (size reduction), EN 1612 (reaction moulding)","Nip guards on all in-running nips, interlocked guards with run-down on winders/pelletisers, pull-wire e-stops along lines, enclosed corona treaters interlocked (HV)","Barrel pressure protection: rupture disc or relief rated for barrel/die, discharge directed away from operator stations and shielded","Melt-pressure transducer with high-pressure shutdown; heater-zone over-temperature alarms and interlocks","Written start-up and die-change procedures: heat soak times, torque sequence with heat-resistant PPE, no one in line of die face during start-up","Blockage clearing without naked flame (use heaters, not torch); screw removal with purpose tool, hoist and cooled barrel","Film towers: guardrails, fixed stairs/platforms, roll-change hoists; web threading with threading tools or tapes at creep speed only","LEV at die/exhaust hoods and at pelletiser/vent ports; ozone extraction at corona treaters; material SDS; hot-melt systems with insulated tank lids, pressure relief, hose inspections, applicator guards"],steps:["Heat-up: verify zone temperatures, soak time, pressure transducer and rupture disc in place; never start screw with cold or partially melted polymer; stand clear of die.","Start-up/threading: creep speed, threading tools, nip guards closed before speed-up; gloves and face shield for die area; remove purge with tools to metal bin.","Running: monitor melt pressure and temperatures; respond to over-temperature or decomposition smell by reducing heat and ventilating; keep guards closed; clear scrap at winders only with winder stopped.","Roll changes/winders: stop winder or use turret in safe mode; cut web with guarded knife; no hands near nip during wrap; secure heavy reels (500–1,000 kg) with cores/stands; mechanical aids.","Die change/bolt tightening: pressure released, heaters as required, two persons, heat PPE, torque sequence; shield against melt squeeze-out; hot tooling in marked cooling area.","Blocked die/frozen melt: isolate screw, follow heater-based procedure; never use oxy torch or apply pressure to a frozen die; replace rupture disc if it has fired and investigate.","Screw removal: barrel at procedure temperature, pressure zero, use screw puller/hoist, heat PPE, exclusion zone; store hot screw in cradle.","Pelletisers/cutters/saws: interlocked guards, stop and isolate for blade changes (cut-resistant gloves), strand bath electrical RCD-protected.","Hot-melt: fill tanks slowly with lid guard, pressure release before hose/applicator change, hose condition checks, heat gloves/face shield, burn first aid kit at station.","Monthly: guard/interlock audit, rupture-disc and transducer checks, LEV flow, hoist/lifting gear, noise; incident review and retraining."],ppe:["Heat-resistant gloves/sleeves and face shield at die/barrel, safety glasses, safety shoes, hearing protection","Respirator per material (A/P combined where fumes), cut-resistant gloves for blades, harness on tower work without rails"],stop:["Rupture disc missing/fired or pressure transducer bypassed","Nip or winder guard open while running at speed","Torch or naked flame used on blocked die","Hands threading web at speed","Decomposition fumes without LEV"],records:["Start-up/die-change procedures and logs, rupture-disc/transducer records, interlock audits, LEV checks, exposure monitoring (ozone, HCl, fumes), hoist/lifting inspections, burn and injury log, training records"],refs:{india:["Factories Act ss.21–23, 29, 31 via state rules / OSH Code; IS 9474; IS 16819 / ISO 12100; Sch. II (ozone 0.1 ppm; HCl; dusts); HOWM Rules; lifting-gear-codes"],ka:["Karnataka Factories Rules 1969 (fencing; Rule 56 Schedule — verify)"],tn:["TN Factories Rules 1950 (Rule 53 Schedule — verify); DISH TN"],osha:["1910.212, 1910.219, 1910.147, 1910.1000, 1910.134, 1910.95; ANSI/PLASTICS B151.5 (extrusion lines — verify)"],intl:["EN 1114-1/-3 (extruders and die heads), EN 12012-1/-3 (size reduction/granulators, pelletisers), EN 1034 (winders/paper & film), ISO 13849-1; UK HSE PPS series (extrusion, winders, hot melt); BPF Health & Safety guidance"]},checklist:"cl4-extruder"},
{id:"p3-calender",t:"Two-Roll Mills, Calenders, Internal Mixers & Curing Presses (Rubber)",cat:"Industrial",tags:["Industrial","Plastics & Rubber","Machinery","Health"],purpose:"Prevent in-running nip entrapment and amputation on mills and calenders, crush injuries at mixers and presses, burns and exposure to rubber fume, carbon black and solvents in rubber and PVC compounding and product plants.",scope:"Open two-roll mills, calenders (3–4 roll), internal (Banbury-type) mixers, extruders/strainers, curing presses and autoclaves, tyre building and retreading, hose and belting, cement/solvent mixing, carbon black handling.",roles:["Compounding/mixing head","Mill operators (never alone)","Maintenance (brakes, trip systems)","Safety officer","Occupational physician (rubber fume/dust surveillance)"],hazards:["Mill nip: hand drawn in while feeding/cutting/blending stock; trip bar (Lunn bar) not stopping rolls within required distance; working alone; roll heat 60–150 °C","Calender nips and hot rolls; stock guides; thread-up; Banbury ram and charging door crush, hopper access, dust; press platens 150–180 °C closing on hands, mould handling; autoclave door/pressure","Rubber fume and dust (IARC Group 1 for rubber industry exposures), carbon black, talc, zinc oxide, accelerators and nitrosamines at curing; solvents (toluene, naphtha, hexane) in cements — fire and neuropathy","Noise; manual handling of 25–30 kg bales and batches; slips from release agents; fire in mixers/mills from overheated stock"],pre:["Mills per Factories Act s.22 and state schedules (TN Rule 53 Schedule — rubber mills","KA Rule 56 Schedule — verify) and EN 1417 benchmark: trip bar/cable at knee and chest height across front and back","Automatic braking stopping rolls within the specified distance for roll speed (verify EN 1417 table), automatic roll separation or reversal on trip, brake tested every shift","Operator rules: two trained persons present when mill runs; feeding tools for cutting and blending; stock cut with mill knife on marked side; sleeves fitted; no gloves near nips (or breakaway gloves only where assessed)","Calenders: nip guards, trip wires, e-stops at both ends, run at creep for thread-up","Mixers: interlocked charging door and hopper, ram control two-hand or guarded, LOTO for chamber cleaning (confined/hot), dust LEV at charging and carbon-black station","Presses: light curtains/two-hand controls, guards for falling moulds, platen heat shields","Health: LEV on mills/curing presses for fume, exposure monitoring (rubber fume/dust, carbon black, nitrosamines where relevant), medical surveillance","Solvents stored and dispensed per flammable-liquids rules, Ex equipment in cement rooms","Fire: hot stock and mill fires — CO2/DCP extinguishers at each mill, no water on hot oil; autoclaves as pressure vessels registered and tested"],steps:["Shift start: test trip bar on each mill (rolls must stop within marked distance and separate/reverse), e-stops on calenders/presses, mixer door interlocks; log; defective mill out of service.","Mill feeding: stand to the side, feed with both hands only from above the nip-guard line, use tools for pushing stock; never reach to clear sticking stock — trip and stop first.","Cutting/blending: mill knife cuts on roll away from nip; peel with tool; no reaching behind the roll.","Calender thread-up: creep speed, two persons, guards closed before run speed; stock guides adjusted only with rolls stopped.","Banbury: charge via hopper with LEV; ram down only with door closed and hands clear; never enter chamber without LOTO, cooling and permit; carbon black bags handled with LEV and FFP2.","Curing presses: load/unload with hands clear of platen zone; two-hand/light curtain functional; heat gloves; mould handling with lifting aids; autoclave door opened only at zero pressure and cooled.","Cement/solvent rooms: earth containers, Ex ventilation, respirators, no ignition sources, quantities limited; waste solvent closed drums.","Fume/dust: LEV running during mixing/milling/curing; hoods positioned; filters maintained; housekeeping by vacuum.","Health surveillance: periodic exams for dust/fume-exposed and solvent-exposed workers; audiometry; skin checks (accelerator dermatitis).","Monthly: trip-bar stopping-distance test with marks recorded, brake maintenance, guard audit, LEV flow, lifting aids; investigate every nip near miss."],ppe:["Fitted FR cotton overalls (no loose sleeves), safety shoes, safety glasses, hearing protection, FFP2/P3 for carbon black and curing fume, heat gloves for presses/autoclaves, solvent gloves/respirator in cement rooms"],stop:["Trip bar fails stop/separation test or brake worn","Single operator on a running mill","Gloves or loose sleeves worn at mill nip","Mixer door interlock or press light curtain bypassed","Autoclave door opened under pressure / solvent room ventilation off"],records:["Trip-bar/brake test log (stopping distance), mill operator authorisations, interlock audits, LEV and exposure monitoring","Pressure-vessel certificates (autoclaves), medical surveillance, solvent inventory, incident/near-miss log"],refs:{india:["Factories Act ss.21–23 (s.22 work on or near machinery in motion), 31, 36A via state rules / OSH Code; IS 9474; Sch. II (carbon black 3.5 mg/m³, rubber solvent, talc, ZnO); Petroleum Rules (solvent cements); HOWM Rules"],ka:["Karnataka Factories Rules 1969 Rule 56 Schedule (rubber mills — verify) & Rule 129 schedules; DFBISH"],tn:["TN Factories Rules 1950 Rule 53 Schedule (rubber mills/calenders — verify); DISH TN"],osha:["1910.216 (mills and calenders in rubber and plastics — trip/stopping distances), 1910.212, 1910.147, 1910.1000, 1910.106"],intl:["EN 1417 (two-roll mills), EN 12301 (calenders), EN 12013 (internal mixers), EN 289 (compression/transfer presses), EN 1612 (reaction moulding)","UK HSE rubber industry guidance (RUBIAC: mills, mixers, fume); IARC Monograph 100F"]},checklist:"cl4-calender"},
{id:"p3-printing",t:"Solvent-Based Printing & Lamination (Flexo/Gravure) – Flammable Inks, Dryers & Static",cat:"Chemical",tags:["Chemical","Plastics & Rubber","Fire","Health"],purpose:"Prevent fire and explosion from solvent inks and adhesives in printing and converting plants, and control solvent exposure, static, dryer hazards and web/roll injuries.",scope:"Rotogravure and flexographic presses, solvent inks (ethyl acetate, toluene, IPA, MEK), solvent and solventless lamination (PU adhesives/isocyanates), ink kitchens, solvent storage and recovery, dryers and ovens, slitters/rewinders, cylinder handling and plating, waste solvent.",roles:["Plant head","Press operators and ink-kitchen staff","Maintenance (Ex equipment, dryers, static control)","Fire officer","Safety officer; occupational physician"],hazards:["Flammable vapours (flash points −10 to 12 °C) in ink trays, kitchens and dryers; ignition from static on fast-moving films (speeds 200–400 m/min), non-Ex lighting/motors, hot bearings, dryer flame or electrical fault","Dryer explosion when LEL exceeded (NFPA 86: ≤ 25% LEL, or 50% with continuous monitoring); fire spread along web and ducts; solvent recovery/RTO flashback","Health: solvent CNS effects, toluene (TLV 20 ppm), ethyl acetate (400 ppm), MEK (200 ppm); isocyanates in PU adhesives (asthma); Cr(VI) in cylinder plating; ozone from corona treaters; noise","Mechanical: nips, doctor blades, rewinders, cylinder lifting (100–500 kg), slitter blades; chemical burns from plating/cleaning; roll handling"],pre:["Hazardous-area classification (IS 5572 / IEC 60079-10-1): Zone 1 at ink trays/kitchen, Zone 2 extended around presses (verify extents)","Ex-rated motors, lights, instruments, forklifts; IS/IEC 60079-17 inspections; LEL detection in press areas with alarms","Static control: earthing/bonding of presses, rollers, doctor blades, ink pumps and containers; passive/active ionisers at unwind/rewind","Conductive flooring and footwear; humidity control; periodic static-charge measurement (keep below ignition levels)","Dryers to NFPA 86 benchmark: LEL monitors with alarm at 25% and shutdown at 50% (continuous monitoring) or exhaust sized for ≤ 25%, purge before ignition, flame safeguard, airflow interlocks","Duct cleaning schedule; solvent recovery or RTO with flashback protection","Solvent storage per Petroleum Rules 2002 (Class A licence beyond exemption), bunded, earthed, closed dispensing systems; ink kitchen with LEV; daily quantities limited at press; waste solvent in closed earthed drums","Fire protection: sprinklers/deluge or CO2 for presses and dryers, foam for storage, extinguishers at each press, exits, fire watch for hot work","Exposure monitoring and health surveillance; isocyanate controls for PU lamination"],steps:["Shift start: check LEL monitors, Ex lighting, ioniser function, earthing straps, dryer safeguards, extinguishers; record.","Ink kitchen: mix under LEV with earthed containers and Ex pumps; keep lids closed; no plastic open containers for Class A; label inks; clean spills with inert absorbent.","Press operation: keep ink trays covered where possible, no electronic devices unless Ex, respond to LEL alarm by slowing/stopping and increasing exhaust; monitor web static; stop on sparking.","Dryer start-up: purge, verify airflow and LEL monitor, ignite via safeguard; never bypass; shut down on flame failure or LEL high.","Web threading, splicing and roll changes: creep speed, nip guards, cutting with guarded knives, roll lifts with shaft/hoist; doctor blade changes with cut-resistant gloves and blade covers.","Cylinder handling: rated lifting devices, two persons, racks secured; plating shop with LEV, Cr(VI) controls and PPE.","Cleaning: solvents in closed washers or with minimum quantities; rags in self-closing metal bins emptied each shift; no cleaning of running press.","Hot work or maintenance: PTW, solvent lines isolated, LEL 0%, ventilation running, fire watch 60 min; Ex equipment reinstated and inspected.","Waste: solvent, inks and rags as hazardous waste (HOWM) with manifests; VOC emissions within SPCB consent; recovery solvent quality controlled.","Health: solvent/isocyanate exposure monitoring, biological monitoring (hippuric acid for toluene — verify), annual medical, audiometry; training and drills (press fire, solvent spill)."],ppe:["Antistatic FR clothing, conductive footwear, chemical goggles, solvent gloves (nitrile/laminate per SDS), respirator (A2/P3) in kitchen and cleaning, cut-resistant gloves for blades, hearing protection"],stop:["LEL alarm or monitor out of service with press running","Non-Ex equipment/phone in Zone 1/2","Static control (earthing/ionisers) not functioning on film line","Dryer safeguard or purge bypassed","Solvent stored beyond licence or unbunded"],records:["Area classification drawings, Ex inspection register, LEL calibration, static measurements and earthing tests","Dryer safeguard tests, PESO licence/stock, HW manifests, exposure/biological monitoring, PTW records, drill reports"],refs:{india:["Petroleum Act 1934 & Rules 2002; Factories Act ss.37, 38, 41B via state rules / OSH Code; IS 5572 & IS/IEC 60079-14/-17; IS 7689 (static)","IS 11457 Pt 1; Sch. II (toluene, ethyl acetate, MEK, Cr(VI)); HOWM Rules 2016; Air Act consent (VOC); Plastic Waste Management Rules 2016 (EPR)"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules — solvents/chrome); PESO Bengaluru; KSPCB"],tn:["TN Factories Rules 1950 (Rule 95 schedules); PESO Chennai; TNPCB"],osha:["1910.106, 1910.107 (flammable finishing), 1910.307, 1910.1000, 1910.1026, 1910.134; NFPA 86 (ovens & dryers), NFPA 30, NFPA 77, NFPA 33"],intl:["ATEX 1999/92/EC & DSEAR; IEC TS 60079-32-1; EN 1010-1/-2/-3 (printing & converting machinery safety); EN 1539 (dryers/ovens releasing flammables); UK HSE printing industry guidance (PIAC)"]},checklist:"cl4-printing"},
{id:"p3-soldering",t:"Soldering, Reflow & Wave Solder – Flux Fume and Lead Control",cat:"Health",tags:["Health","Electronics","Industrial"],purpose:"Prevent occupational asthma from rosin (colophony) flux fume, lead poisoning from tin-lead solder and dross, burns from molten solder and exposure to cleaning solvents in electronics assembly.",scope:"Hand soldering and rework stations, wave and selective soldering machines (solder pots 250–300 °C), reflow ovens (air/nitrogen), stencil and PCB cleaning (IPA, saponifiers), conformal coating and potting, solder paste handling, dross and waste.",roles:["Production manager","Operators (fit-tested where RPE used)","Process/maintenance engineers (LEV, ovens, pots)","Industrial hygienist; occupational physician (blood lead, asthma)","Stores (lead/solder waste)"],hazards:["Colophony fume: respiratory sensitiser causing asthma (UK WEL 0.05 mg/m³ 8-h, 0.15 mg/m³ STEL — verify); once sensitised, trace exposure triggers attacks","Lead: ingestion via hands/food from solder, dross and dust; lead oxide fume at pots; blood lead rises silently (ACGIH BEI 20 µg/dL; action 30 µg/dL benchmark — verify); reproductive toxicity","Burns from solder pots, splash during dross skimming or wet PCBs (steam explosion), hot irons; reflow oven nitrogen (asphyxiation in enclosed oven or N2 room); hot-air rework","Solvents: IPA (flammable), flux thinners; conformal coating fume and UV curing (eye/skin); fine particulate from fume-filter changes; ESD wrist straps without 1 MΩ resistor (shock path)"],pre:["Fume control: tip extraction (on-iron) or arm/hood LEV at every hand-soldering station capturing at source","Enclosed wave/selective/reflow machines exhausted to outside or HEPA/carbon filters; smoke test and airflow checks weekly; LEV thorough examination 14-monthly (benchmark)","Lead hygiene: dedicated area for Pb solder, no food/drink/cosmetics, hand-wash before breaks, wet-wipe benches, HEPA vacuum (no brushing), separate lead work clothes","Prefer lead-free (SAC) where product allows; dross and lead waste as hazardous waste","Medical surveillance: blood lead at placement and 6-monthly for pot/dross workers (yearly for hand soldering), remove from exposure above action level","Respiratory questionnaire and spirometry yearly for colophony-exposed; asthma is a notifiable disease","Solder pots: temperature controllers with over-temperature cut-out, splash shields, dross tools, face shields; dry PCBs/components (moisture)","N2 systems with O2 monitors (< 19.5% alarm) in enclosed areas; reflow oven exhaust and flux condensate management","Solvents stored per flammable rules, dispensed in small closed containers, used under LEV; conformal-coating booths with LEV and UV-shielded curing","ESD programme with 1 MΩ series resistors in wrist straps/mats; electrical safety of irons/stations (earthing, RCD)"],steps:["Shift start: switch on LEV, check airflow indicator/smoke test, filter status, pot temperature, splash shields; report defects.","Hand soldering: keep tip extraction nozzle within 50 mm of joint (verify by smoke test); never lean into fume; use lead-free where specified; sponge/wire tip cleaning.","Wave/selective soldering: pre-heat and dry boards; skim dross with tools and face shield, pour into labelled metal container, let cool, seal as hazardous waste; add solder bars slowly (dry).","Reflow ovens: verify exhaust before start; N2 flow monitored; no entry into oven tunnel until cool and purged; clean flux condensate traps with gloves/respirator.","Breaks and end of shift: wash hands and face before eating/smoking; remove lead-area coat; no food at benches.","Cleaning: wet-wipe benches daily; HEPA vacuum floors; change LEV/fume filters with FFP3 and bag as hazardous waste.","Solvent use: small quantities in dispensers, lids closed, under LEV, away from heat/irons; empty containers capped; spill kit.","Conformal coating/potting: LEV booth, gloves (nitrile), eye protection for UV; skin contact with uncured resin avoided (sensitiser).","Health: blood lead and spirometry programme on schedule; symptoms (wheeze, chest tightness at work) reported and investigated; sensitised workers moved away from flux fume.","Monthly: LEV check records, lead hygiene audit (swabs on benches/canteen doors), waste manifests, training refresh; annual review of exposure data."],ppe:["Safety glasses (face shield at pots), heat-resistant gloves for pots/rework, nitrile gloves for solvents/paste, FFP3 for filter/dross cleaning, lab coat/dedicated clothing in lead areas, ESD footwear/wrist strap with resistor"],stop:["LEV off or failed smoke test at a soldering station","Eating/drinking in lead area","Blood lead above action level without removal from exposure","Pot splash shield missing / wet boards into wave","O2 alarm in nitrogen reflow area"],records:["LEV checks and examinations, blood-lead and spirometry records, lead hygiene audits, pot temperature/maintenance logs","O2 monitor calibration, solvent inventory, HW manifests (dross, filters), training, notifiable disease reports"],refs:{india:["Factories Act s.14, s.87 (dangerous operations — lead), s.89 (notifiable: lead poisoning, occupational asthma) via state rules / OSH Code s.6, s.12","Sch. II (lead 0.05 mg/m³, IPA); IS 3103 (ventilation); HOWM Rules 2016 (lead waste Sch. I); E-Waste Rules 2022; Petroleum Rules (IPA storage)"],ka:["Karnataka Factories Rules 1969 Rule 129 schedule (lead processes — verify); DFBISH; KSPCB"],tn:["TN Factories Rules 1950 Rule 95 schedule (lead — verify) & Form 27 medical; DISH TN; TNPCB"],osha:["1910.1025 (lead — PEL 50 µg/m³, action level 30 µg/m³, medical surveillance), 1910.94, 1910.1000, 1910.134, 1910.1200; NIOSH soldering guidance"],intl:["UK HSE INDG249 (soldering fume), COSHH & EH40 (colophony WEL), MS25 (medical aspects of lead); ACGIH TLV/BEI (lead 20 µg/dL BEI); IPC standards (process); EU RoHS"]},checklist:"cl4-soldering"},
{id:"p3-fab-chem",t:"Clean-Room Chemicals & Specialty Gases – HF, Wet Benches, Silane/Arsine, ESD",cat:"Chemical",tags:["Chemical","Electronics","Process Safety","Health"],purpose:"Prevent chemical burns, toxic and pyrophoric gas incidents, asphyxiation and fire in semiconductor, display, PCB and solar-cell fabs using hydrofluoric acid, strong acids/bases, solvents and specialty gases.",scope:"Wet benches and chemical delivery (HF, BOE, H2SO4/H2O2 piranha, HNO3, HCl, TMAH, KOH, NMP, PGMEA), gas cabinets and bunkers (SiH4, AsH3, PH3, NH3, Cl2, HCl, NF3, WF6, H2), bulk gases (N2, O2, Ar, LN2), exhaust and scrubbers, PCB plating/etching, waste.",roles:["Fab EHS manager","Chemical/gas technicians (certified)","Process engineers and operators","Emergency response team (SCBA, HF first aid)","Occupational physician; industrial hygienist"],hazards:["HF: penetrates skin, binds calcium — delayed, deep burns; > 1% body area at 49% or any exposure to concentrated HF can be fatal (verify); TLV 0.5 ppm TWA / 2 ppm ceiling (ACGIH — verify); eye exposure blinding","TMAH (developer ≥ 2.38%; concentrate 25%): skin absorption lethal with respiratory arrest; piranha (H2SO4+H2O2) exothermic and explosive with organics; hot phosphoric 160 °C; nitric/HCl fumes; KOH/NaOH burns","Gases: silane pyrophoric (ignites in air), arsine (TLV 0.005 ppm) and phosphine (0.05 ppm) acutely toxic, Cl2/HCl/NH3 corrosive, NF3/WF6, H2 explosive","Cylinder change-out leaks; exhaust failure; nitrogen/argon asphyxia in sub-fab","Fire in wet benches (plastic + solvents), exhaust duct fires; electroplating Cr(VI)/cyanide (HCN with acid); ESD discharges; slips; ergonomics; confined ducts and plenums"],pre:["Design per NFPA 318 / SEMI S2 / IFC Ch. 27 benchmark: exhausted wet benches with lids and interlocks, chemical delivery systems with double containment and leak detection","Gas cabinets with exhaust, excess-flow valves, restrictive flow orifices, coaxial tubing, automatic shut-off and purge panels","Toxic gas monitoring system (TGMS) at ½ TLV alarm with auto isolation (verify setpoints)","Gas Cylinders Rules 2016 / PESO: toxic and flammable cylinder storage, licences, segregation; silane in dedicated bunker outdoors with deluge; bulk cryogens per SMPV(U) Rules; O2 depletion monitors in sub-fab and gas rooms","HF response: 2.5% calcium gluconate gel at every HF-use point, HF-specific first-aid training, hospital tie-up with calcium protocols (gluconate IV/arterial), eyewash/showers within 10 s","Medical surveillance; TMAH handled only in closed systems or with full PPE and immediate flush","Chemical hygiene plan: SDS (IS 17859), compatibility segregation, labelled delivery lines, waste segregation (HF to calcium treatment","Cyanide separate from acids), scrubbers for acid/base/VOC exhaust; Cr(VI)/cyanide controls in plating; PPE matrix per chemical","Emergency: ERT with SCBA and Level A/B suits for gas releases, gas-release drills with fire service, shelter-in-place procedure for fab, TGMS alarm response tree; MSIHC compliance where thresholds exceeded"],steps:["Daily: TGMS and O2 monitors status, exhaust flows at benches/cabinets, scrubber pH/flow, leak-detection panels, eyewash/showers; log and escalate faults.","Wet-bench work: lids closed between steps, chemicals added via delivery system or with small labelled containers","Never pipette by mouth; piranha made fresh (acid first, slow peroxide), never stored closed; hot baths with splash guards.","HF/BOE: double gloves (nitrile under neoprene/laminate), face shield + goggles, apron","Any skin contact — flush 5 min, apply calcium gluconate gel while massaging, go to OHC/hospital immediately with SDS; eyes — flush 15 min, hospital.","TMAH: closed dispensing; any skin contact → remove clothing, flush ≥ 15 min, hospital even if feeling well.","Gas cylinder change-out: two certified technicians, PPE per gas (SCBA for AsH3/PH3/Cl2 cabinets per site rule), cabinet exhaust verified, purge cycles completed, leak check, valve protection","Silane change-out outdoors with deluge armed.","TGMS alarm: follow response tree — low alarm: investigate with PPE; high alarm: evacuate zone, isolate at auto shut-off, ERT with SCBA; account for all; notify.","Exhaust or scrubber failure: stop chemical/gas processes in affected area; no wet-bench work without exhaust; duct work as confined space with gas test.","Plating/etching (PCB): LEV at tanks, cyanide and acid separated with physical barriers, Cr(VI) exposure controls (PEL 5 µg/m³), eyewash, waste treatment (cyanide oxidation, chrome reduction) before ETP.","Waste: segregated, labelled, double-contained; HF waste neutralised with lime/calcium; solvent waste earthed; manifests under HOWM; empty cylinders returned with caps.","Training: chemical-specific (HF, TMAH, piranha) before authorisation; gas technician certification; annual drills (gas release, HF burn, cryogen spill); medical surveillance (As, F, Cr biomonitoring where relevant — verify)."],ppe:["Chemical goggles + face shield, chemical-resistant gloves (double; laminate for HF), acid apron/suit, chemical boots; SCBA and gas suits for ERT/cylinder change-out per gas; cryogenic gloves/face shield for LN2; ESD garments"],stop:["TGMS, exhaust or O2 monitor out of service in area with process running","Calcium gluconate or eyewash missing at HF point","Cylinder change-out by single/uncertified person","Piranha stored closed or mixed with organics","Cyanide and acid handled in same area without barrier"],records:["TGMS/O2 calibration and alarm logs, exhaust and scrubber checks, gas cylinder register and PESO licences, chemical inventory/SDS","Change-out logs, HF/TMAH exposure and first-aid records, biomonitoring, HW manifests, drill reports, MSIHC documents"],refs:{india:["Gas Cylinders Rules 2016 & SMPV(U) Rules 2016 (PESO); MSIHC Rules (arsine, phosphine, chlorine, silane thresholds — verify); Factories Act ss.41B–H via state rules / OSH Code Ch. XII","IS 17859 (GHS/SDS); IS 10592 (showers); IS 4209; Sch. II PELs (HF 3 ppm, arsine, phosphine, Cr(VI)); HOWM Rules 2016; E-Waste Rules 2022; ISM/India Semiconductor Mission fab EHS conditions"],ka:["MAH Control (Karnataka) Rules 1994; Karnataka Factories Rules 1969 Rule 129 schedules (acids, chrome, cyanide — verify); PESO Bengaluru; KSPCB"],tn:["TN CIMAH Rules 1994; TN Factories Rules 1950 Rule 95 schedules; PESO Chennai; TNPCB"],osha:["1910.1200, 1910.1000 (HF 3 ppm PEL), 1910.1026 (Cr(VI)), 1910.101/1910.103 (compressed gases, hydrogen), 1910.151(c), 1910.134, 1910.146","NFPA 318 (semiconductor fabrication), NFPA 55 (compressed gases & cryogens), NFPA 400, NFPA 45"],intl:["SEMI S2 (equipment EHS), S6 (exhaust ventilation), S8 (ergonomics), F15 (gas cabinets — verify); IFC Chapter 27; CGA P-1, G-13 (silane)","EIGA Doc 184 (specialty gases); ISO 14644; UK HSE HF first-aid guidance; Honeywell/ICSC HF medical guidance (calcium gluconate)"]},checklist:"cl4-fab-chem"},
{id:"p3-licell",t:"Lithium Cell & Pack Storage, Handling and Thermal-Runaway Response",cat:"Electrical",tags:["Electrical","Electronics","Fire","Energy/Carbon/ESG"],purpose:"Prevent and respond to thermal-runaway fires and toxic off-gassing of lithium-ion cells, modules and packs in cell manufacturing, pack assembly, warehouses, repair/returns and recycling.",scope:"Incoming cell inspection and storage, formation and ageing, pack assembly lines, finished-goods and spares warehouses, damaged/defective/returned (DDR) handling, transport packaging, battery waste; lithium-metal and sodium-ion cells where present.",roles:["Site head / fire officer","Warehouse and stores in-charge","Production/formation engineers","ERT (Li-ion fire trained) and fire service liaison","EHS manager"],hazards:["Thermal runaway from internal short, over-charge/discharge, mechanical damage, heat: cell venting (hissing, sweet solvent smell), smoke, jet flames > 600 °C, propagation through racks","Gases HF, CO, H2, hydrocarbons (toxic and explosive)","Storage: high state of charge, dense stacking, damaged cells mixed with good stock, ignition of packaging; sprinkler water insufficient for deep-seated pack fires; re-ignition for days","Manufacturing: electrolyte (LiPF6 → HF with moisture), NMP solvent in electrode coating (reprotoxic","Verify limit), dry rooms (dew point −40 °C), formation racks (over-charge faults), laser welding fume, lithium-metal (water-reactive — Class D)","Handling: shorting by tools/jewellery, drops, punctures; transport of untested/damaged cells (UN 38.3); recycling/disassembly of charged packs"],pre:["Storage per NFPA 855 / FM Global DS 8-1 benchmark: SoC 30–50% for storage, temperature 10–25 °C, segregated fire compartment or detached building","Sprinklers (density per FM 8-1 — verify), racks with limited stack height, aisles ≥ 2.4 m (verify), quantity limits per fire area, no mixed combustible storage","Detection: early off-gas (VOC/CO/H2) and smoke detection linked to alarm and HVAC isolation, thermal imaging rounds, CCTV","Fire-service information sheet (chemistry, kWh, layout); water supply for prolonged cooling (hydrants/monitors)","DDR cells: separate outdoor quarantine ≥ 15 m from buildings (verify) in metal containers with sand/vermiculite or in rated cabinets; inspected for swelling/leak/heat; discharged before disposal where safe","Manufacturing controls: formation racks with per-channel temperature/voltage trips and local suppression, electrolyte filling under LEV with HF response (calcium gluconate)","NMP recovery and exposure monitoring, dry-room entry limits (hydration, time), ESD/short-circuit prevention (insulated tools, covered terminals)","Transport: UN 38.3 tested cells, UN 3480/3481 packaging and labels, SoC ≤ 30% for air (verify), damaged cells under special provisions; Battery Waste Management Rules 2022 for end-of-life"],steps:["Receipt: inspect packaging and cells (dents, swelling, leakage, odour, temperature); reject suspect lots to quarantine; record SoC/voltage sample; store in designated compartment.","Storage rounds: twice-daily visual and thermal-camera check of racks; check detection panel; no charging in storage; keep aisles and sprinkler clearance; FIFO to limit ageing.","Handling: two persons for packs > 25 kg or lifting aids; terminals covered; no metal tools/jewellery near terminals; never puncture or crush; drop → quarantine 24 h with monitoring.","Formation/ageing: monitor trips; on over-temperature alarm isolate channel, remove cell with heat gloves to quench container (water or sand) if safe; evacuate if venting.","Suspected thermal runaway (hissing, smell, smoke, heat): raise alarm, isolate power, move people away, evacuate area","If a single cell/pack is safely movable at early stage — move to outdoor quench tank; otherwise leave for ERT.","Fire response: call fire service stating 'lithium-ion'; ERT in SCBA applies large volumes of water to cool and prevent propagation (do not try to 'extinguish' with small extinguishers)","Keep upwind; monitor for re-ignition 24–72 h with thermal camera; isolate affected stock outdoors.","Lithium-metal cells: no water — Class D agent/dry sand; segregated storage.","After event: treat debris as hazardous waste, HF/contaminated water contained, investigate root cause, review storage layout and detection.","Waste: discharged and insulated cells to registered recycler under BWMR 2022 with manifests; no landfill or mixing with general scrap.","Drills twice yearly with fire service; training for all handlers (signs of runaway, quarantine, PPE); review of NFPA 855/FM updates and OEM advisories."],ppe:["Safety glasses/face shield, insulated or nitrile gloves (heat gloves for hot cells), FR clothing, FFP3 for cleanup; SCBA and chemical suit for ERT; cryo/HF kit where electrolyte handled"],stop:["Swollen, hot, hissing or leaking cell inside main storage/production","DDR cells stored indoors with good stock","Detection or sprinkler system impaired without compensating measures","SoC or quantity limits exceeded in storage compartment","Charging of cells/packs in warehouse"],records:["Receipt inspection and quarantine register, storage SoC/temperature logs, thermal rounds, detection/sprinkler tests, formation alarm logs, incident and quench records, HW/BWMR manifests, drill reports, UN 38.3 certificates"],refs:{india:["IS 16046 Pt 1/2 (IEC 62133) & IEC 62619 / IS 17855 (cell/battery safety); BIS CRS registration (cells); Battery Waste Management Rules 2022","Factories Act ss.37, 38 via state rules / OSH Code; Fire NOC conditions (NBC Part 4 storage); HOWM Rules (electrolyte, NMP); Sch. II (HF, NMP — verify); IS 2190 (Class D agents)"],ka:["KSFES (BESS/battery storage NOC); Karnataka Factories Rules 1969; KSPCB"],tn:["TNFRS; TN Factories Rules 1950; TNPCB; TN EV/ACC cell plant EHS conditions (verify)"],osha:["1910.157, 1910.176, 1910.1200, 1910.134; NFPA 855 (ESS; storage provisions), NFPA 13 (sprinklers), UL 9540A, UL 1973 / 2580; CSB battery-fire guidance"],intl:["FM Global Data Sheet 8-1 (Li-ion battery storage), IEC 62619, IEC 62485-5/-6, UN 38.3 & UN Model Regulations (SP 376, P908/P911 damaged cells), IATA DGR (SoC 30%); UK HSE/NFCC lithium battery fire guidance; EN 50604"]},checklist:"cl4-licell"},
{id:"p3-wtg-climb",t:"Wind Turbine Tower Climbing, Ladders, Lifts & Fall Arrest",cat:"Construction",tags:["Wind","Construction","Industrial"],purpose:"Prevent falls and medical emergencies while ascending and descending wind turbine towers (80–140 m hubs) by ladder, climb assist or service lift, and while transitioning between platforms.",scope:"Onshore WTG towers (tubular steel, concrete, hybrid) during construction, commissioning and O&M; internal ladders with fall-arrest rail/rope systems, climb-assist, service lifts, platforms and hatches; hub-height work preparation.",roles:["Site manager / O&M lead","Technicians (GWO BST trained, medically fit)","Lead technician (team of ≥ 2)","Lift/ladder inspection competent person","Site ERT / rescue team"],hazards:["Fall from ladder during transitions, hatch openings or when fall-arrester not engaged; rail/rope system defects; harness misuse; dropped tools onto persons below","Physical exhaustion and heat (tower interior 40–50 °C in Indian summer), dehydration, cardiac events during climb; weight of tools and PPE","Service lift faults: overload, trapped persons, door interlocks; pinch points; falls through hatches left open; poor lighting; slippery rungs (oil, water)","Electrical: 690 V/33 kV switchgear at tower base; lightning; wind-induced tower sway; monsoon lightning season; snakes/animals at tower base"],pre:["Training: GWO Basic Safety Training (Working at Heights, First Aid, Manual Handling, Fire Awareness) or equivalent, site induction, turbine-specific familiarisation","Refresher every 24 months; medical fitness assessment (BP, cardiovascular, BMI/weight within PPE limits ~ 136 kg incl. tools — verify) yearly","PPE: full-body harness EN 361 with front/dorsal attachment, twin-leg energy-absorbing lanyard EN 355","Guided-type fall arrester EN 353-1 matched to rail/rope, work-positioning lanyard EN 358, helmet with chin strap EN 12492/397, gloves, boots","6-monthly PPE inspection by competent person plus pre-use","Fall-arrest systems: rail/rope and anchors inspected annually (and after lightning, fault or heavy use) by competent person; ladder rungs, hatches and platforms inspected","Service lift examined per manufacturer and 12-monthly (verify state Lifts Act applicability), with trapped-person release procedure","Rules: minimum two persons per turbine, communication with control room/site office at tower base and hub","Climb only within weather window (see weather procedure), hydration and rest at platforms, tool bags with tethers, hatches closed after passing","Emergency: rescue kit (descender EN 341 Class A, rope ≥ hub height + margin) at nacelle/top platform, first-aid kit and AED at site, evacuation plan to hospital (see remote-site procedure)"],steps:["Pre-climb: tower base check — switchgear status, no lightning alert, wind within OEM limit for climb, communication test, buddy check of harness/lanyards/arrester, tools tethered, water carried; log climb start with control.","Ascending: attach fall arrester to rail/rope before stepping on ladder; three points of contact; one person per ladder section between platforms (verify OEM); rest at each platform; close hatch behind you.","Transitions at platforms/hatches: use twin lanyards to stay connected 100% — one hook on before the other off; anchor only to rated points (marked); never to cable trays or pipes.","Climb assist: pre-use check of motor, rope, brake; weight setting; still connect fall arrester; stop if rope slips or noise.","Service lift: check inspection sticker, load limit (persons + tools), door interlocks, emergency stop, communication","Do not use in lightning alert or when fault lamp lit; follow trapped-person release only by trained persons.","At top: connect to nacelle anchor before unclipping from ladder; report arrival to control; check rescue kit present before starting work.","Descending: same discipline; fatigue is highest — rest at platforms; lower tools by bag/hoist, not carried in hands.","Dropped-object control: exclusion zone at tower base when work in progress above; tool tethers; hatch covers closed; tool inventory before leaving.","Heat: climb early morning in summer; 500 mL water per 30 min of climbing (verify); stop and rest if dizzy; heat-illness first aid.","Monthly: PPE and rescue-kit inspection, ladder/rail checks, lift logbook, climb-log review (durations, incidents); yearly: competent-person inspection of fall-arrest systems and lift."],ppe:["Full-body harness (EN 361), twin energy-absorbing lanyard (EN 355), guided fall arrester (EN 353-1), work-positioning lanyard (EN 358), climbing helmet with chin strap, gloves, safety boots, headlamp, tool tethers"],stop:["Lightning alert or wind above OEM climb limit","Fall-arrest rail/rope or lanyard defective / inspection overdue","Single person on turbine or no communication with control","Technician unwell, dizzy or not medically cleared","Rescue kit missing at top platform/nacelle"],records:["GWO/competence certificates, medical fitness, PPE inspection register (6-monthly), fall-arrest system and lift inspections, climb logs, dropped-object and near-miss reports, rescue-kit inspections"],refs:{india:["OSH Code s.6 & Central Rules 2026 (work at height); BOCW/state rules during construction; CEA Safety Regulations 2023 (electrical installations in WTGs)","IS 3521 (harnesses), IS 15298 (footwear); state Lifts Acts (service lifts — verify applicability); MNRE wind guidelines"],ka:["Karnataka Lifts Act 2012 (service lifts — verify); KREDL wind sites (Chitradurga, Gadag, Davanagere); Karnataka OSH draft rules"],tn:["TN Lifts and Escalators Act 1997 (verify); TANGEDCO/TEDA wind zones (Tirunelveli, Thoothukudi, Coimbatore, Tiruppur); TN BOCW Rules during erection"],osha:["1910.269 (electric power generation — incl. wind), 1910 Subpart D (walking-working surfaces, ladders, fall protection), 1926 Subpart M, 1910.140; ANSI/ASSP Z359 series"],intl:["GWO Basic Safety Training & Advanced Rescue standards; EN 50308 (wind turbines — personnel protective measures); EN 353-1, EN 355, EN 361, EN 358, EN 341","IEC 61400-1; EN 81-43 / EN 1808 (service lifts — verify applicable standard); UK RenewableUK Onshore Wind H&S Guidelines"]},checklist:"cl4-wtg-climb"},
{id:"p3-wtg-rescue",t:"Rescue from Height in Wind Turbines (Tower, Nacelle, Hub)",cat:"Fire & Emergency",tags:["Wind","Construction","Industrial"],purpose:"Ensure an injured or suspended technician can be reached, stabilised and lowered to the ground within the suspension-trauma window using the team on the turbine, and evacuated to hospital from a remote site.",scope:"Self-evacuation and assisted rescue from nacelle roof, nacelle interior, hub/spinner, tower ladder and platforms, service lift; casualty types: suspended in harness, unconscious on ladder, injured in nacelle, trapped in hub; nacelle fire evacuation.",roles:["Lead technician (rescue leader on turbine)","All technicians (GWO ART or equivalent)","Site manager (ground coordination, ambulance)","Control room (turbine stop, communications)","Local fire service/ambulance (pre-briefed)"],hazards:["Suspension trauma: a motionless suspended person may lose consciousness within 5–20 min; death if not lowered and managed; rescue must start within minutes — fire service cannot arrive in time at remote sites","Rescuer falls while attaching to casualty; rope burns/descender failure; rope too short; casualty struck against tower; nacelle fire with only descent as escape","Casualty on ladder inside tower: extraction up/down narrow sections; weight; platforms and hatches; heat and fatigue of rescuers","Communication failure; ambulance 45–90 min away; night rescue; wind/lightning preventing external descent"],pre:["Every technician trained in GWO Advanced Rescue Training (hub, spinner, nacelle, tower) or equivalent; refresher every 24 months; site rescue plan per turbine model with pre-rigged anchor points identified","Rescue kit at nacelle/top platform: descender EN 341 Class A with rope ≥ hub height + 10% (e.g. 120 m hub → ≥ 135 m)","Rescue stretcher/evacuation sling, pulleys for lifting, casualty harness attachment, rescue knife, head torch","Inspected monthly and after use; second kit for tower ladder rescue at base or mid-platform","Suspension relief: trauma straps on every harness; policy — if suspended and conscious, pump legs/use straps; rescuers lower casualty to ground or platform within 15 min (verify target)","Ground: first-aid responders, AED, trauma kit, stretcher, vehicle ready, GPS coordinates of each WTG, hospital and ambulance numbers posted, mobile/radio coverage map; dedicated access road kept clear","Nacelle fire: automatic suppression/alarms where fitted; escape route via nacelle hatch with personal descender (auto-descent device) carried by each technician in nacelle; drills"],steps:["Alarm: witness calls control and site manager (turbine ID, casualty condition, location); control stops turbine (if safe) and alerts ambulance/fire service with meeting point.","Rescue leader assesses: can casualty self-rescue? conscious? breathing? location; choose pre-planned method (lower from nacelle externally, lower inside tower, lift to platform).","Suspended casualty (external/nacelle roof): rescuer anchors independently, attaches descender rope to casualty, transfers load, cuts/releases lanyard, lowers to ground with controlled speed","Ground crew receives, lays casualty flat/semi-recumbent per current guidance, monitors.","Casualty on tower ladder: attach rescue system above, lift slightly to release fall arrester, lower to nearest platform or ground through ladder bay; manage hatches; second rescuer guides.","Hub/spinner casualty: rotor lock confirmed, hub stable; extract through hub hatch using pulley system to nacelle, then lower externally or via lift if operable.","First aid during rescue: airway, bleeding, spinal care if fall; AED on ground; oxygen if available; keep casualty warm.","Handover to ambulance at meeting point; send technician with casualty details; inform family and statutory authorities as required.","Nacelle fire: raise alarm, attempt extinguisher only on small fire, otherwise evacuate by lift if safe or descend externally with personal descender from pre-identified anchor; account for team at base.","Post-rescue: isolate scene, preserve evidence, replace used kit, debrief, incident investigation and reporting (OSH Code/BOCW/CEA as applicable).","Drills: full rescue drill per team every 6 months (verify) covering at least two scenarios; annual drill with local fire service and ambulance; records."],ppe:["Standard climbing PPE plus personal descender, rescue gloves, head torch; ground crew: first-aid kit, AED, trauma kit, stretcher, blankets"],stop:["Team not current in rescue training or fewer than two trained persons on turbine","Rescue kit missing, rope length insufficient or inspection overdue","No communication with ground/control","Weather prevents safe external descent and no alternative plan","Ambulance/hospital route not known or inaccessible"],records:["Rescue training certificates, site rescue plans per model, rescue-kit inspection register, drill reports and lessons, incident reports, emergency contact and hospital tie-up records"],refs:{india:["OSH Code s.6 & Central Rules 2026 (emergency arrangements, first aid); BOCW rules (rescue/first aid during erection); CEA 2023 (electrical rescue); Code on Social Security 2020 (compensation); IS 3521; NDMA guidelines"],ka:["Karnataka OSH draft rules; KSFES (fire service tie-up); 108 ambulance (Arogya Kavacha)"],tn:["TN OSH rules (draft); TNFRS; 108 ambulance service; TN BOCW Rules"],osha:["1910.140(c)(21) & 1926.502(d)(20) (prompt rescue), 1910.269(b) (first aid/CPR), 1910.151; ANSI/ASSP Z359.4 (assisted rescue), Z359.2"],intl:["GWO Advanced Rescue Training standard; EN 341 (descenders), EN 1496 (rescue lifting), EN 1497/1498 (rescue harnesses/loops)","UK HSE RR708 (suspension trauma) & 'Evidence-based review'; RenewableUK/G+ rescue guidance; IRATA ICOP (rescue)"]},checklist:"cl4-wtg-rescue"},
{id:"p3-wtg-nacelle",t:"Nacelle & Hub Entry, Rotor Lock and Stored-Energy Isolation",cat:"Electrical",tags:["Wind","Electrical","Industrial"],purpose:"Prevent crushing by rotating or pitching components, electrical shock/arc flash, hydraulic injection and falls during work inside nacelles, hubs and spinners, and on nacelle roofs.",scope:"Nacelle interior (gearbox, generator, converter, yaw, brake, hydraulics), hub and spinner (pitch systems, blade bearings, batteries/capacitors), nacelle roof (anemometry, lightning receptors), tower-base switchgear and transformer; O&M, retrofit and commissioning tasks.",roles:["Lead technician (isolation authority)","Technicians (turbine-type trained)","Control room / SCADA operator","HT authorised person for 33 kV","OEM field engineer where required"],hazards:["Rotor turning or pitching while persons in hub: rotor lock not engaged, brake release, wind gust, pitch system energised; crush between hub and nacelle, blade bearing rotation","Electrical: 690 V generator/converter, 33 kV switchgear, back-feed from grid, capacitor banks and pitch batteries/UPS; arc flash; induced voltages","Stored energy: hydraulic accumulators 150–250 bar (brake/pitch), spring-applied brakes, gearbox/bearing heat (70–90 °C), hot oil, high-torque bolting tools (hydraulic 700 bar — injection injury); nacelle crane loads","Falls: open hatches, nacelle roof without rails (wind), hub hatch; confined character of hub (limited egress, heat, fumes from grease/solvents); fire in nacelle"],pre:["Turbine stopped and set to service mode from control","Turbine-specific isolation procedure (LOTO) covering HT (where required — HT PTW via DISCOM/pooling substation)","LV main breaker, converter, pitch/yaw supplies, UPS/batteries, hydraulics (depressurise accumulators), and mechanical locks","Rotor lock: engage all lock pins (both where fitted) with blades feathered and rotor at designated position; verify engagement indicator and visually","Wind below OEM limit for lock engagement (typically ≤ 12–15 m/s — verify); yaw lock where needed; pitch lock/mechanical blocks for blade-bearing work","Hub entry treated as permit-controlled (confined-space-like): two persons, communication, atmosphere check if solvents/grease fumes, lighting, hatch secured open, exit route clear","Nacelle roof access only with anchor points, wind below roof-work limit (≤ 12 m/s — verify) and no lightning","Arc-flash assessment for LV/HT panels; arc-rated PPE and insulated tools for live testing; capacitor discharge times observed (converter/pitch — per OEM, typically 5–10 min — verify); test-before-touch","Lifting: nacelle crane/hoist tested 12-monthly with SWL marked; rigging inspected; exclusion at tower base during lifts; hydraulic bolting tools inspected, hoses and couplings rated; hot-surface and oil handling controls"],steps:["Request service mode from control; verify turbine stopped, brake applied; log start of work and expected duration.","Apply electrical isolation per turbine LOTO list: open and lock main LV breaker, isolate converter and pitch/yaw supplies, isolate UPS/batteries","HT isolation via authorised person with permit where work requires; verify dead with tested instrument on each circuit; apply earths where required.","Depressurise hydraulics (brake/pitch accumulators) per OEM and verify gauges at 0 bar; release spring energy only with tooling specified.","Engage rotor lock: feather blades, rotate to lock position with turning gear/motor, insert pins, verify indicator and visual; place lock tag; engage yaw lock if work on yaw or roof.","Hub entry: open hatch and secure; two persons (one may remain at hatch); check pitch system isolated and mechanical blocks fitted before touching blade bearings; carry radio; no entry without rotor lock verified.","Nacelle roof: connect to anchor before exiting hatch; check wind and lightning status; tools tethered; limit time; no roof work in rain.","Bolting/torqueing: hydraulic tool inspection, hoses clear, hands away from reaction arm, pressure released before adjusting; injection injury → hospital immediately regardless of appearance.","Hot work in nacelle (rare): permit, fire watch, extinguishers, fume control; grease/oil spill control; cleaning solvents in small quantities.","Return to service: remove tools and persons from hub/roof, remove blocks and pins (confirm indicator), remove earths and locks in reverse order, close hatches, reset converter, inform control; final headcount at tower base.","Records: isolation and rotor-lock logs, permits, crane/tool inspections, incident reports; review near misses (unexpected movement, residual voltage) with OEM."],ppe:["Climbing PPE, arc-rated clothing and face shield for electrical testing, Class 0 insulating gloves, insulated tools, heat-resistant gloves, hydraulic-tool face shield, hearing protection near generator, headlamp"],stop:["Rotor lock pins not verified engaged before hub entry","Residual voltage found after isolation / dead test not possible","Accumulator pressure not at zero before hydraulic work","Wind above lock/roof limits or lightning alert","Single person in hub or on roof"],records:["Turbine LOTO procedures and logs, rotor-lock register, HT permits, test-before-touch records, accumulator checks, nacelle crane and bolting tool inspections, hub-entry permits, incident log"],refs:{india:["CEA Safety Regulations 2023 (isolation, permits, earthing; wind farm electrical systems); OSH Code s.6 & Central Rules 2026","IS 5216 (electrical safety procedures), IS 15652 (mats); IS 17893 (permit system); lifting-gear-codes; state Electrical Inspectorate (CEIG) approvals"],ka:["CEIG Karnataka; KPTCL/ESCOM pooling-substation permit procedures; Karnataka Factories Rules where applicable"],tn:["CEIG Tamil Nadu; TANGEDCO/TANTRANSCO permit procedures at wind pooling substations; TN OSH rules (draft)"],osha:["1910.269 (generation — incl. lockout, hazardous energy, enclosed spaces), 1910.147, 1910.333–335, 1910.146; NFPA 70E; ANSI/ASSP Z244.1"],intl:["EN 50308 (wind turbines — personnel protective measures), IEC 61400-1 & IEC 61400-24 (lightning), EN 50110-1 (electrical operation), ISO 14118 (prevention of unexpected start-up), ISO 13849-1","GWO BTT/ART; RenewableUK guidelines"]},checklist:"cl4-wtg-nacelle"},
{id:"p3-blade",t:"Blade Inspection & Repair – Rope Access, Suspended Platforms, Composites",cat:"Construction",tags:["Wind","Construction","Health"],purpose:"Prevent falls, dropped objects, composite-dust and resin exposures, and lightning/weather incidents during external and internal blade work using rope access, blade access platforms, cranes or drones.",scope:"Leading-edge erosion repair and LEP application, lightning receptor and down-conductor checks, crack and damage repair, internal blade-root inspection, blade cleaning, drone inspection; rope access (IRATA/SPRAT), suspended blade platforms, crane baskets; ground-level blade repair after down-tower.",roles:["Blade repair supervisor (IRATA L3 or platform competent)","Rope-access technicians (IRATA/SPRAT certified)","Turbine technicians (rotor lock, isolation)","Drone pilot (DGCA certified) where used","Site manager; ERT"],hazards:["Falls: anchor failure, rope damage on blade edge, single-rope reliance, platform suspension failure, winds swinging technician against blade/tower; dropped tools/materials onto ground crew","Composites: glass/carbon-fibre dust from grinding (respiratory, skin), styrene/epoxy/PU resins and hardeners (sensitisers","Dermatitis), solvents (acetone), heating blankets (burns, fire) — in confined blade interior exposure is intense","Weather: wind > limits, rain (slip, cure failure), lightning (blade is the strike point), heat on composite surface 60 °C+; rotor rotating/pitching if lock fails","Blade interior: confined space — limited egress, dust, solvent vapour, heat; falls inside blade; working alone"],pre:["Rotor locked with blade in 6 o'clock (down) position for external work, pitch locked; turbine isolated per nacelle procedure; adjacent turbines in rotor-shadow assessed","Rope access per IRATA ICOP: two independently anchored systems (working and safety lines), anchors rated (≥ 15 kN each — verify) at designated hub/nacelle points","Rope protectors on edges, Level 3 supervisor on site, rescue plan with pre-rigged system","Platforms (BAP) per EN 1808 with wire ropes, secondary brakes, daily checks and 12-monthly thorough examination","Weather window: wind ≤ 10–12 m/s (verify OEM/IRATA), no rain, no lightning within alert radius, temperature within resin cure limits; forecast checked and monitored continuously (see weather procedure)","Composite controls: LEV/vacuum-shrouded grinders, FFP3 or PAPR, disposable coveralls, nitrile gloves, eye protection","Resin SDS, skin-care programme; heating blankets with thermostats and fire extinguisher; waste in sealed bags","Blade interior entry: permit, two persons (one at root/hub), gas test if solvents used, forced ventilation, lighting, lifeline inside, maximum entry distance per OEM, communication","Drone inspection preferred for external survey (Drone Rules 2021 registration, pilot certificate, airspace)"],steps:["Day plan: weather check, rotor lock and isolation completed and recorded, anchor inspection, rope/platform pre-use checks, ground exclusion zone (radius ≥ blade length — verify) with signage and spotter, radio check.","Rigging: rig working and safety lines to separate anchors, protect ropes at hub/nacelle edges and blade root, verify knots/devices by second technician; lower repair kit by haul line, not carried.","Descent to work zone: continuous monitoring of wind; use positioning aids to stay off blade edge; tools and pots tethered; no loose items.","Repair: grind with LEV and PAPR; mix resin in measured kits, apply within pot life, heating blanket set and monitored; solvent use minimal with vapour control; collect dust and waste in bags.","Platform work: load within SWL, persons harnessed to independent lifeline, no leaning out, stop in gusts; emergency lowering procedure known.","Communication: ground spotter watches weather and traffic, calls 'stop' on gusts/lightning/vehicles; technicians report every 30 min.","Internal blade: ventilate, test atmosphere, enter with lifeline and attendant; grind/sand with extraction; limit continuous time (heat); exit before resin curing fumes build.","Lightning alert: suspend work, ascend/descend to safe position, leave turbine per weather procedure; after a strike on turbine, inspect lightning protection system before further work.","End of day: inventory of tools, remove ropes/platform, release rotor lock per nacelle procedure, clear exclusion zone, dispose waste per HOWM, log hours and observations.","Health: medical fitness for rope access (yearly), skin checks for sensitisation, respiratory surveillance; drone ops logged per DGCA."],ppe:["Rope-access harness (EN 813/361) and devices, helmet, gloves, FFP3/PAPR, disposable coveralls (Type 5/6), nitrile gloves, goggles/face shield, hearing protection, heat-resistant gloves for blankets, headlamp"],stop:["Rotor/pitch lock not verified for blade in work position","Wind, rain or lightning outside limits","Anchor or rope inspection not current / single-rope working","Working inside blade alone or without ventilation and attendant","Exclusion zone not maintained below work"],records:["IRATA/SPRAT certificates and logbooks, anchor and rope inspection records, platform examinations, weather logs","Permits (blade interior), resin/solvent SDS and exposure records, dropped-object log, drone flight logs, waste manifests"],refs:{india:["OSH Code s.6 & Central Rules 2026 (work at height, confined spaces); BOCW rules (suspended platforms); IS 3521; Drone Rules 2021 (DGCA); HOWM Rules (resin/solvent waste); Sch. II (styrene, dusts); CEA 2023"],ka:["Karnataka OSH draft rules; KREDL/KPTCL site permissions; Karnataka Factories Rules where in licensed premises"],tn:["TN BOCW Rules; TN OSH rules (draft); TANGEDCO wind zone procedures"],osha:["1910.27(b) (rope descent systems), 1926 Subpart M & L (suspended scaffolds), 1910.146, 1910.134, 1910.1000 (styrene); ANSI/ASSP Z359; SPRAT standards"],intl:["IRATA International Code of Practice; EN 1808 (suspended access equipment), EN 12841 (rope adjustment devices), EN 795 (anchors)","IEC 61400-24 (lightning protection); GWO Blade Repair standard; UK HSE rope-access guidance (Work at Height Regs 2005 Sch. 5); EN 149/EN 12942 (RPE)"]},checklist:"cl4-blade"},
{id:"p3-wtg-weather",t:"Lightning, Wind & Weather Windows for Turbine Work",cat:"Management",tags:["Wind","Solar","Management","Environment"],purpose:"Define go/no-go weather criteria and monitoring so that climbing, nacelle, hub, roof, blade, crane and electrical work on wind and solar sites stops before lightning, high wind, heavy rain, heat or cyclone conditions make it unsafe.",scope:"All work at wind farms (towers, blades, cranes, substations) and solar parks (rooftop and ground-mount) in India's monsoon, pre-monsoon thunderstorm, cyclone and heat seasons; weather monitoring tools, alerts and stop-work authority.",roles:["Site manager (weather authority)","Control room / SCADA operator (met mast, lightning service)","Lead technicians (on-turbine decision to descend)","Crane supervisor (lift wind limits)","All workers (stop-work right)"],hazards:["Lightning: turbines and towers are strike points; strike while climbing, in nacelle, on roof or blade can be fatal","Induced voltages on structures and cables; storms build fast in pre-monsoon (Apr–Jun) and north-east monsoon (Oct–Dec) in TN","Wind: gusts throw technicians on roofs/blades, make lock engagement unsafe, overturn cranes and lifted modules; wind shear; dust storms reducing visibility","Rain/monsoon: slippery ladders and roofs, flooding of tower bases/cable trenches, electrical faults, lightning; cyclones on TN/AP/Gujarat coasts","Heat: tower interiors 45–50 °C, solar fields 45 °C+ with radiant load; cold at hub height in winter in north"],pre:["Weather limits table per OEM/site (verify each): climbing ≤ 20 m/s (10-min mean); rotor-lock engagement ≤ 12–15 m/s; nacelle roof/spinner external ≤ 12 m/s","Blade rope/platform work ≤ 10 m/s; crane lifts per load chart (often ≤ 9–10 m/s, lower for modules/blades); PV module handling ≤ 10 m/s","Lightning policy: alert when lightning within 30 km (prepare, finish task, pack)","Stop and evacuate turbine/roof when within 15 km (verify radii) or thunder heard (30/30 rule: flash-to-bang ≤ 30 s), resume 30 min after last strike within radius","Sources: IMD nowcasts, lightning-detection subscription, SCADA met mast, Damini app","Monitoring: control room watches met mast wind/gusts and lightning feed and radios all teams; each lead carries anemometer and lightning app; site weather board updated each morning and after changes","Shelter: vehicles (not under turbines or lines), substation control building; no shelter under trees or at tower base in the open; cyclone season plan with evacuation triggers from IMD warnings","Heat plan: WBGT-based schedule, shaded rest, water/ORS, early starts; monsoon plan: drainage of tower bases/inverter stations, cable trench inspections, slip controls, RCD tests"],steps:["Morning brief: review IMD forecast, lightning outlook, wind forecast at hub height, heat index; set work plan and no-go times; record on weather board; brief all teams.","Before each task: lead checks live wind and lightning status against the task limit; log go decision; control room acknowledges team location.","Continuous monitoring: control room alerts any team when wind trend approaches limit (e.g. 80% of limit) or lightning enters 30 km; teams respond and prepare to secure work.","Lightning 15 km / thunder heard: stop, secure tools, descend/evacuate turbine or roof immediately (do not finish tasks), move to vehicles/control building","Do not touch tower, fences or cables during storm; headcount by radio.","Wind over limit: stop task-specific work (roof, blade, lift) first; if climb limit exceeded, no ascents — teams aloft decide to descend while within limit or shelter in nacelle (OEM guidance) and inform control.","Rain: suspend roof/blade/external work, PV module work and open-panel electrical work; check tower-base water ingress; resume only when surfaces dry.","Heat: enforce rest schedule; suspend climbing at WBGT above action level in afternoon; watch for heat illness; hydrate.","Cyclone/red alert: secure site (crane booms down, loose material, modules), evacuate non-essential staff per IMD timeline, turbines in storm mode, communication plan with HQ.","After event: inspect lightning protection (LPS continuity, receptor damage), flooded areas, electrical insulation before re-energising/re-climbing; record strike events.","Review monthly: weather stop events, near misses, forecast accuracy; update limits with OEM; refresher briefing before pre-monsoon and NE-monsoon seasons."],ppe:["Standard site PPE; rain gear with grip soles for monsoon; sun protection (hat under helmet brim, long sleeves), cooling towels; no metal umbrellas in storms"],stop:["Lightning within stop radius or thunder heard","Wind above task limit or gusting erratically","Heavy rain or standing water on work surfaces","WBGT above stop level for strenuous tasks","Communication with control room lost"],records:["Daily weather board/log, lightning alerts and stop events, wind readings at task start, LPS inspection after strikes, heat-stress logs, cyclone preparedness checklists, near-miss reports"],refs:{india:["OSH Code s.6 & Central Rules 2026; IMD warnings and nowcasts; NDMA Guidelines on Lightning Safety & Heat Wave; IS/IEC 62305 (lightning protection), IEC 61400-24; CEA 2023; BOCW rules (weather stoppage during erection)"],ka:["KSNDMC weather/lightning alerts; Karnataka Heat Action Plan; Karnataka OSH draft rules"],tn:["TNSDMA; IMD Chennai RMC; TN Heat Wave guidelines; NE monsoon and cyclone protocols (Thoothukudi/Tirunelveli wind zones)"],osha:["OSHA Lightning Safety Fact Sheet (30/30, 30 min); 1926.1431/1926.1417 (crane wind limits), 1926 Subpart M; OSHA Heat NEP"],intl:["IEC 61400-1 (design wind classes), IEC 61400-24 (lightning); GWO/RenewableUK weather guidance; NOAA/NWS lightning safety; ISO 7243 (WBGT); BS 7121 (crane wind limits)"]},checklist:"cl4-wtg-weather"},
{id:"p3-remote-er",t:"Remote-Site Emergency Response (Wind & Solar Parks)",cat:"Fire & Emergency",tags:["Wind","Solar","Fire & Emergency","Health"],purpose:"Ensure that serious injuries, electrical and HV incidents, snakebite, heat stroke, road accidents and fires at remote renewable-energy sites get first aid, extraction and definitive care despite distances of 30–100 km to hospitals.",scope:"Wind farms and solar parks spread over 10–100 km², pooling substations, access roads, O&M bases, camps; day and night operations; contractor crews; emergencies: trauma, electrical burns/arrest, falls, heat illness, snakebite, vehicle accidents, fire, flood, lost or missing persons.",roles:["Site manager (incident controller)","Control room (communications hub, 24×7)","First-aid responders on every crew (certified)","Site ERT and drivers","Local hospital, 108 ambulance, fire station, police (pre-briefed)"],hazards:["Golden hour lost: ambulance 45–90 min away, rural roads, no signage to turbine locations; mobile dead zones inside towers and valleys","Electrical: HT (33/110 kV) switchyard incidents, arc burns, DC arc on solar; cardiac arrest needing AED within minutes","Environment: snakebite (Russell's viper, cobra, krait, saw-scaled viper), scorpion sting, heat stroke, dust storms, flash floods crossing causeways, wildlife","Road accidents on site/public roads (the leading fatality cause in renewable O&M), lone working, night call-outs; fire in inverter stations/transformers; theft/security incidents"],pre:["Emergency plan with maps: GPS/plus-code of every WTG, inverter station and gate","Road map with distances/times to primary and secondary hospitals (verify 24×7 trauma, ASV availability); ambulance meeting points; posted in vehicles and control room","Communication: VHF/UHF radio network covering site (incl. tower interiors via repeaters), satellite phone at control room for dead zones, mobile coverage map, check-in protocol (every 60 min","Lone working prohibited for HT, height and confined tasks)","Medical: first-aid responders (16-h course or GWO First Aid) on every crew, AED in each O&M vehicle or at least one per cluster (verify)","Trauma kits (tourniquet, dressings, splints, burn gel), stretcher/basket, oxygen where trained","Snakebite kit (pressure-immobilisation bandage; no cutting/sucking/tourniquet) and tie-up with hospital stocking anti-snake venom","Vehicles: fit-for-purpose 4×4 with seat belts, first-aid kit, fire extinguisher, tow rope, torch; drivers trained and rested; journey management for night call-outs; speed limits on site roads; causeway depth gauges","Fire: extinguishers in inverter stations, transformers and vehicles; fire breaks/vegetation control; grass-fire plan; local fire station contact; MSIHC/CEA incident reporting matrix"],steps:["Alert: anyone sees an emergency → radio/phone control room with location (asset ID), nature, casualties; control room starts incident log and alerts site manager and ERT.","Control room: call 108/ambulance and police/fire as needed, give GPS and meeting point, dispatch site vehicle to guide ambulance from the highway; send nearest first-aid responders with AED.","Scene: make safe (isolate electrical supply via control/HT authorised person, stop traffic, lightning/wind check), then first aid; CPR/AED for cardiac arrest; burns cooled; spinal precautions for falls.","Snakebite: calm and immobilise limb, pressure-immobilisation bandage, remove jewellery, note time and snake if seen (photo), transport fast to ASV hospital; no incision, suction or tourniquet.","Heat stroke: move to shade/AC vehicle, cool aggressively (water, fans, ice packs to neck/armpits/groin), hospital.","Transport decision: site vehicle to hospital may be faster than waiting — decide by condition and ETA; responder accompanies; control room informs hospital in advance.","Fire: evacuate, isolate electrical source if safe, fight only small fires; grass fire — fire breaks, wet lines, call fire service; transformer/inverter fire — keep distance, HT isolated.","Missing person/lost contact: last known location, radio call, vehicle search by grid, check tower logs; escalate after 30 min.","Reporting: statutory notices (OSH Code/BOCW/CEA accident report within 48 h; police for fatal), client/HQ notification, family liaison, investigation.","Readiness: monthly AED/kit checks, quarterly drills (one scenario each: trauma at hub height, electrical arrest, snakebite, vehicle crash), annual joint drill with ambulance and fire service; review routes after road changes."],ppe:["First-aid gloves, CPR face shield, hi-vis for scene control, torch; standard site PPE; snake gaiters for vegetation work"],stop:["Control room unmanned or radio network down","Crew without certified first-aider or AED access","Lone working on HT, height or confined tasks","Night work without journey management and vehicle checks","Route to hospital blocked (flood) without alternative"],records:["Emergency plan and maps, hospital/ambulance agreements, responder certificates, AED and kit inspection logs, radio checks, journey logs, drill reports, incident logs and statutory notices"],refs:{india:["OSH Code s.6, s.23 (welfare/first aid) & Central Rules 2026 (ambulance/first aid thresholds); BOCW rules (first aid, ambulance ≥ 500 workers — verify)","CEA Safety Regulations 2023 (accident reporting 48 h); MoHFW National Snakebite Management Protocol & NAPSE 2024; NDMA heat/lightning guidelines; MV Act (site vehicles)"],ka:["Arogya Kavacha 108; KSFES district stations; Karnataka OSH draft rules; district hospitals near Chitradurga/Gadag/Pavagada wind-solar zones"],tn:["108 GVK EMRI; TNFRS; TN BOCW Rules; GH Tirunelveli/Thoothukudi/Udumalpet near wind zones (verify ASV stock)"],osha:["1910.151 (medical/first aid — near proximity), 1910.269(b), 1910.38 (emergency action plans), 1926.50; ANSI/ISEA Z308.1 (first-aid kits)"],intl:["GWO First Aid standard; ISO 45001 cl. 8.2 (emergency preparedness); WHO snakebite guidelines (SE Asia); ERC/AHA resuscitation guidelines; UK HSE L74 (first aid); IRATA rescue provisions"]},checklist:"cl4-remote-er"},
{id:"p3-solar-dc",t:"Solar PV DC Systems – Shock, Arc Flash & Safe Isolation (Rooftop & Utility)",cat:"Electrical",tags:["Solar","Electrical","Fire"],purpose:"Prevent electric shock, DC arc-flash burns and fires from PV strings, combiner boxes, inverters and DC cabling that remain live whenever there is light, during installation, commissioning, O&M and fault-finding.",scope:"Rooftop (10 kW–5 MW) and utility-scale (1–500 MW) PV: modules, strings (600–1,500 V DC), DC cables and connectors, SCBs/combiner boxes, string and central inverters, DC isolators, earthing and SPDs, trackers; cleaning and vegetation work near live DC; inverter rooms/stations.",roles:["Electrical engineer / authorised person","O&M technicians (electrical trade, PV-trained)","Installation contractor (BOCW/OSH registered)","CEIG/Electrical Inspectorate (approvals)","Safety officer"],hazards:["Strings cannot be switched off at the module: 1,000–1,500 V DC present in daylight; shock on touching damaged cables/connectors or during connector mating under load","DC arc: no current zero — arcs sustain at low current; arc flash when opening isolators or connectors under load, loose terminations, water ingress in SCBs; fires in combiner boxes and at MC4 mismatches","Ground faults energising frames/trackers; back-feed from inverter/battery; AC side 415 V–33 kV; capacitor energy in inverters after shutdown","Heat on roofs/fields (module surface 60–70 °C), glare, dehydration; tracker motion (pinch) during maintenance; cable trench collapses; snakes under modules"],pre:["Design per IS/IEC 60364-7-712, IEC 62446-1 and CEA 2023: DC isolators (load-break rated) at string/array and inverter, labelled; 'live in daylight' warning labels on all DC enclosures; SPDs","Earthing of frames; cable routing with UV/rodent protection; firefighter isolation/rapid-shutdown signage; CEIG approval before energising installations above thresholds (verify ≥ 650 V or capacity-based)","Only authorised electrical persons work on DC; PV-specific training (DC isolation, arc-flash, connector practice)","Insulated tools (IEC 60900 1,000 V), Class 0 gloves (verify for 1,500 V — Class 00/0 ratings), arc-rated face shield and clothing (DC arc assessment per NFPA 70E/IEEE 1584 methods); CAT III 1,500 V meters","Written isolation procedure: open AC breaker, open DC isolators, wait inverter capacitor discharge (per OEM ≥ 5 min — verify)","Test string polarity/voltage, use opaque module covers for work on connectors where strings cannot be isolated, never disconnect connectors under load","Thermography programme (IR) for SCBs, inverters and connectors; insulation-resistance and earth-continuity tests per IEC 62446 at commissioning and periodically; SCB covers sealed (IP65), no water ingress","Permit (Electrical) for DC work; LOTO for inverters/trackers; roof/field work per fragile-roof and heat procedures; vegetation and cleaning crews briefed not to touch cables/enclosures"],steps:["Plan: identify strings/equipment, obtain Electrical PTW, confirm isolation points on single-line diagram, check weather (no rain/lightning), tools and PPE inspected.","Isolate: open AC breaker and lock; open DC isolators at inverter and SCB; wait discharge time; verify absence of voltage at work point with proven meter (test on live source before and after); apply lock and tag.","If a string cannot be isolated (connector work): cover modules with opaque covers to drop voltage, measure, work with insulated gloves/tools, never open a connector carrying current (check with clamp meter first).","Connector practice: use matching make/model connectors only, torque per OEM, crimp with correct tooling; replace burnt/discoloured connectors; document.","SCB/inverter inspection: thermography under load from safe distance; open covers only after isolation; check terminations, moisture, rodent damage, SPD indicators; close and seal.","Fault-finding (ground fault/arc-fault alarms): isolate array section, measure IR string by string; do not reset arc-fault trips without finding cause.","Re-energise: remove tools, verify polarity, close DC isolators string by string, then AC; check inverter start and alarms; remove locks; record.","Cleaning crews: water cleaning only when arrays isolated or per OEM for live washing with demineralised water and insulated lances; no pressure jets on connectors/enclosures; dawn/dusk schedule for heat.","Fire: isolate AC and DC where safe, inform fire service that DC remains live in daylight — no cutting cables; CO2/DCP on electrical fires; keep distance from arcing SCBs.","Records: commissioning tests (IEC 62446), PTW/LOTO, thermography reports, connector replacements, ground-fault investigations, incidents (electrical accidents to CEIG within 48 h)."],ppe:["Insulated gloves (Class 0; verify 1,500 V) with leather protectors, arc-rated face shield and clothing per assessment, insulated tools, safety glasses, non-conductive helmet, EH-rated boots, module covers","Sun protection and water"],stop:["Voltage not verified absent at work point / meter not proven","Connector disconnected under load","Working on DC without Electrical PTW or alone","Rain or lightning during open-enclosure work","SCB or inverter enclosure with water ingress or burnt smell energised"],records:["Electrical PTW/LOTO records, test-before-touch logs, IEC 62446 test reports, thermography, connector/SPD replacement log, authorisations and training, CEIG approvals, electrical accident reports"],refs:{india:["CEA Safety Regulations 2023 (incl. renewable/DC installations, approvals, accident reporting); IS/IEC 60364-7-712; IEC 62446-1","IS 14286 & IS 61730 (modules, QCO); IS 16221 / IEC 62109 (inverters); IS 3043 (earthing); IS/IEC 62305 (lightning); IS 5216; MNRE/BIS ALMM; OSH Code s.6"],ka:["CEIG Karnataka approval & periodic inspection; KREDL/BESCOM net-metering safety; Pavagada solar park EHS rules (verify)"],tn:["CEIG Tamil Nadu; TANGEDCO/TEDA interconnection safety; Kamuthi/Ramanathapuram solar park procedures (verify)"],osha:["1910.333–335, 1910.269 (generation), 1926 Subpart K; NFPA 70 Art. 690/691 (PV, rapid shutdown), NFPA 70E (DC arc flash), NEC 2023; IEEE 1584 (DC methods — verify)"],intl:["IEC 62446-1/-2 (testing, maintenance), IEC 61730 (module safety), IEC 60364-7-712; UK IET Code of Practice for Grid-Connected Solar PV; UK HSE PV guidance; EN 50110-1; SEIA/SolarPower Europe O&M best practice"]},checklist:"cl4-solar-dc"},
{id:"p3-fragile-roof",t:"Rooftop PV on Industrial Sheds – Fragile Roofs, Edge Falls & Module Handling",cat:"Construction",tags:["Solar","Construction"],purpose:"Prevent falls through fragile roof sheets and skylights, falls from roof edges and ladders, and injuries from module handling and lifting during rooftop solar installation, cleaning and maintenance.",scope:"Industrial and warehouse sheds with asbestos-cement, fibre-cement, metal (GI/aluminium) and polycarbonate sheets and skylights; RCC roofs with parapets < 1 m; access ladders and hatches; module lifting by crane, hoist or manual; cleaning and O&M visits.",roles:["Installation/O&M contractor (BOCW/OSH registered)","Roof work supervisor (competent)","Installers and cleaners (WAH trained)","Lifting supervisor and crane operator","Building owner (roof condition information)"],hazards:["Fragile roofs: AC/fibre-cement sheets, rusted metal, rooflights — give way without warning under a person's weight; falls 6–12 m onto concrete/machines; asbestos fibres when cutting/drilling AC sheets","Edge falls: no parapet or parapet < 1 m, open eaves, gable ends; ladder falls at access; falls through hatches; wind pushing persons/modules","Module handling: 20–35 kg modules in wind, cut hands, dropped modules onto people below; crane/hoist lifts over occupied buildings; overhead power lines near sheds","Heat (roof surface 60–70 °C), glare, dehydration; slippery wet/mossy sheets in monsoon; lightning; snakes/birds' nests"],pre:["Roof survey before any work: sheet type and condition, fragile areas and rooflights marked on drawing, structural capacity for crawl boards/walkways and PV load, parapet heights, anchor options, overhead lines","Owner's information; AC sheets treated as asbestos-containing — no cutting/drilling without wet methods and asbestos controls (preferably avoid penetration; use clamps on purlins)","Fall protection plan (hierarchy): avoid roof access where possible (drone surveys, ground-level pre-assembly)","Collective protection — edge guardrails (EN 13374), safety nets below fragile roofs (IS 11057/EN 1263), covered/caged rooflights, walkways/crawl boards spreading load across purlins","Where not possible — horizontal lifelines (EN 795 type C) or anchors tested to design load and harness with twin lanyards; ladders secured and extending 1 m above landing","Work-at-height permit; weather limits (wind ≤ 10 m/s for module handling — verify; no work in rain/lightning)","Exclusion zones below work and lifts; power-line clearance; rescue plan (casualty suspended or on roof) with equipment on site","Module lifting: crane/hoist with lift plan and certified gear, module pallets secured, tag lines, lift away from occupied areas or with building evacuated below; manual carrying by two persons with gloves on walkways only","Heat and welfare: early/late schedules, shaded rest at ground, water; first aid; asbestos awareness training where AC sheets present; HOWM disposal for AC debris"],steps:["Pre-start: review roof survey, permit, weather, anchors/guardrails in place, rooflights covered, walkways laid, exclusion zones set, rescue kit present; toolbox talk on fragile areas.","Access: secured ladder/stair tower or scaffold access; attach to lifeline/anchor before leaving ladder; hatch covers closed after passing.","Movement: only on walkways/crawl boards over purlins or on marked safe zones; never step on sheets between boards or on rooflights; no running; stay clipped on when outside guardrails.","Fixing structure: clamps on purlins/standing seams preferred; if drilling AC sheets unavoidable — wet drilling, FFP3, bag debris, no abrasive cutting; metal sheets — cut edges deburred, gloves.","Module handling: two persons, gloves, carry edge-on into wind; stack on rated frames; secure against wind at end of shift; lifting over roof edge with hoist and tag lines, no one under load.","Cabling and connectors: see solar DC procedure; route away from walkways; protect from sheet edges.","Cleaning/O&M visits: same access and fall-protection rules apply even for 10-minute jobs; check anchors/lifelines before use; water from ground-fed lances where possible.","Weather: stop module handling at wind limit, all roof work in rain/lightning; dry wet sheets before access; monsoon moss removal.","End of shift: remove loose items, secure modules, close hatches, check guardrails for next day; report damaged sheets to owner immediately and barricade below.","Records: roof survey, permits, anchor tests, equipment inspections, asbestos records (where applicable), near misses; review after any sheet breakage."],ppe:["Full-body harness with twin lanyards, helmet with chin strap, soft-soled grip boots, cut-resistant gloves, safety glasses/tinted, FFP3 for AC sheet work, sun protection, hi-vis"],stop:["Fragile sheet/rooflight not protected and no walkway/net/lifeline","Worker on roof unattached beyond guardrails","Wind, rain or lightning beyond limits","Lift over occupied area without evacuation/exclusion","AC sheets cut or drilled dry"],records:["Roof condition survey, WAH permits, anchor/lifeline test certificates, PPE and net/guardrail inspections, lift plans and crane certificates, weather log, asbestos work records, incident and near-miss reports"],refs:{india:["OSH Code s.6 & Central Rules 2026; BOCW Central/state rules (work at height, fragile roofs, ladders, nets); IS 3521 (harness), IS 11057 & IS 5175 (nets), IS 3696 (scaffolds/ladders), IS 15298","HOWM Rules & asbestos provisions (state rules dangerous-operations schedule — asbestos); CEA 2023; MNRE rooftop guidelines"],ka:["Karnataka BOCW Rules 2006 (height work, fragile roofs — verify rule numbers); BBMP/GBA building permissions for rooftop PV loads; KSFES"],tn:["TN BOCW Rules 2006 (amended 2025); CMDA/DTCP structural-stability certificate for rooftop PV (verify); TNFRS"],osha:["1926.501(b)(4) (holes/skylights), 1926.502, 1926 Subpart M & X (ladders), 1926.1101 (asbestos), 1926.1400 (cranes); ANSI/ASSP Z359"],intl:["UK HSE HSG33 (health and safety in roof work — fragile roofs), INDG284, Work at Height Regs 2005","EN 13374 (edge protection), EN 1263 (nets), EN 795; ACR[M]001 (fragile roofs test); Control of Asbestos Regs 2012 (UK) as benchmark"]},checklist:"cl4-fragile-roof"},
{id:"p3-bess",t:"Battery Energy Storage Systems (Utility & C&I) – Commissioning, O&M & Fire Response",cat:"Electrical",tags:["Solar","Electrical","Fire","Energy/Carbon/ESG"],purpose:"Prevent thermal runaway, explosion from accumulated off-gas, electric shock and arc flash in containerised and building-mounted lithium-ion BESS (LFP/NMC) from 100 kWh to GWh scale co-located with solar/wind or at substations.",scope:"Containerised and enclosure BESS, battery buildings, PCS/inverters, DC bus (1,000–1,500 V), BMS/EMS, HVAC/thermal management, gas detection and suppression, deflagration venting; delivery, installation, commissioning, energisation, O&M, module replacement, decommissioning.",roles:["Project/O&M manager","Electrical authorised person (HV/LV)","BESS technicians (OEM trained)","Fire officer / local fire service liaison","CEIG/Electrical Inspectorate; safety officer"],hazards:["Thermal runaway in one cell propagating through module/rack; off-gases (H2, CO, hydrocarbons, HF) accumulate in sealed enclosure — deflagration/explosion when door opened or ignition occurs (Surprise, Arizona 2019 benchmark)","DC 1,500 V and AC MV: shock, arc flash on racks/combiners, pre-charge faults, reverse polarity during commissioning; stored energy cannot be switched off — only isolated","Suppression limitations: clean agents stop flame but not runaway; water needed in large volume; re-ignition for days; HF in runoff; container entry after event","Installation: 30–40 t container lifts, trench and cable work, heat; HVAC failure causing over-temperature; coolant leaks (liquid-cooled); rodents"],pre:["Design per NFPA 855 / IEC 62933-5-2 / UL 9540 benchmark with UL 9540A test data: separation distances (≥ 3 m between units, ≥ 15 m to exposures/occupied buildings or fire-rated barriers — verify)","Explosion control (deflagration vents NFPA 68 or exhaust ventilation NFPA 69), gas detection (H2/CO/VOC) with ventilation and alarm, smoke/heat detection, suppression as per OEM, BMS trips, thermal management redundancy","Approvals: CEIG approval before energisation (CEA 2023), Fire NOC with BESS-specific conditions, Battery Waste Management Rules 2022 EPR, BIS/IS 16046/IEC 62619 cell certification; grid code and protection studies","Emergency Response Plan (ERP) agreed with local fire service: site map, chemistry and kWh per unit, isolation points","'do not open doors during gas alarm' rule, water supply (hydrants/monitors ≥ 2 h — verify), runoff containment, standoff distances, re-ignition monitoring","Fire service familiarisation visit before energisation","Electrical: arc-flash study for DC racks and PCS, labels, Class 0 gloves/1,500 V tools, remote racking where possible, LOTO procedures per OEM (DC disconnects, rack breakers, pre-charge), test-before-touch; HV PTW for MV side","Commissioning plan: polarity and insulation tests before closing DC, staged energisation, BMS alarm verification, gas-detector and suppression function tests, HVAC proving","O&M schedule: thermography, torque, coolant, filters, detector calibration, firmware under MoC"],steps:["Receipt/installation: inspect containers for damage and BMS logs during transport; SoC as shipped (≤ 30–50%)","Lift with certified crane and rated lifting points; ground and bond; keep doors closed; no hot work within 15 m without permit.","Commissioning: verify DC polarity and IR string by string, pre-charge sequence per OEM, close rack breakers one at a time monitoring BMS","Test gas detection, ventilation, suppression (simulated), e-stops and remote trips before first charge cycle.","Energisation: HV PTW, CEIG approval in hand, fire service informed, exclusion zone, two authorised persons; staged charge/discharge with thermal monitoring.","Routine O&M: review BMS/EMS alarms daily (cell voltage/temperature deviation), HVAC performance, detector status","Monthly thermography of busbars and PCS; quarterly detector calibration and suppression inspection; annual torque/IR tests.","Module/rack work: isolate rack (DC disconnect + breaker), wait discharge, verify 0 V at work point, insulated tools and gloves, cover adjacent live parts; two persons; module handling with lifting aids (30–60 kg).","Gas alarm / thermal event: DO NOT open doors","Evacuate to standoff (≥ 50 m — verify), trip PCS and isolate AC remotely, let ventilation/deflagration systems work, call fire service with ERP, monitor remotely (BMS/thermal camera).","Fire response (with fire service): defensive posture, protect exposures, apply water from distance via monitors if required for cooling adjacent units","Contain runoff, no entry until gas readings safe and temperatures stable for 24 h","Expect re-ignition.","Post-event: isolate and quarantine damaged units outdoors, handle debris as hazardous waste, HF-contaminated water to authorised disposal, root-cause investigation with OEM, notify CEIG/fire/SPCB as required.","Changes (firmware, chemistry, layout, HVAC) under MoC with hazard review; annual ERP drill with fire service; training records for all technicians.","Decommissioning: discharge to safe SoC, isolate, remove under OEM procedure, transport as UN 3480, recycle under BWMR 2022 with manifests."],ppe:["Arc-rated clothing and face shield per study, Class 0 insulating gloves with protectors, insulated tools, safety glasses, EH boots, hard hat, FFP3; SCBA and chemical suit for ERT post-event; heat gloves"],stop:["Gas (H2/CO) alarm active — doors must stay closed","DC rack not verified de-energised before work","Ventilation, detection or suppression impaired without compensating measures and fire-service notice","Energisation without CEIG approval or ERP in place","Cell temperature/voltage deviation alarm unresolved"],records:["Design/UL 9540A documentation, CEIG approval and Fire NOC, commissioning test reports, BMS/EMS alarm logs","Detector/suppression test records, thermography, LOTO/HV permits, ERP and drill records, MoC, BWMR manifests, incident reports"],refs:{india:["CEA Safety Regulations 2023 & CEA Technical Standards (connectivity; BESS); IS 16046 / IEC 62619 / IEC 62933-5-2; IS 17387 (BESS — verify)","Battery Waste Management Rules 2022; Fire NOC under state Fire Acts with NBC Part 4; IS 2189, IS 15105; MNRE/CERC BESS guidelines; HOWM Rules; OSH Code"],ka:["CEIG Karnataka; KSFES NOC for BESS; KSPCB; KREDL/KPTCL BESS tenders' safety conditions"],tn:["CEIG Tamil Nadu; TNFRS; TNPCB; TANGEDCO BESS safety conditions (verify)"],osha:["1910.333–335, 1910.147, 1910.146; NFPA 855 (2023/2026 editions), NFPA 68, NFPA 69, NFPA 70 Art. 706, NFPA 70E; UL 9540 / 9540A / 1973; CSB and NFPA Research Foundation BESS reports"],intl:["IEC 62933-5-2, IEC 62619, IEC 62485-5; EN 50604; FM Global DS 5-33 (ESS); UK NFCC & HSE BESS guidance; Australian AS/NZS 5139; EPRI BESS Failure Incident Database & ERP guidance"]},checklist:"cl4-bess"},
{id:"p3-quay-crane",t:"Quay Cranes, Yard Equipment & Container Lashing",cat:"Lifting & Tools",tags:["Ports & Marine","Lifting & Cranes","Transport"],purpose:"Prevent struck-by, crush, fall and dropped-container incidents in container and bulk terminals involving ship-to-shore cranes, RTGs/RMGs, reach stackers, straddle carriers, internal transfer vehicles and lashing gangs.",scope:"STS/quay cranes, mobile harbour cranes, RTG/RMG yard cranes, reach stackers, empty handlers, straddle carriers, terminal tractors, lashing/unlashing on deck and on quay, twistlock handling, reefer monitoring, hatch-cover handling; wind and night operations.",roles:["Terminal operations manager","Crane operators (certified, medically fit)","Lashers/stevedores and foremen","Yard planners / TOS control","Maintenance (crane inspections); safety officer"],hazards:["Persons struck by containers, spreaders, hatch covers or ITVs on quay; working under suspended loads; crane boom/gantry collision with ship or other crane; wind-driven gantry run-away","Lashing: falls from container tops and lashing bridges (> 2.5 m), struck by swinging containers while on deck, lashing rods/turnbuckles (20 kg) dropped, twistlock bins; hand injuries","Yard: reach stacker tip-over with high load, straddle blind spots, RTG wheel crush, pedestrians/truck drivers out of cabs, stack collapse in wind, damaged or over-weight (VGM) containers, hazardous DG containers","Fatigue (12-h shifts, night), heat on steel decks, slips on wet quay/hatch covers, falls into open hatches/between ship and quay"],pre:["Lifting appliances tested and examined per Dock Workers (Safety, Health & Welfare) Regulations 1990 (under OSH Code): initial and periodic tests, 12-monthly thorough examination, register","Spreader twistlock indicators, load/overload and anti-collision devices, boom limits, gantry anti-collision and storm anchoring","Operators: certification per port/DG Shipping or terminal competency scheme, medical (vision, fitness), simulator/practical assessment; fatigue limits per Dock regs/OSH Code hours","Pedestrian exclusion: no walking on quay operational lanes; marked walkways, lashing platforms/cages for twistlock work, ITV drivers stay in cab under crane","Radio/visual signals; night lighting ≥ 50 lux at work areas (verify)","Wind: operations stop limits (e.g. STS ≥ 20 m/s / 72 km/h — verify terminal limit), stack height reduced and empties secured ahead of cyclone warnings, storm pins; anemometers on cranes with alarms","Container integrity: CSC plates, VGM verification, damaged boxes isolated; DG per IMDG and port DG rules; reefer plugs/unplug with gloves and insulated tools"],steps:["Shift start: crane pre-use checks (brakes, limits, spreader, anti-collision, wind alarm, lights), yard equipment daily checks, radio check, lashing gear inspection; defects tagged out.","Vessel planning: stow plan reviewed for DG, over-height/out-of-gauge, hatch sequence; lashing gang briefed on bays, cell guides, falls from height and exclusion zones.","Hatch covers: lifted only with crane in correct mode, no persons on deck in swing path, placed on marked quay areas with barricades.","Container lifts: operator confirms twistlocks locked (indicators), lifts clear of cell guides, no person within 10 m on quay; ITV driver in cab; load not passed over people.","Lashing: use lashing platforms/cages; never climb container stacks or work on top without edge protection/fall arrest; handle rods in pairs; twistlocks to bins; stop when crane works adjacent bay.","Yard: speed limits (≤ 25 km/h ITV","≤ 10 km/h near pedestrians — verify), reach stackers lift at height only with stable load and no slope, straddle paths segregated, truck drivers stay in cab at interchange or in marked zone; RTG wheel-turn alarms.","Wind rising: TOS control monitors; at pre-alarm stop high stacking and lashing on top tiers; at limit stop crane operations, stow booms, pin gantries, secure stacks.","Damaged/leaking container: isolate, identify contents (UN number/DGD), DG procedure; over-weight → re-weigh, do not lift until verified.","Incidents: stop operations in zone, treat casualty, preserve scene, notify port authority/Dock Safety Inspector and police as applicable (fatal/ dangerous occurrence) within statutory time.","Weekly: lashing-gear inspection, walkway/lighting audit, near-miss review; annual: thorough examination of cranes and spreaders, operator refresher and medical."],ppe:["Helmet with chin strap, hi-vis, safety boots, gloves (impact-rated for lashing), safety glasses, harness where fall-arrest used on container tops/bridges, lifejacket near open water edges, hearing protection in engine areas"],stop:["Person on quay/deck within crane working radius or under load","Wind above terminal limit or anemometer failed","Twistlock indicator fault or spreader not locked","Lashing on container tops without platform/fall arrest","Crane examination overdue or safety device bypassed"],records:["Lifting appliance register and test/examination certificates, operator certificates and medicals, daily equipment checks","Lashing-gear inspections, wind logs and stop events, DG container register, incident/dangerous-occurrence notices, near-miss log"],refs:{india:["Dock Workers (Safety, Health and Welfare) Act 1986 & Regulations 1990 (now under OSH Code Ch. on dock work; DGFASLI Dock Safety Inspectorate); OSH Code 2020 & Central Rules 2026","Major Port Authorities Act 2021 & port regulations; IS 3177/IS 807 (crane design), IS 13367; MV Act (terminal tractors on public roads); IMDG via Merchant Shipping Act/DG Shipping circulars"],ka:["New Mangalore Port Authority / Karwar port regulations; Karnataka Maritime Board; DGFASLI Mangalore inspectorate (verify)"],tn:["Chennai, Kamarajar (Ennore), V.O. Chidambaranar (Thoothukudi) Port regulations; TN Maritime Board; DGFASLI Chennai inspectorate"],osha:["29 CFR 1917 (marine terminals — 1917.45 cranes, 1917.71 terminal lifting, 1917.112 guarding), 1918 (longshoring — 1918.85 containerised cargo), 1910.179; ANSI B30.2/B30.4"],intl:["ILO Code of Practice 'Safety and Health in Ports' (2016), ILO C152; PEMA/ICHCA safety briefings (lashing, twistlocks, wind); BS 7121 Pt 1/14; IMO CSC 1972; SOLAS VI/2 (VGM); FEM/ISO 4306 crane standards"]},checklist:"cl4-quay-crane"},
{id:"p3-hold-entry",t:"Ship Hold & Enclosed-Space Entry – Oxygen Depletion, Fumigants & Bulk Cargoes",cat:"Industrial",tags:["Ports & Marine","Industrial","Chemical"],purpose:"Prevent deaths of stevedores, surveyors and crew entering cargo holds, tanks and adjacent spaces with oxygen-deficient, toxic or flammable atmospheres, and injuries from hold ladders, grabs and mobile plant in holds.",scope:"Bulk carriers and general cargo ships at berth or anchorage (coal, ore, DRI, grain, fertiliser, sulphur, logs, wood pellets, steel turnings), fumigated cargoes, container holds, tanker and barge spaces; hold ladders, hatch coamings, dozers and grabs in holds.",roles:["Stevedore company safety officer / foreman","Ship's master and officers (enclosed-space procedures, SOLAS)","Port Dock Safety Inspector","Licensed fumigator (gas-free certification)","Entrants, attendants and rescue team (SCBA)"],hazards:["O2 depletion by cargo oxidation/respiration (coal, DRI, steel turnings, grain, logs, wood pellets, copra); CO from wood pellets/coal self-heating","CH4 from coal; H2 from DRI contact with water; dust; adjacent spaces (stools, ducts, store rooms) sharing atmosphere","Fumigants: phosphine (AlP tablets/sachets in grain — TLV 0.05 ppm ACGIH; OSHA PEL 0.3 ppm) persists in cargo and adjacent spaces; methyl bromide, sulfuryl fluoride; 'fumigated in transit' cargoes under IMO recommendations","Falls from vertical hold ladders (20–25 m), hatch coamings, open hatches, into hoppers; struck by grab/bulldozer","Cargo shifting/slides (iron ore fines, bauxite liquefaction), sulphur dust explosion, ammonium nitrate decomposition; heat 45 °C+ in holds","Rescue fatalities: would-be rescuers entering without SCBA are a large share of enclosed-space deaths (IMO data)"],pre:["Every hold/tank/adjacent space is an enclosed space until proven otherwise: master's enclosed-space entry permit (SOLAS XI-1/7 — ship carries calibrated multi-gas detector) plus stevedore permit","Atmosphere tested at several levels (O2 20.9%, LEL < 1% / 10% for work, CO < 25 ppm, H2S < 5 ppm, PH3 < 0.3 ppm — verify) before and during entry; ventilation ≥ 2 air changes before test (verify)","Fumigated cargo: fumigator's gas-free certificate for holds and adjacent spaces, placards removed only after clearance","Residual-fumigant check before stevedore entry and daily; no entry during 'in-transit' fumigation; disposal of spent AlP residues by licensed fumigator","Access: ladders inspected by officer, rest platforms, safety harness and fall arrester on Australian ladders where fitted, lighting, hatch coaming guardrails or exclusion, lifelines/retrieval for vertical access","One person on ladder at a time","Mobile plant in holds: CO monitoring with diesel equipment, exhaust scrubbers/ventilation, no persons in hold while grab working or dozer moving (except in protected cage), trimming hatch sequence","Cargo-specific IMSBC Code precautions (self-heating, liquefaction, dust)","Rescue: SCBA sets at hatch (≥ 2), rescue harness/tripod/stretcher, attendant at hatch with communication to crane/ship; ship-shore emergency plan; medical oxygen; never enter to rescue without SCBA"],steps:["Before gangs board: ship-shore meeting — cargo type and IMSBC hazards, fumigation status, hold ventilation status, enclosed-space permits, emergency contacts; agree exclusion and signalling.","Ventilate hold (open hatches, fans) and test atmosphere from the top at three depths with calibrated detector; record; if any reading fails — continue ventilation and re-test; no entry on smell/visual judgement.","Issue permit (ship and stevedore), post attendant, log entrants; entrants carry personal 4-gas monitors; continuous monitoring in deep holds and whenever cargo disturbed.","Descend hold ladder one at a time, three points of contact, harness/arrester where fitted, tools on hoist line; rest at platforms; no descent during grab/dozer operation.","Work in hold: stay out of grab swing and dozer path; exit before grab resumes; dust control (water sprays for coal/ore where allowed); hydrate and rotate for heat; report dizziness/headache immediately (CO/O2).","Adjacent spaces (stool, duct keel, store rooms): separate test and permit — toxic gases migrate from fumigated or self-heating cargo.","Fumigated holds: wait for fumigator clearance; check PH3 at cargo surface and in pockets; treat tablet residues/sachets as hazardous; stop and exit if detector alarms.","Emergency in hold: attendant raises alarm (ship's whistle/ radio), never enters; rescue team in SCBA with lifelines","Casualty hoisted in rescue harness/stretcher by crane; oxygen and medical evacuation; notify Dock Safety Inspector.","Hot work or repair in holds/tanks: ship's hot-work permit, gas-free certificate, fire watch; tank entry per tank-cleaning procedure.","Records: permits, gas logs, fumigation certificates, ladder inspections, incident reports; weekly review of readings and near misses with ship agents and stevedore foremen."],ppe:["Helmet, boots, gloves, personal multi-gas monitor, dust respirator (FFP3) for bulk cargo, goggles, harness/fall arrester on vertical ladders, hi-vis; SCBA for rescue team; chemical PPE for fumigant residues"],stop:["Atmosphere not tested or outside limits","Fumigated cargo without gas-free certificate","Attendant or rescue SCBA not at hatch","Grab or dozer operating with persons in hold","Hold ladder damaged or coaming unguarded"],records:["Enclosed-space entry permits (ship and shore), gas-test logs, calibration records, fumigation/gas-free certificates","Ladder and hatch inspections, entrant logs, rescue equipment checks, drill records, incident/dangerous-occurrence notices"],refs:{india:["Dock Workers (Safety, Health & Welfare) Regulations 1990 (entry into holds/enclosed spaces, ladders, mobile plant in holds — verify regs); OSH Code 2020","Merchant Shipping Act 2025 (verify — replaces 1958) & DG Shipping circulars on enclosed-space entry; Insecticides Act 1968 & PPQS fumigation accreditation (AlP); IMSBC Code adoption; Port DG rules"],ka:["New Mangalore Port (coal/iron ore handling) regulations; DGFASLI Dock Safety Mangalore"],tn:["Kamarajar (coal), V.O. Chidambaranar (coal, fertiliser), Chennai Port regulations; DGFASLI Dock Safety Chennai; TNPCB dust norms at ports"],osha:["29 CFR 1918.93 (hazardous atmospheres in holds), 1918.94 (ventilation/fumigants), 1918.25 (ladders), 1917 Subpart B (confined/hazardous atmospheres), 1910.146, 1910.1000 (phosphine 0.3 ppm)"],intl:["SOLAS Reg. XI-1/7 (atmosphere testing instruments), IMO Res. A.1050(27) (enclosed-space entry), IMO MSC.1/Circ.1264 (safe use of pesticides in ships — fumigation), IMSBC Code","ILO Code of Practice Ports (2016); ICHCA/InterManager enclosed-space guidance; UK MCA MGN 659"]},checklist:"cl4-hold-entry"},
{id:"p3-mooring",t:"Mooring Operations, Snap-Back & Ship–Shore Interface",cat:"Construction",tags:["Ports & Marine","Transport","Construction"],purpose:"Prevent deaths and amputations from parting mooring lines, falls between ship and quay, drowning and gangway incidents during berthing, unberthing, shifting and cargo watch at ports, jetties and SPMs.",scope:"Shore mooring gangs and linesmen, mooring boats, bollards and quick-release hooks, ship's mooring decks and winches, gangways/accommodation ladders, ship–shore access control, tugs and pilot transfers, tanker jetties with ESD and breakaway couplings.",roles:["Port/terminal marine supervisor","Mooring gang foreman and linesmen (trained)","Ship's officers and crew (OCIMF MEG4 practices)","Mooring boat coxswain","Jetty operator / loading master (tankers)"],hazards:["Snap-back: a parting line (synthetic or wire) recoils at high speed across the whole mooring area — the entire deck/quay zone is a potential snap-back zone (MEG4); HMPE lines recoil less but still kill","Bights and tension: standing in or stepping over a bight; hands on drum/bollard while heaving; heaving lines with weighted monkey's fists","Line surge on rising/falling tide, passing ships, swell; bollard failure (overloaded or corroded)","Falls into water between ship and quay (crushed by hull), from quay edge in dark/wet; mooring boat capsizing; gangway without net, unsecured, steep at tidal extremes; no lifejacket","Tankers: hose/arm failure, static, vapour; night, fatigue, poor communication (language), lighting; vehicle traffic on quay during mooring"],pre:["Mooring plan agreed ship–shore before arrival: number/position of lines, bollard SWL vs line MBL, tidal range, weather (wind/swell limits for berthing/remaining alongside), tug use, communication channel (VHF) and language","Emergency release (quick-release hooks tested)","Linesmen trained (line handling, snap-back awareness, boat safety), fit; minimum team size per line; PPE incl. lifejackets (EN ISO 12402-3 150 N) within 2 m of quay edge or on boats","Quay edge lighting ≥ 20 lux (verify), lifebuoys with lines every 50 m, ladders at intervals for self-rescue","Bollards/hooks inspected and load-tested (periodic — verify), corroded or cracked bollards taken out of service","Snap-back and no-standing zones marked on quay/deck as 'whole area' with warning signs; heaving lines without added weights","Gangway/accommodation ladder: ship's responsibility but shore verifies — safety net rigged, angle ≤ 55° (verify), handrails, secured against surge, lit, lifebuoy at foot, access controlled (ISPS)","Only authorised persons board","Tanker jetties: ESD, breakaway couplings, drift/excursion alarms, ISGOTT ship–shore checklist, mooring tension monitoring where fitted; weather and swell limits for disconnect"],steps:["Pre-berthing: foreman briefs gang on berth plan, tide, line sequence, snap-back zone rules and stop signals; verify boat, PPE, lighting, bollard condition and quay traffic stopped.","Receiving lines: stand clear of quay edge until line is in reach; never grab a line until it is slack and on the quay; keep clear of bights; one hand for the line, eyes on the ship's winch.","Making fast: eye over bollard in correct sequence (dip the eye when two lines on one bollard), step back out of the line path, signal 'fast' to ship; never stand between line and quay edge or in line of pull.","Heaving/tension: watch for line creaking, strand breaks, kinks; if a line appears over-tensioned or chafing — warn ship and stand well back; do not approach a tensioned line.","Letting go: only on ship's order, with winch slack confirmed; slip eye off bollard and step away; quick-release hooks operated from safe position; keep hands clear of hook jaws.","Mooring boat: coxswain in charge, lifejackets for all, no overloading, keep clear of propeller wash and lines in water, communicate with quay and ship.","Cargo watch alongside: check lines each watch and at tide changes; report slack/tight lines; weather change → extra lines or cease cargo and prepare to depart per plan.","Gangway: verify net and securing each shift; no one on gangway while ship shifts; persons who fall into water → lifebuoy, alarm, boat rescue — never jump in.","Tankers: ISGOTT checklist, ESD test, hose/arm connection with PPE, spill containment, no hot work or phones in zone, continuous watch at manifold.","Incident/near miss (line parted, person in water) reported to port authority; investigate with ship; review mooring plan; annual training refresher and drills (man-overboard, line parting)."],ppe:["Lifejacket (150 N) near quay edge and in boats, helmet, hi-vis, gloves (not loose), safety boots with grip, eye protection; hearing protection near winches; torch at night"],stop:["Person in snap-back/line-of-pull zone during tensioning","Bollard SWL below line MBL or bollard damaged","Linesman without lifejacket at quay edge/boat","No communication with ship's mooring officer","Gangway without net or unsecured; weather beyond berth limits"],records:["Mooring plans and ship–shore agreements, bollard/hook inspection and test records, linesman training, PPE/lifejacket inspections, lighting and lifebuoy checks, gangway checks, incident and near-miss reports, drill records"],refs:{india:["Dock Workers (Safety, Health & Welfare) Regulations 1990 (access to ships, gangways, lifesaving appliances, lighting — verify regs); OSH Code 2020","Indian Ports Act 1908 & Major Port Authorities Act 2021 (port rules on mooring/berthing); Merchant Shipping Act (ship-side duties); IS 13416 Pt 5 / IS 14946 (lifejackets — verify)"],ka:["New Mangalore Port Authority marine regulations; Karnataka Maritime Board minor ports (Karwar, Belekeri)"],tn:["Chennai/Kamarajar/VOC Port marine departments; TN Maritime Board (Cuddalore, Nagapattinam); TNFRS marine wing"],osha:["29 CFR 1917 (marine terminals — 1917.124 gangways/ladders, 1917.26 first aid/lifesaving, 1917.123 illumination), 1918.22 (gangways); 1926.106 (working over water)"],intl:["OCIMF Mooring Equipment Guidelines (MEG4, 2018) — snap-back and line management; ISGOTT 6 (tanker ship–shore); ILO Code of Practice Ports (2016)","IMO MSC.1/Circ.1620 (mooring safety); UK MCA Code of Safe Working Practices Ch. 26 (mooring); EN ISO 12402 (lifejackets); PIANC guidelines"]},checklist:"cl4-mooring"},
{id:"p3-dg-container",t:"Dangerous Goods in Containers – IMDG Handling, Fumigated Units & Leak Response",cat:"Chemical",tags:["Ports & Marine","Chemical","Transport","Fire"],purpose:"Prevent fires, explosions, toxic exposures and environmental releases from dangerous goods and fumigated cargo transport units in ports, CFSs, ICDs and warehouses, including mis-declared and leaking containers.",scope:"IMDG classes 1–9 in containers and tank containers; DG yards and segregation; stuffing/de-stuffing and customs examination at CFS; fumigated and off-gassing containers; ammonium nitrate, calcium hypochlorite, lithium batteries, charcoal, fish meal; leaking or damaged units.",roles:["Port/CFS DG officer","Terminal planners (segregation)","Stevedores, CFS workers, customs examiners","Fumigation contractor (licensed)","ERT/fire service (hazmat); PESO (explosives/AN)"],hazards:["Mis-declared or undeclared DG (Tianjin 2015, Beirut 2020 benchmarks): ammonium nitrate stored long-term, calcium hypochlorite self-heating, charcoal/fish meal self-ignition, lithium battery fires, compressed gases","Fumigated containers: phosphine/methyl bromide residue at lethal levels when doors opened; unmarked units","Off-gassing from goods (toluene, formaldehyde, benzene, 1,2-dichloroethane) in CFS de-stuffing — workers overcome on entry","Leaks: corrosives, toxics, flammables from drums/IBCs; incompatible goods in one unit; tank-container valve leaks; reaction with water from firefighting; environmental release to harbour","Fire in stack spreading to adjacent DG; explosives in transit; container-top/door injuries during inspection; heat accelerating decomposition"],pre:["DG acceptance: Dangerous Goods Declaration, UN number, class, packing group, SDS, placards/marks on all four sides, CSC plate","Port DG rules and MSIHC/Explosives/Ammonium Nitrate Rules compliance; refusal of undeclared/mis-declared units; direct delivery for Class 1 and AN (no storage beyond permitted hours — verify)","Segregation per IMDG Code segregation table in a dedicated DG yard with separation distances, shade for Class 5.1 (calcium hypochlorite ≤ 35 °C — verify)","Away from occupied buildings, drainage containment, fire hydrants/monitors, CCTV, access control, inventory updated in real time with max quantities per class","Fumigated CTUs: IMDG 5.5.2 warning mark (UN 3359 'Fumigated unit'), register of fumigated/ventilated units","De-stuffing only after ventilation (door opening by trained person from side with respirator) and gas test (PH3, MeBr, SF; VOCs) by competent person; licensed fumigator for treatment and clearance","Emergency: port hazmat plan (EmS codes, ERG/CHEMTREC-style data), PPE (Level A/B suits, SCBA), absorbents, neutralisers, overpack drums, spill booms for harbour","Fire service familiar with DG yard; evacuation distances per ERG (e.g. 800 m for AN fire — verify)","Training: IMDG Code Ch. 1.3 training for all DG-handling staff (function-specific), refresher 2 years; customs examiners trained in container-atmosphere hazards"],steps:["Receipt: verify documents vs placards; check for damage, leaks, odour, heat (IR thermometer), bulging; non-compliant unit → hold area, notify shipper/agent and DG officer.","Placement: TOS/yard plan enforces segregation and quantity limits; Class 1 and AN handled by direct delivery under PESO licence conditions; reefers with DG checked for power.","Daily DG yard round: thermal check of 4.2/5.1 units and lithium battery units, leak/odour check, drainage closed, hydrants clear, inventory reconciled.","Opening any container for examination/de-stuffing: check fumigation register and marks","Crack doors from the side, step back, ventilate ≥ 30–60 min (verify), gas test at breathing height inside before entry; use respirator per reading; never enter a unit with strong odour.","Fumigation on site: licensed fumigator, exclusion zone, placards, gas-tight sealing, exposure period, aeration and clearance certificate before release; residues disposed by fumigator.","Leaking unit: isolate zone (upwind), identify product (UN number/SDS), ERT in appropriate PPE, stop leak/overpack, contain runoff (block drains), decontaminate, dispose as hazardous waste","Notify port authority, SPCB and shipper.","Fire in DG yard: alarm, evacuate per ERG distances, inform fire service of contents (class, UN numbers, quantities)","Isolate adjacent units by removal if safe, no water on water-reactive goods (Class 4.3), avoid runoff to harbour where possible.","Heat/weather: shade and ventilation for 5.1/organic peroxides (5.2 temperature-controlled), cyclone plan to clear DG yard or secure.","Customs/examination staff: no entry to units until atmosphere cleared; forklifts with DG-rated operators; no smoking/phones in DG yard.","Audit monthly: segregation, marks, inventory vs limits, fumigation register, PPE and spill kits, training currency; incidents and refusals reported to port DG committee."],ppe:["Standard terminal PPE plus chemical gloves and goggles for DG handling, respirator (ABEK/P3) for container opening, Level A/B suits and SCBA for ERT, face shield; IR thermometer and gas detector as 'PPE' for inspectors"],stop:["Undeclared/mis-declared DG or missing placards","Fumigated or odorous container opened without ventilation and gas test","Segregation table or quantity limit breached in yard","Ammonium nitrate or explosives stored beyond permitted period/conditions","Leaking or heating unit left in stack"],records:["DG register and acceptance records (DGD, SDS), yard plan and segregation checks, fumigation register and clearance certificates","Gas-test logs for container opening, daily DG rounds, incident/leak/fire reports, training records (IMDG 1.3), PESO licences"],refs:{india:["IMDG Code (mandatory via Merchant Shipping Act / DG Shipping); port Dangerous Goods regulations under Indian Ports Act 1908 / Major Port Authorities Act 2021","Explosives Rules 2008 & Ammonium Nitrate Rules 2012 (port storage limits, licences)","MSIHC Rules 1989 (storage thresholds); HOWM Rules 2016 (Basel/imports); Insecticides Act 1968 & PPQS (fumigation); Dock Workers Regulations 1990; CTU Code (stuffing)"],ka:["New Mangalore Port DG rules; KSPCB; PESO Bengaluru/Mangalore"],tn:["Chennai/Kamarajar/VOC Port DG rules; TNPCB; PESO Chennai; Customs Chennai CFS examination SOPs"],osha:["29 CFR 1917.22 (hazardous cargo), 1917.23 (hazardous atmospheres & substances), 1918.96 (hazardous cargo); 1910.120 HAZWOPER; 1910.1200; 49 CFR 171–180 (HMR); NFPA 400 (hazardous materials code)"],intl:["IMDG Code (Amdt 42-24) incl. 5.5.2 fumigated units & Ch. 1.3 training; IMO/ILO/UNECE CTU Code 2014; ERG 2024; ILO Code of Practice Ports (2016)","EU/UK fumigated-container guidance (HSE, Dutch Labour Inspectorate studies on off-gassing); IAEA for Class 7"]},checklist:"cl4-dg-container"},
{id:"p3-sugar",t:"Sugar Mills – Cane Yard, Mills, Centrifugals, Bagasse Fire & Sulphur/Lime",cat:"Industrial",tags:["Agri","Industrial","Fire","Process Safety"],purpose:"Prevent vehicle and conveyor fatalities in cane yards, entanglement in mills and centrifugals, bagasse and sugar-dust fires/explosions, SO2 and lime burns, and pressure-vessel incidents through the crushing season.",scope:"Cane yard and weighbridge traffic, unloaders and cane carriers, knives/shredders, mill tandem, bagasse handling and storage, boilers and co-generation, juice heaters/evaporators/pans, sulphitation and lime, centrifugals, sugar dryers/silos, molasses tanks, ETP; off-season maintenance.",roles:["Chief engineer / factory manager","Cane yard controller and traffic marshals","Mill house, boiler (certified attendants) and process operators","Centrifugal station in-charge","Safety officer; fire crew; occupational health"],hazards:["Cane yard: trolleys overturning/rolling, workers crushed between vehicles, unloader grabs, night fatigue, bullock carts; falls from loaded trolleys; carrier/conveyor nip points and hand-feeding of cane","Mills: roller nips, Donnelly chute/knife/shredder access while running, bagasse carrier entanglement; centrifugals: basket burst (1,000–1,500 rpm), lid opened while spinning, hand in basket","Bagasse: spontaneous heating in stacks and dust explosion in conveyors/boiler bunkers; sparks from boiler chimneys igniting bagasse yard; sugar dust explosions in dryers/graders/silos (St 1)","Sulphur burner SO2 (TLV 0.25 ppm STEL), lime slaking (CaO exothermic, burns), hot juice/syrup/massecuite scalds, evaporator/pan vessel failure, molasses tank CO2/ethanol (confined), boiler incidents, HT switchyard","Seasonal migrant labour untrained"],pre:["Cane yard traffic plan: one-way flow, marked waiting lanes, speed ≤ 10 km/h, marshals with radios, lighting, separate pedestrian routes, unloading only when driver clear, no riding on loaded trolleys","Weighbridge queue management; cart/bullock separation","Mill house guarding per Factories Act ss.21–22: cane carrier and bagasse conveyor nip guards, pull-wire stops along carriers, interlocked covers on knives/shredders, no hand feeding (Donnelly chute), LOTO for choke clearing","Centrifugals per state schedule — interlocked lid (cannot open until basket stopped), basket inspection/NDT yearly, over-speed trip, vibration monitoring","Bagasse: stack height/size limits with fire breaks (≥ 15 m — verify), temperature probing of stacks, water monitors and hydrant ring","Spark arrestors on boiler stacks, bagasse conveyor dust control (enclosure, Ex equipment in bunkers), housekeeping","Sugar dust: DHA, Ex zoning, venting on dryers/silos, housekeeping","Boilers under Boilers Act 2025/IBR with certified attendants/BOE; pressure vessels (evaporators, pans, juice heaters) registered and tested","Sulphur burner enclosure and SO2 detection, scrubber; lime slaker guarding and PPE; molasses tanks as confined spaces","Seasonal workforce induction (see seasonal procedure); heat plan; first aid and OHC for 24×7 season; fire crew trained; MSIHC/PESO checks for ethanol/distillery where attached"],steps:["Season start: pre-season audit of guards, interlocks, pressure-vessel certificates, boiler certificate, fire system, traffic plan, bagasse yard layout","Refresher training for permanent staff; induction for seasonal workers before posting.","Cane yard: marshals control each unloading bay; drivers out of cab and in marked zone during grab unloading; trolleys chocked; no manual pushing of trolleys; night lighting checked.","Cane carrier/mills: never clear chokes while running — stop, isolate, use tools; pull-wire tests each shift; knives/shredder covers interlocked; two persons for roller setting under LOTO.","Centrifugals: check lid interlock and brake each shift; never hand-wash basket while turning; load within rated charge; vibration/over-speed trips tested weekly; annual basket NDT.","Bagasse yard: probe stack temperatures daily (alarm > 60–70 °C — verify), rotate stock, keep fire breaks clear, no hot work, water monitors ready; conveyor dust housekeeping each shift.","Boiler house: certified attendant only; blow-down, low-water cut-off tests; bagasse bunker fires — isolate feed, inert/flood per plan; ash handling PPE.","Process house: sulphur burner started by trained operator with SO2 detector; lime added slowly with face shield","Hot-liquor valves operated from side; pan/evaporator entry under confined-space permit after cooling and isolation.","Sugar house: dryers/graders/silos — dust housekeeping, Ex equipment, venting intact; bagging ergonomics (50 kg bags — mechanical aids).","Molasses/ETP: tank entry permit with gas test (CO2, ethanol, H2S); spent-wash lagoons fenced; biogas plant Ex controls.","Weekly season review: injuries/near misses, traffic violations, stack temperatures, interlock faults; off-season: maintenance under PTW/LOTO, confined-space and hot-work controls, contractor management."],ppe:["Helmet, hi-vis (cane yard), safety boots, gloves, face shield and apron (lime/sulphur/hot liquor), hearing protection (mill house), FFP2 (bagasse/sugar dust), heat gloves (pans/boilers), harness for stack/tank work"],stop:["Hand-feeding or choke clearing on running carrier/mill","Centrifugal lid interlock or over-speed trip inoperative","Driver/worker in unloading bay during grab operation","Bagasse stack temperature rising or fire break blocked","Boiler run by uncertified attendant / pressure vessel test overdue"],records:["Pre-season audit, traffic plan and marshal logs, guard/interlock checks, centrifugal inspection/NDT, bagasse stack temperature log","Boiler and pressure-vessel certificates, SO2 monitoring, confined-space permits, seasonal induction records, injury/near-miss log"],refs:{india:["Factories Act ss.21–23, 29, 31, 36, 37, 38 via state rules / OSH Code (seasonal factory provisions); Boilers Act 2025 & IBR; Boiler Attendants/BOE Rules 2011","Sch. II (SO2, dusts); Petroleum Rules (ethanol distilleries); MSIHC; HOWM (press mud/ETP sludge); MV Act (cane transport); Electricity Act/CEA (co-gen)"],ka:["Karnataka Factories Rules 1969 Rule 56 Schedule (centrifugal machines — verify) & Rule 129 schedules; Karnataka Boiler Rules 1982; KSPCB (sugar/distillery norms); Belagavi/Bagalkot sugar belt"],tn:["TN Factories Rules 1950 Rule 53 Schedule (centrifugal/hydro-extractors — verify) & Rule 61; TN Boiler Rules; TNPCB; TN Sugar Factories Control Act 1949 (cane supply)"],osha:["1910.212, 1910.219, 1910.147, 1910.272 (grain-like dust), 1910.1000 (SO2), 1910.146; NFPA 652/61/68 (sugar dust — Imperial Sugar 2008 CSB report), ASME BPVC"],intl:["ILO Code of Practice (agriculture) & ISO 45001; UK HSE food dust/sugar guidance; EN 12547 (centrifuges), ISO 12100; Sugar Industry Technologists / ISSCT safety papers"]},checklist:"cl4-sugar"},
{id:"p3-grain-mill",t:"Rice, Flour & Oil Mills – Grain Dust, Elevators, Husk Boilers, Fumigation & Bag Handling",cat:"Industrial",tags:["Agri","Industrial","Fire","Health"],purpose:"Prevent dust explosions and fires, grain engulfment, machinery entanglement, fumigant poisoning, solvent fires and manual-handling injuries in rice mills, flour/atta mills, dal mills, oil mills and warehouses.",scope:"Grain receipt and cleaning, driers, parboiling, hullers/polishers, roller and hammer mills, bucket elevators and conveyors, silos and flat godowns, bag stacking and loading, husk-fired boilers, hexane solvent extraction and expellers, fumigation of stacks and silos.",roles:["Mill owner/manager","Operators and maintenance","Boiler attendant (certified)","Warehouse/stack supervisor","Licensed fumigator; safety officer (where appointed)"],hazards:["Dust: flour/grain dust explosions originating in bucket elevators (belt slip, bearing heat), hammer mills, dust collectors","Grain dust respiratory disease (TLV 4 mg/m³); husk dust and rice husk ash (crystalline silica — verify)","Engulfment in silos/hopper bins and flat storage; bag-stack collapse (stacks > 15–20 bags high, wet bags); manual handling of 50–75 kg bags (ILO limit 55 kg benchmark; state rules max loads — verify) — back injuries","Machinery: hullers, polishers, roller mills, hammer mills, screw conveyors, elevator boots; unguarded belts; husk furnace fires, boiler incidents, hot parboiling water/steam scalds","Fumigation: aluminium phosphide (phosphine) — fatal exposures to workers and nearby residents; unlicensed use; residues; hexane solvent extraction — Class A petroleum fires/explosions (NFPA 36); rodenticides"],pre:["Dust explosion controls (NFPA 61/652 benchmark): elevators with belt-slip and alignment switches, bearing temperature monitoring, explosion vents to outside, magnets before mills","Dust collectors outside or vented, Ex-rated electricals in dusty areas (IS/IEC 60079-10-2 zones), housekeeping (no layers > 0.8 mm), no compressed-air blow-down near ignition sources, hot-work permit","Silo/bin entry per silo procedure (zero-entry policy, LOTO, lifeline, atmosphere test)","Bag stacking rules: stack height limit (e.g. ≤ 20 bags or per godown design — verify), dunnage, stepped/interlocked stacks, no climbing on stacks without ladders, 1 m clearance from walls","Manual handling: mechanical aids (conveyors, stackers, trolleys), two-person lifts for > 50 kg, bag weights reduced where possible, training in technique; heat plan for loading in summer","Machine guarding (Factories Act ss.21–22; young persons barred), LOTO for clearing chokes; boiler/furnace under Boilers Act/IBR with certified attendant; husk storage away from furnace, spark arrestors, water supply","Fumigation only by licensed fumigator (Insecticides Act 1968; PPQS accreditation for export): gas-tight covers/sealed silos, exclusion zone and placards, exposure period, aeration and clearance (PH3 < 0.3 ppm OSHA PEL","ACGIH TLV 0.05 ppm — verify), no fumigation near housing; solvent extraction per NFPA 36 and Petroleum Rules with hexane LEL monitoring"],steps:["Daily: housekeeping of dust (vacuum/sweep with dampening), check elevator belt tracking and bearing temperatures, dust collector operation, husk furnace area, guards in place.","Receipt/cleaning: magnets and destoners working (tramp metal ignition), aspiration on intake pits, dust suppression at unloading.","Driers/parboiling: hot water/steam valves operated with PPE, LPG/husk burners with flame failure, CO check in enclosed drier rooms, scald first aid.","Milling: clear chokes only after stopping and isolating; guards on hullers/polishers/rolls; hammer-mill doors interlocked; respirators in dusty sections.","Elevators/conveyors: respond to slip/alignment/bearing alarms immediately — stop and inspect; keep boots clean; explosion vents unobstructed.","Silos and bins: no entry without permit per silo procedure; break bridges from outside; LOTO on augers.","Bag stacking: follow height/pattern limits, inspect stacks for lean/wet bags, use ladders, keep aisles; loaders use mechanical aids and share loads; rotate crews in heat.","Fumigation: notify workers/neighbours, clear and seal area, licensed fumigator applies tablets with PPE, placards, locked for exposure period, aerate, test, remove residues; records; never allow workers to apply AlP.","Solvent extraction: Ex equipment, LEL monitoring, earthing, hot-work ban, hexane storage per licence, spent-meal desolventising; emergency plan.","Monthly: dust layer audit, Ex equipment check, boiler log review, stack audit, injury/MSD review; annual: elevator/explosion-vent inspection, electrical thermography, worker lung-function screening for dusty jobs."],ppe:["FFP2/FFP3 dust respirators, safety glasses, gloves, safety boots, hearing protection (hullers/polishers), heat gloves/face shield (parboiling), back-support training (not belts), harness/lifeline for silo work","Respirator with PH3 cartridge/SCBA for fumigator only"],stop:["Dust layers > housekeeping limit with equipment running","Elevator bearing/slip alarm ignored or vent blocked","Silo entry without permit/lifeline","Fumigation by unlicensed person or without exclusion/aeration","Bag stack leaning, over height or climbed without ladder"],records:["Housekeeping/dust audits, elevator sensor logs, Ex equipment register, silo entry permits, bag-stack inspections, manual-handling training","Boiler certificate and log, fumigation records (licence, placards, clearance), solvent licence/LEL logs, injury and respiratory screening records"],refs:{india:["Factories Act ss.14, 21–23, 34 (excessive weights), 36, 37 via state rules / OSH Code; state rules maximum permissible loads (TN/KA — verify); Boilers Act 2025/IBR","Insecticides Act 1968 & Rules 1971; PPQS fumigation accreditation; Petroleum Rules 2002 (hexane); IS/IEC 60079-10-2; FCI/CWC storage & stacking norms; FSSAI; Sch. II (grain dust, hexane 50 ppm)"],ka:["Karnataka Factories Rules 1969 (weights, fencing, dust); Karnataka Boiler Rules 1982; Raichur/Davanagere rice-mill clusters; KSPCB (husk boilers)"],tn:["TN Factories Rules 1950 (maximum permissible loads rule — verify number; dust); TN Boiler Rules; TNPCB; Red Hills/Tiruvarur rice mills"],osha:["1910.272 (grain handling facilities), 1910.212, 1910.147, 1910.146, 1910.1000 (grain dust, phosphine), 1910.1200; NFPA 61 (agricultural & food processing dust), NFPA 36 (solvent extraction), NFPA 68/69"],intl:["ILO Code of Practice (agriculture), ILO R128 (max weight); UK HSE grain dust & INDG guidance; EN 1127-1; ATEX; FAO fumigation manuals; EU phosphine guidance; ISO 11228 (manual handling)"]},checklist:"cl4-grain-mill"},
{id:"p3-seasonal",t:"Seasonal & Migrant Workforce Induction and Welfare",cat:"Management",tags:["Agri","Management","Welfare/Labour","Construction"],purpose:"Ensure seasonal, contract and inter-state migrant workers in sugar mills, gins, rice mills, cold stores, construction and plantations are legally engaged, inducted in their language, competent before working near hazards, and provided statutory welfare.",scope:"Recruitment through contractors/sardars, age and identity verification, registration (OSH Code inter-state migrant provisions, contractor licence), induction and job-specific training, buddy system, housing/camps, welfare facilities, wages and social security, health, grievance and exit.",roles:["Occupier/principal employer (HR and safety)","Contractors and labour suppliers (licensed)","Safety officer/trainer (multilingual)","Welfare officer (500+ workers) / HR","Medical officer / first aiders; workers' committee"],hazards:["Untrained workers placed on dangerous machines/vehicles in the first days (sugar season peaks); language barriers (Odia, Bengali, Hindi, Chhattisgarhi crews in TN/KA mills); supervisors assuming prior experience","Child/adolescent labour via contractors; no age proof; adolescents (14–18) in hazardous processes; women on night shifts without statutory conditions","Camps: poor sanitation, unsafe drinking water, LPG/stove fires, heat, vector-borne disease, snakebite, overcrowding; no first aid or transport at night; wage theft and debt bondage reducing willingness to report hazards","Lack of ESI (seasonal factories exempt) or EC coverage; no PPE issued by contractor; fatigue from 12-h shifts; no grievance channel"],pre:["Legal: contractor licence (OSH Code — 50+ contract workers threshold — verify), inter-state migrant registration and journey allowance (OSH Code Ch. XI), Form/portal registrations, age verification (Aadhaar/school certificate","None < 14; 14–18 not in hazardous processes per Child & Adolescent Labour Act Schedule), women's night-work conditions (consent, transport, security per state rules)","Induction package in workers' languages: pictorial site hazards, life-saving rules, PPE, emergency, reporting, welfare entitlements, grievance","Minimum 1 day general + job-specific training with competence sign-off before unsupervised work; colour-coded helmet/band for workers in first 30 days","Buddy/mentor system: each new worker paired with an experienced worker for 2 weeks; supervisors' span of control limited","No new worker on cane yard traffic, centrifugals, boilers, HT or confined spaces until trained and authorised","Welfare: drinking water (IS 10500), toilets/bathing (ratios per state rules), rest shelters, canteen (250+ workers — verify), crèche (50+ women)","First aid boxes and OHC/ambulance arrangements, camp standards (ventilation, space, fire safety, lighting, waste), vector control","Wages via bank with slips, PF/ESI or EC insurance; grievance box and committee including migrant representatives","Health: pre-placement fitness for hazardous jobs, vaccination advice (tetanus), TB/malaria awareness, heat plan, snakebite plan; records retained"],steps:["Before season/mobilisation: verify contractor licence and worker lists (name, age proof, origin state, skills); register inter-state migrants; agree PPE supply and induction responsibilities in contract.","Day 1: identity and age check at gate, medical screening for hazardous jobs, issue ID card and PPE, allot housing; induction in language with interpreter; test understanding (pictorial quiz/demonstration).","Day 1–3: job-specific training with supervisor; competence demonstrated and signed; buddy assigned; coloured identifier worn.","First 30 days: daily toolbox talk in language, supervisor checks, no lone high-risk work; feedback on unsafe conditions encouraged (no retaliation).","Camps: weekly inspection (water test, toilets, cooking area/LPG, electrical, lighting, waste, mosquito control); night transport/first aid arrangements posted; fire extinguishers and exits.","Wages and records: pay through bank on time, muster rolls, overtime limits, weekly off; EC/ESI coverage confirmed; welfare officer accessible.","Health: first-aid boxes stocked, OHC hours, ambulance tie-up, heat and snakebite protocols; sick workers not pressured to work; occupational disease/injury notified.","Grievance: multilingual helpline/committee; issues logged and closed; labour department helpline displayed (Shram Suvidha/state).","Season end: exit health check for hazardous exposures, settlement of dues, return journey allowance, feedback on safety; records retained for inspection.","Audit: monthly HR–safety audit of induction coverage (100% before work), training records vs job placement, camp conditions, wage compliance; corrective action with contractor; report to safety committee."],ppe:["Issued free by employer/contractor: helmet (colour-coded for new), safety shoes, hi-vis, gloves, dust mask, eye protection, task PPE; sized for women; replacement register"],stop:["Worker without induction/competence sign-off on hazardous task","Age proof missing or under-18 in hazardous process","Camp without safe water, sanitation or fire safety","Contractor without licence/registration for migrant workers","Wages or PPE withheld"],records:["Contractor licences, worker registers with age proof, migrant registrations, induction and competence records (language)","Buddy assignments, camp inspections, welfare facility checks, wage/PF/EC records, health records, grievance log, audits"],refs:{india:["OSH Code 2020 Ch. XI (inter-state migrant workers), Ch. on contract labour, ss.23–24 (welfare), s.6; OSH Central Rules 2026; Code on Social Security 2020 (EC, ESI — seasonal factory exemption s.1(4) ESI Act legacy — verify)","Child & Adolescent Labour (P&R) Act 1986 (amended 2016) & Schedule; Code on Wages 2019; BOCW rules (construction); Plantations provisions in OSH Code; Shram Suvidha Portal"],ka:["Karnataka Factories Rules 1969 (welfare, canteen, crèche); Karnataka Labour Dept migrant worker registration; Karnataka Shops & Establishments (night work for women, 2026 amendment)"],tn:["TN Factories Rules 1950 (welfare ratios); TN Labour Dept inter-state migrant worker registration (post-2023 drives); TN BOCW Welfare Board; Tiruppur/Coimbatore migrant worker guidelines"],osha:["1910.142 (temporary labour camps), 1928 (agriculture), 1910.1200 (HazCom — training in understandable language), OSHA Temporary Worker Initiative"],intl:["ILO C97/C143 (migrant workers), C184 (agriculture), C155/C187; ILO Code of Practice (agriculture); ISO 45001 cl. 7.3 (awareness), 7.4; Ethical Trading Initiative base code; GRI 403"]},checklist:"cl4-seasonal"},
{id:"p3-dg-room",t:"DG Sets, Fuel Day Tanks & Generator Rooms",cat:"Electrical",tags:["Facilities","Electrical","Fire","Environment"],purpose:"Prevent electrocution, auto-start injuries, CO poisoning, fuel fires, noise and emission violations at diesel generator installations in offices, hospitals, malls, data centres, sites and plants.",scope:"DG sets 15 kVA–3 MVA in rooms, basements, rooftops and acoustic enclosures; AMF/synchronising panels and changeover; starting batteries; diesel day tanks and bulk tanks; exhaust stacks; fuel transfer; maintenance and testing; waste oil.",roles:["Facility/electrical in-charge (authorised)","DG operators/technicians","AMC vendor (OEM-trained)","Fire officer","Environment coordinator (CPCB norms)"],hazards:["Automatic start on mains failure during maintenance — rotating fan/belts, hot exhaust (400–500 °C), 415 V live terminals; back-feed to grid if changeover fails (electrocutes utility workers)","CO and exhaust gases in basements/enclosures; hot exhaust pipes igniting combustibles; diesel spills on hot manifold; fuel day tank overfill/leaks; battery hydrogen and acid","Noise > 100 dB(A) inside enclosures; vibration; crush during engine lifting; falls from rooftop DG platforms; arc flash at synchronising panels; radiator fan guards missing","Statutory: diesel storage above PESO exemption, CPCB emission (CPCB IV+) and noise norms, stack height, used-oil handling"],pre:["Design/approval: CEIG/Electrical Inspectorate approval for DG above thresholds (CEA 2023 — verify capacity), licensed electrical contractor","Earthing (neutral and body) tested, changeover/ATS with mechanical and electrical interlock to prevent back-feed, emergency stop outside room, panel arc-flash labels","Room/enclosure: ventilation sized for engine heat and combustion air, exhaust piped to roof/stack at CPCB height (H = h + 0.2 × √kVA), insulated and clear of combustibles (≥ 0.5 m — verify)","CO detector in basements, fire detection and CO2/DCP/clean-agent extinguishers or fixed system per Fire NOC, no storage in DG room, lighting, signage 'May start automatically'","Fuel: day tank ≤ exempt quantity per Petroleum Rules (Class B — verify current exemption and container-size condition) or PESO licence, bund 110%, drip trays, overfill alarm/level gauge, shut-off valve, spill kit, no smoking","Bulk tank per tank procedure","Maintenance control: LOTO procedure — AMF to manual/off, battery disconnected, control fuse removed, test before touching; AMC vendor inducted; PTW for work on live panels (electrical); lifting plan for alternator/engine","Compliance: CPCB IV+ compliant engines for new installs (from 1 Jul 2023 — verify), acoustic enclosure 25 dB(A) insertion loss and 75 dB(A) at 1 m","Stack emission tests, used-oil to registered recycler (HOWM/used-oil EPR), running-hour and fuel logs for SPCB/CCTS Scope 1"],steps:["Weekly test run: inform occupants, check coolant/oil/fuel, battery, belts, guards, exhaust leaks, vibration; run on load 15–30 min; log readings; defects to AMC.","Before any maintenance: switch AMF to OFF/manual, disconnect battery negative, remove control fuse, lock and tag, verify engine cannot crank, isolate alternator breaker and test dead; allow exhaust to cool.","Work on changeover/synchronising panels: Electrical PTW, isolate both sources where possible, arc-rated PPE for live testing, insulated tools, second person.","Fuel transfer/filling: engine off (or per OEM), bonding of drums/tanker, drip trays, watch level gauge, stop at 90%; clean spills immediately; no filling in lightning.","Battery: ventilation, no sparks near terminals, PPE for electrolyte, insulated tools; replace swollen batteries.","Basement DG rooms: CO detector tested monthly, exhaust duct integrity, door seals; stop and ventilate on CO alarm; no occupancy during runs.","Noise: enclosure doors closed during runs, hearing protection inside enclosure, neighbour complaints logged; noise test yearly.","Emission: stack monitoring per SPCB consent, maintain injectors/filters, log running hours and diesel consumption (Scope 1 reporting).","Fire: hot exhaust clearance, no rags/combustibles, extinguishers inspected, fire detection linked to BMS; fuel leak → shut down, isolate, contain.","Annual: CEIG inspection where applicable, earth testing, insulation resistance, protection relay testing, acoustic enclosure check, PESO/SPCB compliance review, AMC and operator competence records."],ppe:["Hearing protection (SNR ≥ 25) inside enclosures, insulated gloves and arc-rated face shield for panel work, safety glasses, heat-resistant gloves, oil-resistant safety shoes, acid PPE for batteries"],stop:["AMF not disabled and battery not disconnected before work","Back-feed interlock defective or bypassed","CO alarm in basement/enclosure","Fuel leak or storage beyond licence/unbunded","Exhaust within clearance of combustibles / fire system impaired"],records:["CEIG approvals and test reports, DG log book (runs, readings), LOTO/PTW records, fuel receipts and stock vs licence, CO detector tests, noise and emission tests, AMC reports, used-oil manifests, fire system checks"],refs:{india:["Electricity Act 2003 & CEA Safety Regulations 2023 (installations, approvals, back-feed prevention, accident reporting); IS 3043 (earthing), IS 732, IS 1646, IS 5216; Petroleum Act & Rules 2002 (Class B diesel storage)","EP Act — CPCB DG set emission (CPCB IV+ from 2023 — verify) & noise norms (Schedule VI/Noise Rules; 75 dB(A) at 1 m), MoEF stack-height formula; HOWM Rules & Used Oil EPR 2023; NBC 2016 Part 4 (DG rooms); OSH Code"],ka:["CEIG Karnataka (DG approvals); KSPCB (consent, DG noise/emission); KSFES NOC conditions for DG in basements; BESCOM back-feed requirements"],tn:["CEIG Tamil Nadu; TNPCB; TNFRS; TANGEDCO conditions for captive DG/changeover"],osha:["1910.147, 1910.303–305, 1910.335, 1910.95, 1910.1000 (CO 50 ppm), 1910.106; NFPA 110 (emergency power systems), NFPA 37 (stationary engines), NFPA 70 Art. 700/701/702, NFPA 70E"],intl:["ISO 8528 (generating sets), IEC 60034; UK BS 7671 & HSE guidance on generators/back-feed; EN 50110-1; EU Stage V emission benchmark"]},checklist:"cl4-dg-room"},
{id:"p3-hvac",t:"HVAC Plant Rooms, Chillers & Refrigerant Handling",cat:"Industrial",tags:["Facilities","Industrial","Chemical","Environment"],purpose:"Prevent refrigerant asphyxiation and toxic decomposition exposure, pressure incidents, burns, falls and legionella risks in HVAC plant rooms, chillers, AHUs, rooftop units and refrigerant servicing in buildings and plants.",scope:"Centrifugal/screw chillers (R-134a, R-1234ze, R-514A, R-123 legacy), VRF/split systems (R-410A, R-32 A2L), ammonia/CO2 systems, propane (A3) chillers, AHUs and fan rooms, cooling towers, ducts and plenums, refrigerant recovery/charging, brazing, pressure testing, rooftop units.",roles:["Facility engineering head","HVAC technicians (refrigerant-handling trained)","AMC/OEM service engineers","Fire officer (hot work)","Safety officer; water-treatment contractor"],hazards:["Refrigerant leak in machinery room displaces oxygen (A1 refrigerants) — asphyxiation; A2L (R-32, R-1234yf) mildly flammable","A3 (R-290) flammable; B2L ammonia toxic; R-123 (toxic, ODS); decomposition to phosgene/HF when heated by brazing or fire","Pressure: compressor discharge, pressure testing with wrong gas (never oxygen/air — oil explosion), over-pressurised cylinders in heat, liquid-trapped lines; cylinder handling; frostbite from liquid refrigerant","Mechanical: AHU fan start during filter change, belt nips, chiller rotating parts; falls from rooftop units, AHU platforms, ladders; confined ducts/plenums/chilled-water tanks; hot surfaces and steam/hot water (calorifiers)","Electrical: VFD panels, capacitor banks; legionella in cooling towers and condensate; noise in plant rooms; chemical dosing (water treatment); ODS Rules compliance for HCFC phase-out and venting ban"],pre:["Machinery rooms per ASHRAE 15 / EN 378 benchmark: refrigerant detectors with alarm and automatic ventilation (setpoint per refrigerant RCL/TLV — e.g. 1,000 ppm R-134a alarm (verify))","Mechanical ventilation, self-closing doors opening outward, emergency shut-off switch outside, O2 monitor for large charges, no open flames, signage with refrigerant type and charge","Technicians trained and certified in refrigerant handling (recovery, charging, leak detection) — ODS Rules 2000 compliance: no venting","Recovery machines and cylinders; registration of servicing enterprises where required (verify); refrigerant log per system; retrofit plans for HCFC (R-22) phase-out","Pressure work: nitrogen (OFN) with regulator and PRV for pressure/leak tests at design pressure, never oxygen or compressed air","Refrigerant cylinders stored upright, shaded, ≤ 50 °C, valve caps; hot-work permit for brazing with refrigerant evacuated and OFN purge, fire watch, extinguisher","LOTO for AHUs/fans/chillers; guards on belts; fixed platforms/guardrails or anchors for rooftop units","Confined-space permits for ducts, plenums and tanks; chemical dosing with PPE, eyewash; cooling towers per legionella procedure","Emergency: escape respirators/SCBA for ammonia or large A1 charges, evacuation plan, ventilation override, refrigerant leak response (isolate, ventilate, no entry without O2 reading), first aid for frostbite/inhalation"],steps:["Daily round: detector/O2 status, ventilation, chiller alarms, leaks (oil traces), pressures/temperatures, plant-room housekeeping, no storage against panels.","Before service on a system: identify refrigerant and charge, isolate electrically (LOTO), recover refrigerant into rated cylinder (weigh, do not overfill > 80%), log quantity; never vent to atmosphere.","Leak testing: OFN at test pressure with gauge and relief; electronic leak detector; soap test; no refrigerant-oxygen mixtures.","Brazing: hot-work permit, system evacuated and purged with OFN flowing, ventilation on, fire watch, PPE; phosgene/HF awareness — stop if refrigerant smell/irritation.","Charging: by weight/sight glass per OEM, liquid/vapour per manufacturer, gloves and goggles; A2L/A3 — Ex-rated tools, ventilation, no ignition sources, charge limits per room size (EN 378).","AHU/fan work: LOTO, confirm fan stopped, guard belts after service, filter changes with respirator for dusty/microbial filters; condensate pans cleaned (microbial growth).","Rooftop units: edge protection/anchors, weather check, no work in lightning; ladders secured.","Ducts/plenums/tanks: confined-space permit, isolate fans and dampers, atmosphere test, attendant.","Refrigerant alarm/leak: leave room, activate ventilation, close door, isolate system if safe from outside, no re-entry until O2 and refrigerant readings safe; large/ammonia leaks → evacuate and ERT with SCBA.","Records and compliance: refrigerant inventory and loss rate (Kigali/ODS reporting), technician certificates, detector calibration, hot-work permits, pressure-test records, legionella scheme; review leaks > 5%/yr for repair."],ppe:["Safety glasses/goggles, cryogenic/insulated gloves for refrigerant, hearing protection in plant rooms, heat gloves","Harness on roofs, FFP2/3 for filters, escape respirator (plant rooms with large charges), SCBA for ammonia ERT"],stop:["Refrigerant/O2 alarm or ventilation failure in machinery room","Pressure test with oxygen or compressed air","Brazing without recovery/OFN purge and hot-work permit","AHU/fan not isolated before internal work","A2L/A3 charging with ignition sources or without ventilation"],records:["Refrigerant log per system (charges, recoveries, leaks), technician certificates, detector and O2 calibration, hot-work permits","Pressure-test records, LOTO, confined-space permits, roof work permits, legionella scheme and results, ODS compliance reports"],refs:{india:["Ozone Depleting Substances (Regulation & Control) Rules 2000 (as amended; HCFC phase-out, venting ban, servicing enterprise registration — verify) & India Cooling Action Plan/Kigali; IS 660 (mechanical refrigeration safety)","IS 4544 (ammonia); Gas Cylinders Rules 2016 (refrigerant cylinders); Factories Act s.31/36 via state rules / OSH Code; IS 3103 (ventilation); CEA 2023; NBC Part 8 (building services)"],ka:["Karnataka Factories Rules 1969; KSPCB (ODS/HFC reporting); KSFES"],tn:["TN Factories Rules 1950; TNPCB; TNFRS"],osha:["1910.147, 1910.146, 1910.1000 (refrigerant PELs), 1910.253 (brazing gases), 1910.101; ASHRAE 15 & 34 (safety classification), ASHRAE 188; EPA Section 608 (technician certification) as benchmark"],intl:["EN 378-1 to -4 (refrigerating systems safety), ISO 5149, ISO 817 (refrigerant designation/safety class); IIAR 2 (ammonia)","UK F-Gas Regs & IOR safety guides; EN 13313 (competence of personnel); EIGA (nitrogen pressure testing)"]},checklist:"cl4-hvac"},
{id:"p3-lift-mr",t:"Lifts & Escalators – Machine Rooms, Pits, Car-Top Work & Passenger Release",cat:"Industrial",tags:["Facilities","Industrial","Electrical"],purpose:"Prevent falls into hoistways, crushing by cars and counterweights, electrocution and entrapment injuries during lift and escalator maintenance, inspection and passenger rescue in buildings, malls, hospitals and factories.",scope:"Passenger, goods, hospital/bed and fire lifts (traction, MRL, hydraulic), service lifts, escalators and travelators; machine rooms, hoistways, pits, car tops, landing doors and interlocks; maintenance contractors; trapped-passenger release; statutory licensing and inspection.",roles:["Building owner/occupier (licensee)","Lift maintenance contractor (licensed firm, trained mechanics)","Facility manager / security (first response to entrapment)","Electrical Inspectorate (Lifts Act licensing, inspection)","Safety officer"],hazards:["Landing door opened with no car present — persons fall into shaft (the leading cause of lift deaths); door interlocks bypassed with jumpers by mechanics; passengers climbing out of stalled car between floors","Mechanic on car top struck by overhead/crushed in headroom when car moves at normal speed; pit work with car descending or counterweight","Falls into pit from landing; stored energy (hydraulic pressure, buffer springs, suspended loads)","Electrical: live controllers, 415 V in machine room, lighting circuits separate from mainline; brake release manual operations; ropes/sheaves pinch points; escalator step/chain drives and comb plates during maintenance","Untrained security/facility staff attempting passenger release — forcing doors, moving car; fire/smoke in shaft; hospital bed lifts with patients"],pre:["Statutory: lift installation permission and operating licence under state Lifts Act (TN 1997 / KA 2012 — amendments 2025–26","Verify periods), periodic inspection by Electrical Inspectorate, maintenance by licensed firm under written AMC","Licence and load-capacity notices displayed in car, lift log book, ARD (automatic rescue device) and intercom/alarm working","Safe working rules for mechanics: no 'jumpers' on door interlocks except per OEM procedure with controlled removal","Car-top work only in INSPECTION mode at reduced speed with stop switch, car-top guardrail (where clearance > 0.3 m — verify EN 81-20), two persons for hoistway work","Pit stop switch and ladder; LOTO at mainline and car-light switches before work in machine room/controller","Trapped-passenger release: only by trained lift mechanics (or trained facility staff for ARD-equipped lifts per written procedure): confirm car position","Switch off mainline, release only when car within landing zone (≤ 0.3–0.5 m — verify), never pull passengers out when car is between floors beyond zone","Reassure via intercom; target response ≤ 30 min","Hoistway/machine-room access control: locked doors (keys controlled), signage, lighting, no storage","Landing-door emergency keys controlled by trained staff only; fire lift provisions per NBC; escalators: emergency stops, comb-plate/skirt guards, pit LOTO","Contractor management: induction, PTW for hoistway/machine-room work, barricading of landings during work, communication, lifting plan for motor/machine replacement"],steps:["Monthly maintenance visit: contractor signs in, posts 'lift under maintenance' barriers at landings, isolates as required (LOTO), checks door interlocks, brakes, ropes (discard criteria), safety gear, ARD, alarm/intercom","Records in log book.","Car-top access: call car to floor below, open landing door with key, operate car-top stop switch, set INSPECTION mode, step on car top only after confirming stop","Move only at inspection speed with stop in hand; stand clear of counterweight and overhead.","Pit access: stop switch on, light on, car parked above with doors mechanically blocked or car in inspection with second person at controls; use pit ladder; never enter pit under a car that can move normally.","Machine room/controller: LOTO mainline, verify dead, discharge capacitors (VVVF drives — wait per OEM), guard sheaves; manual brake release only with two persons and car movement controlled.","Door interlock faults: repair, never bypass permanently; test every landing door lock before returning lift to service; remove any jumper before leaving.","Return to service: all persons out of hoistway, tools removed, inspection switches reset, test run with doors; remove barriers; log.","Trapped passengers: security confirms lift and floor from indicator/intercom, calls mechanic/ARD operates","Keeps talking to passengers, tells them not to force doors; medical emergency → fire service; release by trained person per rule; record time and cause.","Escalator maintenance: LOTO, barricade both ends, work in pits with second person, replace step chains per OEM; daily visual (comb plates, skirts, handrail) by facility staff.","Fire/emergency: lifts recalled to ground (fireman's switch), fire lift for fire service only, evacuation by stairs; hospital bed lifts with ARD and emergency power.","Annual: statutory inspection and licence renewal, rope/brake/safety-gear tests, ARD and emergency-power tests, AMC review, trapped-passenger drill with security","Incidents (falls, entrapments > 1 h, injuries) reported to Inspectorate as required."],ppe:["Safety shoes, gloves, safety glasses, helmet in hoistway/pit, insulated tools and gloves for controller work, harness where car-top clearance/guardrail inadequate, torch, hi-vis for landing barricading"],stop:["Door interlock bypassed with lift in normal service","Car-top or pit work without INSPECTION mode/stop switch and second person","Passenger release attempted by untrained person or with car outside landing zone","Licence/inspection expired or AMC lapsed","Landing door opened without confirming car present"],records:["Lifts Act licence and inspection reports, AMC and maintenance log book, LOTO/PTW records, door-interlock test records","ARD/alarm tests, entrapment log with response times, trained-releaser list, escalator inspections, incident reports to Inspectorate"],refs:{india:["Tamil Nadu Lifts & Escalators Act 1997 & Rules (amended 2025/Feb 2026 — online applications, licence 5 yrs — verify); Karnataka Lifts, Escalators & Passenger Conveyors Act 2012 & Rules (amended 2025 — verify)","IS 14665 series (electric traction lifts), IS 17900 (lifts — verify), IS 14671 (hydraulic), IS 15259 (escalators — verify)","NBC 2016 Part 8 Sec. 5 & Part 4 (fire lifts); CEA 2023; Factories Act s.28 (hoists & lifts) via state rules / OSH Code"],ka:["Karnataka Electrical Inspectorate (CEIG) lift licensing & inspections; KSFES (fire lift)"],tn:["TN Electrical Inspectorate (CEIG) licensing (e-Forms 1–34 — verify); TNFRS"],osha:["1910.147 (LOTO), 1910.27, 1910.333; ANSI/ASME A17.1/CSA B44 (safety code for elevators), ASME A17.2 (inspection), A17.4 (emergency evacuation of passengers); NEII/EESF guidance"],intl:["EN 81-20/EN 81-50 (lifts), EN 115 (escalators), EN 81-28 (remote alarm), EN 13015 (maintenance); UK LOLER 1998 & HSE PM7 (lift maintenance), SAFed guidance on entrapment release; ISO 8100 series"]},checklist:"cl4-lift-mr"},
{id:"p3-housekeeping",t:"Housekeeping & Soft-Services Contractors – Chemicals, Façade Access, Waste & Dignity",cat:"Management",tags:["Facilities","Management","Health","Chemical"],purpose:"Protect housekeeping, pantry, waste and façade-cleaning contract staff from chemical, sharps, slip, height and biological hazards and ensure statutory welfare, dignity and prohibition of manual scavenging.",scope:"Office, hospital, mall, campus and plant housekeeping; toilet and floor chemicals; high-level and façade cleaning (MEWPs, gondolas/BMUs, rope access); waste segregation (biomedical, e-waste, hazardous); pantry/LPG; septic tanks and drains (no manual entry); women and night shifts.",roles:["Facility manager (principal employer)","Housekeeping contractor (licensed, trained supervisors)","Housekeeping staff","Infection control/EHS (hospitals)","Security (night escort); POSH committee"],hazards:["Chemicals: HCl-based toilet cleaners (10–30%) with bleach → chlorine gas; caustic drain openers; phenyl/solvents; decanting into unlabelled bottles; splashes to eyes; no gloves","Sharps and biomedical waste (needles in bins, blood spills) — HBV/HCV/HIV; infectious laundry","Falls on wet floors (own and others), ladders for high dusting, façade work from gondolas/BMUs without harness or inspection; electrical (wet mopping near sockets, floor machines)","Manual scavenging: cleaning septic tanks/sewers/drains by hand — fatal H2S/asphyxia; illegal under PEMSR Act 2013; ergonomics (bent mopping, bin lifting), heat on terraces, pest-control chemicals, LPG in pantries","Exploitation: underpayment, no PPE, long hours, harassment of women on night shifts, no toilets/changing rooms for staff"],pre:["Contract terms: minimum wages, PF/ESI, PPE and training supplied, supervisors trained, prohibition of manual scavenging and septic/sewer entry (mechanised cleaning only), POSH compliance, grievance channel","Principal employer verifies monthly","Chemical control: approved list with SDS in local language, colour-coded and labelled dispensers/bottles (no decanting into drink bottles)","Dilution charts, never-mix rule (acid + bleach), dosing stations, eyewash/first aid, gloves/goggles for toilet cleaning","Storage room ventilated, locked, bunded","Height and façade: no ladders above 3 m for cleaning — use MEWPs/scaffold/BMU/rope access by trained persons","Gondola/BMU tested 12-monthly (LOLER/BOCW benchmark), daily pre-use, harness to independent anchor, wind limits, exclusion below; WAH permit","Biomedical/sharps: puncture-proof containers, colour-coded BMW segregation (BMW Rules 2016), spill kits, hepatitis B vaccination and post-exposure prophylaxis protocol for hospital staff, no hand compaction of waste","e-waste/hazardous waste segregated with manifests","Welfare and dignity: toilets, changing rooms, rest area, drinking water for contract staff; women's night-shift conditions (consent, transport, security, two or more)","ID cards; training in language with pictograms; floor-cleaning schedules to limit wet-floor exposure (signage, barriers)"],steps:["Daily start: supervisor allocates tasks, checks PPE, chemicals in labelled bottles, wet-floor signs, equipment (RCD-protected machines, cables), ladders condition; briefs on special risks (events, spills).","Toilet/floor cleaning: gloves and goggles, ventilate, one chemical at a time, rinse between acid and bleach products, wet-floor signs both ends, mop with technique to reduce bending","Report splashes immediately and use eyewash.","High dusting/light fittings: isolate electrical where touching fittings, use platform steps with handrail or MEWP; no standing on furniture.","Façade/atrium cleaning: WAH permit, trained operators, gondola/BMU checks, harness and lifeline, communication, weather check, exclusion zone and signage below.","Waste: segregate at source, sharps only in puncture-proof bins, no hands inside bins, lift with legs/trolleys, BMW bags ≤ 3/4 full and sealed, store in designated area; manifests for BMW/hazardous/e-waste.","Spills (blood/body fluids): gloves, absorbent, disinfectant (1% hypochlorite), dispose as BMW, wash hands; needlestick → wash, report, PEP within 2 h.","Drains/septic tanks/sumps: no manual entry — mechanised cleaning by licensed agency; facility to prove alternatives","Any sump/pit entry is a confined space under permit by trained persons with gas test and retrieval, never housekeeping staff.","Pantry/LPG: cylinder storage, regulator/hose checks, leak response; electrical appliances RCD-protected; kitchen fire extinguisher (Class F).","Night shifts: minimum two staff, security escort to transport, well-lit routes, panic/call system; POSH awareness and complaint route displayed.","Monthly: principal employer audit (wages, PPE, training, chemical labels, BMW compliance, welfare), incident review, staff feedback; annual health check for hospital housekeeping; vaccination records."],ppe:["Nitrile/rubber gloves, goggles/face shield for toilet and chemical work, non-slip shoes, aprons, FFP2 for dusty/biological tasks, puncture-resistant gloves for waste, harness and helmet for façade/height, hi-vis for outdoor"],stop:["Manual entry into septic tank, sewer or drain","Mixing acid cleaner with bleach / chemicals in unlabelled bottles","Façade or height cleaning without permit, trained operator and fall protection","Sharps handled by hand or compacted","Woman on night shift alone or without transport/security"],records:["Contractor compliance file (licence, wages, PF/ESI), training (language), chemical list and SDS, PPE issue, WAH permits and gondola inspections","BMW/hazardous/e-waste manifests, needlestick/injury log, vaccination records, POSH committee records, monthly audits"],refs:{india:["OSH Code 2020 (contract labour, welfare, women night work) & Central Rules 2026; Prohibition of Employment as Manual Scavengers & their Rehabilitation Act 2013 & Rules","BMW Management Rules 2016; E-Waste Rules 2022; HOWM Rules; POSH Act 2013; Minimum Wages/Code on Wages; BOCW rules (gondolas/BMUs); IS 17859 (GHS); state Shops & Establishments Acts"],ka:["Karnataka Shops & Commercial Establishments Act (2026 amendment on women's night work); Karnataka Contract Labour Rules; KSPCB (BMW authorisation)"],tn:["TN Shops & Establishments Act 1947; TN Contract Labour Rules; TNPCB BMW authorisation; TN Manual Scavenging monitoring (Madras HC orders)"],osha:["1910.1030 (bloodborne pathogens — sharps, PEP), 1910.1200, 1910.22 (walking surfaces), 1910.146, 1910.67 (MEWPs), 1910.27(b) (rope descent); ANSI/IWCA I-14.1 (window cleaning)"],intl:["UK HSE cleaning industry guidance (chemicals, slips, window cleaning), LOLER (BMUs), Working at Height Regs; EN 1808 (BMUs/gondolas); ISO 45001 cl. 8.1.4 (contractors); ILO C189 (domestic/cleaning workers — benchmark)"]},checklist:"cl4-housekeeping"},
{id:"p3-events",t:"Events, Temporary Structures & Crowd Management",cat:"Management",tags:["Facilities","Management","Fire","Construction"],purpose:"Prevent crowd crush, structural collapse, fire, electrical and heat incidents at corporate events, exhibitions, product launches, campus festivals, religious/ sports gatherings and mall promotions using temporary structures and large audiences.",scope:"Stages, trusses, LED walls, marquees/pandals, grandstands, barricades, temporary power and lighting, pyrotechnics/fireworks and SFX, food stalls with LPG, crowd flows (entry, egress, pits), VIP movements, medical and fire cover, weather; event build-up, show and tear-down.",roles:["Event owner (organiser) and venue licensee","Event safety officer / crowd manager","Structural engineer (temporary structures certification)","Electrical contractor (licensed), pyrotechnician (PESO licensed)","Police, fire service, medical provider; stewards/marshals (trained)"],hazards:["Crowd crush and stampede at entries/exits/stage front (Bengaluru RCB stampede June 2025, 11 dead — benchmark): over-capacity, free entry rumours, closed gates, bottlenecks, surges, no real-time counting","Temporary structure collapse (wind on LED walls/trusses/pandals, overloaded stages, inadequate ballast), falls during rigging, dropped objects; grandstand failure","Fire: pandal fabrics, decorations, pyrotechnics/cold pyro, LPG stalls, generator fuel, blocked exits (Kumbakonam/Uphaar benchmarks); electrical shocks from temporary wiring in wet conditions","Heat stroke in outdoor afternoon events, dehydration, no shade/water; medical emergencies (cardiac) without AED; traffic and parking chaos; weather (rain, lightning, wind)"],pre:["Permissions: police (crowd/traffic), fire service NOC for temporary structures/pandals (state Fire Act), municipal/venue permission","PESO licence for fireworks/pyro, electrical inspector/licensed contractor certificate, food-stall FSSAI/LPG compliance","Event safety plan submitted (capacity, crowd plan, structures, fire, medical, weather, emergency)","Capacity and crowd plan: occupant load per NBC Part 4 (assembly, e.g. 0.6 m²/person standing — verify) and exit width (≥ 2 exits, widths per NBC), ticketed/counted entry with real-time counting","Segregation of flows, no free-entry announcements without plan, front-of-stage barriers with pit and extraction, stewards ratio (benchmark 1:250 — verify, more at pinch points), PA and signage, VIP routes separate","Temporary structures: design and certification by structural engineer for wind (IS 875 Pt 3) and crowd loads, ballast/anchoring, daily inspections","Wind action plan (lower LED walls/sails at defined speeds), erection by trained riggers with fall protection and exclusion zones","Grandstands certified and inspected","Fire and electrical: flame-retardant pandal fabrics (certificates), extinguishers per area, fire lane access, no pyro without licensed operator and fire-service presence","LPG stalls separated with extinguishers, generators fenced with fuel bunding, temporary wiring with RCDs, earthing, cable protection, weather-proof distribution","Lighting of exits","Medical/weather: medical post with doctor/paramedics, ambulances (ratio per attendance — verify), AEDs, first-aid points","Water points and shade for outdoor; heat plan; weather monitoring with lightning/wind triggers; emergency communication (radios, control room, CCTV)"],steps:["Planning (weeks before): risk assessment, capacity calculation, crowd-flow drawings, structural designs, permissions, contractor appointments, stewards' briefing material; tabletop exercise for evacuation and crush scenarios.","Build-up: site induction for all crews, PTW for rigging/height and hot work, exclusion zones under rigging, structural inspection and sign-off before loading, electrical certification, fire extinguishers placed, exits marked.","Pre-doors: final walk-through with police/fire/venue: exits unlocked and clear, barriers secure, stewards in position with radios, counting system live, PA tested, medical post staffed, weather check","Go/no-go decision recorded.","Entry: controlled queuing with barriers in snake lanes, counters at each gate, stop entry at capacity, communicate wait times, separate exits; monitor density (stop and relieve if > 4 persons/m² — verify) at pinch points.","During event: control room monitors CCTV/density/weather; stewards report surges; stage manager can pause show on crowd-manager call; announce safety messages; keep fire lanes clear.","Wind/lightning/rain: follow structure wind action plan; suspend outdoor event and shelter at trigger; never continue with LED walls/trusses above limits.","Egress: staged dispersal announcements, all exits open and staffed, traffic plan active, lighting on; avoid counter-flows; monitor until crowd disperses.","Emergency: evacuation announcement script, stewards guide to exits, medical triage, fire service access, incident commander (police) liaison","Crush indicators (people falling, screams, pressure) → stop entry, open all exits, pause show, relieve pressure.","Tear-down: PTW, exclusion zones, fall protection, controlled dismantling, electrical isolation, waste clearance; debrief.","Post-event report: attendance vs capacity, incidents, near misses, structural/electrical issues, lessons; share with authorities as required."],ppe:["Stewards: hi-vis, radios, torches; riggers: harness, helmet, gloves, boots; electricians: insulated tools/gloves; pyro: FR clothing, eye protection; medical: standard kits"],stop:["Attendance approaching capacity without controlled entry/counting","Exit locked, blocked or stewards not in position","Temporary structure uncertified or wind above action limit","Pyro/LPG/generator without licence, separation or extinguishers","Lightning or storm trigger at outdoor event"],records:["Event safety plan and risk assessment, permissions/NOCs/licences, structural certificates and inspections, electrical certificate","Steward training and deployment, counting/attendance logs, medical and incident logs, weather log, post-event report"],refs:{india:["NDMA Guide 'Managing Crowd at Events and Venues of Mass Gathering' (2014) & NDMA/MHA SOPs post-2025","Karnataka Crowd Control (Managing Crowd at Events and Venues of Mass Gathering) Bill/Act 2025 (verify status); NBC 2016 Part 4 (assembly occupancy, exits, temporary structures) & SP 7:2026","State Fire Acts (pandal/temporary structure NOC); Explosives Rules 2008 (fireworks/pyro — PESO); IS 875 Pt 3 (wind loads)","CEA 2023 (temporary installations); Police Acts (licences for public assemblies); Disaster Management Act 2005"],ka:["Karnataka Fire Force Act 1964 (temporary structures NOC); Bengaluru City Police event permissions; GBA/BBMP; KSNDMC weather alerts; Karnataka Crowd Control law 2025 (verify)"],tn:["TN Fire & Rescue Services Act 2025 (verify) — temporary structure licences; Chennai Police event permission; TN Public Buildings (Licensing) Act 1965 (pandals); TNSDMA"],osha:["General Duty Clause; 1910.36–38 (exits, emergency action plans); NFPA 101 (assembly occupancies), NFPA 102 (grandstands/tents), NFPA 1126 (proximate pyrotechnics), NFPA 70 Art. 525/590; ANSI E1.21 (temporary stage structures)"],intl:["UK Purple Guide to Health, Safety and Welfare at Music and Other Events; UK SGSA Green Guide (sports grounds, stewards, egress); ISO 20121 (event sustainability), ISO 22320 (emergency management)","BS 7909 (temporary electrical systems for events); IStructE Temporary Demountable Structures guidance; Love Parade 2010 & Astroworld 2021 lessons"]},checklist:"cl4-events"},
{id:"p3-sewer",t:"Sewer, Septic Tank & STP Sump Entry – Mechanised Cleaning First (PEMSR Act)",cat:"Industrial",tags:["Industrial","Water","Facilities","Health"],purpose:"Eliminate deaths from manual cleaning of sewers, septic tanks, manholes and STP/ETP sumps by requiring mechanised cleaning, and control H2S, methane, oxygen deficiency, drowning and biological hazards when entry is unavoidable.",scope:"Municipal and campus sewers, manholes, septic tanks, STP/ETP wet wells, sludge pits, grease traps, storm drains; cleaning by jetting/suction machines and robots; entry for inspection, repair and rescue; contractors and sanitation workers.",roles:["Occupier/principal employer (campus, plant, housing society)","Licensed mechanised cleaning agency / sanitation contractor","Entry supervisor, attendant, entrants (trained; not sanitation labourers)","Rescue team with SCBA","Medical officer"],hazards:["H2S (10 ppm TLV; 100 ppm IDLH; > 500 ppm instant collapse), CH4 (explosive), CO2/O2 deficiency, ammonia; most deaths occur to rescuers following the first victim","Drowning/engulfment in sludge and sudden inflow (rain, upstream discharge); slips on ladders; falls through manholes; traffic at road manholes","Biological: hepatitis A/E, leptospirosis, gastro-enteritis, skin infections, needle-stick from sewage; chemical discharges (industrial effluent, solvents) in sewers","Illegal manual scavenging: contractors sending workers into tanks with no equipment — criminal offence under PEMSR Act 2013; Supreme Court 2023 directions (₹30 lakh compensation for deaths — verify)"],pre:["Policy: no person enters a sewer/septic tank/sump to clean it by hand; cleaning by jetting-cum-suction machines, desilting machines, bandicoot-type robots","Agency empanelled/licensed by ULB; contract clauses prohibit manual entry; principal employer liable","Entry (inspection/repair only) under permit-required confined-space programme: isolation of inflows (upstream penstock/valve, pump LOTO), ventilation ≥ 20 min with blower (verify)","Atmosphere testing at top/middle/bottom (O2 19.5–23.5%, H2S < 10 ppm, LEL < 10%, CO < 25 ppm), continuous monitoring, harness with lifeline on tripod/winch, attendant, communication","Rescue: SCBA sets and trained rescuers at the manhole for every entry; non-entry retrieval as first option; ambulance tie-up; never enter to rescue without SCBA","Health and hygiene: vaccination (hepatitis A/B, tetanus, typhoid advised), washing facilities, PPE decontamination, no eating at site; medical surveillance; leptospirosis awareness","Traffic management for road manholes (IRC:SP:55 signage, cones, barriers), lighting, weather check (no entry when rain forecast); equipment inspection (blowers, detectors calibrated, tripod/winch, SCBA)"],steps:["Request for cleaning: supervisor verifies machine availability and agency credentials; manual methods refused; schedule jetting/suction; record.","Mechanised cleaning: cordon area, open manhole with tools (hook/keys), stand upwind, operate jetting/suction from surface; handle hoses with gloves; dispose sludge to designated STP/ULB site.","If entry is unavoidable: written justification, permit, isolation of inflows and pumps (LOTO), ventilate, test atmosphere and record, assign attendant and rescue; entrant on lifeline with 4-gas monitor.","Entry: descend ladder with harness attached to retrieval line; continuous gas reading relayed; immediate exit on alarm, odour change or dizziness; work time limited; no hot work.","Attendant: never leaves, never enters; counts entrants; maintains communication; calls rescue and starts non-entry retrieval on alarm.","Emergency: raise alarm, winch victim out, SCBA team only if winch fails; CPR/oxygen; ambulance; notify police/ULB/labour department and DISH (fatal/dangerous occurrence) as required; preserve scene.","Post-work: close and secure manhole, decontaminate PPE and equipment, wash, dispose waste; record readings and permit closure.","STP/ETP sumps and digesters: biogas lines isolated, inert/ventilate, LEL and H2S tests, no entry during sludge transfer; chlorine/chemical dosing rooms separate controls.","Contractor audit: training certificates, equipment, insurance, wages, PPE; any manual entry observed → stop work, remove contractor, report under PEMSR Act.","Review every entry and near miss; annual drill with fire service; update inventory of sewers/tanks and cleaning schedule to reduce entries."],ppe:["Full-body harness with retrieval line, 4-gas monitor, chemical/cut-resistant gloves, gumboots, coveralls, goggles/face shield, FFP3 (biological aerosols), SCBA for rescue; washing and disinfection facilities"],stop:["Any proposal for manual entry to clean a tank or sewer","Atmosphere outside limits or detector not calibrated","No attendant, retrieval system or SCBA rescue at manhole","Inflows/pumps not isolated; rain expected","Contractor not licensed/trained for confined-space entry"],records:["Mechanised cleaning records, entry permits with gas logs, isolation records, equipment calibration/inspection","Rescue drill records, vaccination/medical records, contractor credentials, incident/near-miss reports, PEMSR compliance file"],refs:{india:["Prohibition of Employment as Manual Scavengers and their Rehabilitation Act 2013 & Rules","Supreme Court Balram Singh v. Union of India (2023) directions; NAMASTE scheme & MoHUA SOP for cleaning of sewers and septic tanks (2018)","Factories Act s.36 via state rules / OSH Code s.6; IS 11972 (safety in sewers/confined spaces — verify title), IS 10245 (SCBA); Sch. II (H2S 10 ppm); BMW/HOWM Rules (sludge)"],ka:["Karnataka SOP for sewer/septic cleaning (KUWS&DB/BWSSB mechanised cleaning); Karnataka Factories Rules 1969 (confined space); KSPCB STP norms"],tn:["TN Urban Local Bodies mechanised cleaning SOP (CMWSSB); TN Factories Rules 1950 Rule 61A (confined space — verify); TNPCB; Madras HC monitoring of manual scavenging deaths"],osha:["1910.146 (permit-required confined spaces), 1910.1000 (H2S), 1910.1030 (bloodborne pathogens), 1926 Subpart AA; NIOSH sewer entry guidance; NFPA 350"],intl:["UK Confined Spaces Regs 1997 & L101; Water UK 'Occasional Guidance' on sewer entry; EN 14593/14594 (breathing apparatus)","ILO Code of Practice (sanitation workers); WHO/World Bank 'Health, Safety and Dignity of Sanitation Workers' (2019)"]},checklist:"cl4-sewer"},
{id:"p3-crusher",t:"Crushing & Screening Plants, Haul Roads & HEMM",cat:"Industrial",tags:["Mines","Industrial","Transport","Health"],purpose:"Prevent crusher entanglement and blockage-clearing deaths, conveyor injuries, dumper/HEMM collisions and rollovers, dust disease and noise damage in quarries, aggregate plants, captive mines and crushing units.",scope:"Jaw, cone, impact and VSI crushers; vibrating screens; feeders, hoppers and conveyors; stockpiles and tunnels; haul roads; dumpers/tippers, excavators, loaders, drills; weighbridge traffic; mobile crushing plants.",roles:["Mine manager / plant in-charge (DGMS-recognised where mine)","Crusher operators and maintenance","HEMM operators (licensed/authorised)","Haul-road supervisor","Safety officer; occupational health (silica surveillance)"],hazards:["Crusher blockage: workers entering jaw/cone or using bars while running — crushed or struck by ejected rock; stored energy in jammed material releasing when freed","Conveyors: nip points at head/tail/return rollers, cleaning spillage near running belts, riding belts, falling from elevated conveyors; stockpile tunnels (engulfment, dust)","HEMM: dumper over-edge at tips, rollovers on haul roads, reversing over pedestrians/light vehicles, brake failure on grades, fatigue; blasting interface","Respirable crystalline silica (TLV 0.025 mg/m³; India Sch. II 0.1 mg/m³ — verify) → silicosis (notifiable); noise 95–110 dB(A); vibration; heat; electrical on mobile plant"],pre:["Crushers: feed and discharge interlocks, hopper grids/rock breakers for oversize, blockage-clearing procedure with LOTO (crusher and feeder isolated","Stored energy released), no entry into crusher chamber without permit and isolation","Emergency stops at all stations; guarded flywheels/belts","Conveyors: nip guards on all pulleys and return idlers within reach, pull-wire stops full length, crossing bridges, cleaning only with belt stopped/isolated or using long-handled tools from outside guards","Stockpile tunnels as confined spaces with reclaim feeders isolated","Haul roads: design width ≥ 3× widest vehicle (two-way — verify), gradient ≤ 1 in 16 (verify DGMS norm)","Berms/bunds ≥ half wheel height at edges, drainage, dust suppression, signage, speed limits, light-vehicle segregation and radio protocol","Tip-edge bunds and stop blocks; run-off ramps on long grades","HEMM: pre-shift checks, brakes tested on grade, seat belts, reversing cameras/alarms, ROPS/FOPS, fire suppression","Operator competency (DGMS/state certificates where applicable), fatigue management (shift ≤ 8 h in mines), no overloading","Dust: wet suppression at crushers/screens/transfer points, enclosures and dust extraction, cab air-conditioning with filters, respirators (FFP3) for exposed tasks","Silica monitoring and medical surveillance (chest X-ray/PFT per Mines Rules/Factories Rules); hearing conservation"],steps:["Shift start: inspect guards, pull-wires, e-stops, interlocks, water sprays, haul-road condition (berms, surface, visibility), lighting; HEMM pre-use checks; brief crews.","Feeding crushers: oversize removed with rock breaker or excavator — never by hand or bar while running; operator at console with camera view; stop feeder on blockage.","Blockage clearing: stop and isolate crusher and feeder (LOTO), release stored energy (jack/rock breaker from outside), permit, exclusion zone, two persons, no one inside chamber unless isolated and material secured","Restart only after all clear.","Conveyor spillage: stop and isolate belt before shovelling near pulleys; use guards and bridges; never ride belts; maintain skirting to reduce spillage.","Screens/transfer points: isolate before changing meshes/liners; lifting with rated gear; dust sprays on during operation.","Stockpile tunnels/hoppers: entry only under confined-space permit with feeders isolated, lifeline, gas test, never walk on live stockpiles (engulfment).","Haul traffic: dumpers give way per site rules, light vehicles keep 50 m and call before overtaking, no reversing without camera/spotter, tipping only behind stop blocks with spotter at night","Speed ≤ 30 km/h (verify); wet weather restrictions.","Maintenance on HEMM: park on level, isolate, lower buckets/beds, prop raised bodies, tyre work by trained persons (inflation in cage).","Dust/noise/health: sprays maintained, respirators where > limit, audiometry yearly, silica surveillance per rules; notify silicosis cases.","Weekly: haul-road inspection record, guard audit, incident/near-miss review; monthly: DGMS/statutory returns and inspections, blasting-crusher interface review."],ppe:["Helmet, hi-vis, safety boots, FFP3 respirator in dusty zones, hearing protection (SNR ≥ 30), gloves, safety glasses, harness for elevated conveyor work, seat belts in HEMM"],stop:["Blockage cleared or chamber entered without LOTO and permit","Conveyor guard or pull-wire missing/inoperative","Haul-road berms missing at edges/tips or road width/gradient out of limits","HEMM with defective brakes, seat belt or reversing aids","Dust suppression down with crushing in progress"],records:["Guard/interlock inspections, LOTO/permits for blockage and conveyor work, haul-road inspection log, HEMM pre-use and maintenance","Operator certificates, dust and noise monitoring, medical surveillance (silica), DGMS/state statutory registers and returns, incident log"],refs:{india:["Mines Act 1952 / Metalliferous Mines Regulations 1961 (haul roads, machinery, dust, DGMS circulars incl. Tech. Circ. on dumpers & haul roads — verify) where a mine","Factories Act ss.21–22, 36 via state rules / OSH Code for standalone crushers; MV Act (tippers); Sch. II silica; Third Schedule (silicosis notifiable); IS 9474; CPCB/SPCB stone-crusher siting & dust norms; blasting-codes"],ka:["Karnataka Minor Mineral Concession Rules 1994 (quarries); KSPCB stone crusher regulations (Karnataka Regulation of Stone Crushers Act 2011); DGMS Bengaluru region"],tn:["TN Minor Mineral Concession Rules 1959; TNPCB stone crusher siting norms; DGMS Chennai region; TN Factories Rules 1950 for crushing units"],osha:["30 CFR Part 56 (MSHA surface metal/non-metal — 56.14107 guarding, 56.9300 berms, 56.12016 LOTO); 1910.212/219; 1926.602; 1910.1053 (silica)"],intl:["UK Quarries Regulations 1999 & HSE QNJAC guidance (crusher blockages, haul roads, tipping); EN 620 (conveyors), EN 1009 (crushing machinery safety); ISO 19296 (mining machinery); ILO C176"]},checklist:"cl4-crusher"},
{id:"p3-cement-kiln",t:"Cement Kiln, Preheater & Coal Mill – Hot Meal, Blockage Clearing & Refractory Work",cat:"Industrial",tags:["Heavy Industry","Industrial","Fire","Health"],purpose:"Prevent hot-meal burns (the leading fatal hazard in cement plants), CO and explosion incidents in coal mills and preheaters, falls and entrapment during kiln/preheater/cooler entry, and refractory and silica exposures.",scope:"Preheater cyclones and risers, calciner, kiln inlet and hood, clinker cooler, coal/petcoke mills and bins, raw mills, kiln shutdown and refractory replacement, alternative fuels (AFR) feeding, cement mills and silos, bulk loading.",roles:["Plant head / production manager","Kiln and CCR operators","Blockage-clearing crews (trained, two persons minimum)","Refractory contractor","Safety officer; fire crew; occupational health"],hazards:["Hot meal (800–1,000 °C powder behaving like fluid) released when clearing cyclone/riser blockages or opening poke holes/doors — engulfs and burns persons below; kiln inlet hot-meal flushes during restart","Coal/petcoke mills and bins: CO build-up and self-heating → fire/explosion; dust explosions; inerting failures; hot gas back-flow","Kiln/preheater/cooler entry during shutdown: residual heat, falling brick/coating, CO, oxygen deficiency, dust (silica from clinker/raw meal), falls at cooler grates, kiln rotation during work","AFR waste hazards (biological, chemical)","Cement/clinker silos and bulk loading: engulfment, dust, falls; hot clinker transport; chromium (VI) in cement (dermatitis); noise; heights on preheater tower (100 m)"],pre:["Blockage-clearing procedure: only trained crew with written method; poke holes with blast-proof covers; air cannons/CO2 blasters remote-operated; no one below or in line of discharge","Exclusion zones and barriers on all levels below work; aluminised PPE; escape routes clear; never open inspection doors with meal built up above","Coal mill/bin safety: CO and O2 monitoring with alarms and inerting (CO2/N2) on bins, temperature monitoring, explosion vents, inert operation when idle, no hot work near; housekeeping; DHA for coal/petcoke dust","Kiln/preheater/cooler entry: full shutdown, cooling to < 40 °C, isolation of fuel, air, feed and rotation (kiln drive LOTO plus mechanical block)","CO/O2 testing, confined-space permit, scaffold/platform for refractory with protection from falling coating (chipping from safe side), lighting, rescue","Coating removal by trained crews","Falls: guardrails and gratings on preheater tower, cooler, silo tops; WAH permits; dust control (sprays, extraction), silica surveillance; heat-stress plan for tower work; AFR handling with PPE and SDS","Emergency: burn first-aid stations (cool water, burn dressings) at each preheater level and kiln hood, hospital burn-unit tie-up, fire crew, evacuation routes marked"],steps:["Daily: CCR trends (cyclone pressures/temperatures) to detect build-ups early; poke-hole covers intact; CO levels in coal bins; housekeeping on tower levels.","Minor build-up: clear by air blaster from remote position","If manual poking needed — permit, crew in aluminised suits/face shields, barriers below, one person pokes from the side while second watches; never stand in front of poke hole.","Major blockage: stop feed, reduce temperature, plan with production head, isolate levels below, use remote tools; consider shutdown rather than manual clearing; brief all affected.","Restart after stop: expect hot-meal flushes at kiln inlet/cooler — clear personnel from inlet area and cooler before feed on; monitor.","Coal mill: inert before start/stop as per procedure; respond to CO alarm (> 100 ppm action — verify) by inerting and isolating; fire → CO2 flooding, no opening of doors.","Shutdown entry: cool, isolate (fuel, feed, fans, kiln drive with block), test atmosphere, remove loose coating from safe position, permit entry with attendant","Refractory demolition/installation with scaffold, dust control, heat limits.","Clinker cooler: isolate grate drive and hammers, cool, entry permit; hot clinker spills handled with machines; silo entry per silo procedure.","AFR: segregated reception, SDS, PPE, fire detection in storage, no entry into bunkers.","Burn injury: cool with running water 20 min, remove from hot zone, cover, hospital; report as dangerous occurrence where applicable.","Monthly: blockage-clearing drills and PPE audit, coal-mill safety-system tests, guard/guardrail audit, dust monitoring, incident review; annual: shutdown safety review with contractors."],ppe:["Aluminised suit, hood with gold-coated visor, heat-resistant gloves and gaiters for hot-meal work; FFP3/PAPR for dust; helmet, harness on tower; CO monitor for coal/kiln areas; chemical gloves for cement (Cr VI)"],stop:["Person below or in discharge line of a blockage-clearing point","Coal bin CO/O2 monitoring or inerting out of service","Kiln/preheater entry without cooling, isolation and permit","Poke-hole or inspection door opened with meal above","Guardrail missing on tower/cooler platforms"],records:["Blockage-clearing permits and crew training, CO/O2 monitoring logs, coal-mill interlock tests, shutdown isolation and entry permits","Refractory contractor records, burn injuries and drills, dust/silica monitoring, WAH permits, incident reports"],refs:{india:["Factories Act ss.21, 31, 36, 37, 38 via state rules / OSH Code; Sch. II (cement dust, silica, CO 50 ppm); Third Schedule (silicosis); IS/IEC 60079-10-2 (coal dust zones)","HOWM Rules (AFR co-processing authorisations — CPCB guidelines); EC Act/CCTS (cement GEI targets); Mines Act for captive limestone mines"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules; confined space); KSPCB (AFR, dust); Karnataka Safety Audit Rules 2024"],tn:["TN Factories Rules 1950; DISH TN; TNPCB (Ariyalur cement cluster)"],osha:["1910.146, 1910.147, 1910.212, 1910.1053 (silica), 1910.1000 (CO); NFPA 85 (pulverised fuel systems), NFPA 652/654; MSHA 30 CFR 56 (quarry)"],intl:["Cement Sustainability Initiative/GCCA Safety Guidelines (hot meal, blockage clearing, contractor safety); UK HSE cement industry guidance; EN 1127-1; VDI 2263 (dust fires/explosions in coal mills); ISO 45001"]},checklist:"cl4-cement-kiln"},
{id:"p3-steel-gas",t:"Steel Plant Fuel Gases (BF/CO/BOF Gas) – CO Poisoning Prevention & Hot-Metal Areas",cat:"Chemical",tags:["Heavy Industry","Chemical","Process Safety","Foundry & Metals"],purpose:"Prevent carbon-monoxide poisoning from blast-furnace, coke-oven, converter and producer gases, gas explosions during purging and hot work, and molten-metal/slag incidents at integrated and secondary steel plants, DRI and foundries using gas.",scope:"BF gas, COG, BOF/LD gas, producer and mixed gas networks; gas holders, cleaning plants, mains and valves; purging, isolation (water seals, goggle valves, blinds) and hot work on gas lines; stoves and furnaces; cast house, converter, ladle and torpedo-car areas; DRI kilns.",roles:["Gas safety officer / energy department head","Gas-line permit issuers and rescue squad","Operators of BF, SMS, coke ovens, rolling mill furnaces","Maintenance and contractors (hot work on gas lines)","Occupational health (CO exposures)"],hazards:["CO: odourless; BF gas 20–30% CO, producer gas 20–25%, COG 5–10% (plus H2, benzene); leaks at valves, seals, bleeders, stoves, furnace doors, gas-holder tops; low-lying accumulation; deaths in groups when rescuers enter","Explosion: air ingress into gas mains during purging/shutdown, hot work without adequate purge (CO2/N2) and gas test, water-seal failure, gas back-flow; furnace light-off without purge; dust (BF flue dust) explosions","Hot metal/slag: ladle/torpedo-car breakouts, water–molten metal explosions, skull falls, converter slopping; burns from splash; hot-metal rail traffic; radiant heat","Confined spaces in gas cleaning plant, stoves, furnaces; H2S/benzene at coke ovens (benzene carcinogen); hydraulics; falls on gas mains walkways; nitrogen asphyxiation"],pre:["Gas safety organisation: designated gas safety officer, trained gas crew for isolation/purging/hot work, permit system specific to gas lines (IS 17893 plus plant gas permit)","Fixed CO monitoring at leak-prone points with alarms (25 ppm warning, 50 ppm evacuate — verify), wind socks, gas-area signage, restricted zones around bleeders and stoves","Personal CO monitors mandatory for everyone in gas areas; escape sets (CO filter self-rescuers) carried","SCBA sets and resuscitators at gas rescue stations; two-person rule; CO exposure limits (Sch. II 50 ppm TWA / ACGIH 25 ppm)","Isolation standards: positive isolation by goggle valve plus blind or water seal maintained at required head, purge with N2/CO2 (or steam) until CO < 1% and O2 criteria for hot work (verify)","Gas tests before and during work; no hot work on live gas mains; bleeder operation under permit","Hot-metal areas: dry charge/scrap, ladle and runner integrity, water-free pits, refractory inspection, breakout emergency plans, radiant-heat PPE, controlled access to cast house/converter aisle during tapping","Crane/ladle lifting under crane procedures","Furnaces/stoves: automatic purge and flame-failure, double block and bleed on gas trains, interlocks; confined-space entry after cooling and gas-freeing; health surveillance for CO and benzene-exposed workers"],steps:["Shift start: check fixed CO monitors, wind direction, water-seal levels, bleeder status, personal monitors calibrated, rescue station equipment; log.","Entering gas areas: monitor on, two persons, stay upwind of bleeders/stoves, no lying down/sitting in low areas; leave immediately on alarm, report.","Gas line isolation for maintenance: gas permit; close goggle valve, insert blind/raise water seal, purge with N2/CO2, verify CO/LEL/O2 at vents and work point","Display isolation tags; test again before hot work and every 2 h (verify).","Hot work on gas lines/holders: permit with fire watch, continuous gas monitoring, SCBA on standby, no work during gas pressure fluctuations; re-purge if readings rise.","Restoring gas: purge air from line with N2 until O2 < 1% (verify), then admit gas slowly; check for leaks with CO monitors; remove blinds under permit.","Furnace light-off: purge cycle complete, flame safeguard proven, operator at side of burner; never bypass; on flame failure, close gas and purge before relight.","Cast house/converter: during tapping only required crew in area, heat shields, dry tools/additives, no water lines leaking near runners; ladle/torpedo inspection before fill; breakout — alarm, evacuate, do not use water.","CO victim: do not enter without SCBA; rescue squad removes to fresh air, oxygen, CPR if needed, hospital (hyperbaric where available); treat as dangerous occurrence; investigate leak.","Coke ovens: door/lid emissions control, benzene monitoring, PPE, medical surveillance; gas cleaning plant and stove entries under confined-space permits.","Monthly: gas safety audit (monitors, seals, bleeders, permits), rescue drill, CO exposure review; annual: gas network integrity survey, valve/seal maintenance, training refresh."],ppe:["Personal CO monitor and self-rescuer in gas areas; aluminised/FR clothing, face shields, heat gloves and spats in hot-metal areas; SCBA for rescue and gas crews; helmet, safety boots, hearing protection"],stop:["Person in gas area without CO monitor or alone","CO alarm active or fixed monitoring down in occupied area","Hot work on gas line without positive isolation, purge and gas test","Water seal below required head / goggle valve not closed","Water near molten-metal runners/ladles or wet charge"],records:["Gas permits and isolation records, purge/gas-test logs, fixed and personal CO monitor calibration, water-seal and bleeder logs","Rescue station checks and drills, CO exposure/medical surveillance, hot-metal breakout drills, incident and dangerous-occurrence reports"],refs:{india:["Factories Act ss.36, 37, 38, 41B–H via state rules / OSH Code Ch. XII; MSIHC Rules (CO/gas holder thresholds — verify); IS 17893 (permits); IS 11457; Sch. II (CO 50 ppm; benzene 1 ppm)","Third Schedule (CO poisoning notifiable); DGFASLI steel-plant safety guidelines; Steel Ministry Safety Guidelines (gas safety, hot metal) — MoS/SAIL safety codes; EC Act/CCTS (iron & steel)"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules); KSPCB; Ballari–Hospet steel cluster (JSW, Kirloskar) safety regimes; MAH Control (Karnataka) Rules 1994"],tn:["TN Factories Rules 1950; TN CIMAH Rules; DISH TN (Salem Steel, secondary steel units in Gummidipoondi)"],osha:["1910.146, 1910.147, 1910.252 (hot work), 1910.1000 (CO 50 ppm), 1910.1028 (benzene), 1910.120; NFPA 86 (furnaces), NFPA 56 (fire and explosion prevention during cleaning and purging of flammable gas piping); ANSI Z49.1"],intl:["worldsteel Safety & Health guidance (gas safety, hot metal); EN 746-2 (industrial thermoprocessing — combustion & fuel handling safety)","UK HSE steel-industry gas-safety guidance (ISG), IGEM/SR/22 (purging); EIGA Doc 44 (nitrogen hazards); ISO 13577-2"]},checklist:"cl4-steel-gas"},
{id:"p3-chp-ash",t:"Coal Handling Plants, Bunkers & Ash Handling",cat:"Industrial",tags:["Power","Industrial","Fire","Health"],purpose:"Prevent conveyor entanglement, coal-dust fires and explosions, bunker fires and CO, engulfment in bunkers/silos, and injuries in ash handling and ash-pond operations at thermal power plants and captive power units.",scope:"Wagon tipplers and track hoppers, crushers, conveyors and transfer towers, stacker-reclaimers and stockyards, coal bunkers and feeders, coal mills (pulverisers), bottom-ash and fly-ash systems (ESP hoppers, silos, slurry/dense-phase), ash ponds/dykes, ash utilisation loading.",roles:["CHP/AHP in-charge","Conveyor and tippler operators","Maintenance (belts, idlers, electrical Ex)","Fire crew; shift safety officer","Ash pond/dyke engineer"],hazards:["Conveyor nip points (the single largest injury source in CHP), belt cleaning and idler changes while running, falls from galleries, transfer-tower dust; wagon tippler/side-arm charger crush; track hopper engulfment","Coal dust explosions in crushers, transfer points, mills and bunker tops; spontaneous heating in stockpiles and bunkers (CO, fires); mill fires/puffs; hot work near dust","Bunker/silo entry: engulfment, CO/O2 deficiency, bridging, poking from inside; ash silos: hot fly ash (200 °C) flows like liquid — burns and engulfment; ESP hopper poking; compressed-air conveying ruptures","Ash ponds: dyke failure/breach (slurry flood), drowning, slurry pipeline bursts, dust storms from dry ponds; heat; noise; silica in ash (verify crystalline fraction)"],pre:["Conveyors: nip guards on head/tail/take-up/return idlers, pull-cords full length tested weekly, belt-sway and zero-speed switches, crossing bridges","Galleries with handrails and toe boards, no cleaning or idler change on running belt (LOTO), dust suppression/extraction at transfer points, housekeeping to prevent layers > 0.8 mm","Fire/explosion: DHA for coal dust (NFPA 652/85 benchmark), Ex-rated electricals in Zone 21/22 areas, CO and temperature monitoring in bunkers/silos","Inertisation (steam/CO2) for bunker fires, mill fire-fighting and inerting procedures, stockpile compaction and FIFO, thermal scanning, hot-work permit system covering CHP","Bunkers/silos: zero-entry policy; entry only with feed/discharge isolated (LOTO on feeders and conveyors), bridging assessment, atmosphere test (CO, O2, CH4), lifeline and retrieval, attendant","Poking from outside with air cannons/vibrators; ESP hoppers poked only with heater and isolation (hot ash)","Ash handling: fly-ash silo level/temperature monitoring, PRVs, dense-phase lines pressure-rated with blow-off protection, burns PPE; bottom-ash hopper quench","Ash pond dyke inspection (freeboard, seepage, piezometers), raised-dyke design per CEA/CPCB, emergency plan for breach; dust suppression on dry ponds/roads","Health: silica/coal-dust monitoring, respirators, audiometry, heat plan; training for all CHP staff and contractors; Form/registers per Factories Rules; EC/CCTS Scope 1 data from coal flow meters"],steps:["Shift start: walk conveyors — guards, pull-cords, spillage, hot spots (smell/thermal camera), bunker CO/temperature trends; tippler and stacker-reclaimer checks; log.","Belt operation: pre-start alarm, no persons on galleries at start; spillage cleared only with belt stopped and isolated or from outside guards with tools; never cross belts except at bridges.","Idler/belt maintenance: LOTO at MCC and local isolator, belt clamped, counterweight secured; splicing with vulcaniser under hot-work rules; guards refitted.","Dust: sprays on at transfer points, extraction filters maintained, vacuum/wash-down housekeeping; no compressed-air blow-down; hot work only after cleaning and permit.","Bunker fire/heating (CO rising, temperature > limit): stop feed, inert with steam/CO2, run bunker down to mill under controlled conditions, no opening of doors, fire crew ready","Mill fire — follow OEM inerting/isolation, no water jets into mill.","Bunker/silo entry: only after all alternatives, permit, isolations verified, bridging checked from top with camera, lifeline/winch, attendant; never below hanging material.","Stockyard: compaction, temperature probing, reclaim hot spots first, keep stockpile slopes within machine limits; stacker-reclaimer exclusion zones; dust suppression.","Fly-ash: silo unloading to closed tankers with level/pressure watch, dust-free loading spouts, burns PPE; ESP hopper evacuation with heaters, poking only from outside with isolation; dense-phase line inspection.","Ash pond: daily dyke inspection (freeboard ≥ 1 m — verify, seepage, cracks), slurry pipeline patrol, no entry into pond area alone, lifebuoys at decant structures, rain-season emergency plan, dust control on dry areas.","Monthly: conveyor guard/pull-cord audit, Ex equipment check, bunker/silo entry review, fire-system tests, dust monitoring; annual: dyke stability review, DHA update, training refresh."],ppe:["Helmet, safety boots, FFP3 respirators in dusty areas, safety glasses/goggles, gloves, hearing protection","Harness and lifeline for bunker/silo/gallery work, heat-resistant PPE for ash hoppers/silos, lifejacket at ash pond water edges"],stop:["Work on running conveyor near nip points","Pull-cord or guard missing on a running belt","Bunker CO/temperature alarm ignored or inerting unavailable","Bunker/silo entry without isolation, lifeline and attendant","Ash-pond dyke freeboard/seepage outside limits"],records:["Conveyor inspection and pull-cord tests, LOTO records, bunker CO/temperature logs, hot-work permits, confined-space entry permits","Ex equipment register, dust and silica monitoring, fire-system tests, ash pond inspection and piezometer records, incident log"],refs:{india:["Factories Act ss.21–22, 36, 37 via state rules / OSH Code; Electricity Act/CEA (Technical Standards for Construction & Safety of thermal plants) 2023 regs; CPCB fly-ash notification (utilisation","Ash pond norms) & EP Rules; Sch. II (coal dust, silica); IS/IEC 60079-10-2; IS 11592 (belt conveyors — verify); CEA guidelines on ash dyke design & safety; EC Act/CCTS (thermal power)"],ka:["Karnataka Factories Rules 1969; KSPCB (ash pond consents, fly-ash); KPCL (RTPS/BTPS) safety procedures"],tn:["TN Factories Rules 1950; TNPCB (NCTPS, MTPS ash ponds); TANGEDCO safety rules; DISH TN"],osha:["1910.212, 1910.219, 1910.147, 1910.146, 1910.269 (generation), 1910.1053; NFPA 85 (boiler & combustion systems hazards, pulverised fuel), NFPA 652/654, NFPA 120 (coal mines — benchmark); EPA CCR rule (ash ponds — benchmark)"],intl:["EN 620 (conveyors), EN 1127-1; UK HSE conveyor guidance (nip points) & coal-handling fire guidance; VDI 2263; ICOLD tailings/ash dam guidance; ISO 45001"]},checklist:"cl4-chp-ash"},
{id:"p3-loading-dock",t:"Loading Docks, Yard Traffic & Trailer Loading",cat:"Lifting & Tools",tags:["Warehouse","Transport","Industrial","Food"],purpose:"Prevent forklift drive-offs, trailer creep, dock-edge falls, pedestrian strikes and manual-handling injuries at warehouse and factory loading docks, tail-lifts and yards.",scope:"Dock doors, levellers and plates, vehicle restraints, trailer and container loading/unloading, tail-lifts, yard traffic (trucks, LCVs, forklifts, pedestrians), drivers' waiting areas, night and peak operations, reefer trailers, cross-docks and dark stores.",roles:["Warehouse/dock manager","Forklift operators (authorised)","Dock loaders/pickers","Truck drivers (visitors)","Yard marshal; safety officer"],hazards:["Forklift drives off dock edge or into gap when trailer creeps/pulls away during loading; trailer landing-gear collapse; dock leveller falls","Pedestrians (loaders, drivers) struck by forklifts/trucks in yard; drivers walking between vehicles; reversing trucks; poor lighting/rain","Falls from dock edge (1.2 m) and from trailer beds/tail-lifts; crush at tail-lift; loads falling from trailers (shifted cargo, container doors springing open)","Manual handling of cases/bags, awkward postures in trailers; heat in containers (50 °C+); CO from diesel forklifts in trailers; reefer unit noise; security/theft incidents"],pre:["Dock equipment: levellers with lip and maintenance props, dock plates rated and secured, vehicle restraints (wheel-lock/hook) with communication lights or wheel chocks plus 'keys-to-loader' rule","Dock bumpers, edge guards/barriers at unused doors, lighting ≥ 100 lux (verify) in trailers and docks","Yard traffic plan: one-way flow, marked truck lanes and pedestrian walkways, drivers' waiting room, speed limit ≤ 10 km/h, reversing with banksman or cameras, mirrors at blind corners, no pedestrians in reversing zones","Night lighting and hi-vis for all","Procedures: loading sequence (restrain → check trailer floor and landing gear → inspect load → load → release)","Container door opening from the side with door-restraint strap, tail-lift operation by trained persons only with exclusion area, forklift capacity vs trailer floor rating","Manual handling: pallet jacks, conveyors/extendable belts into trailers, lifting aids, two-person rule for > 25 kg (verify site limit), rotation","Heat plan for container unloading; CO limits — electric forklifts in enclosed trailers or ventilation","Security and welfare: driver check-in, ID, drivers stay in waiting area, toilets/water for drivers; first aid; incident reporting including visiting drivers"],steps:["Vehicle arrival: marshal directs to door, driver reverses with banksman/cameras, engine off, brake on; keys handed to dock office or restraint engaged and light turned green.","Before loading: check trailer floor condition, landing gear/stands (use trailer stand for dropped trailers), restraint/chocks in place, leveller lip on trailer bed","Open container doors from side with strap, check for shifted load.","Loading/unloading: forklift drives straight on/off at walking pace, horn at entry, forks low; loaders out of trailer while forklift inside; stack and strap loads per plan; no climbing on loads.","Tail-lift: operator trained, platform rated, load secured, nobody on platform except operator where permitted, exclusion area; stow before driving.","Pedestrians: use walkways, stay out of trailer path; drivers remain in waiting area until released; no walking in yard lanes.","Completion: forklift out, leveller stored, restraint released only after confirmation, keys returned, light red; driver checks load securing before departure.","Dock doors not in use: barrier/chain across edge; levellers in stored position; good housekeeping (no pallets/wrap on floor).","Weather: wet docks — non-slip surfaces, extra care at edges; wind — container doors secured; heat — rest/water for trailer work.","Maintenance: monthly leveller/restraint inspection, bumpers, lighting, floor condition; forklift daily checks; yard markings repainted.","Weekly: near-miss review (drive-offs, creep, pedestrian conflicts), driver feedback; quarterly yard traffic audit; training refresh for loaders and marshals."],ppe:["Hi-vis, safety shoes, gloves, helmet where overhead risk, knee pads for container unloading, sun protection; hearing protection near reefers"],stop:["Trailer not restrained/chocked and keys not controlled before forklift entry","Pedestrian in yard lane or trailer with forklift moving","Dock leveller or plate damaged/unsecured","Container doors opened without restraint strap or from front","Trailer landing gear/floor unsafe"],records:["Vehicle restraint/chock logs or key register, dock equipment inspections, forklift checks and operator authorisations, yard traffic plan and audits, driver induction records, near-miss/incident log, manual-handling training"],refs:{india:["Factories Act s.7A (safe workplace), s.34 (weights) via state rules / OSH Code s.6; MV Act 1988 (vehicles in premises)","Shops & Establishments Acts (warehouses); IS 15298 (footwear); pit-racking (forklift codes); NBC Part 4 (storage occupancy)"],ka:["Karnataka Factories Rules 1969; Karnataka Shops & Commercial Establishments Act; RTO Karnataka"],tn:["TN Factories Rules 1950; TN Shops & Establishments Act; RTO TN"],osha:["1910.178 (forklifts — dock boards, trailer restraints 1910.178(k)/(m)), 1910.26 (dockboards), 1910.176, 1910.28 (dock edges), 1910.1000 (CO); ANSI MH30.1 (dock levellers), ANSI/ITSDF B56.1"],intl:["UK HSE HSG136 (workplace transport), 'Delivering safely' guidance, Loading dock guidance (LOLER for tail-lifts), EN 1756 (tail-lifts), EN 1398 (dock levellers); ISO 45001"]},checklist:"cl4-loading-dock"},
{id:"p3-heat-treat",t:"Heat Treatment – Furnaces, Quench Tanks, Salt Baths & Protective Atmospheres",cat:"Industrial",tags:["Foundry & Metals","Industrial","Fire","Chemical"],purpose:"Prevent burns, quench-oil fires, explosions of protective/endothermic atmospheres, salt-bath eruptions, CO poisoning and crane/charge incidents in heat-treatment shops and in-house hardening lines.",scope:"Batch, continuous, sealed-quench and pit furnaces; carburising/nitriding with endothermic gas, ammonia or methanol; vacuum furnaces; induction hardening; oil/polymer/water quench tanks; salt baths (neutral, nitrate/nitrite, cyanide); tempering; washing lines.",roles:["Heat-treatment shop head","Furnace operators (trained per furnace type)","Maintenance (gas trains, burners, atmosphere generators)","Fire crew; safety officer","Occupational health (CO, ammonia, cyanide exposure)"],hazards:["Protective atmospheres (endothermic gas: 20% CO, 40% H2; dissociated ammonia","Methanol): explosion if air enters furnace below 760 °C (verify) or on power/gas failure without purge; CO leaks at doors/flame curtains; ammonia and methanol toxicity/fire","Quench: oil quench fires when load not fully submerged, water contamination of oil (steam explosion), low oil level, high oil temperature near flash point; polymer/water quench steam; hot load dropping from crane/manipulator","Salt baths: moisture/organics in nitrate–nitrite salts → eruptions/explosions; cyanide salts (HCN with acid/water, toxicity); hot salt splashes 500–900 °C; vapour/fume","Burns from furnace doors, charge baskets, radiant heat; falls into pit furnaces/quench tanks; induction HF/EMF and cooling-water leaks; vacuum furnace implosion/ nitrogen asphyxia; heat stress"],pre:["Furnaces per NFPA 86 benchmark: safety-ventilated or inert-purged atmospheres, burn-off pilots/flame curtains at doors, interlocks (low temperature, low gas/air pressure","Power failure) that purge with nitrogen before atmosphere admitted or removed, flame safeguards on burners and generators, gas-train double block-and-bleed, CO monitoring in shop with ventilation","Quench tanks: oil level and temperature interlocks (prevent quench when oil < minimum level or > set temperature","Flash point margin ≥ 50 °C — verify), agitation, cooling, covers/lids with CO2 or dry-powder fixed suppression, drain/ bund, water ingress prevention, no water lines above tanks","Load fully submerged by design; emergency hoist power","Salt baths: dry pre-heated work and tools, covered storage of salts, no cyanide and nitrate baths adjacent, fume extraction","PPE (face shield, aluminised apron/gloves), spill tools, cyanide antidote kit and trained first aiders where cyanide used","Salt disposal as hazardous waste","Charging: baskets and fixtures inspected (creep/cracks), crane/manipulator capacity, lifting gear rated for temperature, exclusion zones during transfer, pit-furnace and tank guardrails/covers","Ammonia/methanol storage per gas/petroleum rules; nitrogen with O2 monitors in enclosed areas","Training for atmosphere furnaces (start-up, shutdown, power failure), fire drills (quench fire), medical surveillance (CO, ammonia, cyanide)"],steps:["Start-up: verify interlocks, purge with N2 to O2 < 1% (verify) before admitting endothermic gas, light pilots/flame curtains, check generator; log.","Running: keep doors closed except loading; monitor CO in shop; respond to interlock alarms — never bypass; on power or gas failure follow emergency purge procedure and evacuate until atmosphere safe.","Loading/unloading: inspect baskets, position crane/manipulator, exclusion zone, transfer hot load directly to quench without delay; no one between furnace and tank.","Quench: confirm oil level/temperature and agitation before transfer; submerge fully; on fire — keep load submerged, close lid, operate suppression, isolate heaters, do not use water; evacuate smoke.","Salt baths: dry work and tools over bath before immersion, lower slowly, keep face away; skim with dry tools; add salt in small dry amounts; cyanide — PPE, no acid nearby, waste controlled.","Shutdown: purge atmosphere with N2, burn off, cool with doors closed; confirm CO low before opening; isolate gas and lock.","Maintenance/entry: furnace cooled, atmosphere purged, gas isolated and locked, confined-space permit for furnace interior, refractory dust (ceramic fibre — RCF) controls, hot-work permit","Induction units isolated and capacitors discharged.","Gas/chemical storage: ammonia cylinders/tanks per gas rules with leak detection; methanol per Petroleum Rules; nitrogen and endo gas lines labelled; LPG/PNG gas trains tested yearly.","Waste: quench oil, salts, washing-line effluent as hazardous waste under HOWM; cyanide waste detoxified before disposal.","Monthly: interlock and flame-safeguard tests, oil flash-point/water-content checks, suppression inspection, CO monitor calibration, PPE audit, drill","Annual: furnace safety audit (NFPA 86 style), lifting gear tests, medical surveillance."],ppe:["Face shield with heat-resistant visor, aluminised apron/sleeves/gloves, FR clothing, safety boots (metatarsal)","Hearing protection, CO monitor in atmosphere-furnace area, respirator for salt fume/RCF dust, cyanide first-aid awareness"],stop:["Atmosphere admitted below safe temperature or interlock bypassed","Quench oil low/hot or water contamination suspected","Wet work or tools near salt bath","CO alarm in shop or flame curtain out","Basket/fixture cracked or crane gear not rated for hot loads"],records:["Furnace interlock/flame-safeguard tests, purge logs, CO monitor calibration, quench oil tests, suppression and extinguisher inspections","Basket/lifting gear inspections, salt bath logs, hot-work/confined-space permits, HW manifests, medical surveillance, drill records"],refs:{india:["Factories Act ss.21, 31, 36, 37, 38 via state rules / OSH Code; Gas Cylinders Rules 2016 (ammonia); Petroleum Rules 2002 (methanol, quench oil Class C); PNGRB/IS 6044 (gas supply)","Sch. II (CO 50 ppm, ammonia 25 ppm, cyanide 5 mg/m³, RCF); HOWM Rules; IS 9474; foundry-codes (state dangerous-operations schedules — heat treatment/cyanide)"],ka:["Karnataka Factories Rules 1969 (Rule 129 schedules — cyanide/heat treatment — verify); DFBISH; KSPCB"],tn:["TN Factories Rules 1950 (Rule 95 schedules); DISH TN; TNPCB; Coimbatore/Hosur heat-treatment clusters"],osha:["1910.1000 (CO, HCN), 1910.147, 1910.146, 1910.212; NFPA 86 (ovens & furnaces — Class A/B/C/D), NFPA 30 (quench oil), NFPA 12 (CO2 systems); ANSI Z49.1"],intl:["EN 746-1/-2/-3 (industrial thermoprocessing equipment — combustion, atmosphere gases), EN 1127-1; UK HSE heat-treatment guidance (salt baths, quench-oil fires), COSHH; ISO 13577 series"]},checklist:"cl4-heat-treat"},
{id:"p3-fuel-station",t:"Retail Fuel Outlets & Site Fuel Dispensing – Tank-Lorry Decanting, Dispensers, CNG",cat:"Chemical",tags:["Oil & Gas","Chemical","Fire","Transport"],purpose:"Prevent fires, explosions, vapour exposure and vehicle incidents during tank-lorry decantation, dispensing of petrol/diesel/CNG/LPG-auto, tank gauging and maintenance at retail outlets, captive fuel stations and construction-site fuel points.",scope:"Retail outlets (PSU/private), captive bunks in plants/mines/ports, construction-site skid tanks and bowsers, CNG compressor/dispensing stations, auto-LPG; underground/above-ground tanks, dispensers, vapour recovery, forecourt traffic, generators, hot work and tank maintenance.",roles:["Dealer/outlet manager (licensee)","Forecourt attendants (trained, PESO-aware)","Tank-lorry crew","Oil company/PESO inspector","Site fuel attendant (construction/mines)"],hazards:["Petrol (Class A) vapour ignition during decanting and dispensing: static from hose/nozzle, mobile phones, running engines, smoking, hot vehicle parts; vapour pooling in pits/drains; spills","Tank-lorry decantation: wrong-tank/wrong-product connections, overfill, hose rupture, lorry moving while connected, lightning","Tank-lorry fires; underground tank leaks contaminating groundwater; dip-pipe/manhole chamber confined space","CNG: 200–250 bar gas — cylinder/hose rupture, jet fire, compressor room explosion, cascades; auto-LPG BLEVE on tank fire; forecourt traffic strikes on attendants; robbery/violence at night","Site fuel points: bowser/skid tanks without bunds or earthing, refuelling hot machines, jerry-can filling, diesel exposure/dermatitis"],pre:["Licences and layout per Petroleum Rules 2002 (Form XIV/XV — verify) and OISD-STD-117/118 benchmarks (retail outlet safety distances","Electricals in Zone 1/2, earthing pits ≤ 1 Ω for lorry/tank earthing — verify), Gas Cylinders/SMPV Rules and PNGRB T4S for CNG","Vapour-recovery stage I/II where mandated (CPCB); CEIG for electricals","Equipment: dispensers with breakaway couplings and auto shut-off nozzles, emergency shut-off switch (ESD) for dispensers and CNG, flame arresters/vents, overfill prevention (level gauging/high-level alarm)","Earthing clamp and bonding point for lorries, Ex-rated lighting/pumps, extinguishers (DCP 9 kg ×4 at least per outlet — verify) and sand buckets, spill kits, 'no smoking/engine off/phone off' signage","Decantation SOP: two persons, lorry earthed and chocked, engine off, compartment seals/dip verified, correct product–tank identification (colour codes/labels)","Hose check, continuous watch, no dispensing from the tank being filled, weather (no decanting during lightning), night lighting","Staff trained (OMC safety training), uniforms antistatic cotton, first aid, fire drill quarterly","Forecourt traffic layout (one-way, speed ≤ 10 km/h, pedestrian paths); CNG compressor room ventilation, gas detection, PRVs, hose inspection/replacement schedule","Site fuel points (construction/mines): bunded skid tanks/bowsers with earthing, PESO licence above exemption, refuelling of cold engines only","No jerry cans except approved safety cans, spill kits, extinguishers, fire-safe distance from camps and hot work"],steps:["Lorry arrival: position at decant bay, engine off, chocks, earth clamp attached before any hatch/hose; verify invoice vs compartments, seals, dip/density; attendant and crew stay throughout.","Decanting: connect hose to correct tank fill point (verify label), open valves slowly, monitor level/overfill alarm, no vehicle refuelling at adjacent dispensers of that tank","Stop on spill/leak; disconnect and cap, record quantity and dip.","Dispensing: customer engine off, no phones/smoking, nozzle in contact with filler neck (bonding), no overfilling or topping-off, two-wheeler riders dismount; stop on spill; no filling of plastic containers unless approved.","Spill: stop pump, isolate ignition, absorb with sand/absorbent, dispose as hazardous waste; vapour cloud → evacuate forecourt, ESD, call fire service.","Fire: ESD, extinguishers on small fires, evacuate, call fire service (101/112), move vehicles away if safe; CNG/LPG jet fire — do not extinguish flame, isolate supply, cool surroundings, evacuate 100 m+.","Tank gauging/dip: by trained person with antistatic rope/tape, after settling time; manhole chambers entered only under confined-space permit (vapour).","CNG: pre-shift check of compressor room gas detection, hoses, nozzles, PRVs; fill with vehicle engine off and cylinder test date verified; stop on hissing/odour.","Maintenance/hot work: PTW, gas-free certificate for tanks/lines, Ex equipment reinstated; tank cleaning per tank-cleaning procedure; leak detection/tightness tests for USTs periodically (verify interval).","Night operations: lighting, two attendants, CCTV, cash control, panic alarm; women attendants' safety per state rules.","Monthly: extinguisher/earthing/ESD checks, dispenser calibration, vapour-recovery function, staff drill; annual: PESO/OMC inspection, electrical inspection, UST tightness test."],ppe:["Antistatic cotton uniform, safety shoes (antistatic), nitrile gloves for spills/diesel, safety glasses for decanting, hi-vis on forecourt, hearing protection in CNG compressor rooms"],stop:["Lorry not earthed/chocked or engine running during decanting","Wrong product–tank connection suspected","Ignition source (phone, smoking, running engine) on forecourt during fuelling/decanting","ESD, earthing or extinguishers not functional","Lightning during decanting"],records:["PESO licence and approved layout, decantation logs (dip/seal/earthing), dispenser calibration, extinguisher/earthing/ESD inspections","Vapour-recovery tests, UST tightness tests, staff training, incident/spill log, CNG equipment inspections"],refs:{india:["Petroleum Act 1934 & Rules 2002 (retail outlet licensing, Class A/B, safety distances); OISD-STD-117 (fire protection for retail outlets), OISD-STD-118 (layouts), OISD-STD-105 (permits)","Gas Cylinders Rules 2016 & PNGRB T4S for CNG stations; SMPV(U) Rules (auto-LPG); CPCB vapour-recovery (Stage I/II) directions; IS 7689 (static), IS 5572; CEA 2023; MV Act"],ka:["PESO Bengaluru; KSPCB VRS compliance (Bengaluru outlets); KSFES; Karnataka Shops & Establishments (attendants' hours)"],tn:["PESO Chennai; TNPCB VRS; TNFRS; TN Shops & Establishments Act"],osha:["1910.106 (flammable liquids — service stations), 1910.110 (LPG), 1910.1200; NFPA 30A (motor fuel dispensing facilities), NFPA 52 (CNG), NFPA 58 (LPG), NFPA 77; API RP 1615/1621"],intl:["UK Petroleum (Consolidation) Regulations 2014 & Energy Institute 'Design, construction… of filling stations' (Blue Book)","EN 13617 (dispensers), EN 14678 (LPG dispensers), ISO 16923 (CNG stations); EI 'Safe decanting' guidance"]},checklist:"cl4-fuel-station"},
{id:"p3-lpg-bottling",t:"LPG Bottling Plants & Bulk LPG Installations",cat:"Chemical",tags:["Oil & Gas","Chemical","Fire","Process Safety"],purpose:"Prevent LPG releases, flash fires, BLEVE and vapour-cloud explosions at cylinder bottling plants, bulk storage (mounded/above-ground bullets), tank-lorry gantries and industrial bulk LPG installations.",scope:"LPG receipt by tank-lorry/pipeline, mounded and above-ground bullets, pumps/compressors, carousel filling, cylinder evacuation and testing, valve change, leak testing, cylinder storage sheds, loading/unloading gantries, fire-water systems, industrial bulk tanks and vaporisers.",roles:["Plant manager (PESO licensee)","Shift in-charge and operators (trained per OISD)","Fire and safety officer; ERT","Maintenance (Ex equipment, instruments)","Tank-lorry crews; PESO/OMC auditors"],hazards:["LPG vapour (heavier than air, flammable 1.8–9.5%) from hose/valve/flange leaks, cylinder valve leaks, overfilled cylinders (hydraulic rupture when warmed), pump seal failure","Ignition by static, non-Ex equipment, vehicles, phones","BLEVE of bullets or tank-lorries under fire impingement; vapour-cloud explosion in congested filling sheds; jet fires at gantries; frost burns from liquid LPG","Cylinder handling: manual lifting 30–50 kg, falling stacks, conveyor nips, carousel moving parts, valve-change tools; cylinder evacuation of defective cylinders; hydro-test pit","Tank-lorry movement with hose connected, brake failure in gantry; lightning; monsoon flooding of bunds; security/sabotage; MAH off-site consequences (Vizag 1997 HPCL, benchmark incidents)"],pre:["Licences/standards: PESO licence under Gas Cylinders Rules 2016 and SMPV(U) Rules 2016","Layout and safety distances per OISD-STD-144 (LPG bottling plants), OISD-STD-150 (mounded storage), OISD-STD-169 (small LPG installations)","MSIHC/Chemical Accidents Rules (MAH site: safety report, on-site/off-site plans, mock drills); CEIG electrical; hazardous-area classification with Ex equipment (IS 5572/60079)","Fixed protection: gas detectors (alarm 20% LEL, trip/ESD 40% — verify) across sheds, gantries and storage, ESD system isolating pumps/compressors and remote-operated valves (ROVs) on bullets and gantries","Excess-flow and back-check valves, water deluge/sprinklers on bullets, cylinder sheds and gantries (OISD-116/144 rates), fire-water storage/pumps, monitors, hydrants","Lightning/earthing; wind socks","Operations: SOPs for receipt, filling (electronic scales with check weighing, auto cut-off), leak testing (water bath/detector)","Valve change (cylinder evacuated), evacuation of defective cylinders to flare/recovery, hydro-test","Static bonding of lorries; two-person rule; no hot work without permit and gas-free; mobile phones/vehicles restricted to designated zones","Tank-lorries: PESO-approved vehicles, driver training (OISD-GDN-207 style — verify), wheel chocks, earthing, engine off, hose inspection (test date), excess-flow/breakaway, no parking of loaded lorries in plant","Night loading only where licensed","Emergency: on-site plan with ERT, SCBA, PPE, foam/DCP, mutual aid with OMC plants and fire service, off-site plan with District Crisis Group, siren and evacuation routes, drills 6-monthly","Medical for frost burns; security (CISF/private) per PESO"],steps:["Shift start: gas detector panel, ESD/ROV test (periodic), fire pumps auto-start, deluge valves, hydrant pressure, wind sock, housekeeping; log.","Lorry unloading: position, chock, earth, engine off, driver out; connect liquid/vapour hoses after inspection, open valves slowly, leak check with soap/detector","Operator present throughout; disconnect, cap, release earth, remove chocks; record quantity.","Filling: cylinders inspected (due date, valve, body damage) before carousel; fill by weight with auto cut-off","Check-weigh 100% (verify); overfilled → evacuate; leak test every cylinder at valve/bung; seal and stack ≤ height limit on pallets.","Leaking/defective cylinders: move to designated outdoor evacuation area, evacuate LPG via recovery system (no venting to atmosphere), valve change by trained person with evacuated cylinder, hydro-test per schedule.","Cylinder sheds and storage: upright, valve caps, segregation of full/empty, no ignition sources within distance, forklifts Ex-rated or outside, lighting Ex.","Leak response: gas alarm → stop operations, ESD, isolate source, disperse vapour with water curtains/monitors, no ignition, evacuate crosswind, ERT in PPE/SCBA","Do not extinguish a jet fire until gas isolated; cool exposed tanks.","Fire on tank-lorry/bullet: activate deluge, evacuate 500 m+ (BLEVE), fire service and District Crisis Group alert, off-site plan; do not approach impinged vessel.","Maintenance: PTW, isolation (double block, blind), depressurise and purge (N2) before opening; gas-free test; Ex equipment reinstated (IEC 60079-17 inspection); instrument/ESD function tests per schedule.","Manual handling: rollers/conveyors, lifting aids, two-person for stacking, gloves; carousel guards and e-stops.","Audits and drills: monthly safety audit (OISD-144 checklist), 6-monthly mock drill with district authorities, PESO/OMC inspections, safety report update, training refresh; incident investigation and MSIHC reporting."],ppe:["Antistatic FR coveralls, conductive safety boots, cotton inner wear, leather gloves (cryogenic for liquid LPG), face shield/goggles, helmet; SCBA and fire suits for ERT; no synthetic clothing"],stop:["Gas detector alarm or ESD/deluge impairment without compensating measures","Lorry not earthed/chocked or hose test overdue","Overfilled cylinder not evacuated / check-weighing bypassed","Ignition source (vehicle, phone, hot work) inside licensed area without permit","Fire-water pump or storage below required capacity"],records:["PESO licences and approved drawings, gas detector/ESD/ROV tests, fire-system tests, lorry unloading logs, filling and check-weigh records","Leak-test and defective-cylinder registers, hydro-test records, PTW/gas-free certificates, MSIHC safety report and drill records, training, incident reports"],refs:{india:["Gas Cylinders Rules 2016 & SMPV(U) Rules 2016 (PESO)","OISD-STD-144 (LPG bottling plants), OISD-STD-150 (mounded LPG storage), OISD-STD-169 (LPG installations in industry), OISD-STD-116/117 (fire protection), OISD-STD-105 (permits), OISD-GDN-207 (tank-lorry safety — verify)","MSIHC Rules 1989 & Chemical Accidents Rules 1996; PLI Act; IS 6044 Pt 1/2 (LPG storage installations); IS 5572 & IS/IEC 60079; CEA 2023; Petroleum Act (if petroleum stored)"],ka:["MAH Control (Karnataka) Rules 1994; PESO Bengaluru; KSFES; KSPCB; District Crisis Group (Bengaluru Rural/Devanahalli plants)"],tn:["TN CIMAH Rules 1994; PESO Chennai; TNFRS; DISH TN; District Crisis Groups (Ennore/Manali, Madurai plants)"],osha:["1910.110 (storage and handling of LPG), 1910.119 PSM (LPG ≥ 10,000 lb), 1910.307, 1910.120; NFPA 58 (LP-gas code), NFPA 59, NFPA 15 (water spray), NFPA 77"],intl:["UK HSE LPGA/UKLPG Codes of Practice (COP 1, 7, 22), COMAH","EN 1439/EN 13952 (LPG cylinder filling), EN 12817/12819 (inspection of LPG tanks), EN 14570 (LPG tank equipping), EN 16728 (LPG cylinder periodic inspection); WLPGA guidelines"]},checklist:"cl4-lpg-bottling"}
];
const CHECKLISTS4 = [
{id:"cl4-press",t:"Power Press Shift & Set-Up Check",cat:"Industrial",items:["Operator and die-setter authorised in writing; nobody under 18 on the press","Light curtain tested with test piece at three heights; two-hand controls both required and timed; e-stop works","Brake-monitor lamp normal; stop time within recorded value; stroke selector keyed and key with supervisor","Fixed/interlocked guards fitted at rear and sides; no gaps allowing reach to the point of operation (ISO 13857)","Foot pedal only with light curtain or enclosure; pedal shrouded","Safety blocks/ram props available and used during die setting; die clamped at all designated points","Press isolated (LOTO) before hands enter die space; guard refitted and verified before first stroke","Scrap chutes/conveyors enclosed; blanks handled with cut-resistant gloves or tongs","Hydraulic hoses, relief valve setting and leaks checked; air pressure to clutch/brake within range","Coil handling: band cutter, face shield, decoiler interlocks, coil secured before clamp release","Noise zone marked; hearing protection worn; audiometry current","No bypass keys, jumpers or taped sensors; interlock audit record current","6-monthly thorough examination of press and safety devices within date (12-monthly if fixed guards only — verify)","Double-stroke/light-curtain trip near misses logged and investigated"]},
{id:"cl4-robot",t:"Robot Cell Interlock & Entry Audit",cat:"Industrial",items:["Cell risk assessment and safety validation report on file; stop distances measured and used for guard placement","Perimeter guard ≥ 1.4 m with no reach-over/under/through to the restricted space","Every gate switch/guard lock tested: opening a gate puts all robots into protective stop","Laser scanners/light curtains cover all areas where a person could stand unseen; restart impossible from inside","Request-to-enter and trapped-key/padlock procedure in use; key carried by the person inside","Teach pendant enabling device (3-position) functional; T1 speed ≤ 250 mm/s; T2 authorisations listed","E-stops at every operator station and inside cell; muting functions documented and verified","Pneumatic/hydraulic dump valves and capacitor discharge included in LOTO procedure","Gripper/tooling edges covered; hot tooling and weld spatter controls in place","Cobot force/pressure validation done after last tool or payload change","MoC records show re-validation after program/fixture/layout changes","AGV/AMR interfaces: pedestrian lanes separated, scanner fields validated","Entrant training/authorisation records (operators, cleaners, maintenance) current","No bypassed interlocks, taped sensors or fence openings found on walk-through"]},
{id:"cl4-paintshop",t:"Paint Shop Daily / Weekly Safety Check",cat:"Chemical",items:["Booth ventilation running before spraying; airflow/LEL interlock proved; filters within differential-pressure limits","Area-classification drawing available; all equipment in Zone 1/2 is Ex-rated; Ex inspection register current","No phones, non-Ex tools or vehicles in paint areas; signage in place","Earthing/bonding clamps on parts, conveyors, containers and hoses; conductive flooring/footwear in use","Isocyanate (2K) spraying only with supplied-air hood or PAPR; no one else in booth; clearance time observed","Mix room LEV running; containers closed and earthed; waste solvent in closed earthed drums; rags in self-closing bins","Oven purge, flame-failure and high-temperature limits tested; LEL control functional; no entry until cool","ED/pre-treatment: rectifier isolation proven for work near tanks; tank covers/guardrails in place; eyewash within 10 s","Overspray deposits in booth/ducts within cleaning schedule; no hot work in paint shop without permit and gas test","Spill kits, foam/CO2 extinguishers and sprinklers/suppression in service","Paint sludge, filters and spent solvent stored and manifested as hazardous waste; VOC abatement running","Painters' RPE fit tests, airline flow checks and annual lung-function/HDA monitoring current"]},
{id:"cl4-weldshop",t:"Welding / Body Shop Fume & Safety Check",cat:"Health",items:["LEV running at every manual MIG/RSW station; airflow indicator OK; smoke test shows capture at the arc","Extraction hoods positioned within 150–300 mm of arc (verify by smoke); robotic cells enclosed and exhausted","Welding fume, Mn, Zn, Cr(VI) exposure monitoring within last 12 months; results below limits or RPE in use","RSW guns: insulated handles, two-hand/enable initiation, tip dressers guarded, cables and water hoses undamaged","Water-flow switches and transformer earthing checked; no leaks onto live parts","Laser cells: Class 1 enclosure interlocks tested; LSO named; eyewear and Class 4 service procedure available","Coated/galvanised and stainless welding have extra extraction and RPE; metal-fume-fever symptoms reported","Spark screens, spatter-free zones; sealers/adhesives/cardboard away from arcs; extinguishers within 15 m","Hot-work permit used for welding outside designated shop areas","Fume filters changed per DP with FFP3 and bagged as hazardous waste; floors vacuumed (no compressed air)","Pacemaker warning signs at RSW transformers; hearing protection in zone","Health surveillance (lung function, questionnaire, skin) and LEV 14-monthly examination records current"]},
{id:"cl4-ev-battery",t:"HV / EV Battery Area Inspection",cat:"Electrical",items:["HV work bays marked; only HV-authorised persons working; never alone; rescue hook and AED at bay","Insulated tools (IEC 60900), Class 0 gloves (tested, with protectors), arc-rated face shield, insulated mats available and in date","Service disconnect/plug removed and locked; capacitor discharge time observed; 0 V verified with proven meter before contact","Pack assembly benches insulated; busbars covered; no metal watches/rings; torque tools insulated","Cells/modules inspected at receipt; swollen/damaged/hot cells quarantined immediately","Storage: SoC 30–50 %, 15–25 °C, segregated compartment, detection and suppression in service, no charging in store","DDR cells kept outdoors ≥ 15 m from buildings (verify) in metal containers with sand/vermiculite","Thermal cameras/gas (CO/VOC/H2) detection functional in formation and EOL test areas","Charging bays: cables/connectors undamaged, Type B RCD/6 mA DC detection tested monthly, e-stop works, combustibles clear","Fire plan posted: isolation points, water supply for prolonged cooling, 'lithium-ion' information for fire service","Crashed/damaged vehicles or packs isolated outdoors with 48-h thermal monitoring","Battery waste handed to registered recycler under BWMR 2022; manifests on file","HV authorisations, drills (6-monthly) and HF first-aid (calcium gluconate) kit current"]},
{id:"cl4-test-track",t:"Test Track Daily Opening Check",cat:"Management",items:["Track inspected: debris, oil, standing water, barriers/tyre walls, run-off areas, signage, lighting, fencing intact","Radio/communication check with all marshal posts; track status board set; CCTV working","Controller on duty; maximum vehicles per circuit and test slots planned; entry/exit protocol briefed","Drivers signed in with valid certification tier and medical; zero alcohol; phones off while driving","Vehicles pre-run checked (brakes, tyres, leaks, HV status); helmets/harness/cage for limit tests; extinguisher fitted","Weather within limits (visibility, wet grip, wind, lightning); night tests only with lighting","Dynamic pad/limit-handling tests scheduled with exclusion and outriggers/safety vehicle","Maintenance/pedestrian access only with zone closure, barriers and hi-vis; re-admission only after 'all clear'","Dyno cells: restraints rated, chocks, exhaust extraction, CO monitor, e-stop at console, no one in cell during test","Ambulance/paramedic and recovery vehicle available for high-speed/limit tests; hospital route known","Fatigue plan: driving blocks and breaks per policy; hydration","Incident procedure (red flag/radio stop, HV isolation, scene preservation) known to all"]},
{id:"cl4-ammonia-ref",t:"Ammonia Refrigeration Plant Weekly Check",cat:"Chemical",items:["NH3 detectors reading zero; alarm (25 ppm) and emergency ventilation/shutdown set-points tested; calibration in date","Machinery room: two outward-opening exits with panic bars, emergency stop outside door, lighting, no storage","Eyewash/shower at exit tested; SCBA (≥ 2) and gas suits stored outside room and in test; escape respirators issued","Oil-draining: dead-man valves in place, two trained persons available, written procedure and PPE at station","PRVs vented outdoors to safe height; register shows replacement within 5 years; no blocked vent lines","Pipework labelled (state, pressure, direction); insulation dry; no stains/corrosion under insulation","Receivers/vessels: test certificates in date (state rules/SMPV); gauges and relief calibrated","Evaporators in cold rooms protected by bollards; NH3 detectors in rooms with evaporators","No liquid trapped between closed valves; hot-gas defrost sequence followed; hydraulic shock investigated","Charging/decanting: hose test date, earthing, excess-flow protection, second person at e-stop","MSIHC status checked (quantity vs thresholds); on-site plan and drill records current where applicable","Operator certificates, shift logs, leak/incident log and annual IIAR 6-style inspection on file"]},
{id:"cl4-cip",t:"CIP & Food-Plant Chemical Safety Audit",cat:"Chemical",items:["Chemical inventory with SDS (local language) matches store; acids segregated from caustic and hypochlorite; PAA in cool vented store","Bulk tanks/IBCs bunded (110 %), vented, labelled; delivery couplings unique per chemical","CIP route verified; manways of tanks under CIP locked/tagged; mix-proof valves or physical breaks in place","Tank-empty-of-people confirmation recorded before every CIP start","Dosing automated; concentration and temperature logs within limits; return conductivity verified","Emergency showers/eyewash within 10 s travel, tested weekly, tempered water","PPE at point of use: goggles + face shield, gauntlet gloves, apron, boots; respirators for PAA/hypochlorite fogging","Cleaning cards show chemical, concentration, temperature, PPE and never-mix list; staff and contractors trained","No decanting from 200 L drums by hand; pumps used; all containers labelled","Spill kit and neutraliser available; drains to ETP; discharge within consent","First-aid and splash incidents logged and reviewed; hospital tie-up for alkali eye injuries","Wrong-coupling/near-miss reports reviewed; corrective actions closed"]},
{id:"cl4-silo",t:"Silo / Bin Entry Permit Check",cat:"Industrial",items:["All non-entry methods tried and recorded (poles, air cannons, vibrators, bin whips, cameras)","Feed and discharge equipment (augers, sweeps, elevators, pneumatic lines) isolated, locked and start attempted","Bridging/caking checked by camera; no entry below hanging material or above caked material level","Atmosphere tested at several depths: O2 19.5–23.5 %, CO < 25 ppm, LEL < 10 %, PH3 < 0.3 ppm (verify); continuous monitor carried","Fumigation record checked; no entry to treated bin without clearance","Ventilation running; dust respirator (FFP3 or supplied air) selected for conditions","Entrant in full-body harness on lifeline attached to rated anchor and mechanical retrieval; attendant posted","Communication method tested; rescue team and equipment (tube/vacuum/fire service contact) ready","Roof/hatch access safe: guardrails or anchors, ladder cage/rail, weather acceptable","Hot work prohibited unless silo emptied, cleaned, gas/dust tested and permitted","Explosion vents, bearing/belt sensors and Ex equipment on connected elevators/collectors in service","Permit signed by supervisor; time limits set; permit closed and records filed after exit"]},
{id:"cl4-bakery",t:"Bakery / Hot-Process Line Daily Check",cat:"Industrial",items:["Gas smell check; gas detectors and auto shut-off tested; isolation valve accessible","Oven purge, flame-failure and high-limit devices functional; no manual lighting; CO levels OK in oven room","Fryer high-limit cut-out and suppression/lid available; oil level below max; no water near fryer","Mixer bowl guards, divider/moulder covers and slicer guards interlocked; e-stops tested","Hot-surface signage; gauntlets/sleeves at ovens and fryers; trolleys locked when loading","Flour tipping under LEV; vacuum cleaning only; silo/sifter dust controls intact","Floors dry/clean; non-slip footwear; spill response","LPG/PNG: cylinders outdoors and upright, regulators/hoses in date, changeover by trained person","Burn first-aid kit (cool water access, cling film, dressings) at each hot area","Heat: oven-room ventilation on, water available, WBGT within action level or breaks applied","Night shift: minimum two persons; women's night-work conditions met","Annual burner service by licensed fitter, exhaust duct cleaning and asthma surveillance records current"]},
{id:"cl4-bottling",t:"Bottling / Packaging Line Shift Check",cat:"Industrial",items:["E-stops and interlocked guards tested on every machine; guard locking where run-down > 1 s","No reaching into running machines; jam-clearing procedure followed (stop, run-down, tool, restart)","Polycarbonate guards at filler/capper; face shields and cut-resistant gloves in glass zones","Broken-glass procedure followed: zone cleared, tongs/brush, sharps bin, breakage logged","CO2 detectors in carbonation/tank areas reading normal; calibration in date; ventilation running","CO2 tank: SMPV licence/PRV tests in date; fill by trained operator with PPE","Bottle washer caustic handling PPE available; lids interlocked; isolation before cleaning","Pasteuriser/hot zones guarded; steam/hot-water isolation valves identified","Palletiser/depalletiser cell gates interlocked; key-in-pocket entry rule followed","PET blow moulder: high-pressure air and heaters isolated for mould work","Noise zone signage; hearing protection worn; audiometry current","Floors dry; drip trays and chain-lube controlled; non-slip footwear","LOTO applied for changeovers/maintenance; zero energy verified (air, electrical, gravity)"]},
{id:"cl4-coldroom",t:"Cold Store / Freezer Weekly Safety Check",cat:"Health",items:["Every cold-room door opens from inside even when locked outside; internal release luminous and ice-free","Trapped-person alarm (battery-backed) tested; audible outside and at control room; emergency light and axe inside","Door heaters/seals working; no ice build-up at thresholds; floors de-iced","Sign-in/headcount system in use; nobody working alone in freezers","Work/warm-up schedule posted and followed; heated rest room and warm drinks available","Freezer suits, insulated gloves, thermal boots, balaclavas in good condition; medical fitness records current","CA/ripening rooms locked and placarded; O2 meter calibrated; entry only after ventilation and > 19.5 % O2 with permit","Ethylene detection and Ex equipment in ripening rooms; nitrogen generator area has O2 alarm","Blast freezers: fan isolation and door interlock tested; no entry with air blast running","Forklifts: cold-rated, lights/cameras working, speed ≤ 5 km/h inside; racking inspected for frozen-load damage","Refrigerant (NH3/CO2) detectors in rooms with evaporators tested; alarm response known","Reefer containers/trucks: chocks, door stops, internal release checked; genset exhaust away from doors","Missing-person and frostbite/hypothermia response known; SCBA available for CA-room rescue"]},
{id:"cl4-solvent",t:"Solvent Storage & Recovery Monthly Audit",cat:"Chemical",items:["PESO licence and approved drawings on site; stock within licensed quantities; day-tank quantities limited","Dyke/bund 110 % intact; tank vents with flame arresters; nitrogen blanketing or conservation vents working","Area-classification drawing available; Ex equipment register and IEC 60079-17 inspections current","LEL detectors calibrated; alarm (20 %) and trip (40 %) functional (verify set-points)","Earthing/bonding of tanks, pumps, hoses and drum stations tested; conductive hoses; dip-pipe/bottom filling","Dispensing booth LEV running; Ex pumps; no open pouring of Class A; containers labelled and capped","Peroxide-forming solvents dated; test records before distillation; none distilled to dryness","Recovery column interlocks (cooling, vacuum, level, temperature) tested; relief routed to safe location","No non-Ex phones/tools/forklifts in Zone 1/2; signage in place","Foam stocks (AR-AFFF), deluge, extinguishers and spill kits in service; emergency isolation valves accessible","Hot-work permits show gas test, isolation and fire watch; no hot work on uncleaned drums/tanks","Spent solvent segregated, labelled, ≤ 90 days, manifested to authorised recycler/co-processor","Exposure monitoring (methanol, toluene, DCM etc.) and medicals current; MoC for any change"]},
{id:"cl4-potent",t:"Potent Compound Suite Containment Check",cat:"Health",items:["OEB/OEL assigned for every compound handled; containment strategy matches band (OEB 5 = no open handling)","Isolator pressure (negative) and HEPA alarms clear; glove-port integrity tests logged for campaign","Split-butterfly valves/continuous liners used for transfers; no open scoops or bags cut outside containment","Pressure cascade correct (suite negative to corridor); differential readings logged","Containment verification (SMEPAC-style surrogate test) done at installation and after last modification","Routine air/surface monitoring results below OEL; exit-side surface wipes negative","PAPR/supplied-air units fit-tested, flow-checked; no beards with tight-fitting masks","Disposable PPE (Type 5/6 coveralls, double gloves) in use; de-gowning sequence followed; shower where OEB 5","HEPA vacuum and wet-cleaning only; cleaning agents validated; cloths/PPE bagged inside suite","BIBO filter change by trained team; filters double-bagged for incineration","Potent waste segregated for incineration; wash water treated before ETP","Medical surveillance current; reproductive-health counselling documented; exposure records retained long-term","Containment incidents (breaches, torn gloves) logged and reviewed; MoC for changes"]},
{id:"cl4-cleanroom",t:"Clean Room & HVAC Work Permit Check",cat:"Industrial",items:["AHU isolated at starter and local isolator; fan proved stopped; dampers closed/locked; LOTO tags on","Platform/guardrails or anchors for AHU/rooftop work; ladders secured; roof permit where needed","FFP3/PAPR and bagging for used filters; BIBO for potent/biological areas; DOP/PAO aerosol SDS available","Duct/plenum entry treated as confined space: fans isolated, atmosphere tested, attendant posted","Door interlocks release on fire alarm/power loss; manual override at every door tested","Gas-suppression release isolated (panel + mechanical lock-off) and tagged before entry for maintenance; restored after","Pre-discharge alarm/delay/abort function known to all; CO2 systems in occupiable rooms interlocked","Fumigation (VHP/formaldehyde): room sealed, placarded, doors locked, adjacent areas monitored","Re-entry only after aeration and verified concentration (< 1 ppm H2O2 / < 0.1 ppm HCHO — verify) at head height","Autoclaves/tunnels/lyophilisers: pressure-vessel certificates, door interlocks, cool-down before unloading","Nitrogen areas have O2 monitors (< 19.5 % alarm); UV-C lamps interlocked/off before opening","70 % IPA bulk stored per Petroleum Rules; disinfectants handled per cleaning cards with PPE","Evacuation drill done with gowned staff; fire service aware of suppression gases and fumigation"]},
{id:"cl4-reactor",t:"Reactor Charging Pre-Batch Check",cat:"Chemical",items:["Batch record and reaction hazard sheet reviewed: materials, order, quantities, safe operating limits, relief case","Reaction hazard data (DSC/ARC, onset temperature, gas evolution) available for this process; HAZOP actions closed","Nitrogen supply and O2 analyser working; O2 below inerting limit before powder charging (verify limit)","Reactor, hopper/chute, drums, FIBC and operator earthed; earthing continuity verified; conductive/dissipative liners only","Closed charging system (split valve/hopper/vacuum) used where available; manway charging risk-assessed with LEV","Solvent temperature below flash point where feasible; no free-fall of flammable liquids (dip pipe/bottom entry)","Agitator running/interlocked as required; cooling water flow and temperature alarms functional; emergency cooling/quench available","Relief and vent path clear; rupture disc/PRV in date; scrubber on","Ex equipment only in area; no plastic drums/scoops for Class A solvents","PPE: antistatic FR coveralls, conductive shoes, goggles/face shield, gloves, respirator per material","Sampling via closed sampler; manway not opened on hot/pressurised vessel","Deviation/runaway response (stop feeds, max cooling, quench/dump, evacuate) known to crew","MoC completed for any change of material, vendor, scale or equipment"]},
{id:"cl4-cotton-dust",t:"Cotton Dust & Byssinosis Programme Audit",cat:"Health",items:["Dust monitoring at fixed stations (blow room, carding, ring, weaving, waste room) monthly; personal samples on rotation","Results compared with PEL/action level; posted on department boards; actions where exceeded","Blow-room machines enclosed with suction; card hoods and continuous waste removal working","Central filtration plant: differential pressure normal; discharge outside shed; filters cleaned on schedule","Housekeeping by vacuum/wet methods; no compressed-air blow-down with workers present","Respirators (FFP2/FFP3) issued for blow room, card stripping, filter cleaning and waste rooms; replacement schedule","Pre-placement and periodic spirometry (pre/post shift on first working day of week) by certifying surgeon; records in prescribed form","Symptomatic workers (Monday chest tightness) referred and relocated pending review","Byssinosis cases notified to DISH/DFBISH and ESI; register maintained","Smoking banned in premises; health education sessions in local language recorded","Noise zones marked in ring/weaving sheds; audiometry current","Annual review of exposure trends, medical findings and control upgrades documented"]},
{id:"cl4-dyehouse",t:"Dye House & Boiler Weekly Check",cat:"Chemical",items:["Chemical store segregated: oxidisers (H2O2) away from reducers (hydrosulphite); acids away from hypochlorite and caustic","Hydrosulphite drums sealed, dry, cool; no warm/wet/smoking drums; handled dry","Dye powders weighed in booth with LEV; FFP2/3 worn; SDS in local language available","HT dyeing machines: door interlock (pressure/temperature) tested; PRV and gauge in date; vessel certificate current","Jiggers/winches/steam lines: nip guards, lids, lagging intact; valves opened slowly","Stenter: duct/filter cleaning done (weekly); gas train purge and flame safeguard tested; no manual lighting","Thermic-fluid heater: leak check done; no fluid on hot surfaces; fluid test within year","Boiler: certified attendant on shift; low-water cut-off tested; log book up to date; annual certificate valid","Emergency showers/eyewash within 10 s travel tested; spill kits with dry absorbent (no sawdust)","ETP: H2S monitors at anaerobic units/sumps; confined-space permits for sump work; chlorine dosing PPE","PPE at stations: goggles/face shield, gauntlets, aprons, gumboots, heat gloves","Chlorine-release and hydrosulphite-fire response known; extinguishers and fire crew contacts posted"]},
{id:"cl4-textile-machines",t:"Textile / Garment Machinery Guard Audit",cat:"Industrial",items:["Blow-room beater/cleaner lids interlocked with run-down time delay; not bypassed","Card lickerin/cylinder covers interlocked; stripping/grinding only with machine stopped and locked","Nip guards on drafting/calender rollers; spindle tapes and gears guarded on ring/speed frames","OE rotors and autoconer splicers guarded; stop before threading inside guards","Looms: shuttle guards/fly catchers fitted; e-stops reachable both sides; beam hoist/trolley inspected","Permitted running-task list displayed per machine; cleaning inside running machines otherwise prohibited","Dress code enforced: hair covered, no loose dupatta/scarf/jewellery, fitted sleeves (visitors too)","No women/children at cotton openers; young-worker register checked against dangerous-machine list","Band knife: chain-mail glove and finger guard; straight knife blade guard; blade change under isolation","Sewing/overlock: needle guards and eye guards fitted; broken-needle procedure in use","Fusing presses/irons: interlocks/heat shields, steam hoses inspected, iron boilers within exemption or certified","Exits and aisles (≥ 1.2 m) clear of stock/trolleys; hearing protection in weaving/ring sheds","Guard defects tagged and machines stopped until repaired; monthly audit record with safety committee"]},
{id:"cl4-humidification",t:"Humidification, Heat & Air-Washer Check",cat:"Health",items:["Hygrometer (dry/wet-bulb) readings taken at prescribed times and recorded in Humidity Register","Wet-bulb below statutory limit; humidification switched to ventilation-only when exceeded","Hygrometer wicks clean, water distilled; calibration record","Humidification water of required quality (potable/purified); treatment records","Air-washer sump clear; nozzles spraying; drift eliminators intact; biocide dosing logged","Sump cleaning/disinfection within schedule (≥ quarterly — verify); confined-space permit used; disinfectant neutralised before discharge","TVC/Legionella sampling on schedule; results within action levels","WBGT measured per department; summer protocol (breaks, water/ORS, task rotation) active above action level","Cool rest area and drinking water points within 50 m; new workers acclimatised 7–14 days","Heat-illness cases logged; first aiders trained in heat stroke response","Plant room: fans/pumps guarded, RCD sockets, dry floors, chemical PPE and eyewash","Electrical panels/lights free of condensation ingress; RCD tests current"]},
{id:"cl4-moulding",t:"Injection Moulding Machine Shift Check",cat:"Industrial",items:["Front gate interlocks (electrical + hydraulic/mechanical) tested — machine does not close with gate open","Rear/top guards, purge guard, nozzle guard and hopper interlock in place; e-stops tested","Hands enter mould area only via front gate in semi-auto, or in set-up mode with clamp blocked/machine isolated","Purge procedure: shield down, face shield and heat gloves, nobody in front of nozzle, purge to metal tray","Barrel/nozzle hot surfaces guarded or insulated; hot-runner leaks reported","LEV running for PVC/POM/PU/decomposition-prone materials; no smoke/odour from barrel","Mould change: eyebolts inspected and rated, crane/slings certified, clamps torqued, safety strap on halves","Hydraulic leaks checked; accumulators discharged for maintenance; nitrogen gas-assist lines rated","Take-out robot/sprue picker within guards; perimeter interlocks tested","Granulator: hopper interlock with time delay; blade change under LOTO with cut-resistant gloves","Dryers/hopper loaders isolated before clearing; pellet spills cleaned (slips)","Noise zone/hearing protection; machine safety log signed; defects → machine off until repaired"]},
{id:"cl4-extruder",t:"Extrusion / Film Line Pre-Start Check",cat:"Industrial",items:["Zone temperatures and soak time per procedure; melt-pressure transducer working; rupture disc fitted and directed away from stations","Nip guards closed on haul-off, winders, chill rolls; pull-wire e-stops tested along line","Threading done at creep speed with threading tools; no hands near nips at speed","Die bolts tightened per sequence with heat PPE; nobody in line of die face at start-up","No torch/naked flame used on blocked die; frozen-die procedure available","Screw removal tool/hoist and cradle available; barrel pressure zero before removal","Corona treater enclosure interlocked; ozone extraction running","Pelletiser/strand cutter/saw guards interlocked; blade changes under LOTO","Film tower: guardrails, stairs/platforms, roll-change hoist inspected","Reels/rolls secured on stands; mechanical aids for 500–1,000 kg reels","LEV at die/exhaust hoods running; decomposition smell → reduce heat, ventilate","Hot-melt: tank lid guard, pressure released before hose/applicator change, hoses inspected, burn kit at station"]},
{id:"cl4-calender",t:"Two-Roll Mill / Calender / Mixer Shift Check",cat:"Industrial",items:["Trip bar/cable tested at start of shift: rolls stop within marked distance and separate/reverse","Brake lining and stopping-distance log current; defective mill out of service","Two trained persons present whenever a mill runs; operator rules displayed","Feeding tools and mill knife used; no gloves/loose sleeves at nip; sleeves fitted","Calender nip guards, trip wires and e-stops both ends tested; thread-up at creep with two persons","Banbury: charging door and hopper interlocks tested; ram control two-hand/guarded; LEV at charging","Chamber cleaning only under LOTO, cooling and permit","Curing presses: light curtains/two-hand controls functional; platen heat shields; mould lifting aids","Autoclaves: pressure-vessel certificate current; door opened only at zero pressure and cooled","Carbon-black station LEV and FFP2; housekeeping by vacuum","Solvent/cement room: earthed containers, Ex ventilation, respirators, no ignition sources, closed waste drums","CO2/DCP extinguishers at each mill; no water on hot oil; fume LEV running","Exposure monitoring (rubber fume/dust, nitrosamines) and medicals current"]},
{id:"cl4-printing",t:"Solvent Printing / Lamination Daily Check",cat:"Chemical",items:["LEL monitors at presses/dryers reading normal; calibration in date; alarm/shutdown set-points verified","Ex lighting/motors/instruments intact; no non-Ex phones or tools in Zone 1/2","Earthing straps on presses, rollers, doctor blades, ink pumps and containers; ionisers at unwind/rewind working","Static measurement/earthing test records within schedule; conductive flooring and footwear in use","Dryer purge, flame safeguard and airflow interlocks functional; duct cleaning within schedule","Ink kitchen LEV running; containers closed/earthed; Ex pumps; no open plastic containers for Class A","Solvent stock within PESO licence; bunded storage; waste solvent/inks/rags in closed earthed drums","Rag bins self-closing and emptied each shift; spill kit with inert absorbent","Nip guards on presses/laminators; doctor blade and slitter blades handled with cut-resistant gloves","Gravure cylinders lifted with rated devices; racks secure; plating-shop Cr(VI) controls in place","Isocyanate (PU adhesive) controls: enclosed mixing, LEV, gloves, health surveillance","Sprinklers/CO2/foam systems and extinguishers in service; hot-work permits used; drill records current"]},
{id:"cl4-soldering",t:"Soldering Area Fume & Lead Hygiene Check",cat:"Health",items:["Tip extraction/LEV on at every hand-soldering station; smoke test shows capture; filters within indicator","Wave/selective/reflow machines exhausted to outside or filtered; N2 reflow areas have O2 monitor","Lead solder area designated; no food/drink/cosmetics; hand-wash before breaks; wet-wipe benches","Dross skimmed with tools and face shield into labelled metal container; boards/components dry before wave","Solder pot temperature controllers and over-temperature cut-outs working; splash shields fitted","Flux/IPA/cleaners in small closed dispensers under LEV; bulk stock stored per flammable rules","Conformal coating/potting in LEV booth; UV curing shielded; nitrile gloves for uncured resins","ESD wrist straps with 1 MΩ resistor; irons/stations earthed; RCD tested","Blood-lead and spirometry programme on schedule; results below action levels or workers removed from exposure","Occupational asthma/lead symptoms reported and investigated; notifiable disease reporting known","Fume filters/dross/lead waste manifested as hazardous waste; E-waste rules followed","LEV examination (14-monthly) and training records current"]},
{id:"cl4-fab-chem",t:"Fab Chemicals & Specialty Gas Area Daily Check",cat:"Chemical",items:["TGMS and O2 monitors online; alarm set-points per gas; calibration in date; no bypassed channels","Gas cabinets: exhaust flow verified, excess-flow/RFO valves, auto shut-off and purge panels functional","Cylinder change-outs by two certified technicians with gas-specific PPE; logs complete","Silane bunker outdoors with deluge armed; pyrophoric handling area clear of combustibles","Wet benches: exhaust on, lids closed between steps, splash guards on hot baths, no piranha stored closed","HF points: 2.5 % calcium gluconate gel in date, eyewash/shower within 10 s tested, HF first-aid trained staff on shift","TMAH handled in closed systems; concentrate access restricted; flush/hospital protocol posted","Chemical delivery systems: leak detection and double containment alarms clear","PPE matrix per chemical followed: double gloves (laminate for HF), face shield + goggles, apron, boots","Scrubbers (acid/base/VOC/POU) running within parameters; exhaust duct integrity","Plating/etching: LEV at tanks, cyanide and acid physically separated, Cr(VI) controls, waste treatment logs","Cryogen (LN2) areas: O2 alarm, cryo PPE; sub-fab ventilation normal","Waste segregated/labelled (HF neutralised, cyanide separate); HOWM manifests; empty cylinders capped and returned","ERT SCBA/suits inspected; drill (gas release/HF burn) within schedule; MSIHC documents current where applicable"]},
{id:"cl4-licell",t:"Lithium Cell Storage & Handling Inspection",cat:"Electrical",items:["Storage compartment segregated/fire-rated; quantity and kWh within limits; aisles and sprinkler clearance kept","Cells/packs at 30–50 % SoC; temperature 10–25 °C; no charging in storage","Receipt inspection done (dents, swelling, leaks, odour, temperature); suspect lots quarantined","DDR cells outdoors ≥ 15 m (verify) in metal containers with sand/vermiculite; labelled","Off-gas/smoke detection and sprinklers in service; HVAC isolation on alarm tested","Twice-daily thermal-camera rounds logged; no hot spots","Handling: insulated tools, terminals covered, no jewellery; lifting aids for > 25 kg","Formation/ageing racks: per-channel temperature/voltage trips tested; local suppression in place","Electrolyte/NMP areas: LEV, HF kit (calcium gluconate), exposure monitoring; dry-room entry limits","Water supply for prolonged cooling available; Class D agent only for lithium-metal cells","Fire-service information sheet (chemistry, kWh, layout) current; ERT trained; drill within 6 months","UN 38.3 certificates for shipped cells; UN 3480/3481 packaging; damaged cells shipped under special provisions","Battery waste to registered recycler under BWMR 2022; manifests filed"]},
{id:"cl4-wtg-climb",t:"Turbine Climb Pre-Ascent Check",cat:"Construction",items:["Two persons minimum; GWO BST (or equivalent) and medical fitness current for both","Wind at hub below OEM climb limit; no lightning alert within 30 km; forecast checked","Communication with control/site office tested; climb logged with expected duration","Tower base: switchgear status checked, no live work in progress, base clear of snakes/water","Harness, twin lanyards, fall arrester, positioning lanyard, helmet inspected (6-monthly tag + pre-use)","Fall-arrest rail/rope system inspection in date; rungs/hatches/platforms sound","Climb assist/service lift: pre-use check, load limit, interlocks, e-stop; not used in lightning alert","Tools tethered/in bags; hoist line used; exclusion zone at tower base when work aloft","Water carried (≥ 500 mL per 30 min climbing — verify); rest at each platform; heat plan in summer","Rescue kit at nacelle/top platform with rope ≥ hub height + margin; inspection in date","First-aid kit, AED and vehicle available at ground; hospital route known","Hatches to be closed behind; 100 % tie-off at transitions briefed"]},
{id:"cl4-wtg-rescue",t:"Turbine Rescue Readiness (Monthly)",cat:"Fire & Emergency",items:["All technicians current in GWO Advanced Rescue (or equivalent); at least two trained per turbine team","Site rescue plan per turbine model with anchor points and methods available in vehicles","Rescue kit (descender EN 341, rope ≥ hub height + 10 %, stretcher/sling, pulleys, knife, torch) inspected and sealed","Second kit for tower-ladder rescue at base/mid-platform","Trauma straps on every harness; suspension-trauma response briefed","Personal descenders carried in nacelle for fire escape; nacelle fire alarm/suppression status known","Ground: AED, trauma kit, stretcher, blankets, oxygen (if trained) checked","GPS/plus-codes of each WTG, hospital and ambulance numbers posted; meeting points agreed","Radio/mobile coverage verified; satellite phone at control room","Drill done within last 6 months covering two scenarios; actions closed","Annual joint drill with fire service/ambulance scheduled or done","Incident reporting and family-liaison procedure known to site manager"]},
{id:"cl4-wtg-nacelle",t:"Nacelle / Hub Entry & Rotor Lock Permit",cat:"Electrical",items:["Turbine in service mode from control; stop and brake confirmed; work logged","Electrical isolation per turbine LOTO list: LV main breaker, converter, pitch/yaw, UPS/batteries locked and tagged","HT isolation via authorised person with permit where required; earths applied","Dead test with proven instrument on each circuit; capacitor discharge time observed","Hydraulic accumulators (brake/pitch) depressurised and verified 0 bar","Rotor lock: blades feathered, pins inserted (all), indicator and visual verification, lock tag applied","Yaw lock engaged for yaw/roof work; pitch mechanical blocks for blade-bearing work","Wind below lock/roof limits; no lightning alert; weather monitored","Hub entry: two persons, hatch secured open, radio, lighting, atmosphere check if solvents used","Nacelle roof: anchor connection before exit, tools tethered, time limited, no rain","Hydraulic bolting tools inspected; hoses/couplings rated; hands clear of reaction arm","Nacelle crane/hoist test within 12 months; rigging inspected; base exclusion zone for lifts","Return-to-service sequence (persons/tools out, pins/blocks removed, earths/locks removed, control informed) planned"]},
{id:"cl4-blade",t:"Blade Access / Rope Work Daily Check",cat:"Construction",items:["Rotor locked with blade at 6 o'clock; pitch locked; isolation recorded","Wind ≤ 10–12 m/s (verify), no rain, no lightning within alert radius; forecast monitored continuously","IRATA/SPRAT certificates and logbooks valid; Level 3 supervisor on site","Anchors rated and inspected; two independent systems rigged; rope protectors at edges","Blade platform (if used): daily check done, 12-monthly examination in date, SWL known, secondary brake tested","Ground exclusion zone (≥ blade length) with signs and spotter; radio check","Tools/pots tethered; haul line used; no loose items","Grinders with vacuum shroud; FFP3/PAPR, Type 5/6 coveralls, nitrile gloves, eye protection","Resin/hardener SDS available; pot life and cure temperature planned; heating blanket thermostat and extinguisher","Blade interior entry: permit, two persons, ventilation, gas test, lifeline, maximum distance per OEM","Lightning protection system to be inspected after any strike before work","Drone ops: DGCA registration/pilot certificate, airspace clearance, flight log","Waste bagged for HOWM disposal; end-of-day tool inventory and rotor release plan"]},
{id:"cl4-wtg-weather",t:"Site Weather & Lightning Daily Board",cat:"Management",items:["IMD forecast and lightning outlook reviewed at morning brief; weather board updated","Wind forecast at hub height vs task limits (climb, lock, roof, blade, crane, module handling) recorded","Lightning detection feed/app active; alert (30 km) and stop (15 km — verify) radii known to all teams","Control room monitoring met mast and alerting teams; radio check done","Live wind reading at task start logged by lead technician/crane supervisor","Heat index/WBGT measured; rest schedule and water/ORS in place","Monsoon: tower bases/trenches/inverter stations checked for water; slip controls; RCD tests","Cyclone/red alert plan reviewed in season; evacuation triggers and communication tree current","Shelter locations (vehicles, control building) known; no shelter under turbines/trees/lines","Post-storm LPS/receptor inspection and electrical checks procedure available","Stop-work events logged; near misses reviewed monthly","Pre-season refresher briefing (pre-monsoon / NE monsoon) completed"]},
{id:"cl4-remote-er",t:"Remote Site Emergency Readiness (Monthly)",cat:"Fire & Emergency",items:["Emergency plan with GPS/plus-codes of all assets, access roads and meeting points in every vehicle and control room","Primary and secondary hospitals (24×7 trauma, ASV stock verified) and ambulance numbers posted; travel times known","Radio network coverage (incl. tower interiors) tested; satellite phone at control room; coverage map current","Check-in protocol in use; lone working prohibited for HT, height and confined tasks","Certified first-aid responders on every crew; refresher dates tracked","AED(s) and trauma kits inspected (expiry, battery); stretcher/basket available","Snakebite kit (pressure-immobilisation bandage) and protocol posted; snake gaiters for vegetation work","Vehicles: seat belts, first-aid kit, extinguisher, torch, tow rope; drivers trained; journey management for night call-outs","Causeway/flood depth gauges and alternative routes identified for monsoon","Inverter-station/transformer extinguishers and grass-fire plan in place; local fire station contact","Quarterly drill done (scenario rotation) and actions closed; annual joint drill planned","Incident reporting matrix (OSH Code/BOCW/CEA/police) and family-liaison contacts current"]},
{id:"cl4-solar-dc",t:"Solar PV DC Work Permit & O&M Check",cat:"Electrical",items:["Electrical PTW issued; single-line diagram and isolation points identified; weather dry, no lightning","Only authorised persons on DC work; never alone; PV-specific training current","AC breaker open and locked; DC isolators open at inverter and SCB; inverter discharge time observed","Absence of voltage verified at work point with CAT III 1,500 V meter proven before and after","Opaque module covers used where strings cannot be isolated; clamp meter confirms zero current before any connector is opened","Insulated tools (IEC 60900), insulating gloves (class per voltage — verify) with protectors, arc-rated face shield available and in date","Connectors matched make/model, torqued/crimped per OEM; burnt/discoloured connectors replaced and logged","SCBs/inverters: IP seals intact, no water ingress, SPD indicators normal, terminations tight; thermography within schedule","'Live in daylight' labels on all DC enclosures; firefighter isolation/rapid-shutdown signage present","Earth continuity and insulation-resistance test reports (IEC 62446) current; ground-fault/arc-fault alarms investigated","Tracker motion isolated (LOTO) for maintenance in arrays; trench/cable work controlled","Cleaning crews briefed: no contact with cables/enclosures; no pressure jets at connectors; dawn/dusk schedule","CEIG approval/periodic inspection records available; electrical accidents reported within 48 h"]},
{id:"cl4-fragile-roof",t:"Rooftop PV Work Daily Check",cat:"Construction",items:["Roof survey available: sheet type/condition, fragile areas and rooflights marked, structural capacity confirmed","AC (asbestos) sheets identified; no dry cutting/drilling; clamps on purlins preferred; asbestos controls where unavoidable","WAH permit issued; weather within limits (wind ≤ 10 m/s for modules — verify; no rain/lightning)","Edge protection (guardrails) or lifelines/anchors (tested) in place; harness with twin lanyards worn beyond guardrails","Rooflights/fragile zones covered/caged or netted; walkways/crawl boards laid across purlins","Ladder/stair access secured and extending 1 m above landing; hatches closed after use","Exclusion zones below work and lifts; overhead power-line clearance confirmed","Module lifting: crane/hoist certificates, lift plan, tag lines, pallets secured; manual carry two-person on walkways only","Rescue plan and equipment on site; first aid and water available; heat schedule in force","Tools/materials secured against wind at breaks and end of shift; loose items removed","Damaged sheets reported to owner and barricaded below","Cleaning/O&M visits follow the same access and fall-protection rules; anchors checked before use"]},
{id:"cl4-bess",t:"BESS Monthly Inspection & Alarm Readiness",cat:"Electrical",items:["BMS/EMS alarms reviewed daily; no unresolved cell voltage/temperature deviation","Gas (H2/CO/VOC), smoke and heat detection tested; ventilation/deflagration vents clear and functional","Suppression system (per OEM) inspected; no impairment without compensating measures and fire-service notice","HVAC/thermal management within set-points; coolant levels/leaks checked (liquid-cooled)","'Do not open doors during gas alarm' rule posted; standoff distance marked (≥ 50 m — verify)","Thermography of DC busbars, rack connections and PCS within schedule; torque checks annual","DC rack/PCS LOTO procedure available; insulated tools, gloves, arc-rated PPE in date","Separation distances and fire-rated barriers maintained; no combustible storage near units","ERP agreed with fire service; information sheet (chemistry, kWh, layout, isolation points) current; last drill within 12 months","Water supply (hydrants/monitors) for prolonged cooling available; runoff containment identified","CEIG approval, Fire NOC and UL 9540A/IEC 62619 documentation on site","MoC records for firmware/chemistry/layout changes; technician training current","Decommissioning/battery-waste route under BWMR 2022 defined"]},
{id:"cl4-quay-crane",t:"Quay & Yard Equipment Shift Check",cat:"Industrial",items:["Crane pre-use: brakes, limits, spreader twistlock indicators, anti-collision, wind alarm, lights, radio","Lifting appliance register: tests and 12-monthly thorough examinations in date; defects tagged out","Operator certification and medical valid; fatigue hours within limits","Wind reading below terminal limit; storm pins/anchors ready; stack heights adjusted if warning","Quay operational area clear of pedestrians; ITV drivers in cab under crane; marked walkways in use","Hatch covers placed in marked areas with barricades","Lashing platforms/cages used; no climbing on container stacks; lashing gear inspected; rods handled in pairs","Reach stackers/straddles/RTGs: daily checks, cameras/alarms working, speed limits observed, truck drivers in cabs","Container checks: CSC plates, VGM verified, damaged/leaking boxes isolated, DG placards and segregation","Night lighting adequate at work areas; wet-deck slip controls","Incident/dangerous-occurrence reporting to port authority/Dock Safety Inspector known","Near misses (struck-by, dropped objects, wind events) logged and reviewed weekly"]},
{id:"cl4-hold-entry",t:"Ship Hold / Enclosed-Space Entry Permit",cat:"Industrial",items:["Ship–shore meeting held: cargo type (IMSBC hazards), fumigation status, ventilation, emergency contacts","Hold ventilated; atmosphere tested at three depths with calibrated detector: O2, LEL, CO, H2S, PH3 within limits","Fumigated cargo: gas-free certificate from licensed fumigator; placards removed; residues disposed","Ship's enclosed-space permit (SOLAS XI-1/7) and stevedore permit both issued; attendant at hatch","Entrants carry personal 4-gas monitors; continuous monitoring in deep holds","Hold ladder inspected; one person at a time; harness/fall arrester where fitted; tools on hoist line","Hatch coaming guarded or exclusion maintained; lighting adequate","No persons in hold while grab or dozer operates; CO monitoring with diesel plant; ventilation","Adjacent spaces (stools, ducts, stores) tested and permitted separately","Rescue: ≥ 2 SCBA sets, rescue harness/stretcher, crane standby, oxygen; rescuers never enter without SCBA","Heat/dust controls: hydration, rotation, FFP3, water sprays where allowed","Permit closed on exit; readings and entrant log filed"]},
{id:"cl4-mooring",t:"Mooring Operation Pre-Start Check",cat:"Construction",items:["Mooring plan agreed with ship (lines, sequence, tide, weather limits, VHF channel, language)","Bollards/quick-release hooks inspected; SWL ≥ line MBL; damaged bollards out of service","Linesmen trained; team size adequate; foreman briefed gang on snap-back (whole-area) rule and signals","Lifejackets (150 N) worn by all within 2 m of quay edge and in boats","Quay edge lighting, lifebuoys with lines, self-rescue ladders in place","Heaving lines without added weights; no standing in bights or line of pull","Mooring boat: coxswain, lifejackets, load limit, radio, clear of propeller/lines in water","Quay traffic stopped in mooring area during operations","Gangway: safety net, angle within limit, secured, lit, lifebuoy at foot; access controlled (ISPS)","Tanker jetty: ESD tested, breakaway couplings, ISGOTT checklist signed, drift alarms","Cargo-watch line checks at tide changes scheduled; weather deterioration plan agreed","Man-overboard and line-parting response known; incident reporting route posted"]},
{id:"cl4-dg-container",t:"DG Yard / CFS Dangerous Goods Audit",cat:"Chemical",items:["DGD, UN number, class, SDS and placards (four sides) verified for every DG unit; non-compliant units held","Segregation per IMDG table and quantity limits per class maintained in dedicated DG yard","Class 1 and ammonium nitrate under direct delivery/PESO conditions; no storage beyond permitted period","Class 5.1 (calcium hypochlorite) and 4.2 units shaded/ventilated; lithium battery units monitored","Daily thermal/leak/odour round logged; IR thermometer and gas detector in use","Fumigated unit register current; UN 3359 marks checked; de-stuffing only after ventilation and gas test (PH3/MeBr/VOC)","Container opening procedure (doors cracked from side, ventilation time, breathing-zone test) followed by customs/CFS staff","Hazmat response: Level A/B suits, SCBA, absorbents, overpacks, booms; ERG/EmS references available","Leaking/heating units isolated upwind; drains blocked; shipper/port/SPCB notified","Fire hydrants/monitors clear; fire service familiar with DG yard; evacuation distances known","IMDG Ch. 1.3 training records for all DG-handling and examination staff (refresher 2 yr)","No smoking/phones in DG yard; forklifts DG-rated; cyclone/weather plan for DG stock"]},
{id:"cl4-sugar",t:"Sugar Mill Season Weekly Check",cat:"Industrial",items:["Cane yard: one-way flow, marshals with radios, speed limit, lighting, drivers clear of unloading bays, trolleys chocked","Cane carrier/bagasse conveyor nip guards and pull-wire stops tested; no hand feeding; choke clearing under LOTO","Knives/shredder/mill covers interlocked; roller setting under LOTO with two persons","Centrifugals: lid interlock and brake tested; over-speed/vibration trips tested weekly; annual basket NDT in date","Bagasse stacks: temperatures probed and logged; fire breaks clear; water monitors/hydrants ready; no hot work","Spark arrestors on boiler stacks; bagasse conveyor dust housekeeping done","Boiler: certified attendant, low-water cut-off test, log book; certificate valid; pressure-vessel tests in date","Sulphur burner: SO2 detector working, scrubber running; lime slaking PPE (face shield, gloves) in use","Hot-liquor valves operated from side; lagging intact; scald first aid available","Pan/evaporator/molasses tank entries under confined-space permits with gas tests","Sugar house: dust housekeeping, Ex equipment, venting intact; bagging aids for 50 kg bags","Seasonal workers inducted (language, buddy, colour code) before posting; OHC/first aid 24×7"]},
{id:"cl4-grain-mill",t:"Rice / Flour / Oil Mill Monthly Check",cat:"Industrial",items:["Dust layers below housekeeping limit; vacuum/damp sweeping; no compressed-air blow-down near ignition sources","Bucket elevators: belt-slip/alignment switches and bearing temperature monitors working; explosion vents unobstructed","Magnets/destoners before mills working; tramp-metal log","Ex-rated electricals in dusty areas; no damaged fittings; thermography within year","Hullers/polishers/roller and hammer mills guarded; chokes cleared only after stop and isolation","Husk boiler/furnace: certified attendant, low-water cut-off tested, husk storage away from furnace, spark arrestors","Parboiling/driers: hot water/steam PPE, flame-failure on burners, CO check in enclosed drier rooms","Silos/bins: zero-entry policy; permits, lifeline and isolation for any entry","Bag stacks within height limit, dunnage, interlocked pattern, no lean/wet bags; ladders used","Manual handling: mechanical aids in use; two-person lifts > 50 kg; heat breaks for loaders","Fumigation only by licensed fumigator: placards, exclusion, aeration and clearance records; no worker-applied AlP","Solvent extraction (if any): LEL monitors, earthing, Ex equipment, hexane licence; hot-work ban","Respirators issued for dusty jobs; lung-function screening and noise audiometry records"]},
{id:"cl4-seasonal",t:"Seasonal / Migrant Worker Mobilisation Audit",cat:"Management",items:["Contractor licence/registration valid; worker lists with age proof and origin state; inter-state migrant registration done","No worker under 14; 14–18 not in hazardous processes; age verification records","Induction completed in workers' languages before any work; competence sign-off for job-specific tasks","Buddy/mentor assigned for first 2 weeks; colour-coded helmet/band for workers in first 30 days","No new worker on cane yard traffic, centrifugals, boilers, HT or confined spaces until authorised","PPE issued free, sized (incl. women), replacement register","Welfare: drinking water (tested), toilets/bathing ratios, rest shelters, canteen/crèche where thresholds met","Camps inspected weekly: space, ventilation, lighting, LPG/cooking safety, electrical, waste, vector control, fire extinguishers","Wages via bank on time with slips; overtime limits; weekly off; PF/ESI or EC insurance confirmed","First-aid boxes stocked, OHC/ambulance tie-up; night transport/first aid arrangements posted","Grievance channel (multilingual) and labour helpline displayed; complaints logged and closed","Women's night-work conditions met (consent, transport, security, minimum numbers)","Monthly HR–safety audit done; corrective actions with contractor tracked"]},
{id:"cl4-dg-room",t:"DG Set & Generator Room Weekly Check",cat:"Electrical",items:["'May start automatically' signage; AMF disabled, battery disconnected and control fuse removed before any work (LOTO)","Changeover/ATS back-feed interlock (mechanical + electrical) tested; no bypass","Room ventilation adequate; exhaust piped to stack at CPCB height; insulation intact; ≥ 0.5 m from combustibles (verify)","CO detector in basement rooms tested monthly; no occupancy during runs","Fuel: day tank within exempt quantity or PESO licence; bund 110 %, level gauge/overfill alarm, shut-off valve, spill kit, no leaks","Fuel transfer with bonding, drip trays; no filling in lightning","Battery: terminals clean, no swelling, ventilation, acid PPE and insulated tools available","Guards on radiator fan/belts; hot exhaust manifold shielded; no rags/combustibles in room","Fire detection and CO2/DCP/clean-agent extinguishers or fixed system in service; no storage in room","Noise: enclosure doors closed during runs; 75 dB(A) at 1 m; hearing protection inside enclosure","Weekly test run logged (readings, defects); AMC vendor inducted; CEIG approval/inspection records on file","Emission compliance (CPCB IV+/stack test) and used-oil manifests current; running hours/fuel logged"]},
{id:"cl4-hvac",t:"HVAC Plant Room & Refrigerant Monthly Check",cat:"Industrial",items:["Refrigerant detectors and O2 monitor (where fitted) tested; alarm set-points per refrigerant; ventilation auto-start works","Machinery room: self-closing doors open outward, emergency shut-off outside, no open flames, signage with refrigerant/charge","Refrigerant log per system current; losses > 5 %/yr investigated; no venting (ODS Rules)","Technicians certified in refrigerant handling; recovery machine and rated cylinders available","Pressure/leak testing with OFN and regulator/PRV only; never oxygen or compressed air","Brazing: refrigerant recovered, OFN purge flowing, hot-work permit, fire watch, ventilation","Refrigerant cylinders upright, shaded, ≤ 50 °C, caps on; A2L/A3 refrigerants handled with Ex tools and ventilation","AHU/fan work: LOTO at starter and local isolator; belts guarded after service; filters changed with respirator","Rooftop units: edge protection/anchors, secured ladders, weather check","Ducts/plenums/tanks entered only under confined-space permit","Cooling-tower legionella scheme: dosing, cleaning/disinfection and sampling records current","Chemical dosing PPE/eyewash; hot-surface and steam/hot-water isolation identified","Escape respirators/SCBA for large-charge or ammonia rooms inspected; leak response known"]},
{id:"cl4-lift-mr",t:"Lift & Escalator Statutory and Maintenance Check",cat:"Industrial",items:["Lifts Act licence and periodic inspection report current; licence and load notice displayed in car","AMC with licensed firm; monthly maintenance logged in lift book; mechanics trained","Landing door interlocks tested; no jumpers/bypass; landing-door emergency keys controlled","Car-top: INSPECTION mode, stop switch, guardrail/clearance per standard; two persons for hoistway work","Pit: stop switch, light, ladder, counterweight screen; car blocked/inspection mode before pit entry","Machine room/controller: LOTO at mainline and car-light switches; VVVF capacitor discharge; sheaves guarded; no storage","Ropes/brake/safety gear inspected per schedule; discard criteria applied","ARD, alarm/intercom and emergency light tested; emergency power for hospital/bed lifts","Trapped-passenger release: trained persons listed; response ≤ 30 min; car-position confirmation and landing-zone rule known","Escalator: emergency stops, comb plates, skirt brushes, handrail checked daily; pit work under LOTO and barricades","Fire lift/fireman's switch tested; lifts recall on fire alarm","Entrapment and injury log reviewed; incidents reported to Inspectorate as required"]},
{id:"cl4-housekeeping",t:"Housekeeping Contractor Monthly Audit",cat:"Management",items:["Contractor licence, wages, PF/ESI and attendance verified; PPE and training supplied free","Approved chemical list with SDS in local language; dilution charts and never-mix (acid + bleach) rule displayed","All bottles/dispensers labelled and colour-coded; no decanting into drink bottles; store locked, ventilated, bunded","Gloves/goggles worn for toilet and chemical work; eyewash/first aid available","Wet-floor signs and barriers used; cleaning schedules avoid peak traffic; non-slip footwear","No ladders above 3 m; MEWP/scaffold/BMU/rope access by trained persons with permits","Gondola/BMU: 12-monthly examination, daily pre-use, harness to independent anchor, wind limits, exclusion below","Sharps in puncture-proof containers; BMW colour-coded segregation; bags ≤ 3/4 full; no hand compaction","Needlestick/spill protocol and PEP route known; hepatitis B vaccination records (hospitals)","No manual entry into septic tanks/sewers/drains; mechanised agency used; sump entries only under confined-space permit by trained persons","Floor machines/cables RCD-protected and undamaged; electrical isolation for cleaning fittings","Welfare: toilets, changing room, rest area, drinking water for contract staff; ID cards","Women's night shifts: ≥ 2 staff, escort/transport, lit routes, panic/call system; POSH route displayed","Injury/near-miss log reviewed with contractor; corrective actions closed"]},
{id:"cl4-events",t:"Event Pre-Doors Safety Walk",cat:"Management",items:["Permissions in hand: police, fire NOC (temporary structures), municipal/venue, PESO (pyro), electrical certificate, FSSAI/LPG for stalls","Capacity calculated (NBC assembly loading) and displayed; counting system live at every gate","All exits unlocked, clear, lit and staffed; exit widths per plan; fire lanes clear","Queue barriers in snake lanes; front-of-stage barrier and pit with extraction team","Stewards in position with radios at ratio per plan (benchmark 1:250 — verify; more at pinch points); briefed on crush signs","Temporary structures (stage, trusses, LED walls, pandals, grandstands) certified; ballast/anchors checked today; wind action plan known","Pandal fabrics flame-retardant (certificates); extinguishers per area; LPG stalls separated; generators fenced with fuel bunding","Temporary wiring: RCDs, earthing, cable protection, weather-proof distribution; no cables in walkways","Pyro/SFX: licensed operator, fire service present, exclusion zones, no-fly/no-drop zones","Medical post staffed (doctor/paramedics), ambulances on site, AEDs and first-aid points marked","Water points, shade and heat plan for outdoor; weather/lightning monitoring with triggers","PA/announcement scripts (safety, evacuation, dispersal) tested; control room with CCTV and radios","Go/no-go decision recorded by event safety officer with police/fire/venue"]},
{id:"cl4-sewer",t:"Sewer / Septic Tank Work Permit Check",cat:"Industrial",items:["Mechanised cleaning (jetting/suction/robot) scheduled; manual cleaning entry refused and recorded","Agency licensed/empanelled; contract prohibits manual entry; PEMSR Act compliance file","If entry unavoidable: written justification and permit signed by supervisor","Inflows isolated (penstock/valve) and pumps locked out; rain not forecast","Ventilation ≥ 20 min with blower (verify); atmosphere tested top/middle/bottom: O2, H2S < 10 ppm, LEL < 10 %, CO < 25 ppm","Continuous 4-gas monitor on entrant; alarm = immediate exit","Harness with retrieval line on tripod/winch; attendant posted and never enters","≥ 2 SCBA sets and trained rescuers at manhole; ambulance contact; non-entry rescue first","Traffic management at road manholes (signs, cones, barriers); lighting","PPE: gloves, gumboots, coveralls, goggles/face shield, FFP3; washing/disinfection facility available","Vaccinations/medical records for entrants; no eating at site","Permit closed; manhole secured; equipment decontaminated; readings filed; any manual-entry proposal reported"]},
{id:"cl4-crusher",t:"Crusher Plant & Haul Road Shift Check",cat:"Industrial",items:["Crusher chamber entry/blockage clearing only under LOTO and permit; stored energy released from outside","Hopper grids/rock breaker in use for oversize; no bars used on running crusher","Conveyor nip guards (head/tail/take-up/return idlers) in place; pull-wire stops tested full length","Belt cleaning/idler changes only with belt stopped and isolated; crossing bridges used","Haul roads: width, gradient, berms ≥ half wheel height at edges, tip bunds/stop blocks, drainage, dust suppression","HEMM pre-use: brakes on grade, seat belts, reversing cameras/alarms, ROPS/FOPS, fire suppression, lights","Light-vehicle/dumper radio protocol and separation in use; speed limits posted and observed","Stockpile tunnels/hoppers: confined-space permits; reclaim feeders isolated; no walking on live piles","Dust sprays at crushers/screens/transfer points working; cab filters serviced; FFP3 where exposure","Hearing protection worn in noise zones; audiometry current","Silica monitoring and medical surveillance (X-ray/PFT) records; silicosis cases notified","Tyre work by trained persons in cage; raised bodies propped; buckets lowered","DGMS/state statutory registers, operator certificates and incident log up to date"]},
{id:"cl4-cement-kiln",t:"Kiln / Preheater / Coal Mill Safety Check",cat:"Industrial",items:["CCR trends (cyclone pressure/temperature) reviewed for build-ups; poke-hole covers intact","Blockage clearing: permit, trained crew, aluminised PPE, barriers on all levels below, nobody in discharge line","Air cannons/CO2 blasters operated remotely; manual poking from the side only","Inspection doors not opened with meal build-up above; restart hot-meal flush zones cleared","Coal/petcoke bins: CO/O2 and temperature monitoring working; inerting available; explosion vents clear","Coal mill interlocks and fire-fighting (CO2) tested; no hot work near; dust housekeeping done","Preheater tower/cooler/silo tops: guardrails and gratings intact; WAH permits for open edges","Kiln/preheater/cooler entry: cooled, fuel/feed/fans/drive isolated with mechanical block, atmosphere tested, permit, attendant","Loose coating removed from safe position before refractory work; scaffold/platforms inspected","Burn first-aid stations at each level; burn-unit tie-up; fire crew contacts posted","Dust (silica/cement) controls and respirators in use; monitoring/medical records current","AFR reception: segregated, SDS, PPE, fire detection; no bunker entry","Heat-stress plan active for tower work; incident/near-miss log reviewed"]},
{id:"cl4-steel-gas",t:"Gas Safety & Hot-Metal Area Check",cat:"Chemical",items:["Fixed CO monitors online at leak-prone points; calibration in date; wind socks visible","Personal CO monitors and self-rescuers issued to all entering gas areas; two-person rule enforced","Gas safety officer and rescue squad on shift; rescue station (SCBA, resuscitator) checked","Water seals at required head; goggle valves/blinds status logged; bleeders operated under permit","Gas-line permits show positive isolation, purge readings (CO/LEL/O2) and retest intervals","Hot work on gas mains/holders only after purge and gas test; fire watch; SCBA standby","Restoration: air purged with N2 before gas admitted; leak checks done","Furnace/stove light-off: purge and flame safeguard proven; no bypass; double block and bleed on gas trains","Cast house/converter: dry charge/tools, no water leaks near runners, ladle/torpedo inspection, access restricted during tapping","Radiant-heat PPE (aluminised/FR, face shields) worn; crane/ladle lifting gear in date","Coke ovens: emission controls, benzene monitoring, PPE; confined-space permits for stoves/GCP","CO exposure/medical surveillance and drill records current; incidents investigated"]},
{id:"cl4-chp-ash",t:"Coal & Ash Handling Plant Weekly Check",cat:"Industrial",items:["Conveyor nip guards at head/tail/take-up/return idlers in place; pull-cords tested full length; zero-speed/sway switches working","No work on running belts; LOTO used for idler changes/cleaning; belt clamped and counterweight secured","Galleries/transfer towers: handrails, toe boards, lighting, housekeeping; dust layers < 0.8 mm","Dust suppression/extraction at transfer points and crushers running; no compressed-air blow-down","Ex-rated electricals in Zone 21/22 intact; hot-work permits used; thermal scans of stockpiles logged","Bunker/silo CO and temperature monitoring online; inerting (steam/CO2) available; explosion vents clear","Bunker/silo entry only with isolation, bridging check, lifeline and attendant under permit","Coal mill fire/inerting procedure known; mill interlocks tested","Wagon tippler/side-arm charger exclusion and interlocks; track hopper guarded","Fly-ash silos: level/temperature/PRV checks; loading spouts dust-free; burns PPE; ESP hopper poking under isolation","Ash pond: dyke freeboard, seepage, piezometers inspected and logged; slurry pipelines patrolled; lifebuoys at decant","Respirators/hearing protection in use; dust, silica and noise monitoring current","Fire-system tests and incident/near-miss review done"]},
{id:"cl4-loading-dock",t:"Loading Dock & Yard Daily Check",cat:"Industrial",items:["Vehicle restraints/wheel chocks and communication lights working; 'keys-to-loader' rule in use","Dock levellers/plates: lip engages, maintenance props, no damage; stored when not in use","Dock bumpers, edge barriers/chains at unused doors, lighting ≥ 100 lux (verify) in trailers","Trailer checked before entry: floor, landing gear/stands, load shifted?; container doors opened from side with strap","Forklift drives straight at walking pace; loaders out of trailer while forklift inside; capacity vs trailer floor","Tail-lift: trained operator, platform rated, exclusion area, stowed before driving","Yard: one-way flow, truck lanes/pedestrian walkways marked, speed ≤ 10 km/h, reversing with banksman/cameras, mirrors","Drivers in waiting area until released; no walking in yard lanes","Manual handling aids (pallet jacks, extendable conveyors) available; heat breaks for container work","CO: electric forklifts or ventilation in enclosed trailers","Wet-weather slip controls at dock edges; wind — container doors secured","Near misses (drive-off, creep, pedestrian conflict) logged; monthly equipment inspection records"]},
{id:"cl4-heat-treat",t:"Heat Treatment Shop Monthly Check",cat:"Industrial",items:["Atmosphere furnaces: purge/interlock (low temperature, gas/air pressure, power failure) tested; flame curtains/pilots working","Gas trains: double block-and-bleed, flame safeguards tested; annual gas-train test record","CO monitors in shop calibrated; personal CO monitors in atmosphere-furnace area","Quench tanks: oil level/temperature interlocks, agitation, lids/suppression (CO2/dry powder) tested; no water lines above tanks","Quench oil flash point/water content tested; margin to operating temperature adequate","Salt baths: salts stored dry/covered; nitrate and cyanide baths separated; fume extraction; dry tools/work rule","Cyanide antidote kit and trained first aiders where cyanide used; acids excluded from area","Baskets/fixtures inspected for creep/cracks; crane/manipulator and hot-rated lifting gear in date","Pit furnaces/tanks guarded; exclusion zones during transfers","Ammonia/methanol/nitrogen storage per rules; leak detection; O2 monitors in enclosed areas","Furnace entry: cooled, purged, gas isolated/locked, confined-space permit, RCF dust controls","Waste (quench oil, salts, effluent) manifested; cyanide waste detoxified","PPE (aluminised, face shield, metatarsal boots) in good condition; quench-fire drill done"]},
{id:"cl4-fuel-station",t:"Fuel Outlet / Site Fuel Point Monthly Check",cat:"Chemical",items:["PESO licence/approved layout displayed; quantities within licence; CEIG electrical certificate","Earthing pits/clamps tested (≤ 1 Ω — verify); lorry bonding point in good condition","Dispensers: breakaway couplings, auto shut-off nozzles, no leaks; ESD switch tested","Overfill prevention/level gauging and high-level alarm working; fill points labelled by product","Extinguishers (DCP) and sand buckets in date and accessible; spill kit stocked","'No smoking / engine off / phone off' signage; forecourt traffic layout and speed limit visible","Decantation SOP followed: two persons, chocks, earth, engine off, seals/dip verified, no dispensing from tank being filled","Vapour-recovery (Stage I/II) functional where mandated; vents/flame arresters intact","Manhole chambers/USTs: no water ingress; tightness test in date; entry only under confined-space permit","CNG: compressor room ventilation and gas detection, hoses/nozzles in date, PRVs; auto-LPG equipment checks","Staff training (OMC/PESO), antistatic uniforms, night security (lighting, CCTV, two attendants)","Site fuel points (construction/mines): bunded skid tanks/bowsers earthed, approved safety cans, cold-engine refuelling only","Spill/fire drill done; incident log reviewed"]},
{id:"cl4-lpg-bottling",t:"LPG Plant Shift & Monthly Audit",cat:"Chemical",items:["Gas detectors across sheds/gantries/storage reading normal; alarm/ESD set-points tested; calibration in date","ESD and ROVs on bullets/gantries function-tested per schedule; excess-flow/back-check valves in place","Fire-water: pumps auto-start, storage full, deluge valves/sprinklers on bullets, sheds and gantries tested; hydrants/monitors clear","Area-classification drawings; Ex equipment register and IEC 60079-17 inspections current","Tank-lorry unloading: PESO-approved vehicle, chocks, earthing, engine off, hose test date, operator present throughout","Filling: cylinder inspection (due date, valve, body), electronic scales with auto cut-off, 100 % check-weighing, leak test every cylinder","Defective/leaking cylinders in designated outdoor area; evacuation via recovery (no venting); valve change by trained person","Cylinder storage: upright, caps, full/empty segregation, stack heights, Ex forklifts/lighting","No phones/vehicles/hot work in licensed area without permit and gas-free certificate","PTW for maintenance shows isolation, N2 purge and gas test; Ex equipment reinstated","Carousel/conveyor guards and e-stops; manual handling aids; gloves/antistatic clothing worn","MSIHC: safety report current, on-site plan, 6-monthly mock drill with district authorities, off-site plan liaison","Security per PESO/OMC; lightning protection tested; monsoon bund drainage checked"]}
];
const TALKS4 = [
{t:"Press Shop – Hands Out of the Die",pts:["Test the light curtain and two-hand controls every shift — no test, no run","Never reach in to clear a misfeed: stop, isolate, then clear","Die setting only with safety blocks in and the press locked out","A double stroke is a near miss — report it the same shift","No bypass keys, taped sensors or foot pedals without guards","Ear plugs in; gloves off near rotating parts"]},
{t:"Robot Cells – Nobody Inside While Live",pts:["A still robot is not a safe robot — it may be waiting for a signal","Request entry, wait for the protective stop, take the gate key with you","Inside the cell carry the pendant with e-stop; stay out of pinch zones","Teach at reduced speed with the enabling device; second person at e-stop","Last person out sweeps the cell before reset — nobody restarts from outside blind","Any bypassed interlock is a stop-work"]},
{t:"Paint Shop – Solvents, Static & Isocyanates",pts:["Thinner vapour needs only a spark: earth every container, no phones, no non-Ex tools","Ventilation on before you spray; airflow alarm means stop","2K clear coat = isocyanates = asthma for life; supplied air or PAPR, nobody else in the booth","Rags into self-closing metal bins; empty each shift","Never light an oven by hand; purge and flame-failure protect you","Hot work in the paint shop only with a permit and gas test"]},
{t:"Weld Fume Is Not Just Smoke",pts:["Welding fume is a Group 1 carcinogen — every indoor weld needs extraction","Keep the extraction nozzle close to the arc; if you can see fume in your face, it is not working","Galvanised sheet gives metal fume fever: chills after shift — report it","Stainless means hexavalent chromium — extraction plus RPE","Spot-weld tips crush fingers: both hands on the initiation, tips cool before dressing","Pacemaker wearers stay away from RSW transformers"]},
{t:"High-Voltage Batteries – Orange Means Danger",pts:["Orange cables carry 400–800 V DC — only HV-authorised persons, never alone","Pull the service plug, wait the discharge time, prove the meter, test, then touch","Insulated tools, Class 0 gloves, face shield — no rings or watches","A swollen, hot or hissing cell leaves the building now","Lithium fires need huge volumes of water and come back for hours — call the fire service early","Damaged packs sit outside, 15 m away, watched with a thermal camera"]},
{t:"Test Track Rules",pts:["No entry without the controller's clearance; radio on at all times","Know the speed band for your certification — limit tests only on the dynamic pad","Pull to the shoulder for any fault; never stop on the racing line","Pedestrians and maintenance only when the zone is closed","Rain, fog, lightning or dust: high-speed runs stop","Helmet and harness for limit-handling and rollover tests"]},
{t:"Ammonia – Smell It, Leave It",pts:["Ammonia smells long before it hurts — any smell is a leak, leave and report","Escape respirator on your belt in every NH3 area","Oil draining: two people, dead-man valve, never walk away from an open drain","Never trap liquid between two closed valves","Water fog knocks down vapour; never spray liquid ammonia pools","Eyes or skin splashed: flush 20 minutes, then OHC"]},
{t:"Never Mix Cleaning Chemicals",pts:["Acid plus bleach makes chlorine gas — one chemical at a time, rinse between","Add concentrate to water, never water to concentrate","Label every bottle; never use a drink bottle","Goggles and face shield for caustic — a splash in the eye is permanent","Before CIP starts, confirm nobody is inside the tank — lock the manway","Eyewash within 10 seconds: know where it is before you need it"]},
{t:"Grain & Sugar Silos – Never Walk the Pile",pts:["Flowing grain buries you knee-deep in 4 seconds and fully in 20","Clear bridges and walls from outside with poles — entry is the last option","Entry only with feeders locked out, atmosphere tested, lifeline and attendant","Never stand below hanging material","Dust layers explode: clean daily, no compressed-air blow-down, no hot work","If someone goes under, do not jump in — call rescue"]},
{t:"Hot Ovens & Fryers",pts:["Gas smell: stop, ventilate, isolate — never light by hand","Gauntlets and sleeves at ovens; open steam ovens from the side","Wet product into hot oil spits and boils over — dry it first","Fryer fire: lid or suppression, isolate heat, never water","Mixers and dividers: stop and isolate before scraping or clearing","Flour dust causes baker's asthma — tip under extraction, vacuum, no brooms"]},
{t:"Bottling Line – Guards, Glass & CO2",pts:["Hands never go into a running machine — stop, wait for run-down, use a tool","Glass bursts at the filler: face shield in the glass zone, tongs for shards","CO2 has no smell and fills low places — detector alarm means leave","Caustic from the bottle washer: goggles, gloves, isolate before cleaning","Palletiser cell: enter only through the interlocked gate with the key in your pocket","Wet floors: non-slip boots, clean spills now"]},
{t:"Cold Room – Never Alone, Never Locked In",pts:["Check the inside release before the door closes behind you","Sign in, carry a radio or alarm pendant, keep to the work/warm-up times","Shivering, numb fingers or confusion: leave now","CA rooms have 1–3 % oxygen — never enter to fetch fruit or a friend","Forklifts crawl inside: lights on, horn at doors, stop in fog","Frostbite: warm slowly, no rubbing"]},
{t:"Solvents & Static",pts:["Vapour travels along the floor to the nearest spark","Earth the drum, the pump and yourself before pouring","No splash filling — dip pipe, slow start","Ex equipment only; a phone in Zone 1 is a bomb in your pocket","Peroxide-formers: test before you distil, never to dryness","Spent solvent: closed earthed drum, labelled, out within 90 days"]},
{t:"Potent Compounds – Gown Right, Degown Slower",pts:["Micrograms matter: no open handling of OEB 5 material","Glove ports and split valves are the containment — a torn glove is an incident","Degowning is where most exposure happens — slow, inside-out, respirator last","Wet clean only; no brooms, no compressed air","Pressure alarm or HEPA alarm: stop and report","Tell OHC early if you are pregnant or planning — hormones and cytotoxics are not negotiable"]},
{t:"Clean-Room Work – Interlocks, Fumigation & Gas Suppression",pts:["AHU work: isolate at the panel and the local switch, prove the fan is stopped","Door interlocks must release on the fire alarm — test the override","Fumigation in progress: locked, placarded, no entry until readings clear","Gas suppression room: isolate the release before maintenance inside; pre-discharge alarm means leave now","Nitrogen areas: watch the O2 monitor","Evacuate gowned — nobody degowns in a fire"]},
{t:"Charging the Reactor Safely",pts:["Powder into solvent vapour through an open manway is how pharma fires start","Inert first: O2 below the limit on the analyser, purge on during charging","Earth the drum, the chute, the reactor and yourself; no plastic scoops or liners","Add at the planned rate and in the planned order — accumulation becomes a runaway","Temperature off profile: stop the feed, maximum cooling, call the shift in-charge","Never open a hot or pressurised vessel"]},
{t:"Cotton Dust & Monday Chest Tightness",pts:["Tight chest on Mondays is byssinosis starting — tell the OHC","Suction hoods and the filter plant are your lungs' protection — report blockages","No compressed-air cleaning while people are in the shed","Respirator for blow room, card stripping and waste rooms","Spirometry before and after the Monday shift — do not skip it","No smoking anywhere in the mill"]},
{t:"Dye House Chemicals",pts:["Hydrosulphite plus moisture heats up and burns — keep drums sealed and dry","Peroxide away from reducers; acid away from bleach and caustic","Dye powders only in the booth with extraction and a mask","HT machine door opens only below 80 °C and zero pressure — never bypass the interlock","Steam valves open slowly; lagging stays on","Shower and eyewash: 10 seconds away, tested every week"]},
{t:"Carding & Ring Frames – Stop Before You Clear",pts:["Beater lids open only after the rotor has stopped — the timer is there for a reason","Card stripping with the machine stopped and locked","Hair covered, dupatta tucked, no loose sleeves — frames do not let go","Piece only where you were trained; stop for lapping and tape changes","Shuttle guards stay on; stop the loom before reaching in","Keep aisles and exits clear of trolleys"]},
{t:"Heat in the Spinning Shed",pts:["Wet-bulb above the limit: humidification off, ventilation on","Drink before you are thirsty; ORS in the summer","Dizziness, cramps, no sweating: cool area, water, tell the supervisor","New workers take 7–14 days to acclimatise — watch them","Air-washer tanks are confined spaces","Report hygrometer readings honestly — they protect you"]},
{t:"Moulding Machines – Interlocks Save Hands",pts:["Test the front gate every shift — the machine must not close with it open","Hands in the mould area only through the front gate, never rear or top","Stuck part: set-up mode, clamp blocked, tools not fingers","Mould change: inspected eyebolt, rated crane, hands never between the halves","Granulator blockage: stop, isolate, wait, then clear","Smoke from the barrel means decomposition — lower heat, ventilate"]},
{t:"Hot Plastic & Purging",pts:["Purge behind the shield, face shield on, nobody in front of the nozzle","Hot plastic traps gas and spits — short shots into a metal tray","Never put a torch on a blocked die","Rupture disc in place or no start","PVC and POM fumes burn your lungs — extraction on","Hot screws and dies go in the marked cooling area"]},
{t:"Two-Roll Mills – The Trip Bar Is Your Life",pts:["Test the trip bar at the start of every shift — rolls must stop and separate","Two people on a running mill, always","No gloves, no loose sleeves at the nip","Feed with tools from above the guard line; cut with the knife away from the nip","Sticking stock: trip, stop, then clear","A near miss at the nip is reported the same hour"]},
{t:"Printing Solvents & Dryers",pts:["Ethyl acetate ignites at −4 °C — treat every tray as a fire waiting for a spark","Earthing straps and ionisers on before the web runs","LEL alarm: slow down, more exhaust, then stop","Dryer purge and flame safeguard never bypassed","Rags in closed bins; small quantities at the press","Blade changes with cut-resistant gloves and covers"]},
{t:"Soldering Fume & Lead – Wash Before You Eat",pts:["Rosin fume causes asthma — tip extraction on, nozzle close to the joint","Lead gets in through your hands: wash before breaks, no food at the bench","Skim dross with tools and a face shield, into a metal tin","Wet boards into the wave pot explode","Blood-lead tests are for you — attend them","Wheeze or chest tightness at work: report it"]},
{t:"HF Acid – Calcium Gluconate Now",pts:["HF does not hurt at first — the burn goes to the bone hours later","Any skin contact: flush 5 minutes, rub in calcium gluconate gel, go to hospital","Double gloves, face shield, apron at the wet bench","Piranha: acid first, slow peroxide, never a closed container","TMAH through the skin can stop your breathing — flush and hospital even if you feel fine","Gas alarm: leave the zone, let the ERT handle it"]},
{t:"Lithium Cells – Signs of Thermal Runaway",pts:["Hissing, sweet smell, bulging, heat or smoke: move away and raise the alarm","Store at 30–50 % charge, cool, with aisles clear","Damaged or returned cells go to the outdoor quarantine, never back on the rack","Water in large volume cools; small extinguishers do not stop runaway","Fires re-ignite for days — thermal camera watch after any event","No metal tools or jewellery near terminals"]},
{t:"Climbing the Tower – Clip, Check, Climb",pts:["Two people, weather checked, control informed — then climb","Arrester on the rail before your foot is on the rung","Twin lanyards at every hatch: one on before one off","Close every hatch behind you; tools tethered","Rest at platforms; water every 30 minutes in summer","Dizzy or unwell: say so and come down"]},
{t:"Rescue in 15 Minutes",pts:["A person hanging in a harness can die within minutes — the team on the turbine is the rescue","Rescue kit at the top, rope long enough for the hub height, inspected monthly","Use the trauma straps if you are suspended; keep your legs moving","Lower the casualty, do not try to lift them up the ladder","Nacelle fire: personal descender, out through the hatch","Drill every six months — practice is the plan"]},
{t:"Rotor Lock Before Hub Entry",pts:["All lock pins in, indicator and eyes agree, tag on — then open the hub hatch","Isolate pitch, converter and UPS; prove dead on every circuit","Accumulators at zero before touching hydraulics","Two in the hub or at the hatch, radio on","Wind over the limit or lightning alert: pins stay in, you come down","Hydraulic torque tools: hands clear of the reaction arm"]},
{t:"Blade Work Weather Call",pts:["Rope access only below the wind limit, dry, no lightning within range","Blade at 6 o'clock, rotor and pitch locked, recorded","Two ropes, two anchors, edge protectors — no exceptions","Grinding fibreglass: extraction and FFP3; resin on skin becomes an allergy","Spotter on the ground watches the sky and the road","Lightning alert: finish nothing, come off the blade"]},
{t:"Lightning – 30 km Out, We Come Down",pts:["Lightning at 30 km: pack up; at 15 km or thunder heard: leave the turbine or roof","Shelter in vehicles or the control building — never under the tower or a tree","Wait 30 minutes after the last strike before climbing again","Do not touch towers, fences or cables during a storm","After a strike on a turbine, inspect the lightning protection before work","The control room's call to descend is not a suggestion"]},
{t:"Remote Site – Know Your Way to Hospital",pts:["Ambulance is an hour away — the first aider on your crew is the first hour","Every vehicle has the turbine GPS list, the hospital route and an AED or knows where one is","Check in every hour; nobody works alone on HT, height or in confined spaces","Snakebite: still limb, pressure bandage, hospital with anti-venom — no cutting, no tourniquet","Heat stroke: cool first, drive second","Road accidents kill more technicians than turbines — seat belts, speed limits, no tired driving"]},
{t:"Solar DC Is Live in Daylight",pts:["Strings cannot be switched off while the sun is up — treat every DC cable as live","Open AC, open DC isolators, wait for discharge, prove the meter, test","Never pull a connector under load — check current first or cover the modules","Burnt or mismatched connectors start fires; replace, do not tape","Rain or lightning: no open enclosures","Fire service must be told DC stays live — nobody cuts cables"]},
{t:"Fragile Roofs Kill",pts:["Cement sheets and skylights do not hold a person — walk only on boards over purlins","Clip to the lifeline before you leave the ladder","Rooflights covered or netted before anyone steps on the roof","Modules catch wind like sails: two people, stop at the wind limit","Never cut or drill asbestos sheets dry","A ten-minute cleaning job needs the same protection as installation"]},
{t:"BESS Alarm Response",pts:["Gas alarm: doors stay shut — opening them can trigger an explosion","Move to the standoff distance and isolate remotely","Call the fire service with the chemistry and kWh — the ERP is in the control room","Water cools neighbours; nobody enters until gas and temperature are stable for a day","DC racks: isolate, wait, prove dead, insulated tools","Firmware and layout changes go through MoC"]},
{t:"Container Tops & Twistlocks",pts:["Nobody walks under a crane load or in the operational lane","Lashing from platforms and cages — never climb stacks","Twistlock indicators: locked before the lift","Rods in pairs, bins for twistlocks, gloves on","Wind rising: top tiers stop first, cranes stow at the limit","ITV drivers stay in the cab under the crane"]},
{t:"Ship Holds – Test Before Entry",pts:["Coal, grain, logs and steel eat oxygen; fumigated cargo leaves phosphine behind","No entry on smell or guesswork — a calibrated meter at three depths, then a permit","Attendant at the hatch never enters; rescuers wear SCBA or stay out","One person on the ladder at a time, tools on the hoist line","Grab or dozer working: nobody in the hold","Headache or dizziness: get out and report"]},
{t:"Mooring Lines – Snap-Back Zones",pts:["The whole mooring deck and quay area is a snap-back zone","Never stand in a bight or in line with a tensioned line","Grab a line only when it is slack and on the quay","Lifejacket within 2 m of the edge and on the boat","Creaking or strand breaks: warn the ship, step well back","Someone in the water: lifebuoy and boat — never jump in"]},
{t:"Dangerous Goods Containers",pts:["Placards and the declaration must match — if not, the box goes to the hold area","Fumigated units: ventilate, test, then open","Crack the doors from the side and step back","Leak or heat: isolate upwind, identify the UN number, call the DG officer","Ammonium nitrate and explosives do not stay in the yard","No smoking, no phones in the DG yard"]},
{t:"Sugar Mill Season Start",pts:["Cane yard traffic kills more than machines: marshals, one-way, drivers out of the bay","Never hand-feed the carrier or clear a choke while it runs","Centrifugal lid opens only when the basket has stopped","Bagasse heats itself — probe the stacks, keep fire breaks clear","Hot juice and lime: face shield, open valves from the side","New workers wear the new-worker colour — look out for them"]},
{t:"Grain Dust & Elevators",pts:["Most mill explosions start in the bucket elevator — belt slip, hot bearing, dust","Keep dust off ledges and motors; vacuum, no compressed air","Magnets and destoners stop tramp metal sparks","Never walk on stored grain; bins are entered only under permit","Phosphine fumigation is for licensed people only — keep out of placarded areas","Lift bags with your legs and a partner"]},
{t:"New Season, New Workers – Buddy Up",pts:["No one works near machines, vehicles or heights before induction in their language","Every new worker has a buddy for two weeks and wears the new-worker colour","Ask, do not assume: show how, watch, then sign off","Age proof for everyone; no under-18s on hazardous jobs","Safe camps: water, toilets, LPG kept outside, fire extinguisher","Report unsafe conditions — nobody loses wages for speaking up"]},
{t:"DG Room – It Can Start by Itself",pts:["Mains fails, the DG starts — AMF off, battery off, fuse out before any work","Back-feed can electrocute the lineman down the street: never bypass the interlock","Exhaust at 400 °C; no rags, no diesel near the manifold","Basement DG rooms: CO detector on, nobody inside during runs","Fuel transfer: bonding, drip tray, stop at 90 %","Doors closed, ear protection inside the enclosure"]},
{t:"Refrigerant Rooms – Air You Cannot Smell",pts:["A refrigerant leak pushes out the oxygen — the detector is your nose","Alarm: leave, ventilate, close the door, isolate from outside","Pressure test with nitrogen only — never oxygen or air","Brazing a line with refrigerant inside makes phosgene — recover first, purge with nitrogen","Cylinders upright, shaded, capped","Venting refrigerant is illegal and wasteful — recover it"]},
{t:"Lift Shafts – Never Open a Landing Door Blind",pts:["Most lift deaths are falls into an empty shaft — confirm the car is there","No jumpers on door locks; remove them before you leave","Car-top work only in INSPECTION mode with the stop switch and a second person","Pit entry with the car blocked and the stop switch on","Trapped passengers: trained mechanic releases, car at the landing, power off","Tell passengers to stay inside — climbing out between floors kills"]},
{t:"Housekeeping Chemicals & Sharps",pts:["Toilet acid plus bleach makes chlorine — never together","Labelled bottles only; gloves and goggles for toilet cleaning","Needles only in the puncture-proof box; never push waste down with hands","Needlestick: wash, report, PEP within 2 hours","No ladders above 3 m; façade work for trained people with harness","Nobody enters a septic tank or drain — ever"]},
{t:"Crowd Events – Exits, Marshals, Headcount",pts:["Count people in; stop at capacity — no free-entry rumours","Every exit unlocked, lit, staffed","Crowd surge signs: people falling, screaming, pressure — pause the show, open all exits","LED walls and trusses come down at the wind limit","Pandal fabric flame-retardant; LPG stalls separated; extinguishers everywhere","Medical post, AEDs and water points before the doors open"]},
{t:"Sewer & Septic Tanks – No Manual Entry",pts:["Manual cleaning of sewers and septic tanks is illegal and lethal — machines do it","H2S kills in one breath and takes the rescuer next","Inspection entry only: isolate inflows, ventilate, test, lifeline, attendant, SCBA at the manhole","Attendant never enters; rescue is pulled out by winch","Rain forecast: no entry","Anyone asked to go in by hand says no and reports it"]},
{t:"Haul Roads & Dumpers",pts:["Berms at the edges, stop blocks at the tip, spotter at night","Light vehicles keep 50 m and call before overtaking","Reverse only with camera or spotter; pedestrians stay out of the pit road","Brakes tested on the grade every shift; seat belt on","Blocked crusher: isolate, release the energy from outside — no bars in a running jaw","Dust sprays on; mask when they are not"]},
{t:"Hot Meal Burns",pts:["Hot meal is 800 °C powder that flows like water","Nobody stands below or in line with a poke hole or inspection door","Clear blockages remotely first; manual poking only in aluminised PPE from the side","Doors stay shut when meal is built up above","Restart flushes the kiln inlet — clear the area before feed on","Burn: cool with water 20 minutes, straight to hospital"]},
{t:"CO – The Silent Killer in Steel Plants",pts:["Blast-furnace gas has no smell; your CO monitor is the only warning","Monitor on, buddy with you, stay upwind of bleeders and stoves","Alarm: leave uphill and upwind, report — never finish the job","Collapsed colleague: do not go in without SCBA — call the rescue squad","Gas-line work only after goggle valve, blind, purge and test","Water near molten metal explodes — dry tools, dry charge"]},
{t:"Coal Bunkers & Conveyors",pts:["Nip points at every pulley — no cleaning near a running belt","Pull-cord tested, guards on, cross only at bridges","Coal dust on beams is explosion fuel — clean, no compressed air","Bunker CO rising means a fire inside: inert, do not open","Bunker and silo entry: isolate, test, lifeline, attendant","Ash is hot and flows — hopper poking under isolation only"]},
{t:"Loading Dock – Chock Before You Load",pts:["Trailer creeps, forklift drops — restraint or chocks and keys in the office first","Check the trailer floor and landing gear before driving in","Container doors open from the side with a strap","Loaders out of the trailer while the forklift is inside","Drivers wait in the driver room, not between vehicles","Green light means go; red means the trailer is not ready"]},
{t:"Quench Tanks & Furnace Atmospheres",pts:["Endothermic gas explodes if air gets in — never bypass the purge","CO monitor on in the furnace area","Low oil or hot oil: no quench — the load will light the tank","Water in oil or salt erupts; dry work, dry tools, dry salt","Fire in the tank: load stays under, lid down, suppression on, no water","Baskets with cracks do not go in the furnace"]},
{t:"Fuel Station – Static & Decanting",pts:["Earth the lorry before any hatch or hose","Engine off, chocks in, two people watching the whole decant","Right product, right tank — check the label twice","Phones, smoking, running engines: not on the forecourt","Spill: stop, isolate ignition, sand, report","Lightning: stop decanting"]},
{t:"LPG Cylinders – Leaks & BLEVE",pts:["LPG sinks and travels — a leak at the carousel reaches the gate","Smell or alarm: stop, ESD, no ignition, move crosswind","Overfilled cylinder bursts in the sun — check-weigh every one","Jet fire: do not put it out until the gas is isolated; cool the tanks","Tank-lorry fire: 500 m back, BLEVE can happen","Earth, chock, engine off, hose in date — every lorry, every time"]}
];
